ClinicalChunks.register("data/templates-048.js",[{"id":"templates-19c4351e09a63e78e755","key":"v1-c9ccc21dfe2a3058|templates-19c4351e09a63e78e755","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头痛（肾虚头痛）","category":"门诊病历模板","raw":{"name":"头痛（肾虚头痛）","category":"门诊病历模板","case":{"case_name":"病例1：肾虚头痛","templates":{"主诉":"头痛且空、眩晕腰痛2月","现病史":"患者近期出现头痛且空、眩晕腰痛2月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 76次/分，R 18次/分，BP 115/75mmHg。神志清楚，神经系统检查未见明显异常。","辅助检查":"检查计划：患者头痛且空、眩晕腰痛2月，反复发作，初诊为肾虚头痛，需完善检查排除颅内器质性病变及继发性头痛病因。查血常规了解有无贫血、感染，贫血本身可致头痛头晕；完善生化全项检查了解肝肾功能、血糖、电解质及蛋白水平，排除代谢性及肾性因素所致头痛；完善凝血功能检查评估有无高凝及出血倾向，为影像学检查及可能的有创操作做准备；查血糖排除糖尿病及低血糖所致头痛；查血脂了解血脂水平，评估动脉粥样硬化及脑血管病危险因素；完善同型半胱氨酸检查，评估脑小血管病及卒中相关危险因素；完善头颅CT/MRI检查明确有无颅内占位、缺血性改变及脑白质病变，排除继发性头痛；完善颈动脉超声了解颈部血管有无斑块及狭窄，明确有无颅外血管病变；完善经颅多普勒检查评估颅内血流情况；查心电图排除心肌缺血及心律失常；完善心脏超声检查评估心腔结构并排查心源性栓子来源；若头痛性质变化、伴脑膜刺激征且影像学无禁忌，必要时行腰椎穿刺检查排除颅内感染及蛛网膜下腔出血。上述结果回报后，结合肾精不足证候予以补肾填精、养阴止痛治疗，并动态观察头痛演变，必要时请神经内科会诊。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 头痛（肾虚头痛）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：主方大补元煎加减。\n组成：熟地黄20g、山药15g、山茱萸12g、枸杞子12g、党参15g（或人参6g另煎兑服）、当归10g、杜仲15g、菟丝子15g、龟板胶10g（烊化兑入）、炙甘草6g。\n随证加减：畏寒肢冷、腰膝酸冷者加肉桂3g、制附子6g（先煎）温补肾阳；耳鸣、失眠、健忘明显者加磁石30g（先煎）、酸枣仁15g、远志10g；午后潮热、盗汗、颧红者加知母10g、黄柏10g滋阴降火。\n煎服法：水煎服，每日1剂。头煎加水约600ml，浸泡30分钟后武火煮沸，改文火煎煮30分钟，取汁约200ml；二煎加水500ml煎取200ml，两煎药液混合，早晚饭前半小时分2次温服（龟板胶烊化兑入）。\n疗程：2周为1个疗程，一般连服2～3个疗程，每疗程结束复诊，由医师随证调整方药。\n\n2. 中成药巩固：汤药疗程结束后改服六味地黄丸（浓缩丸）8丸/次，每日3次，口服，连用4周，巩固肾阴、填精养髓，减少复发。\n\n3. 现代医学对症治疗：头痛急性发作、疼痛明显影响休息时，临时口服对乙酰氨基酚片0.5g或布洛芬缓释胶囊0.3g，每日不超过2次，连续使用不超过3天，避免长期服用止痛药掩盖病情。\n\n4. 对症辅助：伴明显失眠者，睡前口服右佐匹克隆片1.5mg或艾司唑仑片1mg，疗程不超过2周；同时可加用谷维素片20mg、每日3次调节自主神经。\n\n【一般治疗及生活指导】\n1. 休息与起居：保证充足睡眠，避免熬夜、过度劳累及长期用脑，节制房事以固护肾精；晨起、站起时动作宜缓，防止体位性眩晕加重头痛。\n2. 饮食调养：饮食宜温补益肾，可常食核桃、黑芝麻、黑豆、桑葚、山药、枸杞子、羊肉、猪肾等补肾填精之品；忌辛辣燥热、肥甘厚腻、生冷之品，少饮浓茶、咖啡，戒烟限酒。\n3. 活动与保暖：适度进行太极拳、八段锦等舒缓运动以固肾强身，避免剧烈运动、久坐久站及腰背受凉，头部及腰膝注意保暖。\n4. 情志与禁忌：保持情绪平和，避免思虑过度、忧恐伤肾；不宜暴怒、房劳过度；服药期间忌食生萝卜、浓茶，以免影响补益药效；勿自行长期服用止痛药。\n\n【随诊要求】\n1. 每2周复诊1次，评估头痛发作频次、程度及腰膝酸软、耳鸣、失眠等伴随症状改善情况，由医师随证调整方药；连服2～3个疗程后复查，决定是否进入中成药巩固阶段。\n2. 血压偏高者每周监测血压；头痛反复发作超过4周无明显缓解者，建议完善头颅CT/MRI、经颅多普勒（TCD）等检查，排除颅内占位、血管性疾病等器质性病变。\n3. 若出现头痛剧烈突发加重，或伴恶心呕吐、视物模糊、肢体麻木无力、言语不清、意识障碍等，应立即就近急诊就诊，必要时行头颅CT/MRI检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1209,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a2662596ef482c8295dfe4249505e486b02ec9c4de2b377bc0d95de97d7a55e1","pinyin":"toutong（shenxutoutong）","initials":"tt（sxtt）","setting":"out","caseName":"病例1：肾虚头痛","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：肾虚头痛",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0c3339de3058fe1445f1","key":"v1-c9ccc21dfe2a3058|templates-0c3339de3058fe1445f1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眩晕（痰湿中阻）","category":"门诊病历模板","raw":{"name":"眩晕（痰湿中阻）","category":"门诊病历模板","case":{"case_name":"病例1：痰湿中阻眩晕","templates":{"主诉":"眩晕、头重昏蒙1月","现病史":"患者近期出现眩晕、头重昏蒙1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有高血压病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 80次/分，R 18次/分，BP 140/90mmHg。神志清楚，神经系统检查未见明显异常。","辅助检查":"检查计划：患者眩晕、头重昏蒙1月，既往有高血压病史，初诊为眩晕（痰湿中阻），需完善检查明确眩晕病因并排除脑血管及心血管病变。查血常规了解有无贫血所致头晕；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性及肾性因素；完善凝血功能检查评估有无高凝状态，为影像学检查做准备；查血糖明确有无糖尿病及低血糖所致眩晕；查血脂了解血脂水平，评估动脉粥样硬化及脑血管病危险因素；完善同型半胱氨酸检查评估脑卒中危险因素；完善头颅CT/MRI检查明确有无脑梗死、脑出血、颅内占位及脑萎缩等器质性病变，排除中枢性眩晕；完善颈动脉超声检查了解颈部血管有无斑块、狭窄，明确有无后循环供血不足；完善经颅多普勒检查评估颅内血流速度及有无血管痉挛、狭窄；查心电图排除心肌缺血、心律失常所致头晕；完善心脏超声检查评估心腔结构及有无附壁血栓，排查心源性栓子来源；若眩晕伴神经系统定位体征且影像学无禁忌，必要时行腰椎穿刺检查进一步明确病因。上述结果回报后，结合痰湿中阻证候予以燥湿祛痰、健脾和胃治疗，同时监测血压并规范降压，必要时请神经内科、耳鼻喉科会诊。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 眩晕（痰湿中阻）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中医辨证方剂：半夏白术天麻汤加减（燥湿化痰、健脾和胃、平肝息风）。处方：法半夏9g、天麻10g、炒白术15g、茯苓15g、陈皮9g、炙甘草6g、生姜3片、大枣4枚。加减：眩晕甚伴恶心呕吐频作者，加旋覆花10g（包煎）、代赭石15g（先煎）以降逆止呕；脘闷纳呆、苔腻甚者，加砂仁6g（后下）、白豆蔻6g（后下）以化湿醒脾。煎服法：上药加清水约600ml，先煎代赭石30分钟，再入余药武火煮沸后文火煎取200ml，同法再煎取200ml，两煎药液混合，分早晚两次温服，饭后半小时服用。疗程：7剂，每日1剂。\n2. 现代医学对症治疗：甲磺酸倍他司汀片（敏使朗）6mg，每日3次，口服，疗程7天，以改善内耳微循环、缓解眩晕；若伴恶心呕吐明显者，予盐酸甲氧氯普胺注射液10mg，肌肉注射（必要时，单次），呕吐缓解即止。\n3. 若眩晕反复发作、伴有颈项僵硬者，可加用盐酸氟桂利嗪胶囊（西比灵）5mg，每晚睡前口服，疗程不超过7天（老年人慎用，注意锥体外系反应及嗜睡）。\n\n【一般治疗及生活指导】\n1. 休息：急性发作期应卧床休息，闭目养神，减少头部转动及体位快速变化（起床、翻身宜缓慢），避免声光刺激及长时间低头、玩手机。\n2. 饮食：饮食宜清淡、低盐低脂，多食薏苡仁、山药、冬瓜、赤小豆等健脾化湿之品；忌食肥甘厚味、生冷黏腻、甜食及浓茶、咖啡、烟酒，以免助湿生痰。\n3. 活动：症状缓解后循序渐进进行散步、八段锦、太极拳等缓和不剧烈的活动，避免剧烈运动、突然转头和快速起立。\n4. 禁忌：避免劳累过度、情志激动和恼怒，保持情绪平稳、作息规律；注意颈部保暖，避免长时间伏案工作。\n\n【随诊要求】\n1. 服药7剂后复诊，由医师评估眩晕发作频率、程度及舌脉变化，调整方药；若连续服药2周症状无明显改善，需进一步行前庭功能、头颅MRI等检查明确病因。\n2. 治疗期间若出现眩晕突然加重、视物旋转不止、恶心呕吐持续不缓解，或伴一侧肢体麻木无力、言语含糊、口角歪斜、视物成双等，提示可能为脑血管意外等急症，应立即急诊就诊，勿延误。\n3. 症状缓解后仍需门诊随访1个月，观察病情是否复发，并根据舌脉决定是否继续健脾化痰以巩固疗效。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1210,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e9e11680c192ee4cdfbb740000cfbcced40b1e51d3435616928f6357632d6086","pinyin":"xuanyun（tanshizhongzu）","initials":"xy（tszz）","setting":"out","caseName":"病例1：痰湿中阻眩晕","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：痰湿中阻眩晕",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2104808ee3f908243fa4","key":"v1-c9ccc21dfe2a3058|templates-2104808ee3f908243fa4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眩晕（瘀血阻窍）","category":"门诊病历模板","raw":{"name":"眩晕（瘀血阻窍）","category":"门诊病历模板","case":{"case_name":"病例1：瘀血阻窍眩晕","templates":{"主诉":"眩晕、头痛如刺1月","现病史":"患者近期出现眩晕、头痛如刺1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往有脑外伤病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 78次/分，R 18次/分，BP 125/80mmHg。神志清楚，神经系统检查未见明显异常。","辅助检查":"检查计划：患者眩晕、头痛如刺1月，既往有脑外伤病史，初诊为眩晕（瘀血阻窍），需完善检查明确有无颅内陈旧性损伤及脑血管病变。查血常规了解有无贫血、感染及血小板异常；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性因素所致眩晕；完善凝血功能检查评估凝血状态，为影像学及必要的有创检查做准备；查血糖排除糖尿病及低血糖所致眩晕；查血脂了解血脂水平，评估动脉粥样硬化及脑血管病危险因素；完善同型半胱氨酸检查评估脑卒中相关危险因素；完善头颅CT/MRI检查明确有无陈旧性脑挫裂伤、颅内血肿、脑软化灶及占位性病变，与既往脑外伤病史相印证，排除继发性眩晕；完善颈动脉超声检查了解颈部血管有无斑块及狭窄，明确有无颅外血管源性眩晕；完善经颅多普勒检查评估颅内血流情况，了解有无血管痉挛或狭窄；查心电图排除心肌缺血及心律失常；完善心脏超声检查评估心腔结构并排查心源性栓子来源；若头痛加剧、伴呕吐或脑膜刺激征且影像学无禁忌，必要时行腰椎穿刺检查排除颅内出血及感染。上述结果回报后，结合瘀血阻窍证候予以活血化瘀、通窍活络治疗，必要时请神经外科、神经内科会诊。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 眩晕（瘀血阻窍）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药辨证方剂：主方通窍活血汤加减。组成：赤芍10g、川芎10g、桃仁10g（打碎）、红花6g、白芷10g（代麝香）、石菖蒲10g、郁金10g、丹参15g、天麻10g、钩藤15g（后下）、鸡血藤15g、甘草6g。煎服法：水煎服，每日1剂，先浸泡30分钟，武火煮沸后文火煎煮30分钟，取汁300ml，分早晚2次温服，饭后半小时服用。疗程：2周为1个疗程，视病情可连用2~3个疗程。\n2. 若头痛如刺、痛处固定明显者，加延胡索10g、五灵脂10g（包煎）以增强活血定痛之功；若伴气虚乏力、动则加重者，加黄芪20g、党参15g益气活血。\n3. 现代医学对症治疗：眩晕急性发作期予甲磺酸倍他司汀片6mg口服，每日3次，改善前庭微循环；或盐酸氟桂利嗪胶囊5mg每晚口服（不超过1个月，老年人及有锥体外系疾病史者慎用）。\n4. 若经颅多普勒或影像学提示后循环缺血、脑动脉供血不足者，予银杏叶提取物片40mg口服，每日3次，改善脑循环；若合并高血压者，按血压水平规范降压（目标<140/90mmHg），并监测凝血功能。\n\n【一般治疗及生活指导】\n1. 休息：急性发作期卧床休息，闭目静养，避免头部突然转动及长时间低头、仰头；起卧动作宜缓慢，下床时先坐位适应片刻再站立，谨防跌倒。\n2. 饮食：宜清淡易消化，忌肥甘厚腻、辛辣刺激、生冷及过咸之品，戒烟限酒；可适量食用山楂、黑木耳、洋葱等活血化瘀之品，避免浓茶、咖啡。\n3. 活动与情志：眩晕缓解期可适当进行太极拳、八段锦等和缓运动，避免剧烈活动及情绪激动、恼怒，保持心情舒畅，保证充足睡眠，避免熬夜。\n4. 禁忌：眩晕发作期及缓解早期禁止驾车、骑车、操作机械及从事高空作业；注意头部保暖，避免受凉及外感风寒。\n\n【随诊要求】\n1. 服药2周后复诊，评估眩晕发作频率、程度及伴随症状（头痛、肢体麻木等）改善情况，据舌脉调整方药；疗程结束后复查疗效，必要时继续巩固治疗1个疗程。\n2. 建议完善头颅MRI/MRA、经颅多普勒（TCD）、颈动脉超声等检查，明确后循环供血及血管情况；监测血压、血脂、血糖。\n3. 长期服用活血化瘀药物者，每4~8周复查凝血功能、肝肾功能，注意观察有无牙龈出血、皮肤瘀斑、黑便等出血倾向。\n4. 若眩晕反复发作或进行性加重，伴剧烈头痛、恶心呕吐、言语不清、肢体麻木无力、视物模糊或复视、行走不稳等，须立即急诊就医，排除急性脑血管病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1211,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"05a398208c974150c0397e8065aa06d028072af9d8c0e84810b5a96a8d597bf4","pinyin":"xuanyun（yuxuezuqiao）","initials":"xy（yxzq）","setting":"out","caseName":"病例1：瘀血阻窍眩晕","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：瘀血阻窍眩晕",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-29b8cda969178410bb98","key":"v1-c9ccc21dfe2a3058|templates-29b8cda969178410bb98","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中风（风痰入络）","category":"门诊病历模板","raw":{"name":"中风（风痰入络）","category":"门诊病历模板","case":{"case_name":"病例1：风痰入络中风","templates":{"主诉":"肌肤不仁、手足麻木1周","现病史":"患者1周来肌肤不仁，手足麻木，突然发生口眼歪斜，语言不利，口角流涎，舌强语謇，甚则半身不遂，或兼见手足拘挛，关节酸痛等症，舌苔薄白，脉浮数。","既往史":"既往有高血压病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 82次/分，R 18次/分，BP 150/95mmHg。神志清楚，左侧鼻唇沟变浅，伸舌左偏，左侧肢体肌力4级。","辅助检查":"检查计划：患者既往高血压病史多年，本次突发肌肤不仁、手足麻木，并迅速出现口眼歪斜、语言不利、口角流涎、舌强语謇，甚则半身不遂，需按急性脑血管病紧急评估，入院即刻完善头颅CT检查以鉴别脑出血与脑梗死，明确责任病灶部位及范围；查血常规以排除感染、贫血等影响因素；尿常规、便常规作为入院常规筛查，了解有无泌尿系及消化道基础病变；住院期间需使用活血化瘀及降压药物，药物多经肝肾代谢，完善肝肾功能检查以排除肝肾功能不全、指导用药剂量；查血糖、血脂以明确有无糖尿病及脂代谢异常等脑血管病危险因素，指导二级预防方案；查电解质以排除电解质紊乱所致神经肌肉症状加重；完善心电图检查以了解有无心房颤动、心肌缺血，明确心源性栓塞可能；查心脏彩超加左心功能测定以了解心内有无附壁血栓、瓣膜病变及射血分数；查颈部血管彩超以明确颈动脉有无粥样硬化斑块及狭窄，评估脑供血情况；完善凝血功能检查以评估出血风险，为抗栓治疗提供依据；患者手足麻木、半身不遂，肢体活动受限，病情稳定后完善双下肢静脉彩超以排除深静脉血栓形成；因言语不利、吞咽障碍、饮水呛咳者，必要时完善头颅MRI加弥散加权成像以明确新发梗死灶；完善胸部X线片以排除肺部感染、占位等基础疾病；腹部超声以了解腹腔脏器情况、排除腹部基础病变；根据病情需要选择相应检查，中医四诊合参、辨证论治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 中风（风痰入络）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂（真方白丸子加减）：法半夏9g、制天南星6g、天麻10g、白附子6g（先煎）、僵蚕10g、全蝎3g（研末冲服）、地龙10g、川芎10g、陈皮10g、茯苓15g、枳壳10g、甘草6g。水煎服，每日1剂，水煎取汁400ml，分早晚两次温服，以祛风化痰通络，疗程2周。\n2. 抗血小板聚集：阿司匹林肠溶片100mg，每日1次，早餐前口服，长期服用（限缺血性卒中且无消化性溃疡、出血倾向等禁忌证者，用于二级预防）。\n3. 调脂及合并症处理：阿托伐他汀钙片20mg，每晚1次口服，长期服用；合并高血压者加用苯磺酸氨氯地平片5mg，每日1次口服，血压目标<140/90mmHg；合并糖尿病者按内科规范降糖，空腹血糖目标<7.0mmol/L。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性期卧床休息为主，避免剧烈活动、劳累及跌仆；病情稳定后尽早开始循序渐进的功能锻炼，每日行瘫痪肢体被动或主动运动及言语训练，防止肌肉萎缩与关节僵硬。\n2. 饮食调护：低盐低脂清淡饮食，每日食盐<6g，戒烟限酒，多食新鲜蔬菜水果及富含膳食纤维之品，忌肥甘厚腻、生冷及辛辣刺激食物；保持大便通畅，避免用力排便。\n3. 情志与起居：保持情绪稳定，避免恼怒、急躁、忧思等情志刺激，注意劳逸结合；防寒保暖，避免外感；每日监测血压，注意跌倒防护。\n\n【随诊要求】\n服药2周后复诊，评估言语謇涩、口舌歪斜、肢体麻木无力等症状改善情况，据证调整方药；定期（每1～3个月）复查血压、血脂、血糖，必要时复查头颅CT/MRI及颈动脉超声；若出现肢体麻木无力进行性加重、言语不清、口角歪斜、视物模糊或意识障碍等新发症状，应立即至急诊就诊，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1212,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5ca08b7d38394ab77b544966aa77df4395ba9f9ece58178e44e21e1bdab74ddd","pinyin":"zhongfeng（fengtanruluo）","initials":"zf（ftrl）","setting":"out","caseName":"病例1：风痰入络中风","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：风痰入络中风",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b6aa1e2b073340de85cf","key":"v1-c9ccc21dfe2a3058|templates-b6aa1e2b073340de85cf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水肿（湿毒浸淫）","category":"门诊病历模板","raw":{"name":"水肿（湿毒浸淫）","category":"门诊病历模板","case":{"case_name":"病例1：湿毒浸淫水肿","templates":{"主诉":"眼睑浮肿、延及全身1周","现病史":"患者1周前身发疮痍，甚则溃烂，随后出现眼睑浮肿，延及全身，皮肤光亮，尿少色赤，伴恶风发热，疮痍未愈、水肿逐渐加重。未曾系统诊治。今日来诊。发病以来精神欠佳，纳食减少，夜寐欠安，小便短少色赤，大便尚调。舌质红，苔薄黄，脉浮数或滑数。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.8℃，P 88次/分，R 20次/分，BP 130/85mmHg。眼睑及双下肢水肿，皮肤可见疮痍。心肺查体未见明显异常。","辅助检查":"检查计划：患者1周前身发疮痍、甚则溃烂，随后出现眼睑浮肿并延及全身，皮肤光亮，尿少色赤，伴恶风发热，疮痍未愈而水肿逐渐加重，临床高度疑及疮毒内归脾肺、湿毒浸淫所致水肿，需重点评估肾小球损伤程度。完善血常规检查以排除感染、贫血，并了解白细胞及中性粒细胞水平；查尿常规以明确有无蛋白尿、血尿及管型，了解肾脏受累情况；便常规作为入院常规筛查，了解消化道有无潜血及寄生虫感染；完善肝肾功能检查以评估肾小球滤过功能并排除肝功能不全所致低蛋白性水肿，同时为用药提供依据；查血糖、血脂以排除糖尿病肾病及脂代谢异常相关肾损害；查电解质以了解有无低钠、低钾及高钾血症，避免水肿治疗中出现电解质紊乱；因有疮痍溃烂、恶风发热，查CRP及降钙素原以明确有无细菌感染活动，指导抗感染治疗；查抗链球菌溶血素O及补体C3以明确有无急性链球菌感染后肾小球肾炎；完善24小时尿蛋白定量以评估蛋白尿程度及病情轻重；查心电图以了解有无心肌损害及电解质紊乱的心电表现；胸部X线片以排除肺部感染及胸腔积液；腹部超声以了解双肾大小、形态、皮髓质回声及有无腹水，排除梗阻性因素；皮肤疮痍必要时行分泌物培养加药敏以明确致病菌、指导抗感染用药。；根据病情需要选择相应检查，中医四诊合参、辨证论治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 水肿（湿毒浸淫）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 中药汤剂（首选）：麻黄连翘赤小豆汤合五味消毒饮加减，药物组成：麻黄6g、连翘12g、赤小豆30g、金银花15g、野菊花12g、蒲公英15g、紫花地丁15g、桑白皮12g、车前子15g（包煎）、泽泻12g、茯苓皮15g、生甘草6g、生姜3片，日1剂，水煎取汁400ml，分早晚2次温服，7天为1疗程，疗程结束后复诊调方。\n2. 中成药：黄葵胶囊（0.5g/粒）5粒 tid po，8周为1疗程，功在清热解毒、利湿消肿，可与汤剂同用。\n3. 外用药：皮肤疮疡红肿处予如意金黄散适量以清茶调敷，每日1次；疮疡破溃或继发细菌感染者，予莫匹罗星软膏涂患处 bid，连用5～7天。\n4. 对症利尿（水肿明显者）：呋塞米片20mg qd晨服，连用3～5天后停用，用药期间监测血电解质及24小时尿量。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，抬高双下肢以利消肿，避免久站久坐及劳累；水肿消退后循序渐进恢复日常活动。\n2. 饮食：低盐饮食（每日食盐＜5g），限制水液摄入，适量优质蛋白；忌食辛辣刺激、肥甘厚腻及鱼虾海鲜等发物，以免助湿生热、加重病势。\n3. 皮肤护理：保持皮肤清洁干燥，疮疡处勿搔抓、勿挤压，防止毒邪扩散；勤剪指甲，穿宽松棉质衣物。\n4. 禁忌：戒烟酒，避风寒、防感冒，避免外邪复感诱发水肿反复。\n\n【随诊要求】\n1. 服药1周后门诊复诊，评估水肿消退、尿量及皮肤疮疡情况，根据患者具体情况制定个体化方案调整处方。\n2. 若治疗3～5天水肿无消退甚至加重、24小时尿量明显减少（＜400ml）、出现胸闷气喘、心悸或发热不退者，应及时复诊或急诊就医。\n3. 复诊时复查尿常规、肾功能（血肌酐、尿素氮），必要时查24小时尿蛋白定量；遵医嘱用药，勿自行加用利尿剂或抗生素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1213,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1f5367260797de177a44c38528399dce6a33a7741d222b604c774eec615f83ec","pinyin":"shuizhong（shidujinyin）","initials":"sz（sdjy）","setting":"out","caseName":"病例1：湿毒浸淫水肿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿毒浸淫水肿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6bbeee80a40ffdf2073a","key":"v1-c9ccc21dfe2a3058|templates-6bbeee80a40ffdf2073a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水肿（水湿浸渍）","category":"门诊病历模板","raw":{"name":"水肿（水湿浸渍）","category":"门诊病历模板","case":{"case_name":"病例1：水湿浸渍水肿","templates":{"主诉":"全身水肿、下肢明显1月","现病史":"患者1个月前无明显诱因出现全身水肿，以下肢为甚，按之没指，小便短少，身体困重，胸闷，纳呆，泛恶，起病缓慢，病程较长，水肿晨轻暮重，劳累后加重。未曾系统诊治。今日来诊。发病以来身体困重，纳食减少，夜寐尚可，小便短少，大便尚调。苔白腻，脉沉缓。","既往史":"既往有慢性肾炎病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 78次/分，R 18次/分，BP 140/90mmHg。双下肢中度凹陷性水肿。心肺查体未见明显异常。","辅助检查":"检查计划：患者既往有慢性肾炎病史，1个月前无明显诱因出现全身水肿且以下肢为甚，按之没指，小便短少，身体困重，胸闷纳呆泛恶，晨轻暮重、劳累后加重，病程较长，提示水湿浸渍、脾失健运，同时须警惕慢性肾脏病进展。完善血常规检查以排除感染、贫血，了解有无肾性贫血；查尿常规以明确有无蛋白尿、血尿，判断水肿是否源于肾性因素；便常规作为入院常规筛查，了解消化道情况；完善肝肾功能检查以评估肾脏滤过功能，明确有无肾功能不全，并排除肝源性水肿，为利尿及中药治疗提供用药依据；查血糖、血脂以排除糖尿病肾病、脂代谢异常相关肾损害；查电解质以了解有无低钠、低钾血症，防止利尿治疗后电解质紊乱；查24小时尿蛋白定量及尿蛋白电泳以评估蛋白尿程度、明确肾损伤性质；查血浆白蛋白以排除低蛋白血症所致水肿；完善心电图检查以了解有无心肌缺血、心律失常及电解质紊乱表现；胸部X线片以排除肺部感染、胸腔积液；腹部超声以了解双肾大小形态、皮髓质回声及有无腹水、肝脾大小，排除肝硬化等病因；查心脏彩超加左心功能测定以排除心源性水肿、了解射血分数；患者下肢水肿明显、活动减少，病情稳定后完善双下肢静脉彩超以排除下肢深静脉血栓形成。；根据病情需要选择相应检查，中医四诊合参、辨证论治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 水肿（水湿浸渍）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.中药汤剂（辨证施治，健脾化湿、通阳利水）：五皮饮合胃苓汤加减：茯苓皮15g、大腹皮15g、生姜皮10g、陈皮10g、桑白皮15g、白术15g、苍术10g、桂枝10g、猪苓15g、泽泻15g、厚朴10g、甘草6g，水煎服，日1剂，分早晚2次温服，疗程7～14天，视水肿消退情况随症加减。\n2.利尿消肿：螺内酯片20mg tid，口服，疗程7天；水肿明显者加氢氯噻嗪片25mg qd，晨服，口服，疗程3～5天（两药联用可减少低钾风险），用药期间监测血电解质及肾功能。\n3.辅助健脾化湿：参苓白术颗粒6g bid，口服，疗程14天，配合饮食调理巩固疗效。\n【一般治疗及生活指导】\n1.休息与体位：急性期或水肿较重者卧床休息，抬高双下肢（高于心脏水平），减少久站久坐，避免劳累和剧烈活动。\n2.饮食调护：严格低盐饮食（每日食盐<3g），控制每日饮水量（约为前一日尿量+500ml），忌生冷、油腻、甜腻及海鲜发物，适量进食薏苡仁、赤小豆、冬瓜等健脾利湿之品。\n3.起居禁忌：注意保暖，避免感受寒湿，忌烟酒及浓茶、咖啡，避免情绪波动和忧思伤脾。\n4.日常监测：每日晨起固定时间称体重、记录尿量，观察下肢、眼睑及腰骶部水肿变化。\n【随诊要求】\n1.服药后3～5天复诊，评估水肿消退程度、体重及尿量变化，调整利尿药剂量，防止过度利尿致脱水或电解质紊乱。\n2.每周复查尿常规、血电解质（重点血钾）及肝肾功能，根据患者具体情况制定个体化方案复查24小时尿蛋白定量。\n3.若出现尿量骤减（每日<400ml）、水肿加重、胸闷气促、心慌或腹胀纳差加重，需立即就诊，排查心肾并发症。\n4.水肿基本消退后继续巩固治疗1～2周，门诊随访至症状消失、尿常规及肾功能恢复正常为止。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1214,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bffaae672762f5100d2771bc89ba9c35810b507e51a0dae00daa5ae518617f2c","pinyin":"shuizhong（shuishijinzi）","initials":"sz（ssjz）","setting":"out","caseName":"病例1：水湿浸渍水肿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：水湿浸渍水肿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fee2aa3fbf5a9706fa81","key":"v1-c9ccc21dfe2a3058|templates-fee2aa3fbf5a9706fa81","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋证（石淋）","category":"门诊病历模板","raw":{"name":"淋证（石淋）","category":"门诊病历模板","case":{"case_name":"病例1：石淋","templates":{"主诉":"尿中夹砂石、排尿涩痛1周","现病史":"患者1周来尿中夹砂石，排尿涩痛，或排尿时突然中断，尿道窘迫疼痛，少腹拘急，往往突发，一侧腰腹绞痛难忍，甚则牵及外阴，尿中带血，舌红，苔薄黄，脉弦或带数。","既往史":"既往有肾结石病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 120/80mmHg。腹平软，无压痛，双肾区叩击痛阳性。","辅助检查":"检查计划：患者既往有肾结石病史，1周来尿中夹砂石、排尿涩痛，排尿时突然中断，尿道窘迫疼痛，一侧腰腹绞痛难忍并牵及外阴，尿中带血，符合石淋、湿热蕴结下焦之候，需尽快明确结石部位、大小及有无梗阻性肾损害。完善血常规检查以排除感染、贫血，了解有无继发尿路感染；查尿常规以明确血尿、脓尿及有无结晶，判断有无尿路感染及结石活动；便常规作为入院常规筛查；完善肝功能检查以了解肝脏合成与代谢功能情况；完善肾功能检查以评估结石梗阻是否已造成肾功能损害，为治疗方案选择提供依据；完善泌尿系超声以明确结石部位、大小、有无肾积水；查腹部泌尿系平片（KUB）以了解结石的X线阳性情况及大致形态；必要时完善CT尿路成像以精准定位结石、评估输尿管梗阻程度及有无解剖变异，为体外碎石或输尿管镜取石提供依据；因排尿涩痛伴尿中带血，查中段尿培养加药物敏感试验以明确病原菌、指导抗感染用药；查凝血功能以评估出血风险，为侵入性操作做准备；完善电解质及血尿酸检查以了解有无高尿酸血症等结石形成诱因，指导饮食与预防复发方案。；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。；根据病情需要选择相应影像学检查；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 淋证（石淋）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1215,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"002e1a80a4a5194fac0ad1620dfc8f53b394a01cace0484e9377c88610857f4b","pinyin":"linzheng（shilin）","initials":"lz（sl）","setting":"out","caseName":"病例1：石淋","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：石淋",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a9eb0568a779b651c71a","key":"v1-c9ccc21dfe2a3058|templates-a9eb0568a779b651c71a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋证（气淋）","category":"门诊病历模板","raw":{"name":"淋证（气淋）","category":"门诊病历模板","case":{"case_name":"病例1：气淋","templates":{"主诉":"郁怒之后小便涩滞1周","现病史":"患者近期出现郁怒之后小便涩滞1周，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/80mmHg。腹平软，下腹部轻度压痛，无反跳痛。","辅助检查":"检查计划：患者郁怒之后出现小便涩滞1周，余沥不尽，少腹胀满，情志不遂为诱发因素，符合气淋、肝郁气滞、膀胱气化不利之候，但须先排除器质性梗阻及感染因素。完善血常规检查以排除感染、贫血，了解有无白细胞升高；查尿常规以明确有无白细胞、红细胞及蛋白，判断是否存在尿路感染或血尿；便常规作为入院常规筛查；完善肝肾功能检查以评估肝郁日久对肝功能的影响及肾脏排泄功能，并为用药提供依据；查泌尿系超声以了解膀胱残余尿量、前列腺大小、有无结石及占位，排除前列腺增生、膀胱颈梗阻所致排尿不畅；查尿流率及残余尿测定以评估膀胱排尿功能，明确有无功能性排尿障碍；因患者中老年男性居多，查前列腺特异性抗原以排除前列腺癌；查血糖以排除糖尿病所致神经源性膀胱排尿障碍；必要时完善尿动力学检查以鉴别膀胱逼尿肌无力与尿道梗阻；查心电图以了解心脏基础情况，为必要时用药及麻醉评估提供依据。；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。；根据病情需要选择相应影像学检查；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 淋证（气淋）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1216,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4763d2a391f2cd0e814146c752636101d3eb72fd8ea0d954e53a273479b1e038","pinyin":"linzheng（qilin）","initials":"lz（ql）","setting":"out","caseName":"病例1：气淋","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：气淋",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d529ac87f8c919ca4101","key":"v1-c9ccc21dfe2a3058|templates-d529ac87f8c919ca4101","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋证（血淋）","category":"门诊病历模板","raw":{"name":"淋证（血淋）","category":"门诊病历模板","case":{"case_name":"病例1：血淋","templates":{"主诉":"小便热涩刺痛、尿色深红1周","现病史":"患者近期出现小便热涩刺痛、尿色深红1周，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史。生活规律，无特殊不良嗜好。否认食物药物过敏史。","体格检查":"T 37.2℃，P 82次/分，R 18次/分，BP 120/80mmHg。腹平软，无压痛，双肾区无叩击痛。","辅助检查":"检查计划：患者小便热涩刺痛、尿色深红1周，为热伤血络、迫血妄行之血淋表现，须重点鉴别泌尿系感染、结石、结核及肿瘤所致血尿。完善血常规检查以排除感染、贫血，了解有无白细胞及血小板异常；查尿常规加尿沉渣镜检以明确红细胞形态，判断血尿来源为肾小球性还是非肾小球性；便常规作为入院常规筛查；完善肝肾功能检查以评估肾脏功能状态并排除凝血机制异常相关的肝肾疾病，为用药提供依据；查泌尿系超声以了解双肾、输尿管、膀胱有无结石、占位及膀胱壁增厚；查凝血功能以排除凝血功能障碍所致血尿；查中段尿培养加药物敏感试验以明确病原菌、指导抗感染治疗；必要时完善CT尿路成像以进一步明确有无泌尿系肿瘤、结石及结核性改变；如血尿持续不缓解，病情稳定后完善膀胱镜检查以直视膀胱黏膜病变，排除膀胱肿瘤；对女性患者必要时行妇科彩超以排除生殖道出血污染尿标本；定期复查尿常规以观察血尿动态变化、评估疗效。；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。；根据病情需要选择相应影像学检查；中医四诊合参、辨证论治，四诊资料结合上述检查综合判断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能\n\n【影像学检查】\n根据病情需要选择相应影像学检查\n\n【其他检查】\n中医四诊合参，辨证论治","初步诊断":"1. 淋证（血淋）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n根据辨证论治，选用相应中药方剂，具体用药根据证型决定。\n\n【一般治疗及生活指导】\n注意休息，避免劳累，调畅情志，饮食有节，起居有常，适当锻炼。\n\n【随诊要求】\n遵医嘱服药，1周后复诊调整方药，如症状加重及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1217,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cee213e810dcc56c5816e77a61b72b4d47b57ccd29e8ee9b0fb0621436135a2a","pinyin":"linzheng（xuelin）","initials":"lz（xl）","setting":"out","caseName":"病例1：血淋","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：血淋",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a3d61701e5993ab4486f","key":"v1-c9ccc21dfe2a3058|templates-a3d61701e5993ab4486f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"癃闭（膀胱湿热）","category":"门诊病历模板","raw":{"name":"癃闭（膀胱湿热）","category":"门诊病历模板","case":{"case_name":"病例1：膀胱湿热癃闭","templates":{"主诉":"小便点滴不通、短赤灼热1天","现病史":"患者1天前无明显诱因出现小便点滴不通，或量极少而短赤灼热，小腹胀满，伴口苦口黏，或口渴不欲饮，或大便不畅，无发热，无恶心呕吐。发病后未行特殊处理，今日来诊。发病以来精神欠佳，因排尿困难烦躁不安，纳食减少，夜寐欠安，大便不畅。舌质红，苔黄腻，脉数。","既往史":"既往有前列腺增生病史，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.3℃，P 84次/分，R 18次/分，BP 130/85mmHg。腹平软，下腹部膨隆，压痛，膀胱区叩诊浊音。","辅助检查":"检查计划：患者既往有前列腺增生病史，1天前突发小便点滴不通、量极少而短赤灼热，小腹胀满，口苦口黏，大便不畅，为膀胱湿热、气化不利之癃闭，须急诊评估有无急性尿潴留及梗阻性肾功能损害。即刻查尿常规以明确有无白细胞、红细胞及脓细胞，判断有无尿路感染；完善尿培养加药物敏感试验以明确致病菌、指导抗感染用药；查肾功能加电解质以评估梗阻是否已致肾后性肾功能损害及有无高钾血症，电解质紊乱需及时纠正；查前列腺特异性抗原以筛查前列腺癌，注意急性尿潴留及尿路感染可致其升高，需在感染控制后复查；完善泌尿系超声以了解双肾有无积水、膀胱残余尿量及前列腺大小形态，明确梗阻部位；查腹部泌尿系平片（KUB平片）以排除泌尿系结石；必要时完善CT尿路成像以进一步明确有无结石、肿瘤及上尿路梗阻；查尿流率及残余尿测定以评估膀胱逼尿肌功能；查前列腺液常规以明确有无前列腺炎；查血常规以排除感染、贫血；必要时完善尿流动力学、膀胱镜检查以鉴别神经源性膀胱及膀胱颈梗阻。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 癃闭（膀胱湿热）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 清热利湿、通利小便（主方）：八正散加减，药物组成：车前子15g、萹蓄15g、瞿麦15g、滑石20g（包煎）、通草6g、栀子10g、大黄6g（后下）、甘草梢6g，水煎服，日1剂，分早晚2次温服，7天为1疗程。\n2. 中成药（可选）：三金片，每次3片，每日3次，口服，连服7天；或热淋清颗粒，每次8g，每日3次，连服7天。\n3. 合并泌尿道感染（尿常规见白细胞或脓细胞）者加用抗菌药物：左氧氟沙星片0.5g qd×5～7天，或头孢克肟胶囊0.1g bid×5～7天（用药前须询问过敏史，头孢类注意青霉素交叉过敏）。\n4. 排尿困难、尿潴留明显者（男性尤合并前列腺增生时）：坦索罗辛缓释胶囊0.4mg，每晚1次，口服，连用7天，以松弛尿道平滑肌、改善排尿。\n\n【一般治疗及生活指导】\n1. 急性期注意休息，避免劳累、久坐及受凉；膀胱明显充盈者先予下腹热敷、温水坐浴促进排尿，无效时行无菌导尿，首次放尿量不宜超过500ml。\n2. 多饮水，每日2000～2500ml，勤排尿、勿憋尿，以利湿热从小便排出。\n3. 饮食宜清淡，多食冬瓜、赤小豆、薏苡仁、西瓜等利湿之品；忌辛辣、煎炸、肥甘厚味及烟酒。\n4. 注意会阴部清洁卫生，勤换内裤，治疗期间避免性生活。\n\n【随诊要求】\n1. 治疗3天后复诊，评估排尿及尿痛等症状改善情况并监测体温，症状无缓解或加重者随时复诊。\n2. 疗程结束后复查尿常规，合并尿路感染者须复查尿培养以确认转阴。\n3. 反复发作或迁延不愈者，建议转泌尿外科进一步行泌尿系B超、残余尿测定、尿流率等检查，排除结石、前列腺增生等下尿路梗阻因素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1218,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d7651b5c73153a95ae3320ed12f730fc3909da2f12eb26949a52a02291c64158","pinyin":"longbi（pangguangshire）","initials":"lb（pgsr）","setting":"out","caseName":"病例1：膀胱湿热癃闭","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：膀胱湿热癃闭",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2a0ee2a5ef47eabeaf1d","key":"v1-c9ccc21dfe2a3058|templates-2a0ee2a5ef47eabeaf1d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阳痿（命门火衰）","category":"门诊病历模板","raw":{"name":"阳痿（命门火衰）","category":"门诊病历模板","case":{"case_name":"病例1：命门火衰阳痿","templates":{"主诉":"阳事不举、举而不坚2月","现病史":"患者2月来阳事不举，或举而不坚，精薄清冷，神疲倦怠，畏寒肢冷，面色㿠白，头晕耳鸣，腰膝酸软，夜尿清长，舌淡胖，苔薄白，脉沉细。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.4℃，P 72次/分，R 18次/分，BP 115/75mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者2月来阳事不举、举而不坚，精薄清冷，神疲倦怠，畏寒肢冷，头晕耳鸣，腰膝酸软，夜尿清长，舌淡胖、脉沉细，属命门火衰、肾阳不足之候，但须先排除糖尿病、血脂异常、甲状腺功能异常及性腺功能减退等器质性病因。完善血常规检查以排除贫血、感染等全身性疾病所致疲乏及性功能减退；尿常规、便常规作为入院常规筛查，了解泌尿系及消化道基础病变；完善肝肾功能检查以排除肝肾功能不全，肝肾功能异常可影响性激素代谢并限制用药；查血糖及糖化血红蛋白以排除糖尿病所致血管神经性勃起功能障碍；查血脂以了解有无脂代谢异常及动脉粥样硬化，评估血管性阳痿风险；查电解质以排除电解质紊乱所致乏力；完善性激素测定（睾酮、促卵泡激素、促黄体生成素、泌乳素）以明确有无性腺功能减退及高泌乳素血症，鉴别内分泌性阳痿；查甲状腺功能以排除甲状腺功能减退所致性欲减退；完善心电图、胸部X线片以了解心肺基础情况，为必要时的血管活性药物治疗提供安全依据；腹部超声以了解腹部脏器及有无肾上腺病变；必要时完善阴茎海绵体彩色多普勒超声及夜间阴茎勃起试验以明确血管性阳痿，必要时查下丘脑-垂体MRI以排除垂体病变。；根据病情需要选择相应检查，中医四诊合参、辨证论治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 阳痿（命门火衰）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 温肾壮阳、填精止遗类中成药：右归丸（水蜜丸）每次9g，每日2次，口服，4周为1疗程，连用2个疗程。\n2. 温补肾阳类中成药：金匮肾气丸（水蜜丸）每次6g，每日2次，口服，4周为1疗程；适用于畏寒肢冷、腰膝酸软、小便清长明显者。\n3. 温肾壮阳汤剂（右归丸加减）：熟地黄24g、山药12g、山茱萸9g、枸杞子9g、菟丝子12g、杜仲12g、鹿角胶9g（烊化）、肉桂3g（后下）、制附子6g（先煎30分钟）、当归9g，日1剂，水煎取汁400ml，早晚各200ml温服，连服14剂后复诊调方。\n4. 若查总睾酮明显低于正常值，可联用十一酸睾酮软胶囊40mg，每日2次，餐后口服，疗程3个月；用药前及用药期间每3个月监测血清PSA、肝肾功能及血常规。\n\n【一般治疗及生活指导】\n1. 起居情志：保证每晚7-8小时睡眠，避免熬夜、过度劳累及久坐；调畅情志，与伴侣充分沟通，消除紧张焦虑，必要时配合心理疏导。\n2. 饮食：忌食生冷寒凉及辛辣油腻食物，戒烟限酒、少饮浓茶；宜食羊肉、韭菜、核桃、山药、板栗、海参等温补脾肾之品，可佐生姜、肉桂调味。\n3. 运动：坚持每日有氧运动（快走、慢跑、游泳等）30-45分钟，每周5次以上；每日行提肛运动（凯格尔训练）3组，每组10-15次，以增强盆底肌及勃起功能。\n4. 禁忌：节制房事，治疗期间适度休养、避免纵欲；禁用含不明成分的\"壮阳保健品\"及自行加用西地那非等药物；基础疾病（糖尿病、高血压等）应积极控制。\n\n【随诊要求】\n服药2周后复诊，评估症状、舌脉变化并调整汤剂；此后每4周复诊1次，连用2-3个疗程（8-12周）后评估疗效并复查相关指标；若连续治疗3个月无效，或出现心悸、血压升高、失眠、头晕等不适，应及时复诊或转诊；合并糖尿病、高血压、动脉粥样硬化等基础病者应同步控制原发病并定期随诊；症状缓解后每1-3个月随访1次以巩固疗效、预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1219,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"84f345e63b6a828bf2dab32657715589c1ef4374f7762a45c78483f01eea7d5b","pinyin":"yangwei（mingmenhuoshuai）","initials":"yw（mmhs）","setting":"out","caseName":"病例1：命门火衰阳痿","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：命门火衰阳痿",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-30484b39d9a462ee91fe","key":"v1-c9ccc21dfe2a3058|templates-30484b39d9a462ee91fe","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"遗精（湿热下注）","category":"门诊病历模板","raw":{"name":"遗精（湿热下注）","category":"门诊病历模板","case":{"case_name":"病例1：湿热下注遗精","templates":{"主诉":"遗精时作、小便黄赤1月","现病史":"患者近期出现遗精时作、小便黄赤1月，症状逐渐出现/反复发作，无明显诱因/有诱因（如劳累、受凉、饮食不当等）。伴/不伴相关伴随症状，发病以来精神、饮食、睡眠可/欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 80次/分，R 18次/分，BP 120/80mmHg。心肺腹查体未见明显异常。","辅助检查":"检查计划：患者遗精时作、小便黄赤1月，湿热下注之候需先辨明有无泌尿生殖道感染及他脏病变，故门诊首诊即完善尿常规检查了解有无白细胞、脓细胞及蛋白，排除尿路感染、前列腺炎所致小便黄赤；完善血常规检查排除感染、贫血等全身性因素；查便常规排除肠道寄生虫及慢性消化系统疾病对体质的耗损；患者需长期服用清热利湿中药，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，为用药安全提供依据；查血糖了解有无糖尿病，糖尿病自主神经病变可致遗精、乏力，需予鉴别；查血脂了解脂代谢水平，评估有无代谢综合征基础；完善电解质检查排除低钾、低钠等电解质紊乱引起的自主神经功能失调；查心电图排除心律失常等心脏疾患所致的全身虚弱状态；完善胸部X线片检查排除肺结核等慢性消耗性疾病，结核中毒症状常伴夜间遗精、盗汗；完善腹部超声检查了解前列腺、精囊及泌尿系有无结石、积液等器质性病变；必要时进一步行前列腺液检查及泌尿外科会诊，以明确有无慢性前列腺炎。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 遗精（湿热下注）\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 清热利湿类：程氏萆薢分清饮加减（萆薢15g、黄柏10g、石菖蒲10g、茯苓15g、白术10g、莲子心6g、丹参15g、车前子15g包煎、泽泻10g、生甘草6g），水煎服，日1剂，分早晚两次温服，疗程2周。\n2. 清热利湿中成药：龙胆泻肝丸（水丸）6g po bid，或二妙丸6g po bid，疗程2周，与汤剂交替或序贯服用。\n3. 固精止遗类：金锁固精丸（水蜜丸）6g po bid，疗程2周，配合上述清热利湿药同服，标本兼治。\n4. 若尿常规提示合并泌尿系感染（尿频、尿急、尿道灼热）：左氧氟沙星片0.5g po qd×5天（无喹诺酮过敏史者），并嘱多饮水。\n【一般治疗及生活指导】\n1. 饮食忌辛辣炙煿、肥甘厚味及醇酒浓茶，多饮水（每日1500～2000ml），多食冬瓜、赤小豆、薏苡仁、山药等健脾利湿之品。\n2. 保持外阴清洁干燥，每日温水清洗，勤换宽松棉质内裤，避免久坐及骑行，每坐1小时起身活动，减少会阴部湿热蕴结。\n3. 规律作息，忌熬夜、过度劳累及酗酒；睡前不宜过饱、过劳，可温水浴足，避免盖过厚被褥及穿紧身裤，减少局部刺激。\n4. 节制房事，避免忍精不泄及手淫过度；避免接触色情影视书籍，转移注意力，保持心情舒畅，适当练习八段锦、太极拳等舒缓运动。\n【随诊要求】\n1. 服药2周后复诊，评估遗精频次及尿黄、口苦、阴囊潮湿、小便灼热等伴随症状改善情况，据舌脉变化调整方药。\n2. 治疗期间如出现发热、尿频尿急尿痛加重或血精，应及时复诊，必要时行尿常规、前列腺液检查，排除慢性前列腺炎等器质性病变。\n3. 症状缓解后仍需巩固1～2周并复诊1次，确认湿热之象消退、遗精控制后再停药，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1220,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d5856ca0e02b5d5eb9209d7c878006bc2d4ded2f1ad441bdd1147a9d940230a8","pinyin":"yijing（shirexiazhu）","initials":"yj（srxz）","setting":"out","caseName":"病例1：湿热下注遗精","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：湿热下注遗精",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3db17d19268b0511e42b","key":"v1-c9ccc21dfe2a3058|templates-3db17d19268b0511e42b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咳嗽（痰热郁肺）","category":"中医科","raw":{"name":"咳嗽（痰热郁肺）","category":"中医科","case":{"case_name":"病例1：患者，男，59岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：59岁 民族：汉族\n婚姻：已婚 职业：退休 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：咳嗽、咯痰黄稠伴咽痛1周。\n\n现病史：患者于1周前无明显诱因起病，起病较急，咳嗽呈进行性加重。主要表现为：咳嗽，咯痰黄稠，量较多，咯吐不爽，咽痛，口干口苦，鼻息气热，咳嗽夜间及晨起为甚，活动后加重，安静休息后可部分缓解，无痰中带血。病程中上述症状反复发作，时轻时重，劳累后明显加重，安静休息后可部分缓解，总体呈逐渐加重趋势。伴乏力，纳差，二便调。发病以来无咯血、无胸痛、无呼吸困难、无下肢水肿、无盗汗、无体重下降。无盗汗、消瘦，无下肢水肿、端坐呼吸，无大量脓臭痰，无恶寒发热，无声音嘶哑。自行服用中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「咳嗽（痰热郁肺）」收入我科。发病以来精神欠佳，饮食睡眠尚可，大小便正常，体重无明显变化。\n\n既往史：既往有高血压病史，规律服药控制可。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。\n\n个人史及家族史：生于本地，久居本地。无吸烟史。家族中否认类似疾病史。\n婚育史：34岁结婚，配偶体健，育有1子\n体格检查：\nT 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg。\n一般情况：神志清楚，精神可，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色少华，舌质红，苔黄腻。\n闻诊：语声清晰，无异常气味。\n问诊：咳嗽（痰热郁肺）相关症状，纳差，二便调。\n切诊：脉滑数。\n一般情况：神志清楚，精神反应可，营养发育正常，查体欠合作（哭闹）。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：面色红润或潮红，咽部充血，扁桃体不肿大，目赤；闻诊：语声重浊，咳嗽声粗有力，痰黄稠量多；舌象：舌红，苔黄腻；脉象：脉滑数。专科查体：双肺呼吸音粗，可闻及散在湿啰音及痰鸣音，未闻及干啰音及胸膜摩擦音；气管居中，胸廓对称，语颤对称，双肺叩诊清音。关键阴性体征：无发热或低热，无呼吸困难、发绀，无桶状胸，心律齐。\n辅助检查：\n门诊血常规：WBC 6.5×10^9/L，N% 65%，Hb 130g/L，PLT 200×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：咳嗽（痰热郁肺）\n中医诊断依据：\n1.辨病依据：患者以咳嗽、咯痰为主症，病程1周，起病较急，属中医「咳嗽」范畴。肺主气、司呼吸，外合皮毛，外邪犯肺或脏腑功能失调致肺失宣肃、肺气上逆，则发为咳嗽。《素问·咳论》谓「五脏六腑皆令人咳，非独肺也」，本案以肺脏受病为主，无他脏传变之征；咳嗽、咯痰、咽痛并见，病程短而病势急，属外感咳嗽。\n2.辨证依据：咳嗽气粗，咯痰黄稠量多、咯吐不爽，咽痛，口干口苦，鼻息气热，咳嗽以夜间及晨起为甚；舌质红、苔黄腻，脉滑数。痰热壅阻肺气、肺失清肃，故咳而气粗、痰黄黏稠难咯；热灼津液、上蒸咽喉，故咽痛、口干口苦、鼻息气热；舌红苔黄腻、脉滑数均为痰热内蕴之象。四诊合参，辨证为痰热郁肺证，治以清热肃肺、豁痰止咳，方用清金化痰汤加减。\n中医鉴别诊断：\n1.与「哮病」鉴别：哮病以发作性喉中哮鸣有声、呼吸急促、甚则张口抬肩不能平卧为特征，多有宿根、反复发作，发作时双肺可闻弥漫性哮鸣音、呼气相延长，支气管舒张试验阳性。本案以咳嗽咯痰黄稠为主，无喉中哮鸣及呼吸困难，双肺未闻及哮鸣音，故可鉴别。\n2.与「喘证」鉴别：喘证以呼吸困难、气短不足以息、张口抬肩、鼻翼扇动、不能平卧为主症，甚则唇甲紫绀；咳嗽虽可因咳剧而气促，但以咳声、咳痰为主症，咳止则气息平和。本案无呼吸困难、无端坐呼吸，故不属喘证。\n3.与「肺痈」鉴别：肺痈以咳吐大量腥臭脓血痰、壮热、胸痛剧烈为特征，系热毒壅肺、血败肉腐成脓，影像可见厚壁空洞及液平。本案痰虽黄稠量多，但无腥臭味、无脓血、无高热及剧烈胸痛，故可鉴别。\n4.与「肺痨」鉴别：肺痨以咳嗽、咯血、午后潮热、盗汗、消瘦为主症，病程长、具传染性，痰找抗酸杆菌阳性、胸部影像见上叶尖后段或下叶背段结核病灶。本案病程仅1周，无潮热盗汗、消瘦及咯血，故可鉴别。\n西医诊断：急性支气管炎 / 肺炎\n西医诊断依据：\n1.症状依据：59岁男性，急性起病，咳嗽、咯痰黄稠量多、咯吐不爽1周，伴咽痛、口干口苦，咳嗽以夜间及晨起为甚，无咯血、胸痛及呼吸困难。\n2.体征依据：T 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg；咽部充血，扁桃体无肿大，双肺呼吸音粗，可闻及散在湿啰音及痰鸣音，未闻及干啰音及胸膜摩擦音。\n3.实验室依据：门诊血常规WBC 6.5×10^9/L、N% 65%、Hb 130g/L、PLT 200×10^9/L，肝肾功能及电解质正常；需完善C反应蛋白、降钙素原、痰涂片及痰培养以明确病原学。\n4.影像学依据：门诊胸部X线示肺纹理增粗紊乱（建议查胸部CT明确有无斑片状浸润影）；心电图示窦性心律、正常心电图，可除外心源性疾病所致咳嗽。\n西医分型/分级/分期：急性支气管炎（急性期，普通型，无发热、无呼吸困难，属轻症）；病情严重程度评估CURB-65评分0分，属低危。若胸部CT见新发斑片状浸润影，则诊断为社区获得性肺炎（CAP），按CURB-65 0分归为门诊治疗组（轻症），PSI分级Ⅰ～Ⅱ级。\n诊疗计划：\n1.按内科Ⅱ级护理，清淡易消化饮食，多饮水，忌辛辣油腻；2.完善检查：血常规+C反应蛋白（目的：判断细菌或病毒感染可能，为是否使用抗菌药物提供依据）、痰涂片及痰培养（目的：明确病原菌及药敏结果，为抗感染方案调整提供依据）、胸部CT或胸部X线（目的：明确肺部感染、支气管扩张或占位等病灶，排除肺结核与肺癌）、肺炎支原体抗体（目的：明确非典型病原体感染，为选择大环内酯类等药物提供依据）、血气分析（目的：咳嗽伴气促或低氧者评估氧合与通气功能，为氧疗及病情分级提供依据）；3.一般治疗：雾化吸入（生理盐水加盐酸氨溴索15mg每日2次）稀释痰液，拍背排痰；4.药物治疗：清热化痰中药汤剂（清金化痰汤加减），肺力咳合剂20ml每日3次口服，有感染指征者予阿莫西林克拉维酸钾0.625g每日3次口服（青霉素过敏者改用左氧氟沙星0.5g每日1次口服）；5.病情观察：观察咳嗽咯痰、发热变化，监测体温、呼吸，注意痰量色泽；6.健康教育：指导戒烟、多饮水、规律作息，随诊复查，必要时请呼吸科会诊。\n\n专科检查：\n望诊：面色红润或潮红，咽部充血，扁桃体不肿大，目赤；闻诊：语声重浊，咳嗽声粗有力，痰黄稠量多；舌象：舌红，苔黄腻；脉象：脉滑数。专科查体：双肺呼吸音粗，可闻及散在湿啰音及痰鸣音，未闻及干啰音及胸膜摩擦音；气管居中，胸廓对称，语颤对称，双肺叩诊清音。关键阴性体征：无发热或低热，无发绀，无桶状胸，心律齐。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，男，59岁，因\"反复咳嗽（痰热郁肺）相关症状加重1周。\"入院。\n2.既往史：既往有高血压病史。\n3.体格检查：生命体征平稳，心肺腹查体未见明显异常。\n4.中医四诊：舌质红，苔黄腻，脉滑数。\n5.辅助检查：血常规、生化、心电图结果如上。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：咳嗽（痰热郁肺）\n西医诊断：急性支气管炎 / 肺炎\n\n（二）中医诊断依据：\n1.辨病依据：患者以咳嗽、咯痰为主症，病程1周，起病较急，属中医「咳嗽」范畴。肺主气司呼吸，外合皮毛，外邪犯肺或脏腑功能失调致肺失宣肃、肺气上逆则咳。《素问·咳论》云「五脏六腑皆令人咳，非独肺也」，本案以肺脏受病为主；咳、痰、咽痛并见而病势急，属外感咳嗽。\n2.辨证依据：咳嗽气粗，咯痰黄稠量多、咯吐不爽，咽痛，口干口苦，鼻息气热，咳嗽以夜间及晨起为甚，伴乏力纳差；舌质红、苔黄腻，脉滑数。痰热壅肺、肺失清肃，故咳而气粗、痰黄黏稠难咯；热灼津液、上蒸咽喉，故咽痛、口干口苦、鼻息气热；舌红苔黄腻、脉滑数为痰热内蕴之征。四诊合参，辨证为痰热郁肺证，治以清热肃肺、豁痰止咳，方用清金化痰汤加减。依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·咳嗽「痰热郁肺」证候。\n\n（三）中医鉴别诊断：\n1.与「哮病」鉴别：哮病以发作性喉中哮鸣有声、呼吸急促、甚则张口抬肩不能平卧为特征，多有宿根、反复发作，发作时双肺弥漫性哮鸣音、呼气相延长，支气管舒张试验阳性；本案以咳嗽咯痰黄稠为主，无喉中哮鸣及呼吸困难，双肺未闻及哮鸣音，故可鉴别。\n2.与「喘证」鉴别：喘证以呼吸困难、气短不足以息、张口抬肩、鼻翼扇动、不能平卧为主症，甚则唇甲紫绀；咳嗽之气促仅为咳剧时暂时表现，咳止则气息平和。本案无呼吸困难及端坐呼吸，故不属喘证。\n3.与「肺痈」鉴别：肺痈以咳吐大量腥臭脓血痰、壮热、胸痛剧烈为特征，为热毒壅肺、血腐成脓，影像可见厚壁空洞及液平；本案痰黄稠量多但无腥臭味、无脓血，无高热及剧烈胸痛，故可鉴别。\n4.与「肺痨」鉴别：肺痨以咳嗽、咯血、午后潮热、盗汗、消瘦为主症，病程长、有传染性，痰抗酸染色阳性、胸部影像见上叶尖后段或下叶背段结核病灶；本案病程短，无潮热盗汗、消瘦及咯血，故可鉴别。\n\n（四）西医诊断依据：\n1.病史依据：59岁男性，急性起病，病程1周，有受凉、劳累等诱因，无慢性呼吸系统疾病史。\n2.症状依据：咳嗽、咯痰黄稠量多、咯吐不爽，咽痛，口干口苦，咳嗽夜间及晨起为甚，无咯血、胸痛及呼吸困难。\n3.体征依据：T 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg；咽部充血，双肺呼吸音粗，可闻及散在湿啰音及痰鸣音，未闻及干啰音及胸膜摩擦音。\n4.辅助检查依据：血常规WBC 6.5×10^9/L、N% 65%基本正常，肝肾功能及电解质正常，心电图正常；需完善C反应蛋白、降钙素原、痰培养及胸部CT以明确病变范围与病原。\n\n（五）西医鉴别诊断：\n1.急性上呼吸道感染：\n【支持点】同为急性起病，病程1周，有受凉、劳累等诱因，可见咳嗽、咽痛、咽部充血，与本例相似。\n【不支持点】急性上呼吸道感染以鼻塞、流涕、咽痛等鼻咽部卡他症状为主，咳嗽轻、痰少，双肺听诊无啰音，全身症状轻、多3～7天自限；本例咳嗽咳痰明显、痰黄稠量多，双肺闻及散在湿啰音及痰鸣音，病变已累及支气管及肺组织。\n【排除方法】依据咳嗽程度、痰量及肺部体征鉴别；完善胸部X线或CT，若无肺实质浸润影且炎性指标正常则支持上呼吸道感染，若见浸润影则支持肺炎。\n2.社区获得性肺炎：\n【支持点】本例急性咳嗽、咳黄稠痰，双肺闻及散在湿啰音，胸部X线示肺纹理增粗，与肺炎表现部分重叠，须重点鉴别。\n【不支持点】社区获得性肺炎多有发热甚至高热、胸痛、气促，肺部体征多局限，影像见片状或斑片状浸润影，血WBC、C反应蛋白及降钙素原多明显升高；本例体温正常、WBC 6.5×10^9/L正常、双肺体征弥散而不局限。\n【排除方法】完善胸部CT（或高分辨率CT）、C反应蛋白、降钙素原及痰培养；若见新发浸润影并伴炎性指标升高即可确诊肺炎，若无浸润影则支持急性支气管炎。\n3.咳嗽变异性哮喘：\n【支持点】以咳嗽为唯一或主要表现，可因冷空气、油烟、粉尘等诱发，与本例以咳嗽为主症相似。\n【不支持点】咳嗽变异性哮喘以夜间及凌晨刺激性干咳为主、痰少或无痰，双肺无湿啰音，抗菌药物及化痰治疗无效，病程多超过8周，支气管激发试验阳性；本例病程仅1周、痰黄稠量多，双肺有湿啰音及痰鸣音。\n【排除方法】若抗感染化痰治疗迅速见效则支持急性支气管炎；若咳嗽迁延超过8周，完善肺功能、支气管激发试验及呼出气一氧化氮检测明确。\n4.上气道咳嗽综合征（鼻后滴漏综合征）：\n【支持点】可有咽部不适、咽痒、清嗓样咳嗽及咽部充血，与本例咽痛、咽部充血相似。\n【不支持点】上气道咳嗽综合征多有慢性鼻炎、鼻窦炎病史，表现为鼻塞、流涕、咽后壁黏液附着感及鼻后滴流感，咳嗽以晨起及体位改变时明显，常为慢性咳嗽（＞8周）；本例无鼻部症状及鼻后滴流感，痰液来自下气道、量多色黄。\n【排除方法】行鼻内镜及鼻窦影像学检查了解鼻腔、鼻窦情况；若抗感染化痰后咳嗽缓解、鼻窦无异常则可除外。\n5.胃食管反流性咳嗽：\n【支持点】亚急性咳嗽可为反流唯一表现，进食后及平卧时加重，与本例咳嗽夜间为甚有部分重叠。\n【不支持点】胃食管反流性咳嗽多伴烧心、反酸、嗳气、胸骨后灼痛，咳嗽以干咳为主、痰少，与体位及进食关系密切，抗菌药物无效；本例痰黄稠量多、无烧心反酸，双肺闻及湿啰音。\n【排除方法】必要时行24小时食管pH-阻抗监测或质子泵抑制剂诊断性治疗2～4周，结合抗感染治疗反应判断。\n6.肺结核：\n【支持点】可见咳嗽、咳痰，病程可长可短，早期表现可与急性支气管炎相似。\n【不支持点】肺结核多伴午后低热、盗汗、乏力、消瘦，可有咯血或痰中带血，抗感染治疗无效，胸部影像见上叶尖后段或下叶背段渗出、增殖、纤维化或空洞病灶；本例病程短、体温正常、无结核中毒症状，胸部X线未见结核好发部位病灶。\n【排除方法】完善痰抗酸染色及结核分枝杆菌核酸检测、结核感染T细胞检测，胸部CT观察有无结核好发部位病灶，必要时支气管镜检查。\n7.支气管肺癌：\n【支持点】多见于中老年男性，可有咳嗽、咳痰，早期易与急性支气管炎混淆；本例59岁男性，须警惕。\n【不支持点】肺癌咳嗽多为刺激性干咳或原有咳嗽性质改变，常伴痰中带血、胸痛、声嘶、进行性消瘦及锁骨上淋巴结肿大，抗感染治疗无效；本例病程仅1周、痰黄稠无血丝、无消瘦及淋巴结肿大。\n【排除方法】完善胸部CT（必要时增强）及肿瘤标志物检测；若抗感染治疗2周后症状不缓解或影像出现结节、肿块、阻塞征象，应行支气管镜及痰脱落细胞学检查。\n（六）西医分型/分级/分期：急性支气管炎（急性期，普通型，轻症，无发热及呼吸困难）；CURB-65评分0分，属低危。如胸部CT及炎性指标提示肺实质浸润，则诊断为社区获得性肺炎（CAP），CURB-65 0分归门诊治疗组（轻症），PSI分级Ⅰ～Ⅱ级。\n\n（七）诊疗计划：\n诊疗计划：\n1.护理与饮食：按内科护理常规，内科Ⅱ级护理；清淡易消化饮食，多饮温水，每日饮水量1500～2000ml，忌辛辣油腻、煎炸炙煿及甜腻生痰之品，戒烟酒。\n2.完善检查（逐项注明检查目的，符合医保对检查必要性与临床指征的要求）：①完善血常规、C反应蛋白、降钙素原（目的：评估感染严重程度及细菌感染可能性，为是否使用抗菌药物提供依据）；②完善痰涂片、痰培养及药敏（目的：明确致病菌及其耐药情况，为抗菌药物精准选择提供依据）；③完善胸部X线或胸部CT（目的：明确有无肺实质浸润影及其部位与范围，为鉴别急性支气管炎与社区获得性肺炎、判断病情严重程度提供依据）；④完善肺炎支原体抗体、流感病毒抗原等病原学检测（目的：明确有无非典型病原体及病毒感染，为是否选用大环内酯类或抗病毒药物提供依据）；⑤完善肝肾功能、电解质、血糖（目的：评估重要脏器功能及用药禁忌，为抗菌药物与化痰药物剂量调整提供依据）；⑥完善心电图（目的：了解有无心律失常及心肌缺血，为除外心源性疾病所致咳嗽、保证用药安全提供依据）；\n3.西医治疗：\n（1）盐酸氨溴索注射液15mg加生理盐水2ml雾化吸入，每日2次，稀释痰液、促进排痰；雾化后拍背排痰，每日2～3次，每次10分钟，注意观察痰量及痰色变化。\n（2）肺力咳合剂20ml口服，每日3次，清热化痰止咳。\n（3）抗菌药物：目前血WBC 6.5×10^9/L、中性粒细胞百分比65%基本正常，降钙素原及痰培养未回，暂不常规使用抗菌药物；若痰转黄绿脓性、体温≥38.5℃，或胸部CT提示肺实质浸润影，则加阿莫西林克拉维酸钾0.625g口服，每日3次（青霉素过敏者改用左氧氟沙星0.5g口服，每日1次）；痰培养回报后据药敏结果调整。\n（4）对症支持：体温≥38.5℃时予布洛芬混悬液10ml口服退热，必要时6～8小时重复，24小时不超过4次；咽痛明显者予复方硼砂含漱液漱口，每日3次；咳嗽剧烈影响睡眠者可予复方甲氧那明胶囊2粒口服，每日3次。\n（5）监测与复查：动态复查血常规、C反应蛋白，注意胃肠道反应、皮疹及QT间期延长等药物不良反应；肝肾功能异常时及时调整剂量。\n4.中医治疗：给予中药方剂以清热肃肺、豁痰止咳，兼以利咽健脾为治则；方选清金化痰汤加减；中药处方如下：黄芩10g 栀子10g 知母10g 桑白皮12g 瓜蒌仁15g（打碎） 浙贝母10g 桔梗6g 麦冬10g 橘红6g 茯苓12g 炒杏仁9g 牛蒡子9g 焦山楂12g 生甘草6g。共14味。用法：水煎服，每日一付，水煎取汁400ml，分2次温服，早晚饭后各服200ml。方解：方中黄芩、栀子苦寒直折肺经实热，清泄痰热之火，为君药；痰热壅肺、痰黄黏稠难咯，故臣以知母、桑白皮、瓜蒌仁清肺润燥、化痰宽胸，其中瓜蒌仁润燥滑痰，专治痰黄黏稠之证，知母既清肺热又滋肺燥，桑白皮泻肺中伏火而平气逆，三药合用使热清痰稀释而易咯；佐以浙贝母清热散结化痰，桔梗宣肺利咽祛痰，二者一散一宣，开提肺气、利咽止痛，使肺气宣降复常；橘红、茯苓理气健脾、渗湿化痰，取「脾为生痰之源、肺为贮痰之器」之意，杜绝生痰之源；麦冬养阴润肺，防黄芩、栀子、知母苦寒燥烈伤及肺阴；炒杏仁降气止咳，牛蒡子疏散风热而利咽，焦山楂消食助运以改善乏力纳差，亦为佐药；使以生甘草清热润肺、调和诸药。全方清、化、宣、降、润同施，使痰热得清、肺气宣降有权，则咳嗽自止。本方慎与罂粟壳、诃子等收涩之品同用，以免留邪；黄芩、栀子苦寒，中病即止，不宜久服，脾胃虚寒者忌用，孕妇慎用。\n5.密切观察病情变化，向家属交代目前病情，注意防跌倒等安全防范，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房，患者神志清楚，精神较昨日好转，自诉咳嗽发作次数较入院时减少，咳痰较前易咯，痰色仍黄质稠，量约每日20～30ml，咽痛减轻，夜间及晨起咳嗽仍较明显，无咯血、无胸痛、无明显气促，无恶寒发热，口干口苦较前缓解，纳食仍欠佳，夜寐一般，二便调。\n查体：T 36.7℃，P 76次/分，R 18次/分，BP 128/78mmHg；咽部充血较前减轻，双肺呼吸音粗，可闻及散在湿啰音及痰鸣音，未闻及干啰音及胸膜摩擦音；心腹查体同前，双下肢无水肿。\n辅助检查回报：血常规WBC 6.8×10^9/L、N% 66.5%、Hb 131g/L、PLT 205×10^9/L；C反应蛋白18mg/L，降钙素原0.05ng/ml；肝肾功能、电解质、血糖均正常；痰涂片见少量中性粒细胞及革兰阳性球菌，痰培养待报；肺炎支原体抗体IgM阴性；心电图窦性心律、正常心电图。\n张主治医师分析病情如下。\n\n一、中医辨病辨证分析\n患者以咳嗽、咯痰为主症，病程1周，起病急骤，先有外感表证，继而表解而咳不减，当属中医「咳嗽」范畴，为外感咳嗽，病位在肺，与脾胃相关。四诊合参：望之面色少华、咽部充血、舌质红、苔黄腻；闻之语声重浊、咳嗽声粗有力、痰黄稠而气秽；问之痰黄稠量多、咯吐不爽、咽痛口干口苦、鼻息气热、咳嗽以夜间及晨起为甚、纳差乏力；切之脉滑数。辨证为痰热郁肺证。病机分析：外邪犯肺，入里化热，灼津为痰，痰热互结，壅阻肺络，肺失清肃、宣降失常，故咳嗽气粗、痰黄黏稠难咯；热为阳邪，夜间阳气入阴、晨起阳气升发，痰热随气动而壅盛，故咳甚于夜间及晨起；热灼津液、上蒸咽喉，则咽痛、口干口苦、鼻息气热；痰热内蕴，脾运受困，故纳差乏力；舌红苔黄腻、脉滑数，均为痰热内蕴之征，其中脉滑主痰、数主热，二者并见，为痰热郁肺之确证。综观脉症，诊断明确，辨证无误，与首次病程记录所辨证型一致，目前治疗方向正确。\n\n二、中医鉴别诊断\n1.与「风热犯肺证」鉴别：风热咳嗽以表证为主，见发热微恶风、鼻塞流黄涕、咽痛、咳嗽痰少色黄易咯，舌边尖红、苔薄黄，脉浮数，病程多短，解表即愈。本案已无恶寒发热、鼻塞流涕等表证，痰黄稠量多、咯吐不爽，苔黄腻而不薄，脉滑数而不浮，属表解而痰热内郁，故辨为痰热郁肺而非风热犯肺。\n2.与「痰湿蕴肺证」鉴别：痰湿咳嗽亦以痰多为主，但痰白黏或白稀、量多易咯，晨起为甚，兼胸脘痞闷、食少体倦、大便时溏，舌苔白腻、脉濡滑。本案痰色黄稠、咯之不爽、咽痛口干，舌红苔黄腻、脉滑数，热象显著，故可鉴别。\n3.与「肝火犯肺证」鉴别：肝火犯肺之咳为气逆作咳、咳引胁肋胀痛、痰少黏如絮、面赤口苦、性急易怒，症状随情志波动，舌红、苔薄黄少津、脉弦数。本案咳嗽以痰多黄稠为主，无胁痛及情志诱发，脉滑数而非弦数，故可鉴别。\n4.与「肺阴亏耗证」鉴别：肺阴不足之咳为干咳痰少、痰中带血丝、口燥咽干、午后潮热、盗汗、舌红少苔、脉细数。本案痰量多而黄稠，舌红而苔黄厚腻，脉滑数有力，非细数之象，为实热而非虚热，故可鉴别。\n\n三、西医鉴别诊断\n1.急性支气管炎（本例主要诊断）：支持点为急性起病，咳嗽伴黄稠痰，双肺呼吸音粗并可闻及散在湿啰音及痰鸣音，血WBC正常、降钙素原不升高。不支持点/需除外者为肺实质感染：胸部影像尚无片状浸润影。拟完善胸部CT进一步证实；急性支气管炎多为病毒所致，痰培养阴性时可不使用抗菌药物。\n2.社区获得性肺炎：支持点为咳嗽咳痰、双肺闻及啰音；不支持点为体温正常、WBC 6.8×10^9/L、降钙素原0.05ng/ml无明显升高、啰音弥散而不局限。若胸部CT见新发浸润影并伴炎性指标升高，则修正诊断为肺炎并启动抗感染治疗。\n3.咳嗽变异性哮喘：支持点为咳嗽以夜间及晨起为甚；不支持点为病程仅1周、咳黄稠痰而非刺激性干咳、双肺有湿啰音，不符合其以干咳为主、病程超过8周的特点。若抗感染化痰治疗后咳嗽迁延不愈，再完善肺功能、支气管激发试验及呼出气一氧化氮检测。\n\n四、国内外相关疾病研究进展\n1.《咳嗽中医诊疗专家共识意见（2021）》指出，急性咳嗽属外感咳嗽者以风热、痰热证最为多见，痰热郁肺证治当清热化痰、肃肺止咳，推荐以清金化痰汤、桑白皮汤等加减，并强调早期慎用收涩止咳之品以免闭门留寇。\n2.2019年《中国咳嗽基层诊疗与管理指南》提出，急性咳嗽首诊需行影像学检查以除外肺炎；对无肺炎证据的急性支气管炎，多数由病毒引起，不推荐常规使用抗菌药物，应以对症化痰、祛痰治疗为主。\n3.一项针对急性支气管炎化痰治疗的随机对照研究（纳入200余例患者）显示，盐酸氨溴索雾化吸入可降低痰液黏稠度、改善气道黏液纤毛清除功能，联合中药清热化痰方治疗可使咳嗽缓解时间缩短约1～2天，痰量减少更明显。\n4.近年一项关于清金化痰汤加减治疗痰热郁肺型急性咳嗽的系统评价（纳入16项随机对照试验、约1400例患者）提示，中药组在总有效率、咳嗽消失时间及痰液性状改善方面优于单纯西医对症治疗，且未见严重不良反应。\n\n五、诊疗计划\n1.中医治疗：治以清肺化痰、肃肺止咳，兼以利咽健脾。方选清金化痰汤加减。处方：黄芩10g、栀子10g、知母10g、桑白皮12g、瓜蒌仁15g（打碎）、浙贝母10g、桔梗6g、麦冬10g、橘红6g、茯苓12g、炒杏仁9g、牛蒡子9g、焦山楂12g、生甘草6g。用法：水煎服，每日一付，水煎取汁400ml，分2次温服，早晚饭后各服200ml。方解：方中黄芩、栀子苦寒直折肺经实热、清泄痰热之火为君；知母、桑白皮、瓜蒌仁清肺润燥、化痰宽胸为臣，其中瓜蒌仁润燥滑痰、专治痰黄黏稠难咯；浙贝母清热散结化痰、桔梗宣肺利咽祛痰，二者一宣一散，使肺气宣降复常，橘红、茯苓理气健脾、渗湿化痰，取「脾为生痰之源、肺为贮痰之器」之意，杜绝生痰之源，共为佐；炒杏仁降气止咳、牛蒡子疏散风热而利咽、焦山楂消食助运以改善纳差，亦为佐药；生甘草清热润肺、调和诸药为使。全方清、化、宣、降同施，使痰热得清、肺气宣降有权，咳嗽自止。慎用罂粟壳、诃子等收涩之品，以免留邪。\n2.西医治疗：①盐酸氨溴索注射液15mg加生理盐水2ml雾化吸入，每日2次，稀释痰液、促进排痰；②肺力咳合剂20ml口服，每日3次，清热化痰止咳；③暂不常规使用抗菌药物，因血WBC及降钙素原无明显升高、痰培养未回；若痰转黄绿脓性、体温≥38.5℃、或胸部CT提示肺实质浸润，则加阿莫西林克拉维酸钾0.625g口服，每日3次（青霉素过敏者改用左氧氟沙星0.5g口服，每日1次）；④继续雾化后拍背排痰，每日2～3次，每次10分钟；⑤动态复查血常规、C反应蛋白，痰培养回报后据药敏调整用药，并注意胃肠道反应及皮疹等药物不良反应。\n3.护理与调摄：饮食宜清淡易消化，多饮温水，每日1500～2000ml，可食梨、白萝卜、冬瓜、荸荠等清热化痰之品；忌辛辣煎炸、肥甘厚味、甜腻生痰之物，戒烟酒。起居有常，注意休息，室内通风并保持湿度50%～60%，避免油烟、烟尘、冷空气及异味刺激；注意保暖，勿汗出当风。情志宜舒畅，勿急躁恼怒，以免气郁化火加重咳嗽。咳嗽痰多时取侧卧位并拍背助痰排出，热退体力恢复后可适度散步，勿过劳。\n4.医患沟通：已向患者及家属说明，目前诊断为咳嗽（痰热郁肺）、急性支气管炎，本次发病与受凉劳累后外邪犯肺、痰热内蕴有关，属常见病、预后良好，规范治疗1～2周多可缓解。同时交代：①中药宜温服，服药期间忌辛辣油腻及烟酒，如出现腹泻、胃脘不适及时告知医师；②每日测量体温2～4次，记录痰量、痰色及是否易咯，痰多时侧卧拍背排痰；③痰转黄绿脓性、痰中带血、高热不退、气促胸闷、口唇发紫者立即告知医护人员；④咳嗽完全缓解需一定过程，勿自行加用强力镇咳药或抗生素。患者及家属表示理解并配合。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，主诉症状较前略有改善，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体同前。继续当前中药治疗方案。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，主诉症状较前明显好转，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。继续当前治疗。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。患者病情平稳，继续巩固治疗，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为咳嗽（痰热郁肺），病情平稳，需住院进一步检查治疗。\n2.诊疗方案：完善相关检查，中医辨证论治，中药汤剂口服，对症支持治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应等。\n4.注意事项：注意休息，清淡饮食，配合检查治疗。\n5.预后情况：经积极治疗后预后较好。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：咳嗽（痰热郁肺）\n西医诊断：相关疾病\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，男，59岁，因\"反复咳嗽（痰热郁肺）相关症状加重1周。\"入院。入院查体：生命体征平稳，心肺腹查体未见明显异常。中医四诊：舌质红，苔黄腻，脉滑数。\n\n诊疗经过：\n入院后完善相关检查，明确中医诊断，给予辨证论治，中药汤剂口服，对症支持治疗，患者病情逐渐好转，症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。查体：生命体征平稳。\n出院医嘱：1. 饮食：低盐低脂清淡饮食，戒烟限酒。\n2. 休息与活动：注意休息，避免劳累，适当活动，循序渐进。\n3. 用药：按医嘱规律服药，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后1-2周门诊复查，如有病情变化随时就诊。\n5. 注意事项：监测血压、血糖等指标，保持良好生活习惯，遵医嘱定期随访。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，主诉症状较前改善，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 125/78mmHg。神志清楚，精神可。舌质红，苔黄腻，脉弦细。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。专科情况较前有所改善。\n辅助检查：相关检查结果回报，较前有所好转。\n四诊合参，本病属中医\"咳嗽（痰热郁肺）\"范畴，辨证论治，随证加减。患者经中药辨证论治后，症状较前改善，治疗有效。继续目前中药治疗，注意观察病情变化，随证加减。注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，主诉症状明显改善，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 74次/分，R 18次/分，BP 124/76mmHg。神志清楚，精神好。舌质红，苔黄腻，脉和缓。双肺呼吸音清，心率74次/分，律齐。腹软，无压痛。专科情况明显改善。\n辅助检查：复查相关指标正常或较前明显改善。\n患者经中药辨证论治后，症状明显改善，病情稳定。继续目前治疗，巩固疗效。今日可出院。建议出院后继续服用中药调理，定期复诊，注意休息，清淡饮食，避免劳累及情志刺激，适当锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月17日 10:00（入院第3天）\n\n今日李主任医师查房，患者精神明显好转，自诉咳嗽较入院时减轻约半，咳痰爽利，痰色由黄稠转黄白相兼、质转稀，量减少至每日10～15ml，咽痛已除，口干口苦基本缓解，夜间可安睡5～6小时，纳食改善，二便调。\n查体：T 36.6℃，P 74次/分，R 18次/分，BP 126/78mmHg；咽部轻度充血，双肺呼吸音略粗，湿啰音及痰鸣音较昨日减少，未闻及哮鸣音及胸膜摩擦音；心腹查体未见异常。\n辅助检查回报：胸部CT示双肺纹理增粗、支气管壁略增厚，未见片状浸润影、空洞及占位，纵隔淋巴结不大；C反应蛋白10mg/L，痰培养未见致病菌生长；余检查同前。\n李主任医师听取汇报、查看患者并审阅病历后分析如下。\n\n一、中医辨病辨证分析\n患者以咳嗽、咯痰为主症，病程1周余，胸CT无肺实质病变，属中医「咳嗽」之外感咳嗽，病位在肺，涉及脾胃。本案辨证要点在三处：一是痰之色质，痰黄稠、咯吐不爽、气秽，为热灼津液成痰之象，是痰热之核心依据；二是舌脉，舌质红、苔黄腻、脉滑数，滑主痰浊、数主热盛，舌脉与症状相符，说明痰热内蕴而非虚热；三是时间规律，咳嗽夜间及晨起为甚，因夜间阳气入阴、痰热内伏，晨起阳气升发、痰随气动，此亦痰热壅肺之佐证。病机为外邪入里化热、灼津为痰，痰热互结壅阻肺络，肺失清肃、宣降失常，气逆而咳。经两日清热化痰治疗，痰由黄稠转黄白而稀、量减、咽痛除、苔黄腻渐化，为痰热渐清、肺气渐降之佳兆，说明辨证准确、方证相应。\n\n二、中医鉴别诊断\n1.与「燥邪伤肺证」鉴别：燥咳多发于秋季，以干咳无痰或痰少黏连成丝、鼻咽干燥、舌红少津、脉浮细为特点，治宜润燥。本案痰量多而黄稠、苔黄腻、脉滑数，为痰湿与热相结，非燥象，故可鉴别。\n2.与「肺痈（初期）」鉴别：肺痈初期亦有咳嗽、痰黄、胸痛，但其痰量极大、渐转腥臭脓血，伴壮热、烦渴、胸痛固定，舌苔黄厚、脉洪数或滑实，影像可见厚壁空洞及液平。本案痰无腥臭脓血，胸CT无空洞液平，热势不盛，故可鉴别。\n3.与「肺胀」鉴别：肺胀以咳、痰、喘、满并见，胸中膨满、气短难续、动则加重，多有久咳宿疾，查体见桶状胸、叩诊过清音、呼吸音减弱，肺功能示持续气流受限。本案无桶状胸及气短难续，亦无慢性咳嗽宿疾，故不属肺胀。\n4.与「脾虚生痰（内伤咳嗽）」鉴别：内伤咳嗽之痰多由脾虚湿盛，痰白量多易咯、食少便溏、气短乏力、舌淡苔白、脉细弱，病程长、反复发作，属虚实夹杂。本案起病急、病程短、痰黄稠、脉滑数有力，属外感实热，故可鉴别。\n5.与「喉痹（咽炎）所致咳嗽」鉴别：喉痹以咽部干痒灼痛、咽后壁滤泡增生为主症，咳嗽多为咽痒即咳、痰少，多因外感或粉尘刺激诱发。本案以咳痰黄稠为主，咽部充血为痰热上蒸之兼症，且治疗后咽痛先除而咳嗽仍存，说明病本在肺而不在咽，故可鉴别。\n\n三、西医鉴别诊断（并入疑难分析与诊断修正）\n本案入院时曾疑社区获得性肺炎，今胸部CT未见肺实质浸润影、C反应蛋白仅轻度升高、降钙素原正常、痰培养阴性，故修正诊断倾向为急性支气管炎，可排除肺炎、肺结核及肺部占位。仍需与以下两类咳嗽鉴别：咳嗽变异性哮喘者多为夜间刺激性干咳、痰少、病程超过8周、肺功能示可逆性气流受限，与本案咳黄稠痰、病程短、有明确感染征象不符；上气道咳嗽综合征者以白天咳嗽为主、伴鼻塞流涕、咽后壁黏液附着，本例以夜间及晨起为甚、无鼻部症状，可资区别。另需注意胃食管反流性咳嗽的可能，其多在餐后及平卧时加重、伴反酸嗳气，本案无相应表现，暂不考虑，若咳嗽迁延则建议查胃镜或行经验性抑酸治疗验证。\n\n四、国内外相关疾病研究进展\n1.《中国2型糖尿病防治指南（2020年版）》虽然针对代谢病，但其「治疗路径个体化、以疗效与安全性为双重目标」的推荐原则，同样适用于本例抗菌药物的取舍，即依据病原学与炎症标志物而非经验性用药。\n2.2019年《中国咳嗽基层诊疗与管理指南》及2023年美国胸科医师学会（ACCP）相关咳嗽管理建议均强调：急性咳嗽首诊应行影像学检查除外肺炎；对无肺炎证据的急性支气管炎不推荐常规使用抗菌药物，因多数为病毒性，经验性抗菌治疗并不能缩短病程，反增耐药与不良反应风险。\n3.一项纳入约320例急性支气管炎患者的随机对照试验显示，祛痰剂（氨溴索或乙酰半胱氨酸）联合对症治疗可显著改善痰液性状与咳痰困难，缩短咳嗽持续时间约1.5天，但单独使用抗菌药物并无获益。\n4.中西医结合诊疗痰热郁肺型急性咳嗽的多中心研究提示，在常规西医对症基础上联用清热化痰方（清金化痰汤加减），可加快咳嗽缓解、缩短住院时间，并在降低C反应蛋白等炎症指标方面优于单纯西药组，安全性良好。\n\n五、诊疗计划\n1.中医治疗：辨证仍属痰热郁肺，但痰热已渐清而痰量减少，故治则调整为清肺化痰、宣肺止咳，佐以健脾以杜生痰之源。处方在原清金化痰汤基础上调整：黄芩10g、栀子6g（苦寒减量，防久服伤中）、桑白皮12g、瓜蒌皮12g、浙贝母10g、桔梗6g、杏仁9g、麦冬10g、橘红6g、茯苓12g、白术10g、炒谷芽15g、生甘草6g。用法：水煎服，每日一付，分2次温服，早晚饭后各200ml。方解：黄芩、栀子清热泻肺、直折痰热为君，其中栀子减量，取「中病即止」之意；桑白皮、瓜蒌皮、浙贝母清肺化痰、宽胸散结为臣，瓜蒌易仁为皮，因痰已转稀，重在理气宽胸而不必润燥滑肠；桔梗开宣肺气、载药上行，杏仁降气止咳，二者一升一降，调畅肺之气机；橘红、茯苓、白术健脾理气渗湿，炒谷芽消食和胃，共为佐，从脾胃入手杜绝生痰之源；生甘草润肺止咳、调和诸药为使。全方清而不峻、化痰而不伤正，兼顾脾胃。停用苦寒过重之品，勿用收涩镇咳之药。\n2.西医治疗：①继续盐酸氨溴索15mg加生理盐水2ml雾化吸入，每日2次；②肺力咳合剂20ml口服，每日3次；③据CT及炎症指标结果，明确无细菌感染证据，停用抗菌药物观察，若后续出现脓性痰、发热或影像进展再评估启用；④加强气道管理，雾化后拍背排痰、鼓励有效咳嗽；⑤无需特殊氧疗，监测体温、呼吸及血氧饱和度，复查血常规与C反应蛋白评估炎症消退情况。\n3.护理与调摄：饮食以清淡富营养为原则，多饮温水，适量进食梨、百合、山药、白萝卜等润肺健脾之品，忌辛辣煎炸、肥甘厚味及生冷，戒烟酒。起居规律，保证睡眠，室内温湿度适宜（温度20～24℃、湿度50%～60%），避免油烟、粉尘、冷空气刺激，随天气增减衣被。情志调畅，避免忧思恼怒。恢复期可循序渐进进行呼吸功能锻炼，如腹式呼吸、缩唇呼气，每日2次，每次10分钟，并可适度散步，以不觉疲劳为度。\n4.医患沟通：已向患者及家属说明，胸部CT未见肺炎及占位，诊断考虑急性支气管炎，中医为咳嗽痰热郁肺证，经治疗痰热渐清、病情好转，预后良好，无需使用抗菌药物，避免滥用抗生素带来的耐药与肠道菌群失调风险。嘱继续中药调理，按时服药与复诊；如出现痰色转脓、发热、气促或痰中带血，立即就诊。咳嗽缓解后仍需注意避风寒、慎饮食，以防复发。计划继续巩固治疗3～5天，复查血常规、C反应蛋白，若咳嗽明显缓解、炎症指标恢复正常、双肺啰音消失，可考虑出院，出院后1周门诊复诊，必要时复查胸部影像。患者及家属表示理解并同意。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1221,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"357811d4b50bdfcc9a74c28de09d633947a79d45c9f2af8b096108e4cf649126","pinyin":"kesou（tanreyufei）","initials":"ks（tryf）","setting":"in","caseName":"病例1：患者，男，59岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，59岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-e4d10c8549b6f7572849","key":"v1-c9ccc21dfe2a3058|templates-e4d10c8549b6f7572849","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"哮病（冷哮）","category":"中医科","raw":{"name":"哮病（冷哮）","category":"中医科","case":{"case_name":"病例1：患者，女，58岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：女 年龄：58岁 民族：汉族\n婚姻：已婚 职业：退休 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：发作性喉中哮鸣伴呼吸急促1周。\n\n现病史：患者于1周前无明显诱因起病，起病较急，呈发作性，发作频率渐增。主要表现为：发作性喉中哮鸣有声，呼吸急促，喘息不能平卧，张口抬肩，咳痰清稀色白，量少，口不渴，遇寒或接触冷空气、异味刺激后诱发或加重，每次发作持续约数小时，休息后逐渐缓解，缓解期如常人。病程中上述症状反复发作，时轻时重，劳累后明显加重，安静休息后可部分缓解，总体呈逐渐加重趋势。伴乏力，纳差，二便调。发病以来无发热、无恶寒、无自汗盗汗、无五心烦热（四诊合参），无咯血，无胸痛，无呼吸困难持续不缓解，无意识障碍，无紫绀。自行服用中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「哮病（冷哮）」收入我科。发病以来精神欠佳，饮食睡眠尚可，大小便正常，体重无明显变化。\n\n既往史：既往有高血压病史，规律服药控制可。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。\n\n个人史及家族史：生于本地，久居本地。无吸烟史。家族中否认类似疾病史。\n婚育史：33岁结婚，配偶体健，育有1子\n月经史：初潮14岁，已绝经约8年，无痛经\n体格检查：\nT 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg。\n一般情况：神志清楚，精神可，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色少华，舌质淡，苔薄白。\n闻诊：语声清晰，无异常气味。\n问诊：哮病（冷哮）相关症状，纳差，二便调。\n切诊：脉细弱。\n一般情况：神志清楚，精神反应可，营养发育正常，查体欠合作（哭闹）。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：面色晦滞或青灰，端坐呼吸，口唇无明显发绀，汗出不多；闻诊：喉中哮鸣有声，呼吸急促，呼气延长，咳痰清稀色白；舌象：舌淡，苔白滑；脉象：脉弦紧或浮紧。专科查体：双肺可闻及广泛哮鸣音，呼气相明显延长，未闻及湿啰音；胸廓对称，语颤正常，叩诊清音。关键阴性体征：无发热，无颈静脉怒张，无下肢水肿，心率正常，无杵状指。\n辅助检查：\n门诊血常规：WBC 6.5×10^9/L，N% 65%，Hb 130g/L，PLT 200×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：哮病（冷哮）\n中医诊断依据：1.辨病依据：患者以「发作性喉中哮鸣伴呼吸急促1周」为主诉，发作时喉中哮鸣有声、呼吸急促、喘息不能平卧、张口抬肩，缓解期如常人，呈反复发作性，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」的诊断要点；「哮以声响言」，喉中哮鸣如水鸡声为本病特征性表现，故辨病为哮病。2.辨证依据：①主症：喉中哮鸣如水鸡声，呼吸急促，胸膈满闷如塞，喘息不能平卧，咳痰清稀色白、量少，口不渴，形寒怕冷，遇寒或接触冷空气、异味刺激即诱发或加重，天冷易发；②舌象脉象：舌质淡，苔白滑，脉弦紧或浮紧；③病因病机：寒痰伏肺，遇感触发，痰升气阻，肺失宣降，气道挛急，故喉中哮鸣、喘息气促；寒为阴邪，故痰白清稀、口不渴、形寒怕冷，舌淡苔白滑、脉弦紧皆为寒痰内盛之征。四诊合参，属寒痰伏肺、肺失宣降之冷哮证（寒哮）。\n中医鉴别诊断：1.与「喘证」鉴别：喘证以气息言，以呼吸困难、甚则张口抬肩、鼻翼扇动、不能平卧为主症，可见于多种急慢性疾病过程中，无发作性及喉中哮鸣之特征；哮病以声响言，以发作时喉中哮鸣有声为特征，反复发作、有夙根、有诱因可循，间歇期如常人。哮必兼喘，喘未必兼哮，本例喉中水鸡声为辨为哮病之据。2.与「支饮」鉴别：支饮为饮邪留伏胸膈，症见咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病，常伴面浮肢肿、小便不利、颈静脉怒张等饮停之象，病程持续而无倏忽发作之特点；本例无水肿、无颈静脉怒张、双下肢无凹陷性水肿，间歇期如常人，可资鉴别。3.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、心悸、面色晦暗为主症，病程缠绵、进行性加重，多见桶状胸、颈静脉怒张及右心衰竭征象；本例胸廓对称、无桶状胸，缓解期如常人，暂不支持肺胀，然久病不愈者须动态随访。4.与「热哮」鉴别：热哮见气粗息涌、喉中痰鸣如吼、咳痰黄稠、口渴喜冷饮、身热汗出、舌红苔黄腻、脉滑数；本例痰白清稀、口不渴、形寒怕冷、舌淡苔白滑、脉弦紧，寒热之象迥异。\n西医诊断：支气管哮喘（急性发作期）\n西医诊断依据：1.病史及症状依据：发作性喘息、气促伴喉中哮鸣1周，发作时喘息不能平卧、张口抬肩，痰白清稀，遇冷空气及异味刺激诱发或加重，缓解期如常人，符合支气管哮喘「反复发作性喘息、气急、胸闷或咳嗽，多与接触变应原、冷空气、理化刺激及上呼吸道感染有关，可自行缓解或经治疗缓解」的典型特征；2.体征依据：双肺可闻及广泛哮鸣音，呼气相明显延长，未闻及湿性啰音，胸廓对称、无桶状胸，无颈静脉怒张、无下肢水肿、无杵状指，可除外慢性肺源性心脏病及心力衰竭；3.实验室检查依据：门诊血常规WBC 6.5×10^9/L、N% 65%、Hb 130g/L、PLT 200×10^9/L，肝肾功能及电解质正常；嗜酸性粒细胞计数、血清总IgE、呼出气一氧化氮（FeNO）及过敏原检测待完善；4.影像学依据：胸部X线待完善，重点除外肺炎、气胸、胸腔积液及占位；心电图示窦性心律、正常心电图，可基本除外心源性哮喘；5.肺功能依据：肺功能加支气管舒张试验待完善，若FEV1占预计值下降、FEV1/FVC降低，且吸入支气管舒张剂后FEV1增加率≥12%且绝对值增加≥200ml，或PEF昼夜变异率>10%，即可确诊并证实气流受限可逆。\n西医分型/分级/分期：①疾病分期：急性发作期；②急性发作严重程度分级：轻度——呼吸困难程度为步行、上楼时气短，尚可平卧，呼吸频率18次/分（＜30次/分），心率78次/分（＜100次/分），未吸氧SpO2＞95%，双肺散在哮鸣音，无发绀、无意识改变，PEF未查（若＞80%预计值亦支持轻度），符合我国《支气管哮喘防治指南》及GINA方案轻度急性发作标准；③气道炎症表型：临床倾向过敏性（外源性）哮喘，嗜酸性粒细胞表型待FeNO、血嗜酸性粒细胞计数及过敏原检测确认；④病情严重程度（慢性持续期）分级：既往未规范评估，按本次急性发作及病程1周，暂按第2级（轻度持续）管理，缓解后须重新评估；⑤哮喘控制水平：本次为急性发作，提示既往控制不佳（至少为「部分控制」，需完善ACT评分明确）；⑥合并症：高血压病（规律服药，血压130/80mmHg，控制可）。\n\n诊疗计划：\n1.按内科Ⅰ~Ⅱ级护理，清淡易消化饮食，注意保暖，避免接触冷空气及过敏原；2.完善检查：肺功能+支气管舒张试验（目的：明确气道阻塞及可逆性，为哮喘诊断与吸入激素方案提供依据）、嗜酸性粒细胞计数+呼出气一氧化氮（目的：评估气道炎症类型与水平，为抗炎治疗强度提供依据）、血气分析（目的：评估低氧血症及二氧化碳潴留，为病情分级与氧疗提供依据）、胸部X线（目的：排除肺炎、气胸等并发症及其他肺部疾病）、血常规+C反应蛋白（目的：评估有无合并感染，为是否加用抗感染治疗提供依据）、过敏原检测+血清总IgE（目的：明确诱发因素，为环境规避与脱敏治疗提供依据）；3.一般治疗：吸氧（2~3L/min），雾化吸入布地奈德2mg加沙丁胺醇5mg每日2~3次；4.药物治疗：温肺散寒、化痰平喘中药汤剂（射干麻黄汤加减），茶碱缓释片0.2g每日2次口服（监测血药浓度）；5.病情观察：观察喘息、哮鸣音变化，监测呼吸频率、血氧饱和度，警惕哮喘持续状态及呼吸衰竭；6.健康教育：指导规范吸入用药、避免诱因、防寒保暖，必要时请呼吸科会诊。\n\n专科检查：\n望诊：面色晦滞或青灰，端坐呼吸，口唇无明显发绀，汗出不多；闻诊：喉中哮鸣有声，呼吸急促，呼气延长，咳痰清稀色白；舌象：舌淡，苔白滑；脉象：脉弦紧或浮紧。专科查体：双肺可闻及广泛哮鸣音，呼气相明显延长，未闻及湿啰音；胸廓对称，语颤正常，叩诊清音。关键阴性体征：无颈静脉怒张，无下肢水肿，心率正常，无杵状指。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，女，58岁，因\"反复哮病（冷哮）相关症状加重1周。\"入院。\n2.既往史：既往有高血压病史。\n3.体格检查：生命体征平稳，心肺腹查体未见明显异常。\n4.中医四诊：舌质淡，苔薄白，脉细弱。\n5.辅助检查：血常规、生化、心电图结果如上。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：哮病（冷哮）\n西医诊断：支气管哮喘\n\n（二）中医诊断依据：\n1.辨病依据：患者因「发作性喉中哮鸣伴呼吸急促1周」入院，发作时喉中哮鸣有声、呼吸急促、喘息不能平卧，缓解期如常人，呈反复发作性，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，「哮以声响言」，喉中水鸡声为特征性表现，故辨病为哮病。\n2.辨证依据：患者遇寒及接触冷空气、异味即诱发或加重，天冷易发；喉中哮鸣如水鸡声，呼吸急促，胸膈满闷如塞，咳痰清稀色白量少，口不渴，形寒怕冷；舌质淡、苔白滑，脉弦紧或浮紧。此乃寒痰伏肺，遇感触发，痰升气阻，肺失宣降，气道挛急所致；寒为阴邪，故痰白清稀、口不渴、形寒怕冷，舌淡苔白滑、脉弦紧皆寒痰内盛之征。四诊合参，当属冷哮（寒哮）之证。\n3.治法方药：治以温肺散寒、化痰平喘，方用射干麻黄汤加减（射干9g、麻黄9g先煎去上沫、生姜9g、细辛3g、紫菀9g、款冬花9g、法半夏9g、五味子6g打碎、大枣3枚）；痰多胸闷加紫苏子9g、白芥子6g，形寒怕冷甚加桂枝9g、干姜6g。\n依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·哮病·冷哮（寒哮）证；《金匮要略·肺痿肺痈咳嗽上气病脉证治》「咳而上气，喉中水鸡声，射干麻黄汤主之」。\n\n（三）中医鉴别诊断：\n1.与「喘证」鉴别：喘证以气息言，以呼吸困难、甚则张口抬肩、鼻翼扇动、不能平卧为主症，可见于多种急慢性疾病过程中；哮病以声响言，以发作时喉中哮鸣有声、反复发作为特征，间歇期如常人。哮必兼喘，喘未必兼哮，本例喉中水鸡声为辨为哮病之据。\n2.与「支饮」鉴别：支饮为饮邪留伏胸膈，咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病，常伴面浮肢肿、小便不利、颈静脉怒张；本例无水肿、无颈静脉怒张，双下肢无凹陷性水肿，间歇期如常人，可资鉴别。\n3.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、心悸、面色晦暗为主症，病程缠绵、进行性加重，多见桶状胸及右心衰竭征象；本例胸廓对称、无桶状胸，缓解期如常人，暂不支持肺胀，但久病者须动态观察。\n4.与「热哮」鉴别：热哮见气粗息涌、喉中痰鸣如吼、咳痰黄稠、口渴喜冷饮、舌红苔黄腻、脉滑数；本例痰白清稀、口不渴、形寒怕冷、舌淡苔白滑、脉弦紧，寒热之象迥异。\n提示：若见喘息持续不解、张口抬肩、汗出如雨、面青唇紫、神昏烦躁者，为哮病危候（哮喘持续状态、呼吸衰竭），须立即抢救并请上级医师查房。\n\n（四）西医诊断依据：\n1.病史及症状依据：发作性喘息、气促伴喉中哮鸣1周，发作时喘息不能平卧、张口抬肩，痰白清稀，遇冷空气及异味刺激诱发或加重，缓解期如常人，符合支气管哮喘典型临床特征。\n2.体征依据：T 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg，双肺可闻及广泛哮鸣音、呼气相明显延长、未闻及湿性啰音，胸廓对称、无桶状胸，无颈静脉怒张、无下肢水肿、无杵状指。\n3.实验室依据：血常规WBC 6.5×10^9/L、N% 65%、Hb 130g/L、PLT 200×10^9/L，肝肾功能及电解质正常；嗜酸性粒细胞计数、总IgE、FeNO及过敏原检测待完善。\n4.影像学依据：胸部X线待完善，重点除外肺炎、气胸、胸腔积液及占位；心电图示窦性心律、正常心电图，可基本除外心源性哮喘。\n5.肺功能依据：肺功能加支气管舒张试验待完善，若FEV1下降、支气管舒张试验阳性（FEV1增加率≥12%且绝对值增加≥200ml）或PEF昼夜变异率>10%，即可确诊并证实气流受限可逆。\n6.诊断标准对照：符合支气管哮喘诊断标准中「反复发作喘息、气急、胸闷或咳嗽，发作时双肺可闻及散在或弥漫性哮鸣音、呼气相延长，上述症状可经治疗或自行缓解，并除外其他疾病所致喘息」之条件，诊断为支气管哮喘急性发作期（轻度）。\n\n（五）西医分型/分级/分期：\n①疾病分期：急性发作期。②急性发作严重程度分级：轻度（呼吸频率18次/分＜30次/分，心率78次/分＜100次/分，未吸氧SpO2＞95%，无发绀及意识改变，双肺散在哮鸣音，符合轻度急性发作标准）。③气道炎症表型：倾向过敏性（外源性）哮喘，嗜酸性粒细胞表型待FeNO、血嗜酸性粒细胞计数及过敏原检测确认。④病情严重程度（慢性持续期）分级：暂按第2级（轻度持续）管理，缓解后重新评估。⑤控制水平：本次为急性发作，提示既往控制不佳（需完善ACT评分明确为部分控制或未控制）。⑥合并症：高血压病，服药控制，血压130/80mmHg。\n\n（六）西医鉴别诊断：\n1.慢性阻塞性肺疾病急性加重：\n【支持点】两者均以发作性喘息、气促、呼气相延长及双肺哮鸣音为主要表现，均可因冷空气、异味等刺激诱发，故须鉴别。\n【不支持点】本例为中年女性，无长期吸烟及粉尘、生物燃料接触史，无慢性咳嗽咳痰逐年加重史，胸廓对称、无桶状胸，双肺未闻及湿性啰音，缓解期如常人，不符合慢性阻塞性肺疾病持续性、进行性加重的气流受限特点。\n【排除方法】完善肺功能（FEV1/FVC＜70%且支气管舒张试验阴性支持慢性阻塞性肺疾病）、胸部CT（肺气肿、肺大疱），结合吸烟史、起病年龄及症状持续时间综合判断。\n2.急性左心衰竭（心源性哮喘）：\n【支持点】急性左心衰竭可表现为夜间阵发性呼吸困难、端坐呼吸及双肺哮鸣音，与支气管哮喘急性发作相似。\n【不支持点】本例无高血压性心脏病、冠心病、心脏瓣膜病等基础心脏病及心功能不全病史，咳白色稀泡沫痰而非粉红色泡沫痰，无颈静脉怒张、无下肢凹陷性水肿、无奔马律，心电图正常。\n【排除方法】查心电图、心脏彩超（左室射血分数、室壁运动）、血浆BNP/NT-proBNP及胸部X线（心影大小、肺淤血征象），BNP正常且无心衰体征者可除外。\n3.自发性气胸：\n【支持点】自发性气胸起病急骤，可有突发胸痛、呼吸困难及患侧呼吸音减低，需与急性发作期支气管哮喘鉴别。\n【不支持点】本例双肺均可闻及广泛哮鸣音而非单侧呼吸音消失，无突发针刺样胸痛，气管居中，无皮下气肿。\n【排除方法】急查胸部X线或胸部CT，可见气胸线及肺压缩带即可确诊；未见气胸线者除外。\n4.肺栓塞：\n【支持点】肺栓塞可表现为突发呼吸困难、气促、胸闷，可伴哮鸣音及低氧血症，需与支气管哮喘急性发作鉴别。\n【不支持点】本例无下肢深静脉血栓、近期手术制动、骨折或恶性肿瘤等高危因素，无胸痛咯血及晕厥，心率78次/分，无低血压及右心负荷过重表现。\n【排除方法】查D-二聚体、动脉血气分析、心电图（SⅠQⅢTⅢ征）、心脏彩超（右心扩大）及CT肺动脉造影（CTPA）；D-二聚体阴性且无高危因素者基本可除外。\n5.上气道阻塞（气管异物、气管肿瘤、声带功能障碍）：\n【支持点】均可出现呼吸困难与喘鸣，易被误认为支气管哮喘发作。\n【不支持点】上气道阻塞多为吸气性喘鸣，可有三凹征，喘鸣音多局限于颈部且吸气相明显；本例喘鸣以呼气相为主、双肺广泛分布，无异物吸入史，无声音嘶哑及咯血。\n【排除方法】查颈胸部CT、支气管镜及肺功能流速-容量环（吸气相平台样改变提示上气道阻塞），结合喘鸣时相及影像学表现鉴别。\n6.变态反应性支气管肺曲霉病（ABPA）：\n【支持点】该病以哮喘样发作为主要表现，常伴外周血嗜酸性粒细胞增多及血清总IgE升高，与过敏性支气管哮喘相似。\n【不支持点】本例无咳棕色痰栓、无反复肺部浸润影及中心性支气管扩张病史，病程仅1周。\n【排除方法】查血清总IgE（常＞1000IU/mL）、烟曲霉特异性IgE/IgG、外周血嗜酸性粒细胞计数及胸部CT（中心性支气管扩张、黏液栓），阴性者不支持。\n\n（七）诊疗计划：\n诊疗计划：\n1.护理与饮食：按中医科（肺病科）常规护理，二级护理；清淡易消化、温热饮食，忌冰饮、西瓜、螃蟹等寒凉生冷及肥甘厚味、虾蟹等已知致敏食物，可食生姜、山药、大枣，每日食盐＜5g；注意颈背部及双足保暖，避免接触冷空气及过敏原，室温保持20～24℃，避免空调直吹。\n2.完善检查：①复查血常规、嗜酸性粒细胞计数及C反应蛋白（目的：评估有无呼吸道感染及嗜酸性粒细胞增高程度，为判断气道炎症表型提供依据）；②完善肺功能加支气管舒张试验（目的：明确有无阻塞性通气功能障碍及气流受限可逆性，为确诊支气管哮喘、评估病情严重程度及制定吸入激素方案提供依据）；③完善动脉血气分析（目的：评估氧合状态及有无二氧化碳潴留，为氧疗及是否需要通气支持提供依据）；④完善胸部X线及胸部CT（目的：除外肺炎、气胸、胸腔积液及肺部占位，为喘息病因鉴别提供依据）；⑤完善心电图、心脏彩超及血浆BNP（目的：除外心律失常、心肌缺血及心源性哮喘，为鉴别心源性喘息提供依据）；⑥完善血清总IgE、过敏原检测及呼出气一氧化氮（FeNO）（目的：明确致敏原与气道嗜酸性炎症水平，为环境规避、抗炎治疗及病情监测提供依据）。\n3.西医治疗：给予吸入用布地奈德混悬液2mg加硫酸沙丁胺醇雾化溶液5mg，加入生理盐水2ml，氧气驱动雾化吸入，每日2次（喘息加重时可临时加吸1次），抗炎平喘、解除气道痉挛；给予孟鲁司特钠片10mg，每晚1次口服，睡前服，抗白三烯、减轻气道炎症；给予茶碱缓释片0.2g，每日2次口服，餐后服，舒张支气管（用药期间监测血药浓度、心率及血钾，避免与麻黄类制剂叠加致心率增快、血压升高）；给予吸氧2～3L/min，维持SpO2≥95%；若肺功能证实可逆性气流受限，改为布地奈德福莫特罗吸入剂160/4.5μg，每次1吸、每日2次，吸后漱口；患者既往高血压病，继续监测血压，必要时给予苯磺酸氨氯地平片5mg每日1次口服控制血压，避免使用非选择性β受体阻滞剂。\n4.中医治疗：四诊合参，证属冷哮（寒哮），乃寒痰伏肺、遇感触发、痰升气阻、肺失宣降、气道挛急所致，治以温肺散寒、化痰平喘，兼以益气固本为治则；方选射干麻黄汤加减。中药处方如下：射干9g、炙麻黄6g、桂枝9g、干姜6g、细辛3g、紫菀9g、款冬花9g、法半夏9g、紫苏子9g、白芥子6g、五味子6g（打碎）、黄芪15g、炒白术12g、大枣10g、炙甘草6g。用法：水煎服，每日一付，头煎加水500ml煎取200ml，二煎加水400ml煎取200ml，两煎混匀，分2次温服，早晚饭后服；麻黄先煎去上沫，细辛用量宜小，五味子打碎入煎。方解：方中炙麻黄辛温宣肺、开腠散寒，桂枝温通经脉、助麻黄解表散寒，细辛温肺化饮、通达肺窍，射干降气消痰、利咽散结，四药相合辛温发散、宣降并用，共为君药，直解寒痰闭肺、气道挛急之标；紫菀、款冬花润肺下气、化痰止咳，法半夏燥湿化痰、和胃降逆，紫苏子、白芥子降气豁痰、通利胸膈，共为臣药，助君药化痰平喘、通畅气机；干姜温肺化饮以除寒痰之源，五味子酸收敛肺、防辛散太过耗气，二者一散一收，黄芪、炒白术益气健脾固本，取「培土生金」之意，使脾运健则痰无由生，共为佐药；炙甘草调和诸药、兼能化痰止咳，大枣和中补脾，共为使药。全方辛开苦降、散收并用、标本兼顾，共奏温肺散寒、化痰平喘、益气固本之效。另予穴位贴敷（肺俞、定喘、膻中、足三里）每日1次，每次4～6小时，以温通经络、宣肺平喘。\n5.密切观察病情变化，重点观察喘息、哮鸣音及呼吸频率、血氧饱和度变化，警惕哮喘持续状态及呼吸衰竭；向家属交代目前病情，注意防跌倒、防坠床，加强生活照护，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房。患者神志清楚，精神较入院时好转，自述昨夜喉中哮鸣较前减轻，可平卧入睡，未再出现夜间憋醒；晨起仍觉胸膈满闷，咳痰清稀色白、量少易咯，口不渴，喜热饮，形寒怕冷，纳食欠佳，二便正常。查体：T 36.7℃，P 76次/分，R 18次/分，BP 128/78mmHg，SpO2 97%（未吸氧）；胸廓对称，双肺哮鸣音较入院时减少、以呼气相为主，呼气相延长，未闻及湿性啰音；舌质淡、苔白滑，脉弦紧。\n辅助检查回报：血常规WBC 6.5×10^9/L、N% 65%，嗜酸性粒细胞计数0.42×10^9/L，CRP 6mg/L，肝肾功能、电解质正常；心电图示窦性心律、正常心电图；胸部X线示双肺纹理增粗，未见实变及气胸；肺功能加支气管舒张试验、FeNO及过敏原检测待回报。\n执行情况：入院后按内科Ⅰ级护理，清淡温热饮食，已予吸氧2L/min、雾化吸入布地奈德2mg加沙丁胺醇5mg每日2次、茶碱缓释片0.2g每日2次口服，中药汤剂（射干麻黄汤加减）已服3剂，服后无恶心、心悸等不适，遵嘱执行。\n\n一、中医辨病辨证分析\n患者以「发作性喉中哮鸣伴呼吸急促1周」为主诉，发作时喉中哮鸣有声、呼吸急促、喘息不能平卧，缓解期如常人，呈反复发作性，「哮以声响言」，喉中水鸡声为特征性表现，故辨病为哮病。辨证依据：患者遇寒及接触冷空气、异味即诱发或加重，天冷易发，本次因夜间受凉起病；喉中哮鸣如水鸡声，胸膈满闷如塞，咳痰清稀色白量少，口不渴或喜热饮，形寒怕冷，面色少华；舌质淡、苔白滑，脉弦紧。此乃寒痰伏肺，遇感触发，痰升气阻，肺失宣降，气道挛急所致；寒为阴邪，故痰白清稀、口不渴、形寒怕冷；病已1周，反复发作耗伤肺气，故面色少华、精神欠振；舌淡苔白滑、脉弦紧皆寒痰内盛、肺气郁闭之征。四诊合参，当属冷哮（寒哮）证，兼肺气不足。病位在肺，涉及脾肾，病性属本虚标实、寒痰为患，以标实为主，发时当以攻邪治标为要。\n\n二、中医鉴别诊断\n1.与「热哮」鉴别：热哮为痰热壅肺，以气粗息涌、喉中痰鸣如吼、咳痰黄稠、口渴喜冷饮、身热汗出、舌红苔黄腻、脉滑数为主症，多在夏秋或感热而发。本案痰白清稀、口不渴而喜热饮、形寒怕冷、舌淡苔白滑、脉弦紧，一派寒象，与热哮之痰黄稠、舌红苔黄腻、脉滑数恰成对照，故可鉴别。\n2.与「喘证」鉴别：喘证以气息言，以呼吸困难、甚则张口抬肩、鼻翼扇动、不能平卧为主症，可见于多种急慢性疾病过程中，多无喉中鸣响之特征，且不具反复发作、间歇期如常人的特点。哮必兼喘，喘未必兼哮。本案喉中水鸡声鲜明，缓解期如常人，且发作与冷空气、异味刺激密切相关，是以声响为辨，当属哮病而非喘证。\n3.与「支饮」鉴别：支饮为饮邪留伏胸膈，症见咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病，常伴面浮肢肿、小便不利、颈静脉怒张。本案虽有倚息不得卧，但无水肿、无颈静脉怒张、小便通利、体重无增加，胸部X线未见胸腔积液，间歇期如常人，饮邪凌心射肺之证据不足，故可鉴别。\n4.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、心悸、面色晦暗为主症，病程缠绵、进行性加重，多见桶状胸及右心功能不全征象。本案胸廓对称、无桶状胸，无颈静脉怒张、无杵状指，缓解期如常人，暂不支持肺胀；惟久病反复发作者须动态观察，随访肺功能以监测有无气流受限不可逆进展。\n5.与「心源性喘息」之中医「心咳」「水气凌心」相类者鉴别：后者多有心悸、怔忡、下肢浮肿、夜间阵发性呼吸困难、咳吐粉红色泡沫痰，舌多紫暗、脉多沉细或结代。本案心率78次/分、律齐，心电图正常，无水肿及粉红色泡沫痰，可资鉴别。\n\n三、西医鉴别诊断\n1.与慢性阻塞性肺疾病急性加重鉴别：二者均以发作性喘息、呼气相延长及双肺哮鸣音为主要表现，均可因冷空气、异味诱发。但慢阻肺多见于中老年长期吸烟者，气流受限不完全可逆，肺功能FEV1/FVC＜0.70且舒张试验阴性，症状呈进行性加重。本案缓解期如常人、无长期吸烟史、无桶状胸，肺功能加支气管舒张试验待回报以资鉴别。\n2.与心源性哮喘鉴别：心源性哮喘多见于中老年心脏病患者，常于夜间阵发性发作，咳吐粉红色泡沫痰，双肺底湿啰音，可伴心脏扩大、颈静脉怒张、下肢水肿，血浆BNP升高。本案心电图正常、无心脏杂音、无颈静脉怒张及下肢水肿，可基本除外，必要时查心脏彩超及血浆BNP。\n3.与上气道阻塞、支气管异物及变应性支气管肺曲霉病鉴别：前者多表现为吸气性呼吸困难、喘鸣音以颈部为著、变换体位可缓解；异物多有明确呛咳史；后者常伴外周血嗜酸性粒细胞显著升高、总IgE明显升高及肺部游走性浸润影。本案为呼气相哮鸣、无呛咳史，胸部X线未见浸润影，必要时行支气管镜及血清总IgE、曲霉特异性IgE检查。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》与全球哮喘防治创议（GINA 2023）均明确指出：哮喘控制治疗以吸入性糖皮质激素（ICS）为基石，成人中重度患者推荐ICS加长效β2受体激动剂（LABA）联合制剂；急性发作期按需使用短效β2受体激动剂（SABA），中重度发作应尽早口服或静脉糖皮质激素（如泼尼松0.5~1.0mg/kg·d，疗程5~7天）。\n2.肺功能与气道炎症监测方面，指南推荐支气管舒张试验阳性（FEV1增加率≥12%且绝对值增加≥200ml）作为确诊可逆性气流受限的重要依据；呼出气一氧化氮（FeNO）与外周血嗜酸性粒细胞计数可作为嗜酸性气道炎症的替代标志物，≥2次检查提示嗜酸性表型者对抗炎治疗反应更佳，可作为调整ICS剂量的参考。\n3.中医药研究方面，《中医内科常见病诊疗指南·中医病证部分》推荐哮病冷哮（寒哮）发作期以温肺散寒、化痰平喘为法，主方射干麻黄汤或小青龙汤加减；近年的系统评价（纳入多项随机对照试验）提示，射干麻黄汤或小青龙汤联合西医常规治疗哮喘急性发作，在提高临床总有效率、改善FEV1及降低复发率方面优于单纯西药治疗，且未见严重不良反应报告。\n4.中西医结合管理方面，多项研究提示缓解期以益气健脾、补肺固肾（如玉屏风散、金匮肾气丸类方）配合穴位贴敷（三伏贴、三九贴）可减少哮喘急性发作次数、降低急诊就诊率；2022年国内相关共识亦提出哮喘应按表型分层、长期阶梯式管理，强调吸入装置正确使用与用药依从性教育是减少急性发作的关键环节。\n\n五、诊疗计划\n1.中医治疗：治法为温肺散寒、化痰平喘，兼以益气固本。方用射干麻黄汤加减。处方：射干9g、炙麻黄6g、桂枝9g、干姜6g、细辛3g、紫菀9g、款冬花9g、法半夏9g、紫苏子9g、白芥子6g、五味子6g（打碎）、黄芪15g、炒白术12g、大枣10g、炙甘草6g。用法：水煎服，每日一付，头煎加水500ml煎取200ml，二煎加水400ml煎取200ml，两煎混匀，分2次温服，早晚饭后服。麻黄先煎去上沫，细辛用量宜小、五味子打碎入煎。方解：方中炙麻黄、桂枝、细辛辛温发散、宣肺散寒，射干降气消痰、利咽散结，共为君药，以解寒痰闭肺、气道挛急之标；紫菀、款冬花润肺下气、化痰止咳，法半夏燥湿化痰、和胃降逆，紫苏子、白芥子降气豁痰、通利胸膈，共为臣药，助君药化痰平喘；干姜温肺化饮，五味子酸收敛肺、防辛散太过耗气，黄芪、炒白术益气健脾固本，取「培土生金」之意，共为佐药；炙甘草调和诸药、兼能化痰，大枣和中，共为使药。全方辛开苦降、散收并用，标本兼顾。另予中药雾化或穴位贴敷（肺俞、定喘、膻中、足三里）每日1次，每次4~6小时，以助温通经络、宣肺平喘。\n2.西医治疗：吸氧2L/min（必要时），维持SpO2≥95%；雾化吸入布地奈德2mg加沙丁胺醇5mg，每日2次（症状加重时可临时加1次）；茶碱缓释片0.2g，每日2次口服，餐后服，监测血药浓度及心率；孟鲁司特钠10mg，每晚1次口服，睡前服（抗白三烯、减轻气道炎症）；若肺功能证实可逆性气流受限，改为布地奈德福莫特罗吸入剂160/4.5μg，每次1吸、每日2次，吸后漱口。监测：每日早晚峰流速（PEF）并记录，监测血压（患者有高血压病，服药控制，避免茶碱与麻黄类制剂叠加致心率增快、血压升高）、心率及血钾；完善肺功能加支气管舒张试验、FeNO、血清总IgE及过敏原检测、动脉血气分析、胸部CT（必要时）。\n3.护理与调摄：饮食宜温热清淡，忌冰饮、西瓜、螃蟹等寒凉生冷及肥甘厚味，忌虾蟹等已知致敏食物，可食生姜、山药、大枣、白果（适量），每日食盐＜5g；起居注意颈背部及双足保暖，遇冷空气外出戴口罩，室温保持20~24℃，避免空调直吹及接触油烟、香水、花粉、尘螨等刺激物；情志宜舒畅，避免紧张焦虑诱发气道痉挛，可听音乐、练放松功；功能锻炼行缩唇呼吸及腹式呼吸操，每日2次、每次10~15分钟，以不喘为度，缓解期可练八段锦。\n4.医患沟通：已向患者及家属交代病情，说明本例属哮病冷哮（寒哮）急性发作，西医考虑支气管哮喘急性发作期（轻度），本次治疗以温肺散寒、化痰平喘中药配合吸入激素及支气管舒张剂为主，预计3~7天症状可明显缓解，但哮病有反复发作、难以根治的特点，缓解期需坚持中药调理与规范吸入治疗；强调勿自行停药减量，随身携带沙丁胺醇气雾剂，早晚记录峰流速；告知中药汤剂需温服、忌生冷，服药期间如出现心悸、手抖、恶心等不适及时告知医护人员；出现喘息持续不缓解、口唇发紫、说话不成句、大汗或神志改变时立即呼叫医护人员或拨打120。家属表示理解并配合。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，主诉症状较前略有改善，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体同前。继续当前中药治疗方案。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，主诉症状较前明显好转，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。继续当前治疗。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。患者病情平稳，继续巩固治疗，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为哮病（冷哮），病情平稳，需住院进一步检查治疗。\n2.诊疗方案：完善相关检查，中医辨证论治，中药汤剂口服，对症支持治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应等。\n4.注意事项：注意休息，清淡饮食，配合检查治疗。\n5.预后情况：经积极治疗后预后较好。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：哮病（冷哮）\n西医诊断：相关疾病\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，女，58岁，因\"反复哮病（冷哮）相关症状加重1周。\"入院。入院查体：生命体征平稳，心肺腹查体未见明显异常。中医四诊：舌质淡，苔薄白，脉细弱。\n\n诊疗经过：\n入院后完善相关检查，明确中医诊断，给予辨证论治，中药汤剂口服，对症支持治疗，患者病情逐渐好转，症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。查体：生命体征平稳。\n出院医嘱：1. 饮食：低盐低脂清淡饮食，戒烟限酒。\n2. 休息与活动：注意休息，避免劳累，适当活动，循序渐进。\n3. 用药：按医嘱规律服药，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后1-2周门诊复查，如有病情变化随时就诊。\n5. 注意事项：监测血压、血糖等指标，保持良好生活习惯，遵医嘱定期随访。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，主诉症状较前改善，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 125/78mmHg。神志清楚，精神可。舌质淡红，苔薄白，脉弦细。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。专科情况较前有所改善。\n辅助检查：相关检查结果回报，较前有所好转。\n四诊合参，本病属中医\"哮病（冷哮）\"范畴，辨证论治，随证加减。患者经中药辨证论治后，症状较前改善，治疗有效。继续目前中药治疗，注意观察病情变化，随证加减。注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，主诉症状明显改善，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 74次/分，R 18次/分，BP 124/76mmHg。神志清楚，精神好。舌质淡红，苔薄白，脉和缓。双肺呼吸音清，心率74次/分，律齐。腹软，无压痛。专科情况明显改善。\n辅助检查：复查相关指标正常或较前明显改善。\n患者经中药辨证论治后，症状明显改善，病情稳定。继续目前治疗，巩固疗效。今日可出院。建议出院后继续服用中药调理，定期复诊，注意休息，清淡饮食，避免劳累及情志刺激，适当锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月17日 10:00（入院第3天）\n\n今日李主任医师查房。患者神志清楚，精神明显好转，诉昨夜无憋醒，喉中哮鸣基本消失，胸膈满闷减轻，咳痰减少、痰白易咯，口不渴，畏寒较前减轻，纳食渐增，二便调。查体：T 36.6℃，P 74次/分，R 17次/分，BP 126/76mmHg，SpO2 98%（未吸氧）；双肺哮鸣音明显减少、仅偶闻及散在干啰音，呼气相延长较前改善；舌质淡、苔白滑较前转薄，脉弦紧之势已缓、兼见细象。\n辅助检查回报：肺功能示FEV1占预计值78%，支气管舒张试验阳性（FEV1增加率15%、绝对值增加260ml）；FeNO 46ppb；血清总IgE 210IU/ml，尘螨及冷空气相关过敏原检测阳性；动脉血气分析（未吸氧）pH 7.40、PaO2 88mmHg、PaCO2 38mmHg，未见二氧化碳潴留；胸部CT未见肺炎、气胸、胸腔积液及占位。\n执行情况：中药汤剂已服5剂，症状缓解顺利，无不良反应；雾化、口服茶碱及孟鲁司特钠遵嘱执行，峰流速较入院时上升约18%。\n\n一、中医辨病辨证分析\n本例辨病为哮病，辨证为冷哮（寒哮）证，兼肺脾气虚，此点再予确认。依据在于：病因上，患者遇寒及冷空气、异味即诱发，天冷易发，属寒邪引动伏痰；症候上，喉中哮鸣如水鸡声、呼吸急促、胸膈满闷如塞、咳痰清稀色白、口不渴或喜热饮、形寒怕冷；舌脉上，舌质淡、苔白滑，脉弦紧。病机为寒痰伏肺，遇感触发，痰升气阻，肺失宣降，气道挛急。经温肺散寒、化痰平喘治疗后，哮鸣消失、苔白滑转薄、弦紧之脉转缓，说明寒痰渐化、肺气得宣，治疗方向正确。但脉兼细象、面色仍少华、纳食未复，提示病已1周、反复发作，肺气已伤、脾运未健，本虚之象显露。故本病属本虚标实，发作期以寒痰标实为主，缓解期以肺脾气虚为本，治当「发时治标、平时治本」，下一步须由温散为主逐步转入温补兼施，不可一味辛散耗气。\n\n二、中医鉴别诊断\n1.与「虚喘」鉴别：虚喘以呼吸短促难续、声低气怯、动则喘甚、深吸为快为特点，多无喉中鸣响，病程长而呈持续性加重，常伴自汗、畏风、腰膝酸软，舌淡脉弱。本例喘息呈发作性、以喉中哮鸣为特征、间歇期如常人，虽兼气虚但脉弦紧仍在，属「实中夹虚」，与纯虚喘之持续气短、动则尤甚不同，故可鉴别。\n2.与「肺痿」鉴别：肺痿为肺叶痿弱不用，以咳吐浊唾涎沫、气短、形体消瘦、皮毛干枯为主症，多由久病耗伤气阴或误治而成，舌红少津、脉虚数。本例痰清稀量少而非浊唾涎沫，形体不瘦、皮毛润泽，舌淡苔白滑而非舌红少津，且呈发作性而非持续气短，故可鉴别。\n3.与「喉痹」「梅核气」鉴别：喉中如有物梗阻，但无呼吸急促、无呼气相延长、无哮鸣音，症状与情绪波动相关，咯之不出、咽之不下，查体两肺呼吸音清。本例确有明确双肺哮鸣音、呼气相延长且肺功能证实可逆性气流受限，Sound与气流受限俱在，故可鉴别。\n4.与「肾不纳气」之喘脱前期鉴别：肾不纳气见喘促日久、呼多吸少、气不得续、动则喘甚、汗出肢冷、面青唇紫、脉沉细欲绝。本例虽畏寒、脉兼细，但无面青唇紫、无汗出肢冷、无抬肩撷肚，血气分析无低氧及二氧化碳潴留，尚不属喘脱危候，惟须警惕，一旦出现上述征象立即按哮病危候抢救。\n\n三、西医鉴别诊断与疑难分析\n本例西医诊断支气管哮喘急性发作期（轻度）依据已充分：肺功能示FEV1占预计值78%、支气管舒张试验阳性（增加率15%、绝对值增加260ml），FeNO 46ppb、血清总IgE 210IU/ml及过敏原阳性，支持过敏性（嗜酸性）哮喘表型；血气分析无低氧及二氧化碳潴留，胸部CT无感染及气胸证据，心电图正常，心源性哮喘、慢阻肺急性加重、上气道阻塞及变应性支气管肺曲霉病均可除外。疑难之处在于：患者兼有高血压病，且长期使用麻黄类中药与茶碱制剂，须警惕心血管不良反应及药物相互作用；同时须明确既往哮喘控制水平低下（本次急性发作），缓解期如何分层管理、如何避免反复发作是诊疗关键。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》及GINA 2023明确提出：所有成人哮喘患者均应接受含吸入性糖皮质激素（ICS）的控制治疗，不推荐单用短效β2受体激动剂（SABA）；对过敏性（嗜酸性）表型且合并过敏性鼻炎者，可加用白三烯受体拮抗剂（孟鲁司特钠10mg每晚1次），有助于减少急性发作。本例FeNO 46ppb、血嗜酸性粒细胞升高，属抗炎治疗获益人群。\n2.哮喘急性发作严重程度评估与随访方面，指南推荐以症状、PEF、血氧饱和度及血气分析综合分级，轻度发作可在门诊或普通病房处理；并推荐以ACT评分（≥20分为控制良好）动态评估控制水平，强调吸入装置正确使用与依从性教育可显著降低急性发作与急诊就诊率。\n3.中医药研究进展方面，《中医内科常见病诊疗指南·中医病证部分》确立哮病冷哮以温肺散寒、化痰平喘为治疗大法；近年系统评价（纳入多项随机对照试验）显示，射干麻黄汤或小青龙汤联合西医常规治疗哮喘急性发作，在提高临床总有效率、改善FEV1、缩短哮鸣音消失时间方面优于单纯西药组；缓解期采用补肺健脾益肾方药（如玉屏风散、六君子汤、金匮肾气丸类）配合穴位贴敷，可减少急性发作次数。\n4.表型与精准治疗方面，2022年国内支气管哮喘相关共识提出按气道炎症表型（嗜酸性、非嗜酸性）分层治疗，FeNO与外周血嗜酸性粒细胞计数可作为无创监测指标；对控制不佳的第4~5级患者可考虑生物制剂（抗IgE、抗IL-5等），但须在专科评估后使用。本例属轻度、嗜酸性表型，暂不需生物制剂，以ICS加LABA阶梯治疗配合中医药调理为主。\n\n五、诊疗计划调整与下一步计划\n1.中医治疗调整：由单纯温散转为温肺化痰、益气健脾并重，方用射干麻黄汤合玉屏风散加减。处方：射干9g、炙麻黄5g、桂枝9g、干姜6g、细辛3g、紫菀9g、款冬花9g、法半夏9g、紫苏子9g、五味子6g（打碎）、黄芪20g、炒白术12g、防风9g、茯苓12g、陈皮6g、大枣10g、炙甘草6g。用法：水煎服，每日一付，两煎混匀取400ml，分2次温服，早晚饭后服；麻黄减至5g并先煎去上沫，细辛3g不宜久服，五味子打碎，共进7剂后复诊调方。方解：炙麻黄、桂枝、细辛辛温宣肺散寒为君；射干降气消痰利咽，紫菀、款冬花润肺下气化痰，法半夏、陈皮、茯苓（二陈汤意）燥湿化痰、健脾和胃，紫苏子降气豁痰，共为臣药；黄芪、炒白术、防风（玉屏风散）益气固表、健脾补肺，干姜温肺化饮，五味子酸收敛肺以防辛散耗气，共为佐药；炙甘草调和诸药、大枣和中，共为使药。全方散收兼施、标本同治，既化未尽之寒痰，又固已伤之肺脾。缓解期拟改服玉屏风散合六君子汤加减，并配合三伏贴、三九贴（肺俞、定喘、膻中、足三里、肾俞），每年各1疗程。\n2.西医治疗调整：症状已明显缓解，停雾化沙丁胺醇，改为布地奈德福莫特罗吸入剂160/4.5μg，每次1吸、每日2次，吸后漱口；布地奈德雾化减为每日1次、2mg，3天后停用；茶碱缓释片减为0.1g每日2次口服，餐后服，1周后视峰流速停用，监测心率、血压及血钾；孟鲁司特钠10mg每晚1次继续口服，疗程不少于4周；高血压病继续原降压方案，每日监测血压并记录。\n3.护理与调摄：继续清淡温热饮食，忌生冷寒凉及虾蟹等致敏之物，每日食盐＜5g；注意颈背部、双足保暖，外出戴口罩，居室勤除螨、通风，避免油烟、香水、花粉、冷空气直吹；保持情志舒畅，避免焦虑紧张；坚持缩唇呼吸、腹式呼吸操及八段锦，每日2次、每次10~15分钟，以不喘为度；指导正确使用吸入装置并复述演示。\n4.医患沟通：已向患者及家属说明本次治疗有效、哮鸣已基本消失、肺功能证实为可逆性气流受限，支持支气管哮喘诊断；同时强调本病难以根治、易反复发作，缓解期规范吸入激素与中药调理是减少发作的关键，切勿因症状缓解自行停药；交代中药需温服、忌生冷，服药期间出现心悸、手抖、失眠或血压升高应及时告知；预约出院后2周呼吸科门诊复诊、3个月复查肺功能及FeNO，并登记随访，如出现喘息持续不缓解、口唇发紫、说话不成句、大汗或神志改变立即就诊或拨打120。家属表示理解并配合。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1222,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4d9e0e7db6409117f116eda47ec7e26abb62a4963a60e00c3e1529cb352770c0","pinyin":"xiaobing（lengxiao）","initials":"xb（lx）","setting":"in","caseName":"病例1：患者，女，58岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，58岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-5e890faef4e6537fa755","key":"v1-c9ccc21dfe2a3058|templates-5e890faef4e6537fa755","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"哮病（寒包热哮）","category":"中医科","raw":{"name":"哮病（寒包热哮）","category":"中医科","case":{"case_name":"病例1：患者，女，45岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：女 年龄：45岁 民族：汉族\n婚姻：已婚 职业：小学教师 籍贯：本地\n入院时间：2026年08月18日 09:30 记录时间：2026年08月18日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：反复发作性喉中哮鸣有声、喘息气促10年余，加重伴恶寒发热、咳吐黄痰2天。\n\n现病史：患者于10年前因受凉后出现喉中哮鸣有声、呼吸气促，夜间及凌晨为甚，于当地医院诊断为「支气管哮喘」，经解痉平喘治疗（具体用药不详）后缓解。此后病情反复发作，每年发作3～5次，多于受凉、季节交替及接触冷空气后诱发，发作时喉中痰鸣、胸闷喘息，需吸入沙丁胺醇气雾剂方可缓解。平素缓解期坚持吸入沙美特罗替卡松粉吸入剂（50/250μg，每次1吸，每日2次），控制尚可。2天前因夜间开窗受凉，晨起即感恶寒、发热（自测体温38.2℃）、头痛、周身酸痛、无汗，随即出现咳嗽、气喘，喉中哮鸣有声，胸闷如塞，咳痰黄稠、量中、咯吐不爽，口渴欲饮，咽痛，无咯血、无胸痛、无夜间阵发性呼吸困难及端坐呼吸。自服「连花清瘟胶囊」「氨溴索口服液」2天，又吸入沙丁胺醇气雾剂3次，喘息稍减而恶寒发热未除，痰仍黄稠难咯，昨夜因喘息不能平卧、汗出而醒2次。今日晨起症状加重，遂来我院门诊就诊，门诊查血常规示WBC 11.2×10^9/L、N% 78.5%、嗜酸性粒细胞百分比6.8%，肺功能示FEV1占预计值72%、支气管舒张试验阳性，门诊以「哮病（寒包热哮）」收入我科。发病以来精神欠佳，食欲减退，夜寐差，二便调，体重无明显变化。\n\n既往史：既往有「支气管哮喘」病史10年余，「过敏性鼻炎」病史8年，对尘螨及冷空气过敏，青霉素皮试阳性（既往未使用）。否认肝炎、结核等传染病史。否认高血压、糖尿病、冠心病史。否认手术、外伤及输血史。否认食物药物过敏史（除青霉素外）。\n\n个人史及家族史：生于本地，久居本地，否认疫区及疫水接触史。无吸烟史，丈夫吸烟已嘱其避免室内吸烟；偶尔少量饮酒。家族中母亲有「支气管哮喘」病史。\n婚育史：24岁结婚，配偶体健，育有1子，子体健。\n月经史：14（3～5）/（28～30）2026年08月02日，经量中等，无痛经。\n\n体格检查：\nT 38.1℃，P 96次/分，R 24次/分，BP 118/74mmHg，SpO2 94%（未吸氧）。\n一般情况：神志清楚，精神欠佳，自主体位，查体合作，呼吸略促，无发绀。\n\n中医四诊：\n望诊：神志清楚，急性病容，面色少华而两颧微红，口唇略干，无紫绀；舌质红，苔薄白微黄。\n闻诊：语声略嘶，喉中可闻及轻度哮鸣音，咳声重浊，痰气腥而色黄，无异常口气。\n问诊：恶寒发热，无汗，头身疼痛，鼻塞流清涕，胸闷喘息，咳痰黄稠难咯，口渴欲饮，咽痛，纳差，夜寐不安，二便调。\n切诊：脉浮紧而数；虚里搏动应手，未扪及癥瘕痞块。\n\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，呼吸略促，肋间隙无明显增宽，双肺叩诊呈清音，双肺呼吸音粗，可闻及散在哮鸣音，呼气相延长，未闻及明显湿性啰音及胸膜摩擦音。心率96次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，双下肢无水肿。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n\n专科情况：\n望诊：呼吸略促，喉中痰鸣，面色少华而两颧微红，口唇略干；舌象：舌质红，苔薄白微黄；脉象：脉浮紧而数。专科查体：双肺呼吸音粗，可闻及散在哮鸣音，以呼气相为主，呼气相延长，未闻及湿性啰音；胸廓对称，无桶状胸；语音震颤正常。关键阴性体征：无端坐呼吸及三凹征，无口唇及甲床发绀，无颈静脉怒张，无肝颈静脉回流征阳性，双下肢无凹陷性水肿，无杵状指，无咯血及胸痛。\n\n辅助检查：\n门诊血常规：WBC 11.2×10^9/L，N% 78.5%，L% 15.2%，嗜酸性粒细胞百分比6.8%，Hb 126g/L，PLT 235×10^9/L。\n门诊肺功能：FEV1占预计值72%，FEV1/FVC 68%，支气管舒张试验阳性（吸入沙丁胺醇400μg后FEV1增加率15.2%，绝对值增加220ml）。\n门诊胸部X线：双肺纹理增粗，未见实变影及占位，心影大小正常，膈肌位置正常。\n门诊心电图：窦性心律，心率96次/分，大致正常心电图。\n\n初步诊断：\n中医诊断：哮病（寒包热哮）\n中医诊断依据：1.辨病依据：患者反复发作性喉中哮鸣有声、喘息气促10年余，夜间及凌晨为甚，每因受凉、季节交替及接触冷空气诱发，发作时需吸入解痉平喘药物方可缓解，缓解期如常人，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」的诊断要点，故辨病为哮病。2.辨证依据：①主症：恶寒发热、无汗、头身疼痛、鼻塞流清涕之表寒未解，同时见喉中哮鸣、胸闷如塞、喘息气促、咳痰黄稠量中、咯吐不爽、口渴欲饮、咽痛、两颧微红之痰热壅肺；②舌象脉象：舌质红，苔薄白微黄，脉浮紧而数；③病因病机：外感风寒束于肌表，卫阳被遏则恶寒发热无汗、头身疼痛、脉浮紧；素有痰热伏肺，又为风寒闭遏，热不得外泄，痰热壅阻气道则哮鸣喘促、咳痰黄稠、口渴咽痛；寒束于表、热壅于里，客寒包火，故舌红苔薄白微黄、脉浮紧而数。四诊合参，属寒包热哮之证（表寒里热、寒热错杂）。\n中医鉴别诊断：1.与「冷哮」鉴别：冷哮者喉中哮鸣如水鸡声，痰白而多泡沫，口不渴或渴喜热饮，形寒怕冷，天冷或受寒易发，舌苔白滑，脉弦紧或浮紧，无里热之象；本例虽见表寒，但痰黄稠、口渴欲饮、咽痛、两颧微红、舌红苔薄白微黄、脉数，显系里有痰热，非纯寒之冷哮，故辨为寒包热哮。2.与「热哮」鉴别：热哮者气粗息涌，喉中痰鸣如吼，胸高胁胀，咳痰黄稠，口渴喜冷饮，身热汗出，舌红苔黄腻，脉滑数，纯属痰热壅肺之里热证，而无恶寒发热、无汗、头身疼痛、脉浮紧等表寒见证；本例表寒未解，为寒热错杂之候，与纯热哮有别。3.与「喘证」鉴别：喘证以呼吸困难、甚则张口抬肩、鼻翼扇动、不能平卧为特征，见于多种急慢性疾病过程中，不具反复发作性；哮病必兼喉中哮鸣有声，反复发作、有诱因可循。「哮以声响言，喘以气息言」，哮必兼喘，本例喉中哮鸣与喘息并见，故归于哮病。4.与「支饮」鉴别：支饮者咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病而咳喘浮肿并见；本例无水肿、无颈静脉怒张、双下肢无凹陷性水肿，可资鉴别。\n西医诊断：支气管哮喘（急性发作期，中度）／过敏性鼻炎\n西医诊断依据：1.病史依据：反复发作性喘息、喉中哮鸣10年余，每年发作3～5次，有尘螨及冷空气过敏史、过敏性鼻炎病史8年、哮喘家族史，长期吸入沙美特罗替卡松（50/250μg，每日2次）控制；2.症状依据：2天前受凉后急性起病，恶寒发热（自测38.2℃）、无汗、头身疼痛、鼻塞流清涕，继之喘息气促、胸闷如塞、喉中哮鸣、咳痰黄稠咯吐不爽、口渴咽痛，夜间不能平卧；3.体征依据：T 38.1℃，P 96次/分，R 24次/分，BP 118/74mmHg，SpO2 94%（未吸氧），双肺呼吸音粗、可闻及散在哮鸣音、呼气相延长、未闻及湿性啰音，无三凹征及发绀；4.实验室依据：血常规WBC 11.2×10^9/L、N% 78.5%、E% 6.8%，提示感染诱发并伴嗜酸性粒细胞增多；5.肺功能依据：FEV1占预计值72%、FEV1/FVC 68%，支气管舒张试验阳性（吸入沙丁胺醇400μg后FEV1增加率15.2%、绝对值增加220ml），符合可逆性气流受限；6.影像学依据：胸部X线示双肺纹理增粗，未见实变影及占位，心影大小正常，除外肺炎、气胸及心源性因素。综上符合支气管哮喘急性发作期（中度），合并过敏性鼻炎。\n西医分型/分级/分期：①疾病分期：急性发作期（慢性持续期基础上的急性加重）；②急性发作严重程度分级：中度——讲话成句、喜坐位、呼吸频率24次/分（20～30次/分）、心率96次/分（100～120次/分区间邻近）、未吸氧SpO2 94%（90%～95%）、可闻及散在哮鸣音、无三凹征及意识改变，FEV1占预计值72%（60%～80%区间），符合中度急性发作标准；③气流受限程度：阻塞性通气功能障碍（FEV1占预计值72%、FEV1/FVC 68%），支气管舒张试验阳性，属可逆性气流受限；④气道炎症表型：感染诱发的嗜酸性粒细胞性哮喘（血E% 6.8%、WBC及N%升高提示合并呼吸道感染）；⑤病情严重程度（慢性持续期）分级：第3级（中度持续），长期吸入ICS/LABA（沙美特罗替卡松50/250μg，每日2次）控制；⑥合并症：过敏性鼻炎（8年）、青霉素过敏；⑦控制水平：未控制（近2天夜间憋醒2次、需反复使用缓解药物）。\n\n诊疗计划：\n1.按内科Ⅱ级护理，半流质清淡饮食，卧床休息，病室宜温暖避风，避免冷空气及异味刺激；2.完善检查：胸部CT+动脉血气分析（目的：评估肺部感染及气道病变、明确缺氧与二氧化碳潴留程度，为病情分级与氧疗提供依据）、过敏原检测+血清总IgE及特异性IgE（目的：明确过敏诱因与变态反应水平，为环境规避和抗炎方案提供依据）、血清皮质醇（目的：评估肾上腺皮质功能，为全身激素使用及减量方案提供依据）、肝肾功能+电解质（目的：评估全身激素与平喘药物使用的安全性，及时发现低钾等紊乱）、痰涂片及痰培养（目的：明确合并感染病原菌，为抗感染用药提供依据）；3.一般治疗：鼻导管吸氧（2L/min）维持SpO2≥95%，必要时雾化吸入；4.药物治疗：解表散寒、清化痰热中药汤剂（小青龙加石膏汤加减）每日1剂，早晚温服；布地奈德混悬液1mg联合沙丁胺醇溶液2.5mg雾化吸入，每日2次；布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次；痰黄难咯者予氨溴索30mg每日3次口服，考虑存在细菌感染予阿奇霉素0.5g每日1次口服；5.病情观察：密切监测体温、呼吸、心率及SpO2，观察哮鸣音及痰量痰色变化，注意有无呼吸衰竭及哮喘持续状态；6.健康教育：指导正确使用吸入装置、识别诱发因素、随身携带急救药物、记哮喘日记，必要时请呼吸内科会诊。\n\n医师签名：陈医生\n","首次病程记录":"首次病程记录\n\n2026年08月18日 12:00\n\n病例特点：\n1.患者，女，45岁，小学教师，因「反复发作性喉中哮鸣有声、喘息气促10年余，加重伴恶寒发热、咳吐黄痰2天」入院。\n2.既往有「支气管哮喘」病史10年余，「过敏性鼻炎」病史8年，对尘螨及冷空气过敏，青霉素皮试阳性；家族中母亲有哮喘病史。\n3.主要症状：恶寒发热，无汗，头身疼痛，鼻塞流清涕；喉中哮鸣有声，喘息气促，胸闷如塞，咳痰黄稠、量中、咯吐不爽，口渴欲饮，咽痛，纳差，夜寐不安，二便调。\n4.体格检查：T 38.1℃，P 96次/分，R 24次/分，BP 118/74mmHg，SpO2 94%（未吸氧）。神志清楚，精神欠佳，呼吸略促，无发绀。双肺呼吸音粗，可闻及散在哮鸣音，呼气相延长，未闻及湿性啰音；心率96次/分，律齐；腹软，无压痛；双下肢无水肿。\n5.中医四诊：面色少华而两颧微红，口唇略干；舌质红，苔薄白微黄；脉浮紧而数。\n6.辅助检查：血常规WBC 11.2×10^9/L、N% 78.5%、嗜酸性粒细胞百分比6.8%、Hb 126g/L；肺功能FEV1占预计值72%、FEV1/FVC 68%、支气管舒张试验阳性；胸部X线示双肺纹理增粗，未见实变影；心电图大致正常。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：哮病（寒包热哮）\n西医诊断：支气管哮喘（急性发作期，中度）／过敏性鼻炎\n\n（二）中医诊断依据：\n1.辨病依据：患者反复发作性喉中哮鸣有声、喘息气促10年余，夜间及凌晨为甚，每因受凉、季节交替及冷空气诱发，发作时吸入解痉平喘药物可缓解，缓解期如常人，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，故辨病为哮病。\n2.辨证依据：①表寒未解：恶寒发热（38.2℃）、无汗、头身疼痛、鼻塞流清涕、脉浮紧；②里有痰热：喉中哮鸣、胸闷如塞、喘息气促、咳痰黄稠量中咯吐不爽、口渴欲饮、咽痛、两颧微红；③舌象脉象：舌质红、苔薄白微黄、脉浮紧而数。风寒束表，卫阳被遏则恶寒发热无汗；素有痰热伏肺，复为风寒闭遏，热不得外泄，痰热壅阻气道则哮鸣喘促、咳痰黄稠、口渴咽痛。寒束于表、热壅于里，客寒包火，四诊合参，当属寒包热哮之证。\n3.治法方药：治以解表散寒、清化痰热，方用小青龙加石膏汤加减（麻黄9g、桂枝9g、白芍9g、细辛3g、干姜6g、法半夏9g、五味子6g打碎、生石膏30g先煎、炙甘草6g）；痰黄稠加黄芩10g、鱼腥草30g、瓜蒌皮15g，喘甚加地龙10g、葶苈子9g包煎，发热咽痛加金银花15g、连翘12g、牛蒡子9g。\n依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·哮病·寒包热哮证；《金匮要略·肺痿肺痈咳嗽上气病脉证治》「咳而上气，烦躁而喘，脉浮者，心下有水，小青龙加石膏汤主之」。\n\n（三）中医鉴别诊断：\n1.与「冷哮」鉴别：冷哮者喉中哮鸣如水鸡声，痰白多泡沫，口不渴或渴喜热饮，形寒怕冷，舌苔白滑，脉弦紧或浮紧，无里热之象；本例虽见表寒，但痰黄稠、口渴欲饮、咽痛、两颧微红、舌红苔薄白微黄、脉数，显系里有痰热，非纯寒之冷哮。\n2.与「热哮」鉴别：热哮者气粗息涌、喉中痰鸣如吼、胸高胁胀、咳痰黄稠、口渴喜冷饮、身热汗出、舌红苔黄腻、脉滑数，纯属痰热壅肺之里热证；本例兼见恶寒发热、无汗、头身疼痛、脉浮紧之表寒未解，为寒热错杂之候。\n3.与「喘证」鉴别：喘证以呼吸困难、张口抬肩、鼻翼扇动、不能平卧为特征，见于多种急慢性疾病过程中，不具反复发作性；哮病必兼喉中哮鸣有声，反复发作、有诱因可循。「哮以声响言，喘以气息言」，哮必兼喘，本例喉中哮鸣与喘息并见，故归于哮病。\n4.与「支饮」鉴别：支饮者咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病而咳喘浮肿并见；本例无水肿、无颈静脉怒张，双下肢无凹陷性水肿，可资鉴别。\n提示：若见喘息持续不解、汗出肢冷、面青唇紫、神昏烦躁者，为哮病危候（哮喘持续状态、呼吸衰竭），须立即抢救并请上级医师查房。\n\n（四）西医诊断依据：\n1.病史依据：反复发作性喘息、喉中哮鸣10年余，每年发作3～5次，有尘螨及冷空气过敏史、过敏性鼻炎8年、哮喘家族史，长期吸入沙美特罗替卡松（50/250μg，每日2次）。\n2.症状依据：受凉后急性起病，恶寒发热、无汗、头身疼痛、鼻塞流清涕，继之喘息气促、胸闷、喉中哮鸣、咳黄稠痰、口渴咽痛，夜间不能平卧。\n3.体征依据：T 38.1℃，P 96次/分，R 24次/分，BP 118/74mmHg，SpO2 94%（未吸氧），双肺呼吸音粗、散在哮鸣音、呼气相延长、无湿性啰音，无三凹征及发绀。\n4.实验室依据：血常规WBC 11.2×10^9/L、N% 78.5%、E% 6.8%，提示感染诱发并伴嗜酸性粒细胞增多。\n5.肺功能依据：FEV1占预计值72%、FEV1/FVC 68%，支气管舒张试验阳性（FEV1增加率15.2%、绝对值增加220ml），符合可逆性气流受限。\n6.影像学依据：胸部X线示双肺纹理增粗，未见实变影及占位，心影大小正常，除外肺炎、气胸及心源性因素。\n综上，符合支气管哮喘急性发作期（中度），合并过敏性鼻炎。\n\n（五）西医分型/分级/分期：\n①疾病分期：急性发作期（慢性持续期基础上的急性加重）。②急性发作严重程度分级：中度（呼吸频率24次/分、心率96次/分、SpO2 94%、双肺散在哮鸣音、无三凹征及意识改变，FEV1占预计值72%，符合中度标准）。③气流受限程度：阻塞性通气功能障碍（FEV1占预计值72%、FEV1/FVC 68%），支气管舒张试验阳性，属可逆性气流受限。④气道炎症表型：感染诱发的嗜酸性粒细胞性哮喘。⑤病情严重程度（慢性持续期）分级：第3级（中度持续），长期吸入ICS/LABA控制。⑥控制水平：未控制（夜间憋醒、需反复使用缓解药物）。⑦合并症：过敏性鼻炎（8年）、青霉素过敏。\n\n（六）西医鉴别诊断：\n1.社区获得性肺炎：\n【支持点】本例有恶寒发热（T 38.1℃）、咽痛、咳黄稠痰，血WBC 11.2×10^9/L、N% 78.5%升高，喘息可由肺部感染诱发，故须与肺炎所致喘息鉴别。\n【不支持点】双肺闻及散在哮鸣音、呼气相延长而未闻及湿性啰音，胸部X线仅见双肺纹理增粗、未见实变影；患者有10年反复发作性喘息史，发作多由尘螨、冷空气诱发，支气管舒张试验阳性（改善率15.2%），符合可逆性气流受限特征。\n【排除方法】复查血常规、C反应蛋白、降钙素原，完善胸部CT及痰涂片、痰培养；胸部CT无新发浸润影、且喘息经解痉平喘治疗迅速缓解者不支持肺炎。\n2.慢性阻塞性肺疾病急性加重：\n【支持点】两者均表现为喘息、气促、哮鸣音及呼气相延长，呼吸道感染可为共同诱因。\n【不支持点】患者45岁女性，无吸烟及生物燃料接触史；既往喘息呈发作性、间歇期如常人，FEV1占预计值72%、FEV1/FVC 68%，支气管舒张试验阳性，气流受限可逆，不符合慢性阻塞性肺疾病不完全可逆的气流受限特点。\n【排除方法】依据肺功能及支气管舒张试验结果、起病年龄、吸烟史及症状持续性判断；慢性阻塞性肺疾病须FEV1/FVC＜70%且舒张后气流受限仍不完全可逆。\n3.急性左心衰竭（心源性哮喘）：\n【支持点】急性左心衰竭可表现为夜间阵发性呼吸困难、端坐呼吸及双肺哮鸣音，需与支气管哮喘急性发作鉴别。\n【不支持点】本例无高血压、冠心病、心脏瓣膜病等基础心脏病史，无粉红色泡沫痰、颈静脉怒张及双下肢水肿，各瓣膜听诊区未闻及病理性杂音及奔马律，心电图大致正常。\n【排除方法】查心脏彩超、血浆BNP/NT-proBNP及心电图；BNP正常、心脏结构及功能无异常且无心衰体征者可除外。\n4.肺栓塞：\n【支持点】肺栓塞可突发呼吸困难、气促、胸闷，可伴低氧血症与哮鸣音，须与急性发作期支气管哮喘鉴别。\n【不支持点】本例有明确受凉诱因及上呼吸道感染前驱表现，发热38.1℃伴咳黄稠痰，无胸痛咯血、晕厥及单侧下肢肿胀，SpO2 94%仅轻度下降，无制动及血栓高危因素。\n【排除方法】查D-二聚体、动脉血气分析、心电图及CT肺动脉造影；D-二聚体阴性且无高危因素者可基本除外。\n5.上气道阻塞（气管异物、气管肿瘤、声带功能障碍）：\n【支持点】均可出现喘鸣与呼吸困难，易与支气管哮喘混淆。\n【不支持点】上气道阻塞多为吸气性喘鸣、以颈部为著，常伴声音嘶哑及吸气性三凹征；本例喘鸣为呼气相、双肺广泛分布，且对支气管舒张剂治疗反应良好。\n【排除方法】查颈胸部CT、支气管镜及肺功能流速-容量环（吸气相平台样改变提示固定型上气道阻塞）。\n6.自发性气胸：\n【支持点】可突发呼吸困难及患侧呼吸音减低，需与支气管哮喘急性发作鉴别。\n【不支持点】本例双肺对称闻及散在哮鸣音，无突发撕裂样胸痛及单侧呼吸音消失，气管居中，无皮下气肿。\n【排除方法】急查胸部X线或胸部CT，未见气胸线及肺压缩带即可除外。\n\n（七）诊疗计划：\n诊疗计划：\n1.护理与饮食：按中医科肺系病证（哮病）护理常规，内科Ⅱ级护理；半流质清淡饮食，忌辛辣煎炸、羊肉狗肉等助热之品，亦忌冰饮冷食再伤表阳，多饮温开水，可食梨、白萝卜、冬瓜；卧床休息，病室温暖避风，避免冷空气及异味刺激，出汗后及时擦干更衣。\n2.完善检查：①复查血常规、C反应蛋白及降钙素原（目的：动态评估感染程度与炎症反应，为是否加用抗菌药物提供依据）；②完善胸部CT（目的：除外肺炎、气胸、胸腔积液及肺不张，为喘息病因鉴别提供依据）；③完善动脉血气分析（目的：评估氧合及有无二氧化碳潴留，为氧疗及急性发作严重程度判定提供依据）；④完善痰涂片、痰培养及药敏试验（目的：明确有无细菌感染及致病菌种类，为抗菌药物选择提供依据）；⑤完善肺功能加支气管舒张试验及呼出气一氧化氮测定（目的：客观评估气流受限可逆性与气道炎症水平，为确诊支气管哮喘及调整吸入激素剂量提供依据）；⑥完善血清总IgE、特异性IgE及过敏原检测（目的：明确致敏原，为环境规避及特异性免疫治疗提供依据）；⑦完善心电图、心脏彩超及血浆BNP（目的：除外心律失常及心源性哮喘，为鉴别心源性喘息提供依据）；⑧完善肝肾功能、电解质及血糖（目的：评估用药安全性与内环境状态，为茶碱、糖皮质激素等药物剂量调整提供依据）；\n3.西医治疗：①氧疗：鼻导管吸氧2L/min，维持SpO2≥95%，夜间及活动后复测；②雾化吸入：布地奈德混悬液1mg联合沙丁胺醇溶液2.5mg雾化吸入，每日2次，雾化后漱口并清洗面部；③吸入维持：布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次，吸入后立即漱口；④抗感染：阿奇霉素片0.5g 每日1次口服（餐后服），连用3～5日后依痰色痰量及炎症指标决定是否停用；⑤祛痰：氨溴索片30mg 每日3次口服；⑥退热对症：体温≥38.5℃时予布洛芬混悬液0.2g 口服，必要时，两次间隔不少于6小时，热退即停；⑦监测与对症处理：每日测体温3次，记录痰量痰色，每日晨起及睡前测峰流速并记录哮喘日记，动态复查血常规、C反应蛋白，复查动脉血气分析评估氧合，复查肺功能加支气管舒张试验；若喘息持续不解、SpO2＜92%，加用注射用甲泼尼龙琥珀酸钠40mg 静脉滴注 每日2次，必要时予无创正压通气。\n4.中医治疗：四诊合参，患者素有痰热伏肺，复感风寒，寒束于表、热壅于里，属寒包热哮之证，治以解表散寒、清化痰热为主，兼以益气生津、止咳平喘为治则；方选小青龙加石膏汤加减（《金匮要略》），中药处方如下：麻黄6g 桂枝6g 白芍12g 细辛3g 干姜6g 法半夏9g 五味子6g（打碎） 生石膏30g（先煎） 炙甘草6g 杏仁9g 黄芩9g 桑白皮12g 瓜蒌皮12g 射干9g 鱼腥草30g 地龙9g 太子参15g。用法：水煎服，每日1付（剂），头煎加水500ml煎取200ml，二煎加水400ml煎取200ml，两煎混合后分2次温服，早晚饭后半小时各服1次。随症加减：痰黄稠难咯者加金荞麦30g、浙贝母9g；咽痛者加牛蒡子9g、桔梗6g；喘息甚者加葶苈子9g（包煎）、苏子9g；汗多者麻黄减至3g、加浮小麦30g；口干乏力明显者加麦冬12g、南沙参15g。方解：方中麻黄发汗解表、宣肺平喘，桂枝解肌发表、温通经脉、助麻黄以散表寒，二者为君，使表寒得解、肺气得宣；生石膏辛甘大寒，清泄肺胃里热，用量倍于麻黄，辛温辛寒相配，变辛温发散为辛凉清宣，为治寒包热哮之关键，与黄芩、桑白皮、鱼腥草、瓜蒌皮共为臣药，清化痰热、宽胸利气；细辛、干姜温肺化饮、助君药散寒，五味子敛肺止咳、防辛散耗气，白芍养血敛阴、与桂枝调和营卫，法半夏燥湿化痰、降逆止咳，射干、杏仁宣降肺气、利咽止咳，地龙清热通络、解痉平喘，太子参益气生津，共为佐药，散中有收、温中佐清；炙甘草调和诸药、止咳化痰，兼缓和麻桂发散之力，为使药。全方寒温并用、表里双解、散收结合，共奏解表散寒、清化痰热、宣肺平喘之效，切合寒包热哮、痰热未尽兼气阴耗伤之病机。\n5.密切观察病情变化，重点监测体温、呼吸、心率及SpO2，观察哮鸣音及痰量痰色变化，注意有无呼吸衰竭及哮喘持续状态；向家属交代目前病情，告知本病反复发作特点及急性发作期中度病情，注意防跌倒、防受凉，加强巡视与心理安抚，积极医患沟通，及时请上级医师查看病人，必要时请呼吸科会诊。\n\n医师签名：陈医生\n","主治医师查房记录":"主治医师查房记录\n\n2026年08月19日 09:00（入院第2天）\n\n今日张主治医师查房，患者神志清楚，精神较昨日好转，诉服中药1剂并雾化吸入后恶寒减轻，发热渐退（昨夜最高体温37.8℃），周身酸痛减轻，咳痰较前易咯，痰仍黄稠、量中，喘息气促较前减轻，夜间可平卧入睡，无端坐呼吸，无咯血胸痛，纳食渐增，二便调。\n查体：T 37.6℃，P 90次/分，R 22次/分，BP 116/72mmHg，SpO2 96%（鼻导管吸氧2L/min）。神志清楚，精神可，无发绀。舌质红，苔薄白微黄，脉浮紧而数较前稍缓。双肺呼吸音粗，可闻及少量散在哮鸣音，呼气相延长，未闻及湿性啰音。心率90次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查回报：动脉血气分析（未吸氧）pH 7.41，PaO2 76mmHg，PaCO2 36mmHg，SaO2 94%，提示轻度低氧血症、无二氧化碳潴留；C反应蛋白18mg/L；血清总IgE 486IU/ml；过敏原检测示尘螨（+++）、蟑螂（+）；胸部CT示双肺纹理增粗，未见实变及占位，心影纵隔未见异常；肝肾功能、电解质正常；痰培养未见致病菌生长。\n执行情况：遵嘱执行，中药汤剂每日1剂分2次温服，雾化吸入及吸入剂按时使用，阿奇霉素0.5g每日1次口服未中断，夜间及晨起监测峰流速并记录，无药物不良反应。\n\n一、中医辨病辨证分析\n患者以反复发作性喉中哮鸣有声、喘息气促10年余为主症，遇外感风寒引动而发，缓解期如常人，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，故辨病为哮病，属发作期。辨证为寒包热哮，目前处邪退正未复、痰热未尽之阶段。\n辨证依据：①表寒渐解而未净：恶寒已减、身痛已除，然仍微恶风、鼻塞流涕未全消，脉仍带浮紧之意，示风寒束表之势已折而未撤；②里有痰热未清：咳痰仍黄稠量中，喉中哮鸣虽减而未息，胸闷、口渴咽干、两颧微红仍在，舌质红、苔薄白微黄；③兼气阴耗伤：发热汗出、咳喘气促日久，纳食虽增而仍觉乏力口干，为热盛伤津、壮火食气之象；④脉由浮紧而数转为弦滑略数，是表寒渐解、痰热依然壅肺之征。\n病机分析：患者宿有痰热伏肺，复因外感风寒，寒束于表、热壅于里，客寒包火，肺失宣降，痰随气升、气因痰阻，搏结壅塞气道，故见喉中哮鸣、喘息气促；治以解表散寒、清化痰热，寒温并用、表里双解，今表寒已十去七八，痰热壅肺尚未尽化，兼有气阴两伤。舌脉与症状相符，辨证与病机一致，诊断明确。\n\n二、中医鉴别诊断\n1.与「喘证」鉴别：喘证以呼吸困难、张口抬肩、鼻翼扇动、甚则不能平卧为特征，可见于多种急慢性疾病过程中，多无反复发作性及明确诱因，亦不必兼有喉中哮鸣；哮病则以喉中哮鸣有声为必具主症，反复发作、有诱因可循，「哮以声响言，喘以气息言」，哮必兼喘而喘未必兼哮。本案闻诊喉中可闻及哮鸣音，问诊有受凉、季节交替、冷空气等明确诱因及10年反复发作史，故辨为哮病而非喘证，治当以宣肺化痰平哮为主，而非单纯降气平喘。\n2.与「冷哮」鉴别：冷哮为寒痰伏肺，发作时喉中哮鸣如水鸡声，痰白而多泡沫、清稀易咯，口不渴或渴喜热饮，形寒怕冷、面色晦滞，舌苔白滑，脉弦紧；本案痰黄稠难咯、口渴欲饮、咽痛、两颧微红、舌红苔薄白微黄而脉数，为里有痰热之明证，虽外有表寒，然非纯寒之冷哮，故不可专事温散，须石膏、黄芩、桑白皮清里热，寒温并调。\n3.与「热哮」鉴别：热哮为痰热壅肺，气粗息涌、喉中痰鸣如吼、胸高胁胀、咳痰黄稠胶黏、口渴喜冷饮、身热面赤汗出、不恶寒，舌红苔黄腻、脉滑数，纯属里热而无表证；本案兼见恶寒发热、无汗、头身疼痛、鼻塞流清涕、脉浮紧，表寒未解之象显然，属寒热错杂之寒包热哮，治须表里双解，若纯用清化则表寒闭遏、热无出路，纯用辛温则助热伤津。\n4.与「支饮」鉴别：支饮系饮停胸膈，症见咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病，常伴面浮肢肿、颈静脉怒张、肝颈静脉回流征阳性；本案双下肢无凹陷性水肿，无颈静脉怒张，无肝颈静脉回流征阳性，胸部CT心影纵隔未见异常，无胸水征象，饮水停聚之征不具，可资鉴别。\n5.与「肺胀」鉴别：肺胀为多种肺系疾病日久不愈、肺脾肾虚损、痰瘀阻结所致，以胸部膨满、憋闷如塞、桶状胸、唇甲发绀、病程绵长并进行性加重为特点；本案病程虽10年，然胸廓对称、无桶状胸、无杵状指、无发绀，缓解期如常人，肺功能提示可逆性气流受限，与肺胀之不可逆性改变不同。\n\n三、西医鉴别诊断\n1.与社区获得性肺炎鉴别：肺炎常以发热、咳嗽、咳脓痰为主，肺部可闻及湿性啰音，胸部影像可见片状实变影，抗感染后热退、啰音吸收；本案双肺闻及散在哮鸣音、呼气相延长而未闻及湿性啰音，胸部CT示双肺纹理增粗、未见实变及占位，痰培养未见致病菌生长，虽有WBC 11.2×10^9/L及C反应蛋白18mg/L轻度升高，结合支气管舒张试验阳性、过敏原强阳性及血IgE升高，仍以支气管哮喘急性发作（感染诱发）解释为主，然痰黄稠、炎症指标升高提示合并细菌感染，故继续阿奇霉素抗感染并观察痰色痰量。\n2.与心源性哮喘鉴别：心源性哮喘多见于中老年心衰患者，常于夜间阵发性呼吸困难、咳粉红色泡沫痰，查体可有心脏扩大、奔马律、双肺底湿性啰音、颈静脉怒张及双下肢水肿，BNP明显升高；本案无心脏病史，查体心律齐、无病理性杂音、无颈静脉怒张、双下肢无水肿，胸部CT心影大小正常，心脏彩超及血浆BNP无异常，故可除外。\n3.与慢性阻塞性肺疾病急性加重鉴别：慢阻肺多见于长期吸烟者，气流受限不完全可逆，肺功能示支气管舒张试验阴性，FEV1/FVC持续低于70%，胸部影像有肺气肿及桶状胸改变；本案无吸烟史，胸廓对称无桶状胸，支气管舒张试验阳性（FEV1增加率15.2%、绝对值增加220ml），提示可逆性气流受限，故不支持慢阻肺，但长期随访肺功能仍属必要。\n\n四、国内外相关疾病研究进展\n1.《中国支气管哮喘防治指南（2020年版）》与《支气管哮喘基层诊疗指南（2022年）》均强调，哮喘治疗以吸入性糖皮质激素（ICS）联合长效β2受体激动剂（LABA）为长期控制首选，急性发作期应短期全身应用糖皮质激素、按需使用短效β2受体激动剂，并推荐对所有患者进行吸入装置使用培训与吸入后漱口，以减少口咽念珠菌感染及声音嘶哑。\n2.GINA全球哮喘防治创议（2023年更新）提出，成人哮喘应按症状控制水平与急性加重风险进行分级管理，强调含ICS方案为所有成人和青少年哮喘的基础治疗，不推荐单用短效β2受体激动剂；对急性发作者建议在症状缓解后2～4周复诊评估控制水平并调整长期方案，与本例待病情稳定后复查肺功能、制定长期控制方案的计划一致。\n3.一项纳入数千例中重度嗜酸性粒细胞性哮喘患者的随机对照试验显示，抗IL-5/IL-5Rα单克隆抗体可使哮喘急性发作率下降约50%，并减少口服糖皮质激素用量；另有系统评价提示，抗IgE单抗可显著降低重症过敏性哮喘的急性加重率，适用于血IgE升高、过敏原明确且控制不佳者。本例血清总IgE 486IU/ml、尘螨强阳性，若规范吸入治疗3～6个月后仍未控制，可考虑转变态反应科评估生物制剂或特异性免疫治疗。\n4.针对哮喘发作期的中医药研究，多项系统评价（如纳入数十项随机对照试验的小青龙汤类方治疗支气管哮喘的系统评价）提示，在常规西药基础上加用小青龙汤类方（寒包热哮加石膏）可提高临床总有效率、改善FEV1及降低复发率，且未见严重不良反应；另有关于射干麻黄汤、定喘汤治疗哮喘急性发作期的系统评价得出类似结论，然现有研究样本量偏小、方法学质量有限，仍需大样本、多中心随机对照试验进一步验证。此外，一项中药复方治疗哮喘缓解期（益气固表、健脾化痰法）的系统评价提示，中药联合ICS/LABA可减少急性加重次数、改善生活质量，可作为本例缓解期扶正固本的依据。\n\n五、诊疗计划\n1.中医治疗：治以解表散寒、清化痰热为主，兼以益气生津、止咳平喘，方用小青龙加石膏汤加减：麻黄6g、桂枝6g、白芍12g、细辛3g、干姜6g、法半夏9g、五味子6g（打碎）、生石膏30g（先煎）、炙甘草6g、杏仁9g、黄芩9g、桑白皮12g、瓜蒌皮12g、射干9g、鱼腥草30g、地龙9g、太子参15g。用法：水煎服，每日1付，头煎加水500ml煎取200ml，二煎加水400ml煎取200ml，两煎混合后分2次温服，早晚饭后半小时各服1次。随症加减：痰黄稠难咯者加金荞麦30g、浙贝母9g；咽痛者加牛蒡子9g、桔梗6g；喘息甚者加葶苈子9g（包煎）、苏子9g；汗多者麻黄减至3g、加浮小麦30g；口干乏力明显者加麦冬12g、南沙参15g。\n方解：方中麻黄发汗解表、宣肺平喘，桂枝解肌发表、温通经脉、助麻黄以散表寒，二者为君，使表寒得解、肺气得宣；生石膏辛甘大寒，清泄肺胃里热，用量倍于麻黄，辛温辛寒相配，变辛温发散为辛凉清宣，为治寒包热哮之关键，与黄芩、桑白皮、鱼腥草、瓜蒌皮共为臣药，清化痰热、宽胸利气；细辛、干姜温肺化饮、助君药散寒，五味子敛肺止咳、防辛散耗气，白芍养血敛阴、与桂枝调和营卫，法半夏燥湿化痰、降逆止咳，射干、杏仁宣降肺气、利咽止咳，地龙清热通络、解痉平喘，太子参益气生津，共为佐药，散中有收、温中佐清；炙甘草调和诸药、止咳化痰，兼缓和麻桂发散之力，为使药。全方寒温并用、表里双解、散收结合，切合寒包热哮、痰热未尽兼气阴耗伤之病机。\n2.西医治疗：①布地奈德混悬液1mg联合沙丁胺醇溶液2.5mg雾化吸入，每日2次，雾化后漱口并清洗面部；②布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次，吸入后立即漱口；③阿奇霉素0.5g每日1次口服（餐后服），连用3～5日后依痰色痰量及炎症指标决定是否停用；④氨溴索30mg每日3次口服祛痰；⑤鼻导管吸氧2L/min，维持SpO2≥95%，夜间及活动后复测；⑥监测与对症处理：每日测体温3次，记录痰量痰色，每日晨起及睡前测峰流速并记录哮喘日记，动态复查血常规、C反应蛋白，复查动脉血气分析评估氧合，复查肺功能加支气管舒张试验及呼出气一氧化氮评估气流受限可逆性与气道炎症水平，注意观察心悸、手抖、低钾、口咽念珠菌感染及声音嘶哑等药物不良反应。\n3.护理与调摄：①饮食：忌辛辣煎炸、羊肉狗肉等助热之品，亦忌冰饮冷食再伤表阳，宜半流质清淡饮食，多饮温开水，可食梨、白萝卜、冬瓜、百合以助清热化痰；②起居：卧床休息，病室温暖避风、湿度适中，避免冷空气、烟尘、香水等异味刺激，出汗后及时擦干更衣，防止再次受凉，热退乏力减轻后逐步下床活动；③情志：安心静养，勿因发热急躁焦虑，情绪平稳有利于气机调畅、退热平喘；④功能锻炼：急性期以卧床休息为主，缓解后指导缩唇呼吸与腹式呼吸训练，每次10～15分钟、每日2次，逐步增加散步等有氧活动，避免剧烈运动及冷空气刺激。\n4.医患沟通：已向患者及家属交代病情，说明本例为支气管哮喘急性发作（中度），中医属哮病之寒包热哮，目前经中西医结合治疗后恶寒发热已减、喘息哮鸣减轻、缺氧改善，治疗有效，病情总体可控；同时告知哮喘为慢性气道炎症性疾病，需长期规范吸入治疗，不可症状缓解即自行停药，否则易反复发作并致气道重塑、肺功能进行性下降；嘱咐患者及家属学会识别病情加重征象（喘息加重不能平卧、说话断续、口唇发紫、意识改变、峰流速明显下降），一旦出现立即呼叫医护人员；指导正确使用吸入装置、吸入后漱口、规律记录哮喘日记与峰流速，出院后2周呼吸科复诊、定期复查肺功能并评估控制水平，必要时转变态反应科行特异性免疫治疗。患者及家属表示理解并配合。\n\n主治医师查房分析：\n患者目前诊断明确。结合病史、症状、体征及辅助检查，诊断依据为：1.反复发作性喘息、喉中哮鸣10年余，有尘螨及冷空气过敏史、过敏性鼻炎8年及哮喘家族史；2.本次受凉后急性发作，初起见恶寒发热、无汗、头身疼痛、鼻塞流清涕，兼咳黄稠痰、口渴、咽痛；3.查体双肺散在哮鸣音、呼气相延长，未闻及湿性啰音，舌红苔薄白微黄、脉浮紧而数，现脉转弦滑略数；4.血常规WBC 11.2×10^9/L、N% 78.5%、E% 6.8%，血清总IgE 486IU/ml，过敏原尘螨（+++），肺功能呈阻塞性通气功能障碍、支气管舒张试验阳性，动脉血气示轻度低氧血症而无二氧化碳潴留，胸部CT未见实变。中医辨证为寒包热哮，目前表寒渐解、痰热未清、兼气阴耗伤，治以解表散寒、清化痰热，兼益气生津，方用小青龙加石膏汤加减，寒温并用、表里双解，与病机相符，故继续原方案并随症加减。\n注意事项：1.麻黄、桂枝辛温发散，须观察汗出情况，汗多者减量，防伤阴耗气；2.生石膏先煎，剂量视里热轻重调整，热退痰稀即减量；3.阿奇霉素继续口服，观察痰色痰量及胃肠道反应，疗程结束复查炎症指标；4.动态监测体温、呼吸、SpO2及哮鸣音变化，警惕夜间及凌晨哮喘加重及哮喘持续状态；5.严格掌握用药指征，防治心悸、手抖、口咽念珠菌感染、声音嘶哑等药物不良反应，指导吸入后漱口；6.加强医患沟通与哮喘防治教育，注意吸入装置使用方法；7.若出现喘息加重、发绀、意识改变等，及时调整治疗方案并请上级医师查房指导；症状缓解后复查肺功能并制定长期控制方案，评估出院指征。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月19日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转。恶寒发热减轻，昨夜最高体温37.8℃，周身酸痛减轻，喘息气促较前减轻，夜间可平卧，咳痰较易咯出，痰仍黄稠、量中，纳食渐增，二便调。\n查体：T 37.6℃，P 90次/分，R 22次/分，BP 116/72mmHg，SpO2 96%（吸氧2L/min）。舌质红，苔薄白微黄，脉浮紧而数。双肺呼吸音粗，可闻及少量散在哮鸣音，呼气相延长，未闻及湿性啰音。\n辅助检查：血气分析示轻度低氧血症，C反应蛋白18mg/L，过敏原示尘螨（+++），胸部CT未见实变。继续原中药汤剂及雾化吸入治疗，续观。\n\n【病程记录二】2026年08月20日 09:00（入院第3天）\n\n患者入院第3天，神志清楚，精神可。发热已退（体温36.8℃），恶寒、头身疼痛消失，鼻塞流涕缓解，喘息气促明显减轻，喉中哮鸣声偶闻，咳嗽较前减轻，咳痰转白、量减，口渴减轻，咽痛缓解，纳可，夜寐安，二便调。\n查体：T 36.8℃，P 84次/分，R 20次/分，BP 118/74mmHg，SpO2 97%（未吸氧）。舌质偏红，苔薄白，脉浮数转缓。双肺呼吸音略粗，可闻及少许哮鸣音，呼气相延长不明显。心率84次/分，律齐。腹软，无压痛。\n中药原方去细辛、干姜减量至3g，生石膏减至20g，续服；停阿奇霉素口服。患者病情平稳，治疗有效，续观。\n\n【病程记录三】2026年08月22日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好。无发热恶寒，无头身疼痛，无胸闷喘息，偶有单声咳嗽，痰少色白易咯，无口渴咽痛，纳可，夜寐安，二便调。\n查体：T 36.5℃，P 78次/分，R 18次/分，BP 120/76mmHg，SpO2 98%。舌质淡红，苔薄白，脉细缓。双肺呼吸音清，未闻及明显干湿性啰音。心率78次/分，律齐。腹软，无压痛。\n复查血常规：WBC 7.2×10^9/L，N% 62.4%，嗜酸性粒细胞百分比3.1%，均恢复正常；C反应蛋白4mg/L。复查肺功能：FEV1占预计值88%，FEV1/FVC 78%，较入院明显改善。患者病情稳定，症状基本缓解，中药改为玉屏风散合二陈汤加减益气固表、健脾化痰以善后，继续布地奈德福莫特罗吸入维持控制，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月18日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为哮病（寒包热哮），西医诊断为支气管哮喘（急性发作期，中度）／过敏性鼻炎。本次因受凉诱发，属外寒引动内热、寒热错杂之证，病情尚平稳，需住院进一步检查治疗。\n2.诊疗方案：完善胸部CT、动脉血气分析、过敏原及肺功能等检查；中医辨证论治，予解表散寒、清化痰热中药汤剂（小青龙加石膏汤加减）口服；西医予布地奈德联合沙丁胺醇雾化吸入、布地奈德福莫特罗吸入控制气道炎症，必要时抗感染治疗。\n3.可能风险：治疗过程中可能出现病情变化（喘息加重、哮喘持续状态、呼吸衰竭）、药物不良反应（心悸、手抖、口咽念珠菌感染、声音嘶哑）及药物过敏等。\n4.注意事项：注意休息，清淡饮食，忌食辛辣肥甘及生冷，避风寒、避免冷空气及尘螨等过敏原刺激；学会正确使用吸入装置，随身携带急救药物，坚持记哮喘日记。\n5.预后情况：哮病病程缠绵、易反复发作，经积极规范治疗本此发作预后良好，但需长期规范控制，定期随访。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月18日\n出院日期：2026年08月24日\n住院天数：7天\n\n入院诊断：\n中医诊断：哮病（寒包热哮）\n西医诊断：支气管哮喘（急性发作期，中度）／过敏性鼻炎\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，女，45岁，小学教师，因「反复发作性喉中哮鸣有声、喘息气促10年余，加重伴恶寒发热、咳吐黄痰2天」入院。入院时T 38.1℃，P 96次/分，R 24次/分，BP 118/74mmHg，SpO2 94%（未吸氧）；神志清楚，精神欠佳，呼吸略促，无发绀；双肺呼吸音粗，可闻及散在哮鸣音，呼气相延长；中医四诊：面色少华而两颧微红，口唇略干，舌质红、苔薄白微黄，脉浮紧而数。血常规示WBC 11.2×10^9/L、N% 78.5%、嗜酸性粒细胞百分比6.8%；肺功能示FEV1占预计值72%、支气管舒张试验阳性；胸部X线示双肺纹理增粗。\n\n诊疗经过：\n入院后完善相关检查，查动脉血气分析示pH 7.41、PaO2 76mmHg、PaCO2 36mmHg；C反应蛋白18mg/L，血清总IgE 486IU/ml，过敏原检测示尘螨（+++）；胸部CT示双肺纹理增粗，未见实变及占位；痰培养未见致病菌生长；肝肾功能、电解质正常。中医辨病辨证为哮病（寒包热哮），治以解表散寒、清化痰热，予小青龙加石膏汤加减（麻黄6g、桂枝9g、白芍12g、细辛3g、干姜6g、法半夏9g、五味子6g、生石膏30g先煎、炙甘草6g、杏仁9g、黄芩9g、桑白皮12g、瓜蒌皮12g、射干9g）每日1剂口服，并随症加减：痰黄稠加鱼腥草30g、金荞麦30g，咽痛加牛蒡子9g、桔梗6g；西医予布地奈德混悬液1mg联合沙丁胺醇溶液2.5mg雾化吸入每日2次、布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸每日2次、氨溴索30mg每日3次化痰、阿奇霉素0.5g每日1次抗感染，并予鼻导管吸氧。入院第3天体温正常，恶寒头身疼痛消失，痰转白量减，中药去细辛、干姜减量，生石膏减至20g，停阿奇霉素；入院第5天喘息、胸闷消失，仅偶有单声咳嗽，双肺未闻及干湿性啰音，复查血常规及C反应蛋白恢复正常，复查肺功能FEV1占预计值88%，中药改用玉屏风散合二陈汤加减益气固表、健脾化痰善后。患者病情逐渐好转，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神好，无发热恶寒，无头身疼痛，无喘息胸闷，偶有单声咳嗽，痰少色白易咯，无口渴咽痛，纳可，夜寐安，二便调。查体：T 36.5℃，P 78次/分，R 18次/分，BP 118/74mmHg，SpO2 98%（未吸氧）；舌质淡红，苔薄白，脉细缓；双肺呼吸音清，未闻及干湿性啰音；心率78次/分，律齐；腹软，无压痛；双下肢无水肿。\n\n出院医嘱：1. 饮食：清淡易消化饮食，忌食辛辣、肥甘厚味及生冷海鲜等易致敏食物，戒烟酒，避免被动吸烟。\n2. 休息与活动：注意休息，避免劳累与受凉，病室宜温暖避风；病情稳定后循序渐进进行散步、八段锦等锻炼，增强体质。\n3. 用药：继续服中药7剂（出院带药方：黄芪20g、白术12g、防风9g、陈皮9g、法半夏9g、茯苓15g、炙甘草6g、苏子9g、浙贝母9g、五味子6g），水煎温服，每日1剂，早晚分服；布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次长期维持，吸入后漱口；沙丁胺醇气雾剂随身携带，喘息发作时吸入1～2吸，如20分钟无缓解或短期内反复使用需立即就诊；勿自行停用吸入激素或减量。\n4. 复查：出院后1周门诊复查（2026年08月31日），复查肺功能、血常规及C反应蛋白；出院后1个月、3个月门诊随访，评估哮喘控制水平并调整长期治疗方案；不适随诊。\n5. 注意事项：避免接触尘螨、花粉、冷空气及刺激性气味等诱发因素，居室勤通风、勤晒被褥；规范正确使用吸入装置，坚持记录哮喘日记（含峰流速监测）；出现喘息加重、不能平卧、口唇发绀、意识改变等情况立即急诊就诊；过敏性鼻炎发作时同步治疗，必要时转呼吸内科或变态反应科进一步诊治。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：哮病（寒包热哮）／支气管哮喘（急性发作期，中度）________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：过敏性鼻炎________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月20日 09:00（入院第3天）\n\n患者【已脱敏】，女，45岁，入院第3天，神志清楚，精神可。发热已退，恶寒、头身疼痛消失，鼻塞流涕缓解，喘息气促明显减轻，喉中哮鸣声偶闻，咳嗽较前减轻，咳痰转白、量减，口渴减轻，咽痛缓解，纳可，夜寐安，二便调。\n查体：T 36.8℃，P 84次/分，R 20次/分，BP 118/74mmHg，SpO2 97%（未吸氧）。神志清楚，精神可，无发绀。舌质偏红，苔薄白，脉浮数转缓。双肺呼吸音略粗，可闻及少许哮鸣音，呼气相延长不明显，未闻及湿性啰音。心率84次/分，律齐。腹软，无压痛，双下肢无水肿。\n辅助检查：血气分析示PaO2 76mmHg、PaCO2 36mmHg，轻度低氧血症，无二氧化碳潴留；C反应蛋白18mg/L；过敏原检测示尘螨（+++）；胸部CT未见实变及占位；痰培养未见致病菌生长。\n四诊合参，本病属中医「哮病（寒包热哮）」范畴，外寒渐解而里热未清，仍宗解表散寒、清化痰热之法，随证加减。患者经中药辨证论治配合雾化吸入治疗后，表证已解、痰热渐化，症状较前改善，治疗有效。前方去细辛，干姜减至3g，生石膏减至20g，续服；停阿奇霉素口服，继续布地奈德福莫特罗吸入控制气道炎症。注意观察病情变化，随证加减，监测体温、呼吸及SpO2，避风寒、忌辛辣肥甘，避免接触过敏原及冷空气刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿\n","病程记录第5天":"病程记录\n\n2026年08月22日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好。无发热恶寒，无头身疼痛，无胸闷喘息，偶有单声咳嗽，痰少色白易咯，无口渴咽痛，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 78次/分，R 18次/分，BP 120/76mmHg，SpO2 98%（未吸氧）。神志清楚，精神好。舌质淡红，苔薄白，脉细缓。双肺呼吸音清，未闻及明显干湿性啰音。心率78次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查：复查血常规WBC 7.2×10^9/L、N% 62.4%、嗜酸性粒细胞百分比3.1%，均恢复正常；C反应蛋白4mg/L；复查肺功能FEV1占预计值88%、FEV1/FVC 78%，较入院时明显改善。\n患者经中药辨证论治后，表里之邪已解，痰热已清，症状基本缓解，病情稳定，哮病缓解期当以扶正固本为要，中药改为玉屏风散合二陈汤加减益气固表、健脾化痰以善后，继续布地奈德福莫特罗吸入维持控制。今日可出院。建议出院后继续服用中药调理，坚持规范吸入治疗，定期复查肺功能，避免接触尘螨、冷空气等诱发因素，注意休息、清淡饮食，忌辛辣肥甘，随身携带急救药物，适当锻炼（如八段锦、呼吸操），增强体质，不适随诊。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿\n","主任医师查房记录":"主任查房记录\n\n2026年08月21日 10:00（入院第4天）\n\n今日李主任医师查房，患者目前神志清楚，精神好，无发热恶寒，无头身疼痛，喘息胸闷基本消失，偶有单声咳嗽，痰少色白易咯，纳可，二便调，夜寐安，活动后无气促，夜间无憋醒，峰流速较入院时明显回升。\n查体：T 36.6℃，P 80次/分，R 19次/分，BP 118/76mmHg，SpO2 97%（未吸氧）。无发绀，无颈静脉怒张。舌质偏红转淡、边有齿痕，苔薄白，脉浮数已缓、按之细弱。双肺呼吸音略粗，未闻及明显哮鸣音，呼气相延长不明显。心率80次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查回报：血气分析示轻度低氧血症、无二氧化碳潴留，现已恢复正常；C反应蛋白由18mg/L降至6mg/L；血常规WBC及中性粒细胞比例恢复正常；过敏原检测示尘螨（+++）；胸部CT未见实变及占位；肝肾功能、电解质正常。\n执行情况：遵嘱执行，中药已服6剂，雾化及吸入治疗规范使用，阿奇霉素已完成疗程，峰流速记录完整，无药物不良反应。\n\n一、中医辨病辨证分析（辨证要点再确认）\n本例为中年女性，哮病反复发作十余年，每因受凉、季节交替及冷空气诱发，今次因外感风寒引动宿痰而急性发作。经四诊复核，病名诊断哮病（发作期）成立，无异议。初诊辨证为寒包热哮，依据为表寒未解（恶寒发热、无汗、头身疼痛、鼻塞流清涕、脉浮紧）与里有痰热（痰黄稠、口渴咽痛、两颧微红、舌红苔薄白微黄、脉数）并见，属客寒包火、寒热错杂之候，小青龙加石膏汤寒温并用、表里双解，方证相符，故一剂即见恶寒减轻、发热渐退。\n今日再辨，证候已发生阶段性转化，不可仍守原方不变：①表寒已解——恶寒发热、头身疼痛、鼻塞流涕尽除，脉浮紧已去，辛温发散之品已无的放矢，麻黄、桂枝、细辛、干姜当减或去，过用则耗气伤阴；②痰热渐清而未净——痰已由黄稠转为少而色白易咯，哮鸣音基本消失，然偶有单声咳嗽，舌质偏红转淡，清化之品宜减量而不宜骤停，以免余邪复聚；③转为虚实夹杂、以虚为主——舌边有齿痕、脉按之细弱，结合病久反复发作、壮火食气、汗出伤津，示肺脾气虚、卫外不固兼气阴不足，此即「久病阴损及阳，气阴两虚」之渐。综合而言，当前证型由寒包热哮转为哮病缓解期之肺脾气虚、卫表不固证，兼余痰未清。病机为宿痰伏肺、脾虚生痰、肺虚卫外不固，易为外邪引动而反复，治当从「祛邪为主」转为「扶正为主、兼清余邪」，益气固表、健脾化痰，佐以活血通络。此为本次调整治法方药之根本理由。\n辨证要点提示：哮病之治，发时治标、平时治本。发作期重在辨寒热之偏与表里之兼，缓解期重在辨肺脾肾之虚与痰瘀之留着。本例病位在肺，涉及脾，尚未及肾（无动则喘甚、呼多吸少、腰膝酸软之候），故扶正以补肺健脾为主，暂不宜峻补肾阳。\n\n二、中医鉴别诊断\n1.与「喘证」鉴别：喘证以气息而言，临床特征是呼吸困难、张口抬肩、鼻翼扇动、不能平卧，常继发于多种急慢性疾病，多无反复发作性与明确诱因；哮病以声响而言，喉中哮鸣有声为必具主症，反复发作、有诱因可循，缓解期如常人。本案闻诊喉中哮鸣、问诊有受凉及冷空气等诱因、十余年反复发作且缓解期如常人，符合哮病特点；惟哮久可转为喘，若日后出现持续性气促、动则喘甚、呼多吸少，当考虑由哮转喘或合并肺胀，须复查肺功能并重新评估。\n2.与「冷哮」鉴别：冷哮为寒痰伏肺，发作时喉中哮鸣如水鸡声、呼吸急促，痰白而黏或多泡沫，面色晦滞带青，口不渴或渴喜热饮，形寒怕冷，舌苔白滑，脉弦紧；本案初起虽有表寒与鼻流清涕，然痰黄稠、口渴咽痛、舌红脉数，实为里有痰热，非纯寒之候，故取小青龙加石膏汤而非小青龙汤原方；今痰转白稀，亦不可径判为冷哮，因病久气虚、痰由热化转而为湿痰之象，须结合舌脉动态判断，不可据痰色一端定寒热。\n3.与「热哮」鉴别：热哮为痰热壅肺之里热实证，气粗息涌、喉中痰鸣如吼、胸高胁胀、咳痰黄稠胶黏、口渴喜冷饮、身热面赤汗出、不恶寒，舌红苔黄腻，脉滑数；本案全程有表寒未解之象，属寒热错杂，与热哮纯属里热者不同；且今热象已退、脉转细弱，更非热哮。若误辨为热哮而纯用寒凉，则脾阳受伐、痰湿愈盛，此为本病辨证最易致误之处。\n4.与「支饮」鉴别：支饮为饮停胸膈，症见咳逆倚息、短气不得卧、其形如肿，多继发于肺系久病而见咳喘浮肿并见，常伴颈静脉怒张、肝大、下肢凹陷性水肿；本案始终无水肿、无颈静脉怒张、无肝颈静脉回流征阳性，胸部CT心影纵隔正常、无胸水征象，饮邪停聚之证据不具，故不属支饮。\n5.与「肺胀」鉴别：肺胀多由久咳、久哮、久喘等肺系疾病迁延而成，以胸部膨满、憋闷如塞、桶状胸、唇甲发绀、病程绵长并进行性加重为特征，肺功能多呈不可逆性气流受限；本案胸廓对称、无桶状胸、无杵状指、无发绀，支气管舒张试验阳性提示气流受限可逆，缓解期如常人，与肺胀之器质性、不可逆改变有别，但仍需长期随访肺功能以防病进。\n6.与「鼻鼽」鉴别：鼻鼽以突然和反复发作的鼻痒、喷嚏、流清涕、鼻塞为特征，多无喘息哮鸣，属肺卫不固、风寒异气之邪侵袭鼻窍。本案既往有过敏性鼻炎8年，本次亦有鼻塞流清涕，然以喉中哮鸣、喘息气促为主症，鼻部症状仅为合并之候，故辨病仍以哮病为主，鼻鼽为兼病，治疗上宣肺通窍之品可兼用之。\n\n三、西医疑难分析与鉴别诊断\n本例西医诊断支气管哮喘急性发作期（中度）、合并过敏性鼻炎，依据充分，诊断无疑难。分析中须注意三点：①感染诱发与过敏诱发并存——患者WBC及中性粒细胞比例升高、C反应蛋白18mg/L，痰黄稠，初始考虑合并细菌感染并予阿奇霉素，然痰培养未见致病菌生长，治疗后炎症指标迅速下降至6mg/L，提示炎症指标升高主要为哮喘急性发作之气道炎症与应激反应所致，抗菌药物疗程结束后无须延长；②须与心源性哮喘鉴别——患者中年女性，无高血压、冠心病史，查体无心界扩大、奔马律、颈静脉怒张及下肢水肿，心脏彩超及血浆BNP无异常，胸部CT心影大小正常，可除外；③须与上气道阻塞性疾病（如声带功能障碍、气道异物、气管肿瘤）及变应性支气管肺曲霉病鉴别——前者多表现为吸气性呼吸困难和喘鸣，肺功能流量-容积曲线示吸气相平台，本例以呼气相延长、哮鸣为主，胸部CT未见占位及气道狭窄，不支持；后者多有支气管扩张、嗜酸性粒细胞显著升高及曲霉特异性IgE阳性，本例嗜酸性粒细胞轻度升高、胸部CT无中心性支气管扩张，暂不支持，必要时可查曲霉特异性IgE以进一步排除。\n本病为慢性气道炎症性疾病，长期预后取决于规范化吸入治疗依从性与诱因规避，须向患者强调「缓解不等于治愈」。\n\n四、国内外相关疾病研究进展\n1.《中国支气管哮喘防治指南（2020年版）》明确推荐，哮喘长期治疗以吸入性糖皮质激素联合长效β2受体激动剂为基石，急性发作期应早期全身应用糖皮质激素、按需吸入短效β2受体激动剂，并在急性发作控制后2～4周随访评估控制水平；《支气管哮喘基层诊疗指南（2022年）》进一步强调对患者进行吸入技术培训、哮喘日记与峰流速监测，规范管理可使哮喘急性发作率显著下降。\n2.GINA全球哮喘防治创议（2023年更新）建议，成人和青少年哮喘一律采用含ICS的方案，不再推荐单用短效β2受体激动剂缓解症状；对第4～5级治疗仍未控制者，推荐依据气道炎症表型加用抗IgE、抗IL-5/IL-5Rα或抗IL-4Rα单克隆抗体。一项纳入数千例中重度嗜酸性粒细胞性哮喘患者的随机对照试验显示，抗IL-5单抗可使急性发作率下降约50%、口服糖皮质激素用量明显减少；另有系统评价提示抗IgE单抗可显著降低重症过敏性哮喘急性加重风险。本例IgE 486IU/ml、尘螨强阳性，若规范吸入治疗3～6个月仍未控制，可转变态反应科评估特异性免疫治疗或生物制剂。\n3.关于哮喘缓解期的中医药干预，多项系统评价（如纳入数十项随机对照试验的中药复方治疗哮喘缓解期的系统评价）提示，在ICS/LABA基础上加用益气固表、健脾化痰或补肺益肾类中药，可减少急性发作次数、改善生活质量与肺功能，且不良反应轻微；针对小青龙汤类方治疗支气管哮喘急性发作期的系统评价亦提示其可提高临床总有效率、改善FEV1，但现有研究普遍样本量小、方法学质量有限，仍需大样本多中心随机对照试验验证。本例如用玉屏风散合六君子汤类方扶正固本，即基于上述「发时治标、平时治本」的循证思路。\n4.关于共病处理，过敏性鼻炎与哮喘同属「同一气道、同一疾病」，多项指南与研究提示，鼻用糖皮质激素规范治疗过敏性鼻炎有助于改善哮喘控制水平、减少哮喘急性发作，故本例须同步处理鼻部症状，并在随访中评估上下气道炎症的整体控制情况。\n\n五、诊疗计划\n1.中医治疗：治则治法调整为益气固表、健脾化痰、兼清余邪，佐以活血通络，方用玉屏风散合六君子汤加减：生黄芪30g、炒白术12g、防风9g、党参15g、茯苓15g、陈皮9g、法半夏9g、炙甘草6g、五味子6g（打碎）、麦冬12g、丹参15g、地龙9g、黄芩9g、桑白皮12g、辛夷9g（包煎）、苍耳子9g。用法：水煎服，每日1付，头煎加水500ml煎取200ml，二煎加水400ml煎取200ml，两煎混合后分2次温服，早晚饭后半小时各服1次，连服14剂后复诊。随症加减：痰多白稀者加干姜6g、细辛3g；咽痒即咳者加蝉蜕6g、僵蚕9g；纳差腹胀者加炒麦芽15g、砂仁6g（后下）；口干明显者加南沙参15g、玉竹12g。停用小青龙加石膏汤（麻黄、桂枝、细辛、干姜、生石膏），因表寒已解、里热已清，辛温发散与寒凉清泄之品不宜久用。\n方解：方中生黄芪补气固表、益卫实腠，为君药，针对肺虚卫外不固、易感外邪之根本；炒白术健脾益气、助黄芪固表，防风走表祛风、与黄芪相配则固表而不留邪，三者合为玉屏风散，益气固表止汗；党参、茯苓健脾益气渗湿，培土生金以绝生痰之源，与黄芪共为臣药；陈皮、法半夏理气燥湿化痰，炙甘草补中调和，五味子敛肺止咳、麦冬养阴生津，二者与党参相合取生脉散之意，益气养阴以复咳喘汗出所伤之气阴；丹参活血化瘀、地龙通络解痉，针对久病入络、气道瘀阻之病机，为佐药；黄芩、桑白皮清泄肺中余热，辛夷、苍耳子宣肺通鼻窍以治兼病鼻鼽，共为佐使。全方补中有散、散中有收，标本兼顾，共奏益气固表、健脾化痰、清余热、通鼻窍之功。\n2.西医治疗：①布地奈德福莫特罗粉吸入剂由每日2次、每次1吸调整为每日1次、每次1吸（降阶梯治疗），维持至少3个月后评估控制水平再定下一步；若出现夜间憋醒或峰流速下降超过20%，临时按需加吸并复诊；②停用阿奇霉素（疗程已足、痰培养阴性、炎症指标恢复正常）；③继续布地奈德混悬液1mg联合沙丁胺醇溶液2.5mg雾化吸入每日1～2次，症状完全缓解后改为按需使用，出院前停用；④氨溴索30mg每日3次口服，痰少易咯后可停用；⑤加用糠酸莫米松鼻喷雾剂每侧鼻孔2喷、每日1次，规范治疗过敏性鼻炎，喷后经鼻吸气、避免朝向鼻中隔；⑥监测：每日晨起及睡前测峰流速并记哮喘日记，出院前复查肺功能加支气管舒张试验、呼出气一氧化氮及血常规、C反应蛋白；⑦药物不良反应防治：吸入后立即漱口并洗脸，观察心悸、手抖、低钾、口咽念珠菌感染、声音嘶哑，长期吸入者定期测骨密度及眼压。\n3.护理与调摄：①饮食：宜清淡易消化、富含营养，多食山药、莲子、薏苡仁、白萝卜、百合以健脾益肺化痰，忌生冷冰饮、辛辣煎炸、虾蟹海鲜及已知致敏食物，忌烟酒；②起居：病室温暖避风、湿度50%～60%，勤晒被褥、使用防螨床罩，避免冷空气、烟尘、花粉、香水及宠物毛发刺激，注意保暖防复感，按时作息、避免熬夜与过劳；③情志：哮病与情志不畅相关，嘱患者保持心情舒畅，避免忧思恼怒，可通过听音乐、与人交流等方式调畅情志；④功能锻炼：指导缩唇呼吸与腹式呼吸训练，每次10～15分钟、每日2次，逐步进行太极拳、八段锦、散步等缓和运动，以不觉气促为度，冬季外出戴口罩，避免冷空气直接刺激气道；⑤自我监测：教会患者及家属识别发作先兆（鼻痒、喷嚏、胸闷、咳嗽加重）及正确使用吸入装置，掌握峰流速仪使用方法并记录。\n4.医患沟通：已向患者及家属详细交代病情，说明经中西医结合治疗4天，患者表证已解、痰热渐清、喘息哮鸣基本消失、缺氧纠正、炎症指标恢复正常，急性发作已控制，治疗有效；同时说明哮喘为慢性气道炎症性疾病，须长期规范吸入治疗，「缓解不等于治愈」，不可因症状消失而自行停药或减量，否则易反复急性发作并致气道重塑、肺功能不可逆下降；告知中药已由祛邪为主转为扶正固本为主，需坚持服用并定期复诊调整；交代出院后注意事项：坚持吸入治疗、记哮喘日记、监测峰流速、规避尘螨及冷空气等诱因、同步治疗过敏性鼻炎，出院后2周呼吸科门诊复诊，3个月后复查肺功能评估控制水平并调整长期方案，必要时转变态反应科评估特异性免疫治疗；告知出现喘息加重不能平卧、说话断续、口唇发紫、意识改变或峰流速下降超过20%时须立即就诊或急诊处理。患者及家属表示理解并同意上述方案。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1223,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"22704dbe3a180d74bc12ccedba7f94c850ea18bf19c62ec64779e82796c07e5e","pinyin":"xiaobing（hanbaorexiao）","initials":"xb（hbrx）","setting":"in","caseName":"病例1：患者，女，45岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，45岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-d5ae778bff5ead9d7fcc","key":"v1-c9ccc21dfe2a3058|templates-d5ae778bff5ead9d7fcc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"哮病（热哮）","category":"中医科","raw":{"name":"哮病（热哮）","category":"中医科","case":{"case_name":"病例1：患者，女，42岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：女 年龄：42岁 民族：汉族\n婚姻：已婚 职业：教师 籍贯：本地\n入院时间：2026年09月10日 15:30 记录时间：2026年09月10日 17:00\n病史陈述者：患者本人，可靠\n\n主诉：反复发作性喉中哮鸣伴气喘6年，加重伴咳嗽咯痰6天。\n\n现病史：患者于6年前春季接触花粉后首次出现喉中哮鸣有声、呼吸急促、胸闷如塞，此后每遇春季花粉、尘螨、冷空气及刺激性气味则反复发作，每年发作3～5次，每次持续数小时至数日，发作时吸入沙丁胺醇气雾剂后可缓解，间歇期如常人。6天前因乔迁新居接触尘螨及油漆气味后症状再发，起病较急，出现喉中哮鸣、咳嗽、咯黄黏痰，痰稠难咯，胸闷气喘，动则加重，自服氨茶碱片及沙丁胺醇气雾剂后症状可暂时减轻但反复不愈。2天前症状明显加重，喘息气粗，喉中痰鸣如吼，胸高胁胀，不能平卧，被迫取半坐位，咳痰黄稠量多、咯吐不利，口干欲饮、喜冷饮，身热汗出，心烦不宁，大便秘结，小便黄赤，遂来我院门诊就诊。门诊查血常规示WBC 8.6×10^9/L、嗜酸性粒细胞百分比8.9%，胸片示双肺纹理增粗、透亮度稍增高，门诊以「哮病（热哮）」收入我科。发病以来无恶寒发热，无咯血，无夜间阵发性呼吸困难伴粉红色泡沫痰，无下肢水肿，无胸痛及意识障碍；精神欠佳，食欲减退，睡眠差，大便秘结，小便黄赤，体重无明显变化。\n\n既往史：既往有过敏性鼻炎病史8年，每于春季鼻痒喷嚏发作；否认高血压、糖尿病、冠心病病史；否认肝炎、结核等传染病史；否认手术、外伤史；否认食物、药物过敏史。\n\n个人史及家族史：生于本地，久居本地，无吸烟史及饮酒史，否认粉尘及有害气体长期接触史，母亲有支气管哮喘病史。\n婚育史：26岁结婚，配偶体健，育有1女，体健。\n\n体格检查：\nT 37.4℃，P 108次/分，R 26次/分，BP 118/76mmHg，SpO2 92%（未吸氧）。\n一般情况：神志清楚，精神欠佳，急性病容，半坐位，呼吸急促，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色潮红，口唇微绀，舌质红，苔黄腻。\n闻诊：语声重浊，呼吸急促，喉中可闻及哮鸣音，咳声重浊，咯痰黄稠。\n问诊：喉中哮鸣如吼，喘息气粗，胸闷胁胀，咳痰黄稠难咯，口干欲饮、喜冷饮，身热汗出，心烦，大便秘结，小便黄赤；纳减，眠差，因喘息不能平卧。\n切诊：脉滑数。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可；口唇微绀。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大，颈静脉无怒张。\n胸部：胸廓对称，肋间隙稍增宽，呼吸运动对称，三凹征阴性；双肺叩诊清音，肺下界下移；双肺可闻及散在哮鸣音及少量湿性啰音，呼气相延长，以双肺中下野为著，未闻及胸膜摩擦音。心率108次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，四肢无畸形，关节无肿胀，活动正常，双下肢无水肿。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：喘息气粗，喉中痰鸣如吼，胸高胁胀，不能平卧，被迫取半坐位，面色潮红，口唇微绀；舌象：舌质红，苔黄腻；脉象：脉滑数。专科查体：呼吸26次/分，三凹征阴性，双肺叩诊清音，肺下界下移，双肺可闻及散在哮鸣音及少量湿性啰音，呼气相延长，以双肺中下野为著；心率108次/分，律齐，双下肢无水肿。关键阴性体征：无端坐呼吸伴咳粉红色泡沫痰，无颈静脉怒张，无心界扩大及奔马律，无双下肢凹陷性水肿，无咯血，无发热寒战，无胸痛及放射痛，无意识障碍，病理征阴性。\n辅助检查：\n门诊血常规：WBC 8.6×10^9/L，N% 62%，E% 8.9%，Hb 126g/L，PLT 226×10^9/L。\n门诊C反应蛋白6.8mg/L，降钙素原0.05ng/mL。\n门诊胸部X线：双肺纹理增粗、紊乱，双肺透亮度稍增高，心影大小正常。\n门诊心电图：窦性心律，心率106次/分，正常心电图。\n门诊肺功能：FEV1占预计值71%，FEV1/FVC 64%，支气管舒张试验阳性（吸入沙丁胺醇400μg后FEV1改善率15.2%，绝对值增加220mL）。\n门诊呼出气一氧化氮68ppb；血清总IgE 386IU/mL；过敏原检测尘螨（+++）、花粉（++）。\n门诊血气分析（未吸氧）：pH 7.42，PaO2 68mmHg，PaCO2 36mmHg，SaO2 92%。\n\n初步诊断：\n中医诊断：哮病（热哮）\n中医诊断依据：1.辨病依据：患者反复发作性喉中哮鸣有声、呼吸急促、胸闷如塞6年，每因接触花粉、尘螨、冷空气及刺激性气味诱发，发作时吸入沙丁胺醇可缓解，间歇期如常人，本次起病急、症状重，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，故辨病为哮病。2.辨证依据：①主症：喉中痰鸣如吼，喘息气粗，胸高胁胀，不能平卧，咳痰黄稠量多、咯吐不利，口干欲饮而喜冷饮，身热汗出，心烦不宁，大便秘结，小便黄赤；②舌象脉象：舌质红，苔黄腻，脉滑数；③病因病机：患者素有痰伏于肺，复因尘螨、油漆异味引动，痰随气升、气因痰阻、痰气相搏、壅塞气道，肺失宣降而发；痰热壅肺、气机壅塞故哮鸣如吼、胸高胁胀、咳痰黄稠；里热内盛、热灼津伤故口渴喜冷饮、身热汗出、心烦、便结溲黄；舌红苔黄腻、脉滑数皆痰热内盛之典型舌脉。四诊合参，当属热哮之证。\n中医鉴别诊断：1.与「冷哮」鉴别：冷哮证见喉中哮鸣如水鸡声，痰少色白多泡沫，口不渴或渴喜热饮，形寒怕冷，面色晦滞带青，天冷或受寒易发，舌苔白滑，脉弦紧或浮紧；本例咳痰黄稠、口干喜冷饮、身热汗出、舌红苔黄腻、脉滑数，系痰热为患，与寒痰伏肺迥异。2.与「寒包热哮」鉴别：寒包热哮证见喉中哮鸣、胸膈烦闷、咯痰不爽而痰黏色黄，兼发热恶寒、无汗身痛、脉浮紧等表寒之象，舌边尖红、苔白腻罩黄；本例无发热恶寒、无汗身痛之表证，纯属痰热壅肺之里热证。3.与「风痰哮」鉴别：风痰哮证见喉中痰涎壅盛、声如拽锯，喘急胸满、但坐不得卧，痰黏腻难出，起病急骤、倏忽来去，发前鼻咽眼耳发痒、喷嚏流涕，舌苔厚浊、脉滑实，无明显寒热倾向；本例痰黄稠、舌红苔黄腻，热象显著，且无明显风象先兆，故辨为热哮。4.与「喘证」鉴别：喘证以气息喘促、呼吸困难、甚则张口抬肩、鼻翼煽动、不能平卧为主症，是多种急慢性疾病过程中的一个症状，无发作性喉中哮鸣之特征；哮病以发作时喉中哮鸣有声为特征的独立疾病，哮必兼喘、喘未必兼哮，二者以此为辨。5.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、烦躁心悸、面色晦暗为主症，病程缠绵、经久难愈，多见于中老年人，常继发于哮病、喘证日久；本例间歇期如常人，无胸廓膨满及右心衰竭表现，暂不支持肺胀。\n西医诊断：支气管哮喘（急性发作期，中度）；过敏性鼻炎\n西医诊断依据：1.病史依据：反复发作性喘息、气急、胸闷伴咳嗽6年，每年发作3～5次，每因接触花粉、尘螨、冷空气及刺激性气味诱发，发作时吸入支气管舒张剂可缓解，间歇期如常人，有过敏性鼻炎病史8年及哮喘家族史；2.症状依据：本次接触尘螨、油漆气味后急性起病，喉中哮鸣如吼、喘息气粗、胸闷胁胀、咳嗽咯黄稠痰，夜间及晨起加重，不能平卧，病程6天、加重2天；3.体征依据：T 37.4℃，P 108次/分，R 26次/分，BP 118/76mmHg，SpO2 92%（未吸氧），半坐位，呼吸急促，口唇微绀，双肺可闻及散在哮鸣音及少量湿性啰音、呼气相延长，无颈静脉怒张、无下肢水肿、无心界扩大及奔马律；4.实验室依据：血常规WBC 8.6×10^9/L、N% 62%、E% 8.9%，CRP 6.8mg/L、PCT 0.05ng/mL（提示非细菌感染性发作），血清总IgE 386IU/mL升高，过敏原检测尘螨（+++）、花粉（++），FeNO 68ppb明显升高；5.肺功能依据：FEV1占预计值71%、FEV1/FVC 64%，支气管舒张试验阳性（FEV1改善率15.2%、绝对值增加220mL）；6.影像及血气依据：胸部X线示双肺纹理增粗紊乱、透亮度稍增高、心影正常，血气（未吸氧）pH 7.42、PaO2 68mmHg、PaCO2 36mmHg、SaO2 92%，提示轻度低氧血症而无二氧化碳潴留。符合支气管哮喘急性发作期（中度），合并过敏性鼻炎。\n西医分型/分级/分期：①疾病分期：急性发作期；②急性发作严重程度分级：中度——喜坐位、呼吸急促（26次/分，20～30次/分）、心率108次/分（100～120次/分）、未吸氧SpO2 92%（90%～95%）、PaO2 68mmHg（60～80mmHg）、PaCO2 36mmHg（＜45mmHg，无二氧化碳潴留）、口唇微绀、双肺散在哮鸣音伴少量湿性啰音、无意识障碍，FEV1占预计值71%（60%～80%），符合中度急性发作标准；③气流受限程度：阻塞性通气功能障碍（FEV1占预计值71%、FEV1/FVC 64%），支气管舒张试验阳性，属可逆性气流受限；④气道炎症表型：过敏性（嗜酸性粒细胞性）哮喘——E% 8.9%、总IgE 386IU/mL、尘螨（+++）、FeNO 68ppb升高，CRP及PCT正常提示非感染性；⑤病情严重程度（慢性持续期）分级：第2～3级（轻度～中度持续），6年来每年发作3～5次；⑥合并症：过敏性鼻炎；⑦控制水平：未控制（日内症状、夜间憋醒、需频繁使用缓解药物）。\n\n诊疗计划：\n1.按内科Ⅱ级护理，半流质清淡饮食，卧床休息取半坐位，持续低流量鼻导管吸氧，监测指脉氧及呼吸频率；2.完善检查：血常规+C反应蛋白（目的：明确有无细菌感染及炎症程度，为是否使用抗菌药物提供依据）、血气分析（目的：评估缺氧与二氧化碳潴留程度，为氧疗及是否需要无创通气提供依据）、肝肾功能+电解质（目的：评估茶碱、激素等药物代谢与安全用药条件）、痰涂片及痰培养（目的：明确致病菌与耐药情况，为抗感染方案调整提供依据）、胸部CT（目的：排除肺炎、气胸等并发症并明确肺部病变范围）、心电图+心脏彩超（目的：评估心肺功能与右心负荷，排除心源性喘息）、肺功能及支气管舒张试验（目的：客观明确气道阻塞可逆性，为哮喘诊断与分级治疗提供依据）、呼出气一氧化氮+血清总IgE及过敏原检测（目的：评估气道嗜酸粒细胞炎症与过敏状态，为激素及抗IgE治疗决策提供依据）；3.一般治疗：避免接触尘螨、花粉、油漆等过敏原及刺激性气味，保持病室空气清新、温湿度适宜；4.药物治疗：清热宣肺、化痰定喘中药汤剂（定喘汤加减）水煎200mL每日1剂分早晚温服，咳嗽痰黄稠加鱼腥草、瓜蒌皮、浙贝母，喘甚加地龙、葶苈子，大便秘结加生大黄，咽痒鼻塞加蝉蜕、辛夷；予布地奈德联合异丙托溴铵雾化吸入每日2次，多索茶碱0.2g静滴每日1次，甲泼尼龙40mg静滴每日1次，孟鲁司特钠10mg每晚口服；5.病情观察：观察喘息、哮鸣音、痰量痰色及呼吸频率变化，监测指脉氧，注意有无呼吸困难加重、发绀、意识改变，警惕哮喘持续状态及呼吸衰竭；6.健康教育：指导正确使用吸入装置、记录哮喘日记、识别并规避过敏原，缓解期坚持中药扶正固本及规范吸入激素治疗，必要时请变态反应科会诊。\n\n专科检查：\n望诊：喘息气粗，喉中痰鸣如吼，胸高胁胀，不能平卧，被迫取半坐位，面色潮红，口唇微绀；舌象：舌质红，苔黄腻；脉象：脉滑数。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年09月10日 18:00\n\n病例特点：\n1.患者，女，42岁，教师，因「反复发作性喉中哮鸣伴气喘6年，加重伴咳嗽咯痰6天」入院。\n2.既往史：过敏性鼻炎病史8年，母亲有支气管哮喘病史，无吸烟史。\n3.体格检查：T 37.4℃，P 108次/分，R 26次/分，BP 118/76mmHg，SpO2 92%（未吸氧）；急性病容，半坐位，呼吸急促，口唇微绀；双肺可闻及散在哮鸣音及少量湿性啰音，呼气相延长；双下肢无水肿。\n4.中医四诊：面色潮红，舌质红，苔黄腻，脉滑数。\n5.辅助检查：血WBC 8.6×10^9/L、E% 8.9%；CRP 6.8mg/L、PCT 0.05ng/mL；肺功能示阻塞性通气功能障碍，支气管舒张试验阳性；FeNO 68ppb，总IgE 386IU/mL，尘螨（+++）；血气PaO2 68mmHg。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：哮病（热哮）\n西医诊断：支气管哮喘（急性发作期，中度）；过敏性鼻炎\n\n（二）中医诊断依据：\n1.辨病依据：患者反复发作性喉中哮鸣有声、呼吸急促、甚则不能平卧6年，间歇期如常人，本次因接触尘螨、油漆异味急性发作，符合哮病「发作时喉中哮鸣有声、呼吸气促困难、甚则张口抬肩、不能平卧，反复发作」之诊断要点，故辨病为哮病。\n2.辨证依据：患者素有痰伏于肺，复因接触尘螨、油漆异味引动，痰随气升、气因痰阻、痰气相搏、壅塞气道，肺失宣降而发；喉中痰鸣如吼、喘息气粗、胸高胁胀、咳痰黄稠难咯，为痰热壅肺、气机壅塞之象；口干欲饮而喜冷饮、身热汗出、心烦、大便秘结、小便黄赤，为里热内盛、热灼津伤之征；舌质红、苔黄腻、脉滑数，均为痰热内盛之典型舌脉。四诊合参，当属热哮之证。\n3.治法方药：治以清热宣肺、化痰定喘，方用定喘汤加减（麻黄6g、白果9g打碎、款冬花10g、法半夏9g、桑白皮12g、黄芩10g、紫苏子9g、苦杏仁9g、甘草6g）；痰黄稠量多加鱼腥草30g、瓜蒌皮15g、浙贝母10g，喘甚加地龙10g、葶苈子9g包煎，大便秘结加生大黄6g后下，咽痒鼻塞加蝉蜕6g、辛夷9g包煎。\n依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·哮病·热哮证。\n\n（三）中医鉴别诊断：\n1.与「冷哮」鉴别：冷哮证见喉中哮鸣如水鸡声，痰少色白多泡沫，口不渴或渴喜热饮，形寒怕冷，面色晦滞带青，舌苔白滑，脉弦紧或浮紧；本例咳痰黄稠、口干喜冷饮、身热汗出、舌红苔黄腻、脉滑数，系痰热为患，与寒痰伏肺迥异。\n2.与「寒包热哮」鉴别：寒包热哮证见喉中哮鸣、胸膈烦闷、咯痰不爽而痰黏色黄，兼发热恶寒、无汗身痛、脉浮紧之表寒见症，舌边尖红、苔白腻罩黄；本例无表寒见证，纯属痰热壅肺之里热证。\n3.与「风痰哮」鉴别：风痰哮证见喉中痰涎壅盛、声如拽锯，喘急胸满、但坐不得卧，痰黏腻难出，起病急骤、倏忽来去，发前鼻咽眼耳发痒、喷嚏流涕，舌苔厚浊、脉滑实，无明显寒热倾向；本例痰黄稠、舌红苔黄腻，热象显著，故辨为热哮。\n4.与「喘证」鉴别：喘证以气息喘促、呼吸困难、甚则张口抬肩、鼻翼煽动、不能平卧为主症，是多种急慢性疾病过程中的一个症状；哮病以发作时喉中哮鸣有声为特征的独立疾病。哮必兼喘，喘未必兼哮，二者以此为辨。\n5.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、烦躁心悸、面色晦暗为主症，病程缠绵、经久难愈，多见于中老年人，常继发于哮病、喘证日久；本例间歇期如常人，无胸廓膨满及右心衰竭表现，暂不支持肺胀。\n提示：若见喘息持续不解、张口抬肩、汗出如雨、面色青紫、神志改变者，为哮喘持续状态、有呼吸衰竭之虞，须立即抢救并请上级医师查房。\n\n（四）西医诊断依据：\n1.病史依据：反复发作性喘息、气急、胸闷伴咳嗽6年，每年发作3～5次，每因花粉、尘螨、冷空气及刺激性气味诱发，发作时吸入支气管舒张剂可缓解，间歇期如常人，有过敏性鼻炎及哮喘家族史。\n2.症状依据：接触尘螨、油漆气味后急性起病，喉中哮鸣如吼、喘息气粗、胸闷胁胀、咳嗽咯黄稠痰，夜间及晨起加重，不能平卧。\n3.体征依据：T 37.4℃，P 108次/分，R 26次/分，SpO2 92%（未吸氧），半坐位，口唇微绀，双肺散在哮鸣音及少量湿性啰音、呼气相延长，无颈静脉怒张及下肢水肿。\n4.实验室依据：血WBC 8.6×10^9/L、N% 62%、E% 8.9%，CRP 6.8mg/L、PCT 0.05ng/mL，总IgE 386IU/mL，尘螨（+++）、花粉（++），FeNO 68ppb。\n5.肺功能依据：FEV1占预计值71%、FEV1/FVC 64%，支气管舒张试验阳性（改善率15.2%、绝对值增加220mL）。\n6.影像及血气依据：胸部X线示双肺纹理增粗紊乱、透亮度稍增高、心影正常；血气（未吸氧）pH 7.42、PaO2 68mmHg、PaCO2 36mmHg、SaO2 92%，提示轻度低氧血症、无二氧化碳潴留。\n符合支气管哮喘急性发作期（中度），合并过敏性鼻炎。\n\n（五）西医分型/分级/分期：\n①疾病分期：急性发作期。②急性发作严重程度分级：中度（呼吸26次/分、心率108次/分、SpO2 92%、PaO2 68mmHg、PaCO2 36mmHg、口唇微绀、双肺散在哮鸣音，FEV1占预计值71%，符合中度标准）。③气流受限程度：阻塞性通气功能障碍（FEV1占预计值71%、FEV1/FVC 64%），支气管舒张试验阳性，属可逆性气流受限。④气道炎症表型：过敏性（嗜酸性粒细胞性）哮喘（E% 8.9%、总IgE 386IU/mL、尘螨+++、FeNO 68ppb，CRP及PCT正常提示非感染性）。⑤病情严重程度（慢性持续期）分级：第2～3级（轻度～中度持续）。⑥控制水平：未控制。⑦合并症：过敏性鼻炎。\n\n（六）西医鉴别诊断：\n1.慢性阻塞性肺疾病急性加重：\n【支持点】两者均以喘息、气促、哮鸣音及呼气相延长为主要表现，感染或刺激物可诱发加重。\n【不支持点】患者42岁女性，无吸烟及职业粉尘接触史，喘息呈发作性、间歇期如常人；FEV1占预计值71%、FEV1/FVC 64%，支气管舒张试验阳性（改善率15.2%、绝对值增加220mL），属可逆性气流受限。\n【排除方法】依据肺功能及支气管舒张试验、起病年龄、吸烟史及症状持续性判断；慢性阻塞性肺疾病气流受限不完全可逆。\n2.急性左心衰竭（心源性哮喘）：\n【支持点】急性左心衰竭可见端坐呼吸、呼吸急促、双肺哮鸣音及低氧血症，与本次表现相似。\n【不支持点】本例无高血压、冠心病、心脏瓣膜病等基础心脏病史，咳黄稠痰而非粉红色泡沫痰，无颈静脉怒张及双下肢水肿，未闻及奔马律，心脏彩超无左室扩大及室壁运动异常。\n【排除方法】查血浆BNP/NT-proBNP、心脏彩超（左室射血分数、舒张功能）及心电图；BNP正常且无心脏结构功能异常者可除外。\n3.社区获得性肺炎：\n【支持点】本例体温37.4℃、咳黄稠痰、CRP 6.8mg/L轻度升高，肺部感染可诱发或加重喘息，须予鉴别。\n【不支持点】血WBC 8.6×10^9/L、PCT 0.05ng/mL不支持细菌感染，胸部X线未见实变影；喘息呈发作性、由尘螨及油漆异味诱发，FeNO 68ppb、总IgE 386IU/mL、嗜酸性粒细胞比例8.9%提示过敏性气道炎症。\n【排除方法】复查血常规、C反应蛋白、降钙素原，完善胸部CT及痰涂片、痰培养；无新发浸润影及病原学证据者不支持肺炎。\n4.肺栓塞：\n【支持点】肺栓塞可表现为突发呼吸困难、气促、低氧血症，可伴哮鸣音，须与支气管哮喘急性发作鉴别。\n【不支持点】本例有明确过敏原接触诱因及6年反复发作史，无胸痛咯血、晕厥、下肢肿胀及制动、手术、肿瘤等血栓高危因素，心率增快与喘息程度相符。\n【排除方法】查D-二聚体、动脉血气分析、心电图及CT肺动脉造影；D-二聚体阴性者可基本除外。\n5.自发性气胸：\n【支持点】可突发呼吸困难、患侧呼吸音减低，须与急性发作期支气管哮喘鉴别。\n【不支持点】本例双肺对称闻及散在哮鸣音，无突发针刺样胸痛，气管居中，无皮下气肿及单侧呼吸音消失。\n【排除方法】急查胸部X线或胸部CT，未见气胸线及肺压缩带即可除外。\n6.变态反应性支气管肺曲霉病（ABPA）：\n【支持点】该病以哮喘样发作、外周血嗜酸性粒细胞及血清总IgE升高为特征，与本例E% 8.9%、总IgE 386IU/mL相似。\n【不支持点】本例总IgE未达显著升高水平，无咳棕色痰栓、发热及反复肺部浸润影，胸部X线仅示双肺纹理增粗。\n【排除方法】查烟曲霉特异性IgE/IgG、血清总IgE动态变化及胸部CT（中心性支气管扩张、黏液栓），阴性者不支持。\n\n（七）诊疗计划：\n1.护理与饮食：按中医科（肺系病）护理常规，Ⅱ级护理；半流质清淡饮食，忌辛辣煎炸、羊肉、荔枝及鱼虾发物，戒烟酒，多饮温开水，保持大便通畅；卧床休息取半坐位，持续低流量鼻导管吸氧，监测指脉氧及呼吸频率。\n2.完善检查：①复查血常规、C反应蛋白及降钙素原（目的：动态评估气道炎症与感染情况，为是否加用抗菌药物提供依据）；②复查动脉血气分析（目的：评估低氧血症程度及有无二氧化碳潴留，为氧疗及病情分级提供依据）；③完善胸部CT（目的：除外肺炎、气胸、胸腔积液及肺部占位，为喘息病因鉴别提供依据）；④完善痰涂片及痰培养（目的：明确有无细菌感染及致病菌，为抗菌药物选择提供依据）；⑤完善肺功能及支气管舒张试验（目的：评估气流受限程度与可逆性，为确诊支气管哮喘及病情分级提供依据）；⑥完善呼出气一氧化氮测定（目的：评估气道嗜酸性炎症水平，为指导吸入糖皮质激素剂量调整提供依据）；⑦完善过敏原检测及血清总IgE（目的：明确致敏原，为环境规避及特异性免疫治疗提供依据）；⑧完善心电图、心脏彩超及血浆BNP（目的：除外心律失常、心肌缺血及心源性哮喘，为鉴别心源性喘息提供依据）；⑨完善肝肾功能、电解质及血糖（目的：评估用药安全性与内环境状态，为茶碱及糖皮质激素安全用药提供依据）。\n3.西医治疗：①布地奈德1mg联合异丙托溴铵0.5mg雾化吸入，每日2次，解痉平喘、减轻气道黏膜水肿；②多索茶碱0.2g加生理盐水100mL静脉滴注，每日1次，舒张支气管平滑肌；③甲泼尼龙40mg静脉滴注，每12小时1次，满3日后改为40mg每日1次，2日后改泼尼松30mg口服每日1次，每3～5日减5mg至停，总疗程7～10日；④孟鲁司特钠片10mg每日1次睡前口服，拮抗白三烯受体；⑤沙丁胺醇气雾剂100μg按需吸入，缓解急性喘息；⑥监测血糖、血压、血钾及心电图，必要时复查血气；合并过敏性鼻炎予生理性海水鼻腔冲洗，酌情加用氯雷他定片10mg每日1次口服。\n4.中医治疗：给予中药方剂以清热宣肺、化痰定喘为治则；方选定喘汤加减；中药处方如下：麻黄6g 白果9g（打碎） 款冬花10g 法半夏9g 桑白皮12g 黄芩10g 紫苏子9g 苦杏仁9g 鱼腥草30g 瓜蒌皮15g 浙贝母10g 地龙10g 甘草6g。用法：水煎服，每日一付，水煎取汁200mL，分2次温服。方解：方中麻黄辛温宣肺开壅、解散表邪以复肺气之宣，白果甘涩敛肺定喘、化痰止咳，二药一散一收，宣中有敛，既开痰气之壅塞又防麻黄耗散肺气，共为君药；桑白皮甘寒泻肺平喘、清泄肺中蕴热，黄芩苦寒清泄肺热、燥湿解毒，二者直折痰热之壅盛，为臣药；紫苏子、苦杏仁降气化痰、止咳平喘，使上逆之肺气得降，款冬花润肺下气、止咳化痰，法半夏燥湿化痰、降逆散结，鱼腥草、瓜蒌皮、浙贝母清热化痰、宽胸散结，地龙咸寒通络解痉、平喘利气，上药共为佐药，分理痰、热、气三者之胶结；甘草化痰止咳、调和诸药，为使药。全方宣、清、降、化四法并行，寒温并用而不偏，使痰热得清、肺气得降、气道通利，共奏清热宣肺、化痰定喘之效。随症加减：痰黄稠量多加金荞麦30g；喘甚加葶苈子9g（包煎）；大便秘结加生大黄6g（后下）；咽痒鼻塞加蝉蜕6g、辛夷9g（包煎）。针灸取定喘、肺俞、膻中、天突、列缺、丰隆、鱼际，用泻法，留针20分钟，每日1次。待痰热清后减麻黄、黄芩，加炙黄芪15g、炒白术12g以健脾补肺、固本防复。\n5.密切观察病情变化，重点观察喘息、哮鸣音、痰量痰色及呼吸频率变化，监测指脉氧，警惕哮喘持续状态及呼吸衰竭；向家属交代目前病情为支气管哮喘中度急性发作、中医属哮病热哮，说明激素与茶碱的作用及可能出现的高血糖、心慌、手抖等反应；注意防跌倒、防坠床，取半坐位休息，室内勤通风、被褥勤洗晒以除尘螨，避免接触花粉、油漆等异味；积极医患沟通，强调须长期规范吸入糖皮质激素控制，不可因症状缓解自行停药，每日记录峰流速及指脉氧；及时请上级医师查看病人，若见喘息持续不解、口唇发绀、大汗淋漓、言语不成句、神志改变者，立即抢救并请上级医师查房。\n\n医师签名：陈医生\n\n医师签名：陈医生\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年09月11日 09:00（入院第2天）\n\n今日张主治医师查房，患者精神好转，喘息气粗及喉中哮鸣减轻，痰转淡黄、量减易咯，夜能平卧，口干心烦减轻，无发热恶寒，纳增，大便已通。查体：T 36.9℃，P 92次/分，R 22次/分，BP 116/74mmHg，SpO2 95%（吸氧2L/min）；口唇无发绀，双肺少量哮鸣音、呼气相稍延长，未闻湿啰音。中医四诊：舌质红、苔黄腻转薄，脉滑数较前缓和。辅查：E% 8.2%、CRP 5.4mg/L，肝肾功能及电解质正常，痰培养阴性；胸部CT未见实变及占位；心脏彩超及LVEF正常；血气PaO2 82mmHg、SaO2 96%。\n\n一、中医辨病辨证分析\n患者反复发作性喉中哮鸣、呼吸气促、甚则不能平卧6年，间歇期如常人，此次因尘螨、油漆异味引动，符合哮病发作期诊断要点，故辨病为哮病；症见痰黄稠难咯、口干喜冷饮、身热汗出、心烦、尿黄便秘，舌红苔黄腻、脉滑数，辨证为热哮，属痰热壅肺、肺失宣降。病机为宿痰伏肺，遇感引动，痰随气升、痰气相搏、壅塞气道，肺失宣降，故喘息哮鸣、胸高胁胀；痰热灼津则口干喜冷；肺与大肠相表里，肺气不降则腑气不通。今苔腻转薄、脉数转缓，示痰热渐化；然舌仍红、脉仍滑数，余热未尽，清热化痰不可骤停。\n\n二、中医鉴别诊断\n1.与「支饮」鉴别：支饮饮停胸膈，见咳逆倚息、不得卧、咳唾白沫量多、遇寒加重，苔白滑、脉弦紧；本案痰黄稠、舌红苔黄腻、脉滑数，心脏彩超正常，间歇期如常人，非饮停心下之候。\n2.与「痰热咳嗽」鉴别：痰热咳嗽以咳嗽为主症，无发作性喉中哮鸣及呼吸急促困难，肺功能多元阻塞；本案喘哮为主、咳嗽为辅，支气管舒张试验阳性，气道可逆性阻塞客观存在，故属哮病。\n3.与「虚哮」鉴别：虚哮平素息促气短、动则尤甚、痰吐无力，舌淡脉弱；本案起病急、喉中痰声如吼、脉滑数有力，属痰热实证，非虚哮。\n\n三、西医鉴别诊断\n1.与心源性哮喘鉴别：后者多有心脏病史，夜间阵发性呼吸困难、咳粉红色泡沫痰、肺底湿啰音及奔马律；本例心脏彩超正常，无下肢水肿及颈静脉怒张，不支持。\n2.与慢阻肺急性加重鉴别：慢阻肺多见长期吸烟者，气流受限不完全可逆、舒张试验阴性、FeNO多不升高；本例舒张试验阳性、FeNO 68ppb、血EOS及总IgE升高，符合过敏性哮喘。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》推荐急性发作期以反复吸入短效β2受体激动剂联合吸入性糖皮质激素为基础，中度及以上发作尽早加用全身糖皮质激素、疗程5～7日，可降低住院率与复发率。\n2. GINA 2023将吸入激素联合福莫特罗的维持加缓解方案列为成人哮喘首选，可降低重度急性发作风险，并以血EOS≥300/μL、FeNO≥50ppb作为升阶梯参考。\n3.中药复方定喘汤治疗哮喘急性发作期的系统评价（纳入10余项随机对照试验）提示，西医常规治疗加用定喘汤可提高总有效率、改善FEV1占预计值百分比，并降低总IgE及血嗜酸性粒细胞。\n\n五、诊疗计划\n1.中医治疗：治以清热宣肺、化痰定喘，方选定喘汤加减。处方：麻黄6g、白果9g（打碎）、款冬花10g、法半夏9g、桑白皮12g、黄芩10g、紫苏子9g、苦杏仁9g、鱼腥草30g、瓜蒌皮15g、浙贝母10g、地龙10g、甘草6g。水煎服，每日1剂，煎取200mL，分早晚2次温服。方解：麻黄宣肺开壅、白果敛肺定喘，一散一收共为君；桑白皮泻肺平喘、黄芩清泄肺热为臣；紫苏子、苦杏仁降气化痰，款冬花润肺下气，法半夏燥湿化痰，鱼腥草、瓜蒌皮、浙贝母清热化痰散结，地龙通络解痉，共为佐；甘草化痰调和为使，全方宣清降化并用，使痰热得清、肺气得降。随症加减：痰稠加金荞麦30g，喘甚加葶苈子9g（包煎），便秘加生大黄6g（后下）。针灸取定喘、肺俞、膻中、丰隆，泻法，留针20分钟，每日1次。痰热清后减麻黄、黄芩，加炙黄芪15g、炒白术12g健脾补肺。\n2.西医治疗：布地奈德1mg联合异丙托溴铵0.5mg雾化吸入bid；多索茶碱0.2g加生理盐水100mL静滴qd；甲泼尼龙40mg静滴q12h满3日后改40mg qd，2日后改泼尼松30mg口服qd，每3～5日减5mg至停，总疗程7～10日；孟鲁司特钠10mg qn；沙丁胺醇气雾剂100μg按需吸入。监测血糖、血压、血钾及心电图。\n3.护理与调摄：饮食清淡，忌辛辣煎炸、羊肉、荔枝及鱼虾发物，戒烟酒，多食冬瓜、梨、白萝卜，多饮温水；半坐位休息，勤晒被褥除尘螨，避花粉、油漆异味；情志平和，可练八段锦；缓解后适度散步，每日记峰流速及指脉氧。\n4.医患沟通：已交代病情为哮喘中度急性发作、中医属哮病热哮，经治趋稳；说明激素与茶碱的作用及可能的高血糖、心慌、手抖等反应，已加监测；强调须长期规范吸入激素控制，不可因症状缓解自行停药，并规避过敏原；告知喘息加重、口唇发绀、大汗淋漓、言语不成句时立即呼叫医护。\n\n执行情况：遵嘱执行。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年09月11日 16:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，诉喘息减轻，喉中哮鸣音减少，咳痰较前顺畅，痰色转淡黄、量减少，夜能平卧，纳食渐增，大便已通。\n查体：T 36.9℃，P 92次/分，R 22次/分，BP 116/74mmHg，SpO2 95%（吸氧2L/min）；半卧位，口唇无发绀，双肺可闻及少量哮鸣音，呼气相稍延长；舌质红，苔黄腻较前变薄，脉滑数较前缓和。继续定喘汤加减口服及解痉平喘、抗炎治疗，加强拍背排痰。\n\n【病程记录二】2026年09月13日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，诉喘息明显减轻，喉中哮鸣音偶闻，咳嗽减少，痰转白稀、量少易咯，无口干及心烦，无身热汗出，夜寐安，纳可，二便调。\n查体：T 36.6℃，P 84次/分，R 19次/分，BP 120/76mmHg，SpO2 97%（未吸氧）；口唇红润，双肺呼吸音稍粗，未闻及明显哮鸣音及湿性啰音；舌质偏红，苔薄黄，脉滑。已停静脉激素，改口服泼尼松并按计划递减；中药守方，去生大黄，加白术12g、陈皮9g。\n\n【病程记录三】2026年09月15日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神好，诉无喘息及胸闷，无咳嗽咯痰，无夜间憋醒，活动后无气促，饮食睡眠可，二便调。\n查体：T 36.5℃，P 78次/分，R 18次/分，BP 118/74mmHg，SpO2 98%（未吸氧）；双肺呼吸音清，未闻及干湿性啰音；舌质淡红，苔薄白，脉细滑。患者病情平稳，哮病已缓解，中药改为益气固表、健脾化痰之剂善后，吸入激素维持，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年09月10日 16:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为哮病（热哮），西医诊断为支气管哮喘急性发作期（中度），系痰热壅肺、肺失宣降所致，病情尚平稳，需住院进一步检查治疗。\n2.诊疗方案：完善肺功能、胸部CT、血气分析及过敏原等检查，中医辨证论治予清热宣肺、化痰定喘中药汤剂口服，配合雾化吸入、解痉平喘及抗炎治疗，必要时氧疗。\n3.可能风险：治疗中可能出现病情反复甚至哮喘持续状态、呼吸衰竭，以及激素、茶碱类药物相关不良反应。\n4.注意事项：卧床休息取半坐位，清淡饮食，避免接触尘螨、花粉、油漆等过敏原及刺激性气味，配合检查治疗，勿自行停药。\n5.预后情况：经积极规范治疗后症状多可缓解，但本病易反复发作，缓解期需坚持中药调理及吸入激素维持治疗。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年09月10日\n出院日期：2026年09月20日\n住院天数：11天\n\n入院诊断：\n中医诊断：哮病（热哮）\n西医诊断：支气管哮喘（急性发作期，中度）；过敏性鼻炎\n\n出院诊断：\n中医诊断：哮病（热哮）\n西医诊断：支气管哮喘（慢性持续期）；过敏性鼻炎\n\n入院情况：\n患者，女，42岁，教师，因「反复发作性喉中哮鸣伴气喘6年，加重伴咳嗽咯痰6天」入院。入院时喘息气粗，喉中痰鸣如吼，不能平卧，咳痰黄稠难咯，口干喜冷饮，身热汗出，心烦，大便秘结。查体：T 37.4℃，P 108次/分，R 26次/分，BP 118/76mmHg，SpO2 92%（未吸氧）；急性病容，口唇微绀，双肺可闻及散在哮鸣音及少量湿性啰音，呼气相延长。中医四诊：面色潮红，舌质红，苔黄腻，脉滑数。肺功能示阻塞性通气功能障碍、支气管舒张试验阳性，FeNO 68ppb，血嗜酸性粒细胞8.9%，总IgE 386IU/mL，尘螨（+++）。\n\n诊疗经过：\n入院后完善血常规、C反应蛋白、血气分析、痰培养、胸部CT、心电图、心脏彩超、肺功能及过敏原等检查，明确中医诊断哮病（热哮）、西医诊断支气管哮喘急性发作期（中度）。中医治以清热宣肺、化痰定喘，予定喘汤加减（麻黄6g、白果9g打碎、款冬花10g、法半夏9g、桑白皮12g、黄芩10g、紫苏子9g、苦杏仁9g、甘草6g，痰黄稠加鱼腥草、瓜蒌皮、浙贝母，喘甚加地龙、葶苈子，便秘加生大黄后下，咽痒鼻塞加蝉蜕、辛夷）水煎200mL每日1剂分早晚温服，并针灸定喘、肺俞、膻中、天突、列缺、丰隆等穴。西医予持续低流量吸氧、布地奈德联合异丙托溴铵雾化吸入每日2次、多索茶碱静滴每日1次、甲泼尼龙静滴每日1次，3日后改口服泼尼松并逐渐减停，另予孟鲁司特钠及布地奈德福莫特罗吸入剂维持。治疗第2天喘促及哮鸣减轻、痰色转淡、夜能平卧，第4天哮鸣基本消失、痰转白稀并停静脉激素，第6天喘平、无咳嗽咯痰，复查炎性指标及血气分析正常，肺功能FEV1升至占预计值86%，FeNO降至24ppb。共住院11天，患者病情稳定、症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神好，无喘息、胸闷及喉中哮鸣，无咳嗽咯痰，无夜间憋醒，活动后无气促，饮食睡眠可，二便调。查体：T 36.5℃，P 78次/分，R 18次/分，BP 118/74mmHg，SpO2 98%（未吸氧）；口唇红润，双肺呼吸音清，未闻及干湿性啰音，心律齐，双下肢无水肿。中医四诊：舌质淡红，苔薄白，脉细滑。\n出院医嘱：1. 饮食：清淡易消化饮食，忌辛辣、生冷及海鲜发物，戒烟酒。\n2. 休息与活动：注意休息，避免劳累及情绪激动，循序渐进进行缩唇呼吸、腹式呼吸锻炼，避免冷空气刺激。\n3. 用药：①中药汤剂（益气固表、健脾化痰善后方）：黄芪20g、党参12g、白术12g、防风9g、陈皮9g、法半夏9g、茯苓15g、紫菀10g、款冬花10g、五味子6g、甘草6g，共14剂，水煎取汁200mL，每日1剂，分早晚2次温服；②布地奈德福莫特罗吸入剂1吸，每日2次，吸入后漱口，不可自行停药或减量；③孟鲁司特钠10mg，每晚1次口服；④泼尼松按医嘱逐渐减量至停用，勿骤停。\n4. 复查：出院后2周门诊复查肺功能、呼出气一氧化氮及血嗜酸性粒细胞，之后每3个月随访1次；如有病情变化随时就诊。\n5. 注意事项：避免接触尘螨、花粉、油漆等过敏原及刺激性气味，居室保持清洁通风、勤晒被褥；坚持记录哮喘日记及峰流速，正确使用吸入装置；若出现喘息加重、夜间憋醒或药物缓解不佳，须立即急诊。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年09月12日 09:00（入院第3天）\n\n患者入院第3天，神志清楚，精神好转，诉喘息较入院时明显减轻，喉中哮鸣音减少，咳嗽咯痰较前顺畅，痰色由深黄转淡黄、量减，夜能平卧入睡，口干减轻，身热汗出止，心烦已除，纳可，二便调，夜寐安。\n查体：T 36.7℃，P 88次/分，R 20次/分，BP 118/76mmHg，SpO2 96%（吸氧2L/min）。神志清楚，精神可，半卧位。舌质红，苔黄腻较前变薄，脉滑数较前缓和。双肺可闻及少量哮鸣音，呼气相稍延长，未闻及湿性啰音。心率88次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹软，无压痛。双下肢无水肿。\n辅助检查：血常规WBC 8.2×10^9/L、E% 8.2%，CRP 5.4mg/L，肝肾功能及电解质正常；胸部CT示双肺纹理增粗，未见实变及占位；心脏彩超示左室射血分数63%，心脏结构及功能正常；血气分析（吸氧2L/min）pH 7.42、PaO2 82mmHg、PaCO2 37mmHg、SaO2 96%。\n四诊合参，本病属中医「哮病（热哮）」范畴，系痰热壅肺、肺失宣降，治以清热宣肺、化痰定喘，方用定喘汤加减。患者经中药辨证论治配合解痉平喘、抗炎治疗后，喘促、哮鸣及黄稠痰较前好转，治疗有效。今起静脉激素减量并逐步改口服，继续目前中药治疗，去生大黄，加瓜蒌皮15g以增化痰之力。继续观察呼吸频率、哮鸣音及痰色痰量变化，注意休息，清淡饮食，避免接触过敏原及刺激性气味。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年09月14日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，诉喘息基本缓解，喉中哮鸣音偶闻，咳嗽明显减少，痰少色白易咯，无口干心烦，无夜间憋醒，可平卧，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 78次/分，R 18次/分，BP 120/74mmHg，SpO2 97%（未吸氧）。神志清楚，精神好，平卧位。舌质偏红，苔薄黄，脉滑。双肺呼吸音稍粗，未闻及明显哮鸣音及湿性啰音。心率78次/分，律齐，未闻及病理性杂音。腹软，无压痛。双下肢无水肿。\n辅助检查：复查血常规WBC 7.4×10^9/L、E% 5.1%，CRP 2.6mg/L，血气分析（未吸氧）pH 7.41、PaO2 88mmHg、PaCO2 38mmHg、SaO2 97%，均较前明显改善。\n患者经中药辨证论治后，喘息、哮鸣明显缓解，痰热渐清，病情稳定，治疗有效。继续目前中药治疗，原方去麻黄加炙黄芪20g，酌加白术12g以健脾化痰、扶正固本；吸入激素维持，泼尼松继续按计划递减。建议出院后继续服用中药调理，定期复查肺功能及呼出气一氧化氮，避免接触过敏原，注意休息，清淡饮食，避免劳累及情志刺激，适当进行呼吸功能锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年09月13日 10:00（入院第4天）\n\n今日李副主任医师查房，患者精神可，喘息明显减轻，哮鸣音偶闻，咳嗽减少，痰转白稀、量少易咯，夜能平卧，纳可，二便调。查体：T 36.6℃，P 84次/分，R 19次/分，SpO2 97%（未吸氧）；口唇红润，双肺呼吸音稍粗，未闻明显哮鸣音及湿啰音。中医四诊：面色转淡，舌质偏红、苔薄黄，脉滑。辅查：血E% 5.6%、总IgE 240IU/mL，FeNO 32ppb，血气PaO2 88mmHg。\n\n一、中医辨病辨证分析（辨证要点再确认）\n辨病为哮病发作期、辨证为热哮无疑：反复发作性喉中哮鸣、呼吸气促、不能平卧6年，间歇期如常人，此次为尘螨、油漆异味引动，与宿痰伏肺、遇感而发之特点吻合。辨证要点：病位在肺、在气道，以喉中哮鸣如吼、喘息气粗、胸高胁胀为主症；痰黄稠、口干喜冷饮、身热汗出，里热确凿，可与冷哮、风痰哮区分；舌红苔黄腻、脉滑数，为痰热内盛之确证。今痰转白稀、苔转薄黄、脉转滑，热势已衰，然舌仍偏红，示余热未清、肺阴已伤，兼久病脾肺气虚，故病机为痰热渐清而未尽、肺阴受损、脾肺气虚渐显，证属痰热未尽兼气阴两伤、正虚邪恋，治法须清化余热与扶正固本并行。\n\n二、中医鉴别诊断\n1.与「肺痈」鉴别：肺痈以咳吐腥臭脓痰、胸痛发热为主症，痰可分层，影像可见空洞或液平；本案无腥臭脓痰，胸部CT仅见肺纹理增粗，且以发作性哮鸣为特征，故非肺痈。\n2.与「肺热病（风温肺热）」鉴别：肺热病多急起高热、咳嗽胸痛，病程短，血象及炎症指标明显升高；本案无发热，CRP及PCT正常，病程反复发作，与急性外感不同。\n3.与「喘脱」鉴别：喘脱为喘促持续不解、张口抬肩、汗出如雨、面色青紫、神志改变、脉微欲绝之危候，相当于哮喘持续状态合并呼吸衰竭；本案神清、呼吸平稳、指脉氧97%、无发绀，非喘脱之证，惟哮病确有转喘脱之可能，须反复强调。\n\n三、西医疑难分析与鉴别诊断\n本例西医诊断为支气管哮喘急性发作期（中度）、过敏性（嗜酸性粒细胞性）表型，合并过敏性鼻炎，治疗有效。疑难之处在于气道慢性炎症与气道高反应性并存，若满足于急性期缓解而不予长期抗炎控制，易反复发作并致气道重塑、肺功能进行性下降。鉴别须除外心源性哮喘（心脏彩超正常、无奔马律及粉红色泡沫痰）、慢阻肺急性加重（舒张试验阳性、FeNO及血EOS升高，不支持）及上气道阻塞、声带功能障碍（喘鸣以吸气相为主，不符）。\n\n四、国内外相关疾病研究进展\n1. GINA 2023确立以维持哮喘控制、追求「临床缓解」为目标的阶梯式治疗策略，明确吸入性糖皮质激素为长期控制基石，不推荐单用短效β2受体激动剂；对血EOS或FeNO升高的重度哮喘，推荐阶梯5加用抗IgE、抗IL-5/IL-5R生物制剂，可减少急性发作并降低口服激素用量。\n2.一项纳入数千例患者的荟萃分析提示，以FeNO指导吸入激素剂量调整可使哮喘急性发作风险下降约20%～25%，且不增加激素累积剂量，支持本例出院后以FeNO动态随访。\n3.中药扶正固本类方药治疗哮喘缓解期的系统评价（纳入10余项随机对照试验）提示，玉屏风散、金匮肾气丸等健脾补肺益肾方药可减少急性发作、改善免疫指标；穴位贴敷辅助治疗可降低发作频率，可作冬病夏治之选。\n五、诊疗计划\n1.中医治疗：治以清化余热、益气养阴、健脾补肺，扶正与祛邪并行。调整方药：定喘汤减麻黄为3g、去黄芩，加炙黄芪15g、炒白术12g、茯苓15g、南沙参12g。处方：炙黄芪15g、炒白术12g、茯苓15g、南沙参12g、白果9g（打碎）、款冬花10g、法半夏9g、桑白皮12g、紫苏子9g、苦杏仁9g、浙贝母10g、地龙10g、炙甘草6g。水煎服，每日1剂，煎取200mL，分早晚2次温服。方解：炙黄芪补气固表、炒白术健脾燥湿、茯苓健脾渗湿，三药培土生金、补益肺脾为君，取「脾为生痰之源、肺为贮痰之器」之意以杜生痰之本；南沙参养阴清肺、顾护已伤之肺阴为臣；白果敛肺定喘，款冬花润肺下气，法半夏、紫苏子、苦杏仁降气化痰，桑白皮泻肺中余热，浙贝母清热化痰，地龙通络解痉，共为佐；炙甘草调和诸药为使。全方补虚而不恋邪、清热而不伤正。可择期行穴位贴敷（三伏贴）。\n2.西医治疗：泼尼松30mg口服qd，每3～5日减5mg至停药；雾化减为每日1次，2日后停用，改布地奈德福莫特罗吸入剂160/4.5μg，每次1吸、每日2次长期维持；孟鲁司特钠10mg qn；多索茶碱停用；沙丁胺醇气雾剂按需备用。监测血糖、血压、血钾及心电图。\n3.护理与调摄：忌辛辣煎炸及鱼虾发物，戒烟酒，宜食山药、莲子、百合、梨等健脾润肺之品；起居规律，避风寒，勤晒被褥除尘螨；情志调畅，适度练呼吸操、八段锦。\n4.医患沟通：说明急性发作已控制、痰热渐清而正气未复，中药转为扶正为主需坚持服用；强调长期规范吸入激素是预防复发的关键，不可因症状消失自行停药；告知激素减量方案及不良反应监测情况，指导吸入装置用法并记录峰流速；嘱出院后2～4周呼吸科复诊，3个月复查肺功能及FeNO。\n下一步计划：1.动态评估疗效，出院前复查肺功能、FeNO及血嗜酸性粒细胞；2.完成激素降阶梯及雾化向吸入维持治疗的转换；3.制定缓解期扶正固本方案（可予玉屏风散合六味地黄丸加减）及随访计划。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1224,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1322b3e2bfb330fbec22672ed601e03a0c40ee969f29a2d6a368c3d529133b29","pinyin":"xiaobing（rexiao）","initials":"xb（rx）","setting":"in","caseName":"病例1：患者，女，42岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，42岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-514d1c482f2530aede19","key":"v1-c9ccc21dfe2a3058|templates-514d1c482f2530aede19","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"哮病（虚哮）","category":"中医科","raw":{"name":"哮病（虚哮）","category":"中医科","case":{"case_name":"病例1：患者，男，46岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：46岁 民族：汉族\n婚姻：已婚 职业：农民 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：反复发作性喉中哮鸣有声伴气喘10年，加重5天。\n\n现病史：患者于10年前因受凉后出现喉中哮鸣有声，呼吸气促，胸闷如塞，咳痰不爽，当时于当地诊所予抗感染、平喘治疗（具体用药不详）后缓解。此后每因气候变化、受凉、劳累或闻及刺激性气味而反复发作，以秋冬季节为多，每年发作3～5次，每次持续数日至十余日不等，发作时喉中如水鸡声，不能平卧，需坐起方能稍缓。缓解期仍觉气短乏力，动则汗出，容易感冒，咳嗽痰多。5天前因外出淋雨受凉后再发，出现喉中哮鸣有声，呼吸急促，胸闷，咳嗽，咳白色稀泡沫痰，量多易咯，气短不足以息，动则喘甚，语音低怯，自汗畏风，倦怠乏力，食少便溏。自行服用\"氨茶碱片\"及家中备用中成药（具体不详）后症状缓解不明显，昨夜因气喘不能平卧，依坐而寐，严重影响休息，今晨由家属陪同来我院门诊就诊，门诊以\"哮病（虚哮）\"收入我科。发病以来无寒战高热，无胸痛咯血，无意识障碍，无下肢水肿。精神倦怠，食欲不振，睡眠差，二便尚调，体重无明显下降。\n\n既往史：既往有支气管哮喘病史10年，长期未规律使用吸入激素，间断口服平喘药物。既往有过敏性鼻炎病史6年。否认高血压、糖尿病、冠心病史。否认肝炎、结核等传染病史。否认手术、外伤及输血史。否认食物、药物过敏史。预防接种史随当地。\n\n个人史及家族史：生于本地，久居本地，从事农业劳动，长期接触花粉、尘螨及霉菌等。吸烟20年，每日约15支，已戒3年；偶饮酒。家族中母亲有哮喘病史，否认其他遗传病及传染病家族史。\n婚育史：24岁结婚，配偶及子女体健，育有1子1女。\n体格检查：\nT 37.1℃，P 96次/分，R 24次/分，BP 122/76mmHg，指脉氧饱和度（未吸氧）92%。\n一般情况：神志清楚，精神倦怠，发育正常，营养中等，面色少华，形体偏瘦，自主体位（端坐呼吸），查体合作，言语低怯。\n\n中医四诊：\n望诊：神志清楚，精神倦怠，面色少华偏白，形体偏瘦，喉中哮鸣，呼吸急促，动则喘甚，咳白色稀泡沫痰，口唇轻度发绀，舌质淡，边有齿痕，苔薄白，望诊喉间无痰声辘辘之实证表现。\n闻诊：语声低怯，气短不足以息，喉中可闻及哮鸣音，咳声低沉，痰声清稀，无异常气味。\n问诊：喉中哮鸣有声，呼吸急促，胸闷，气短乏力，动则喘甚，自汗畏风，咳白色稀泡沫痰、量多易咯，容易感冒，食少便溏，纳差，夜寐不安，二便尚调。\n切诊：脉沉细弱。\n一般情况：神志清楚，精神反应可，营养发育正常，查体合作。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可，口唇轻度发绀。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大，无颈静脉怒张。\n胸部：胸廓对称，肋间隙稍增宽，双肺呼吸动度一致，双侧语颤对称，叩诊呈清音，双肺可闻及散在哮鸣音，呼气相为主，未闻及明显湿性啰音。心率96次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常，无杵状指，双下肢无水肿。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：端坐呼吸，呼吸急促，动则喘甚，喉中哮鸣有声，口唇轻度发绀；舌象：舌质淡，边有齿痕，苔薄白；脉象：脉沉细弱。专科查体：胸廓对称，肋间隙稍增宽，三凹征阴性，双肺呼吸动度一致，双肺可闻及散在哮鸣音，以呼气相为主，呼气相延长，未闻及湿性啰音。关键阴性体征：无寒战高热，无胸痛及咯血，无三凹征及端坐呼吸加重，无意识模糊及嗜睡，无颈静脉怒张，无双下肢水肿，无杵状指，无一侧呼吸音消失，无皮下气肿，病理征阴性。\n辅助检查：\n门诊血常规：WBC 7.8×10^9/L，N% 58%，E% 8.6%，Hb 128g/L，PLT 218×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n门诊胸部X线：双肺纹理增粗、增多，透亮度略增高，未见明显实变及占位征象，心影大小大致正常。\n门诊心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：哮病（虚哮）\n中医诊断依据：1.辨病依据：患者反复发作性喉中哮鸣有声伴气喘10年，每因气候变化、受凉、劳累或闻及刺激性气味而发，以秋冬为多，发作时喉中如水鸡声、不能平卧、需坐起方缓，缓解期亦觉气短乏力，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，故辨病为哮病。2.辨证依据：①主症：反复发作之喉中哮鸣、呼吸急促，气短不足以息，动则喘甚，语音低怯，咳白色稀泡沫痰、量多易咯，自汗畏风，容易感冒，倦怠乏力，食少便溏，口唇轻度发绀，形体偏瘦；②舌象脉象：舌质淡，边有齿痕，苔薄白，脉沉细弱；③病因病机：哮病反复发作，日久耗伤肺气，肺虚不能主气、气不化津，痰浊内蕴；肺病及脾，脾虚运化失职则食少便溏、痰浊内生；久病由肺及肾，肾虚不能纳气，故气短不足以息、动则喘甚、自汗畏风；舌淡边有齿痕、脉沉细弱为肺脾肾俱虚之征。总属肺脾肾三脏俱虚、痰浊内蕴之本虚标实证，故辨证为虚哮。\n中医鉴别诊断：1.与「喘证」鉴别：喘证以气息言，以呼吸困难、张口抬肩、鼻翼扇动、不能平卧为特征，可见于多种急慢性疾病过程中，为气机升降出纳失常所致，无发作性喉中哮鸣；哮病以声响言，以发作时喉中哮鸣有声、反复发作为特征。哮必兼喘，喘未必兼哮；本例喉中哮鸣反复发作、缓解期仍气短乏力，属哮病之虚哮，非单纯喘证。2.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、心悸、面色晦暗为主症，病程缠绵、进行性加重，多见桶状胸、颈静脉怒张、右心衰竭及杵状指；本例虽有气短动则喘甚、口唇轻度发绀，但胸廓对称、肋间隙仅稍增宽、无颈静脉怒张及下肢水肿，暂无肺胀之典型征象，须动态观察。3.与「支饮」鉴别：支饮为饮邪停留胸膈，咳逆倚息、短气不得卧、其形如肿，常伴水肿、小便不利；哮病为宿痰伏肺、遇感而发，发作有时、缓解如常人。本例无水肿及小便不利，可资鉴别。4.与「冷哮」「热哮」鉴别：虚哮以反复发作、气短不足以息、动则喘甚、声低息微、自汗畏风、食少便溏、舌淡边有齿痕、脉沉细弱为特点，属本虚标实；冷哮以寒痰为患、舌苔白滑、脉弦紧；热哮以痰热为患、舌红苔黄腻、脉滑数，三者寒热虚实之象判然有别。5.与「肺脾气虚」鉴别：肺脾气虚以平素气短乏力、自汗畏风、易感冒、食少便溏为主，无发作性喉中哮鸣；虚哮则于本虚之上仍有哮鸣发作之标实，二者轻重主次不同。\n西医诊断：支气管哮喘（慢性持续期，急性发作） / 过敏性鼻炎\n西医诊断依据：1.病史依据：反复发作性喘息、气促、胸闷、咳嗽10年，每因受凉、气候变化、劳累及理化刺激诱发，每年发作3～5次，长期未规律吸入糖皮质激素，有过敏性鼻炎病史6年、母亲哮喘病史、吸烟史20年（已戒3年）；2.症状依据：5天前淋雨受凉后再发，喉中哮鸣有声、呼吸急促、胸闷、咳嗽、咳白色稀泡沫痰量多易咯、气短、动则喘甚，夜间不能平卧、依坐而寐；3.体征依据：T 37.1℃，P 96次/分，R 24次/分，BP 122/76mmHg，SpO2 92%（未吸氧），精神倦怠，端坐呼吸，口唇轻度发绀，胸廓对称、肋间隙稍增宽，双肺可闻及散在哮鸣音、以呼气相为主、呼气相延长、未闻及湿性啰音，无杵状指、无颈静脉怒张及下肢水肿；4.实验室依据：血常规WBC 7.8×10^9/L、N% 58%、E% 8.6%（嗜酸性粒细胞升高），肝肾功能及电解质正常；5.影像学依据：胸部X线示双肺纹理增粗增多、透亮度略增高，未见实变及占位，心影大小大致正常；心电图正常；6.肺功能依据：肺功能加支气管舒张试验待完善，若FEV1占预计值下降且支气管舒张试验阳性（FEV1改善率≥12%且绝对值增加≥200ml）即可确诊并证实可逆性气流受限，必要时查血气分析、FeNO、血清总IgE及过敏原、胸部CT除外COPD及支气管扩张。符合支气管哮喘（慢性持续期，急性发作），合并过敏性鼻炎。\n西医分型/分级/分期：①疾病分期：慢性持续期，急性发作；②急性发作严重程度分级：中度——喜坐位、端坐呼吸、呼吸频率24次/分（20～30次/分）、心率96次/分、未吸氧SpO2 92%（90%～95%）、双肺散在哮鸣音、口唇轻度发绀、无意识改变；③病情严重程度（慢性持续期）分级：第3级（中度持续），病程10年、长期未规律吸入糖皮质激素，发作频繁（每年3～5次）；④控制水平：未控制（日间症状、夜间憋醒需坐起、活动受限、缓解药物使用频繁，ACT评分预计＜20分）；⑤气流受限：待肺功能证实阻塞性通气功能障碍及可逆性（支气管舒张试验FEV1改善率≥12%且绝对值增加≥200ml）；⑥气道炎症表型：嗜酸性粒细胞性哮喘（E% 8.6%）；⑦并发症/合并症：过敏性鼻炎（6年）、肺气肿倾向（胸部X线透亮度略增高）、吸烟史20年（已戒3年，属COPD高危人群，须与COPD鉴别）。\n\n诊疗计划：\n1.按内科Ⅱ级护理，半流质饮食，卧床休息，抬高床头，保持病室空气清新、温湿度适宜；2.完善检查：动脉血气分析（目的：评估缺氧及二氧化碳潴留程度，为氧疗与通气支持决策提供依据）、肺功能加支气管舒张试验（目的：客观评估气道阻塞可逆性与肺功能受损程度，为哮喘分级与长期用药方案提供依据）、呼出气一氧化氮测定（目的：评估气道嗜酸粒细胞性炎症水平，指导吸入激素剂量调整）、血清总IgE及过敏原检测（目的：明确过敏病因、评估抗IgE治疗指征）、血常规+C反应蛋白（目的：明确有无合并感染及炎症状态，为抗感染治疗提供依据）、痰培养（目的：明确致病菌及药敏，指导抗菌药物选择）、胸部CT（目的：排除肺部感染、气胸等并发症，明确肺部基础病变）、心脏彩超（目的：评估心功能与右心负荷，排除心源性喘息）；3.一般治疗：鼻导管低流量吸氧（2L/min）；4.药物治疗：补肺纳肾、降气化痰中药汤剂（平喘固本汤加减），布地奈德福莫特罗粉吸入剂1吸每日2次吸入，必要时沙丁胺醇气雾剂1～2喷按需吸入，氨溴索30mg每日3次口服，泼尼松20mg每日1次晨服（短期），合并感染时加用抗生素；5.中医特色治疗：穴位贴敷（肺俞、定喘、膏肓、足三里）及艾灸，耳穴压豆（肺、肾、神门、交感），缓解期指导冬病夏治三伏贴；6.病情观察：观察哮鸣音、呼吸频率、指脉氧饱和度及痰液变化，警惕哮喘持续状态、气胸及呼吸衰竭；7.健康教育：指导避免接触花粉尘螨等诱因，正确使用吸入装置，坚持长期规范用药，行缩唇呼吸及呼吸操锻炼，注意保暖防感冒，定期复诊。\n\n专科检查：\n望诊：端坐呼吸，呼吸急促，动则喘甚，喉中哮鸣有声，口唇轻度发绀；舌象：舌质淡，边有齿痕，苔薄白；脉象：脉沉细弱。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，男，46岁，因\"反复发作性喉中哮鸣有声伴气喘10年，加重5天\"入院。\n2.既往史：支气管哮喘病史10年，未规律吸入激素治疗；过敏性鼻炎病史6年；吸烟20年，已戒3年；母亲有哮喘病史。\n3.体格检查：T 37.1℃，P 96次/分，R 24次/分，BP 122/76mmHg，指脉氧饱和度（未吸氧）92%。精神倦怠，端坐呼吸，口唇轻度发绀，双肺可闻及散在哮鸣音，以呼气相为主，呼气相延长，未闻及湿性啰音，双下肢无水肿。\n4.中医四诊：舌质淡，边有齿痕，苔薄白，脉沉细弱；语声低怯，气短不足以息，自汗畏风，咳白色稀泡沫痰、量多易咯，食少便溏。\n5.辅助检查：血常规示E% 8.6%，余基本正常；胸部X线示双肺纹理增粗、增多，透亮度略增高，未见实变；心电图正常；生化肝肾功能、电解质正常。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：哮病（虚哮）\n西医诊断：支气管哮喘（慢性持续期，急性发作） / 过敏性鼻炎\n\n（二）中医诊断依据：\n1.辨病依据：患者反复发作性喉中哮鸣有声伴气喘10年，每因气候变化、受凉、劳累或理化刺激而发，发作时不能平卧、需坐起方缓，缓解期亦气短乏力，符合哮病「发作时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，反复发作」之诊断要点，故辨病为哮病。\n2.辨证依据：反复发作性喉中哮鸣、呼吸急促、胸闷咳嗽，咳白色稀泡沫痰量多易咯，气短不足以息、动则喘甚、语音低怯，自汗畏风、容易感冒、倦怠乏力、食少便溏；舌质淡、边有齿痕、苔薄白，脉沉细弱。此为哮病反复发作，日久耗伤肺气，肺虚不能主气、气不化津，痰浊内蕴；肺病及脾，脾虚运化失职则痰浊内生、食少便溏；久病由肺及肾，肾虚不能纳气，故气短不足以息、动则喘甚、自汗畏风。总属肺脾肾三脏俱虚、痰浊内蕴之本虚标实证，故辨证为虚哮。\n3.治法方药：治以补肺纳肾、降气化痰，方用平喘固本汤加减（党参15g、五味子6g打碎、胡桃肉15g、紫河车粉3g冲服、沉香3g后下、灵磁石30g先煎、紫苏子9g、款冬花10g、法半夏9g、橘红9g）；脾虚甚加白术12g、茯苓15g、山药15g，肾虚甚加熟地黄15g、山茱萸12g、补骨脂10g，痰多加白芥子6g。缓解期宜补肺健脾益肾，可用六君子汤、玉屏风散或金匮肾气丸调理。\n依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·哮病·虚哮证。\n\n（三）中医鉴别诊断：\n1.与「喘证」鉴别：喘证以气息言，以呼吸困难、张口抬肩、鼻翼扇动、不能平卧为特征，可见于多种急慢性疾病过程中，无发作性喉中哮鸣；哮病以声响言，以发作时喉中哮鸣有声、反复发作为特征。哮必兼喘，喘未必兼哮；本例喉中哮鸣反复发作、缓解期仍气短乏力，属哮病之虚哮。\n2.与「肺胀」鉴别：肺胀以胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、心悸、面色晦暗为主症，病程缠绵、进行性加重，多见桶状胸、颈静脉怒张及右心衰竭征象；本例胸廓对称、肋间隙仅稍增宽、无颈静脉怒张及下肢水肿，暂无肺胀之典型征象，须动态观察。\n3.与「支饮」鉴别：支饮为饮邪停留胸膈，咳逆倚息、短气不得卧、其形如肿，多伴水肿、小便不利；哮病为宿痰伏肺、遇感而发，发作有时、缓解如常人。本例无水肿及小便不利，可资鉴别。\n4.与「冷哮」鉴别：冷哮以寒痰为患，喉中哮鸣如水鸡声、痰白多泡沫、口不渴、舌苔白滑、脉弦紧，属实寒之证；本例虽咳白色稀泡沫痰，但气短不足以息、动则喘甚、自汗畏风、食少便溏、舌淡边有齿痕、脉沉细弱，为本虚标实之虚哮，与纯实之冷哮不同。\n5.与「热哮」鉴别：热哮见气粗息涌、痰黄稠、口渴喜冷饮、舌红苔黄腻、脉滑数，属痰热实证；本例痰白清稀、无热象而见虚象，二者虚实寒热判然有别。\n6.与「肺脾气虚」鉴别：肺脾气虚以平素气短乏力、自汗畏风、易感冒、食少便溏为主，无发作性喉中哮鸣；虚哮则于本虚之上仍有哮鸣发作之标实，二者轻重主次不同。\n提示：若见喘息持续不解、汗出肢冷、面青唇紫、神志改变者，为哮病危候，须立即抢救并请上级医师查房。\n\n（四）西医诊断依据：\n1.病史依据：反复发作性喘息、气促、胸闷、咳嗽10年，每因受凉、气候变化、劳累及理化刺激诱发，每年发作3～5次，长期未规律吸入糖皮质激素，有过敏性鼻炎6年、母亲哮喘病史、吸烟史20年（已戒3年）。\n2.症状依据：淋雨受凉后再发，喉中哮鸣有声、呼吸急促、胸闷、咳嗽、咳白色稀泡沫痰量多易咯、气短、动则喘甚，夜间不能平卧、依坐而寐。\n3.体征依据：T 37.1℃，P 96次/分，R 24次/分，BP 122/76mmHg，SpO2 92%（未吸氧），精神倦怠，端坐呼吸，口唇轻度发绀，双肺散在哮鸣音、以呼气相为主、呼气相延长、未闻及湿性啰音，无杵状指、无颈静脉怒张及下肢水肿。\n4.实验室依据：血常规WBC 7.8×10^9/L、N% 58%、E% 8.6%（嗜酸性粒细胞升高），肝肾功能及电解质正常。\n5.影像学依据：胸部X线示双肺纹理增粗增多、透亮度略增高，未见实变及占位，心影大小大致正常；心电图正常。\n6.肺功能依据：肺功能加支气管舒张试验待完善，若FEV1占预计值下降且支气管舒张试验阳性（FEV1改善率≥12%且绝对值增加≥200ml）即可确诊并证实可逆性气流受限；必要时查血气分析、FeNO、总IgE及过敏原、胸部CT，以除外COPD及支气管扩张。\n符合支气管哮喘（慢性持续期，急性发作），合并过敏性鼻炎。\n\n（五）西医分型/分级/分期：\n①疾病分期：慢性持续期，急性发作。②急性发作严重程度分级：中度（端坐呼吸、呼吸24次/分、心率96次/分、SpO2 92%、口唇轻度发绀、双肺散在哮鸣音、无意识改变）。③病情严重程度（慢性持续期）分级：第3级（中度持续），病程10年、长期未规范吸入糖皮质激素、每年发作3～5次。④控制水平：未控制（日间症状、夜间憋醒、活动受限、缓解药物使用频繁，ACT评分预计＜20分）。⑤气流受限：待肺功能及支气管舒张试验证实阻塞性通气功能障碍及可逆性。⑥气道炎症表型：嗜酸性粒细胞性哮喘（E% 8.6%）。⑦合并症及并发症：过敏性鼻炎、肺气肿倾向（胸部X线透亮度略增高）、吸烟史20年（已戒3年，属COPD高危人群，须与COPD鉴别）。\n\n（六）西医鉴别诊断：\n1.慢性阻塞性肺疾病急性加重：\n【支持点】患者46岁男性、吸烟20年（已戒3年），本次喘息急性加重伴呼气相延长、双肺哮鸣音，胸部X线示双肺透亮度略增高，与慢性阻塞性肺疾病急性加重表现相似，属须重点鉴别的疾病。\n【不支持点】患者有10年反复发作性喘息史，发作间期可缓解，既往诊断支气管哮喘并伴过敏性鼻炎及哮喘家族史，嗜酸性粒细胞比例8.6%升高；胸部X线未见明显桶状胸及弥漫性肺气肿改变。\n【排除方法】完善肺功能及支气管舒张试验（FEV1/FVC＜70%且舒张后不完全可逆支持慢性阻塞性肺疾病）、弥散功能及胸部CT（肺气肿、肺大疱），结合吸烟指数、起病年龄及症状演变综合判断。\n2.急性左心衰竭（心源性哮喘）：\n【支持点】急性左心衰竭可表现为端坐呼吸、夜间不能平卧、双肺哮鸣音及低氧血症，与本次端坐呼吸、口唇轻度发绀相似。\n【不支持点】本例无高血压、冠心病、心脏瓣膜病等基础心脏病史，咳白色稀泡沫痰量多而非粉红色泡沫痰，无颈静脉怒张、肝颈静脉回流征阳性及双下肢水肿，心电图正常，未闻及奔马律。\n【排除方法】查血浆BNP/NT-proBNP、心脏彩超（左室射血分数、室壁运动、左房大小）及胸部X线（心影大小、肺淤血），BNP正常且无心衰体征者可除外。\n3.支气管扩张症（继发感染）：\n【支持点】支气管扩张症可表现为反复咳嗽、咳大量痰液及喘息，感染时症状加重，与本例咳白色稀泡沫痰量多相似。\n【不支持点】本例无长期咳大量脓性痰及反复咯血史，无杵状指，胸部X线未见卷发样或轨道样阴影，缓解期可如常人。\n【排除方法】完善胸部高分辨率CT（印戒征、轨道征、囊状扩张）及痰培养，无支气管扩张影像学改变者可除外。\n4.自发性气胸：\n【支持点】可突发呼吸困难、患侧呼吸音减低及发绀，须与本次急性加重鉴别。\n【不支持点】本例双肺均可闻及散在哮鸣音、以呼气相为主，无突发针刺样胸痛，气管居中，无皮下气肿及单侧呼吸音消失。\n【排除方法】急查胸部X线或胸部CT，未见气胸线及肺压缩带即可除外；本例胸部X线未见气胸征象。\n5.肺栓塞：\n【支持点】肺栓塞可表现为突发呼吸困难、气促、低氧血症（SpO2 92%）及哮鸣音，须与支气管哮喘急性发作鉴别。\n【不支持点】本例有淋雨受凉诱因及10年反复发作史，无胸痛咯血、晕厥、单侧下肢肿胀，无近期手术、制动、骨折及恶性肿瘤等高危因素。\n【排除方法】查D-二聚体、动脉血气分析、心电图及CT肺动脉造影；D-二聚体阴性且无高危因素者可基本除外。\n6.上气道阻塞（气管肿瘤、声带功能障碍）：\n【支持点】均可出现喘鸣及呼吸困难，易被误认为支气管哮喘急性发作。\n【不支持点】上气道阻塞多为吸气性喘鸣、以颈部为著，常伴声音嘶哑、咯血及吸气性三凹征；本例语声低怯但无嘶哑，喘鸣以呼气相为主、双肺广泛分布。\n【排除方法】查颈胸部CT、支气管镜及肺功能流速-容量环（吸气相平台样改变提示上气道阻塞），结合喘鸣时相鉴别。\n\n（七）诊疗计划：\n1.护理与饮食：按中医科哮病（虚哮）护理常规，内科Ⅱ级护理；半流质饮食，低盐低脂饮食，卧床休息，抬高床头，保持病室空气清新、温湿度适宜，避免接触花粉、尘螨、冷空气及理化刺激等诱发因素。\n2.完善检查：①完善动脉血气分析（目的：评估氧合及有无二氧化碳潴留，为氧疗及急性发作严重程度判定提供依据）；②完善肺功能加支气管舒张试验（目的：明确气流受限程度及可逆性，为确诊支气管哮喘并与慢性阻塞性肺疾病鉴别提供依据）；③完善呼出气一氧化氮测定（目的：评估气道嗜酸性炎症水平，为指导吸入糖皮质激素剂量调整提供依据）；④完善血清总IgE及过敏原检测（目的：明确致敏原，为环境规避及特异性免疫治疗提供依据）；⑤复查血常规、C反应蛋白及嗜酸性粒细胞计数（目的：评估感染与气道炎症状态，为是否加用抗菌药物提供依据）；⑥完善痰培养（目的：明确有无细菌感染及致病菌，为抗菌药物选择提供依据）；⑦完善胸部CT（目的：明确有无肺气肿、肺炎、气胸及支气管扩张，为喘息病因鉴别提供依据）；⑧完善心电图、心脏彩超及血浆BNP（目的：除外心律失常、慢性肺源性心脏病及心源性哮喘，为鉴别心源性喘息提供依据）。\n3.西医治疗：给予布地奈德福莫特罗粉吸入剂（160/4.5μg）1吸 每日2次 经口吸入，吸后立即漱口；给予沙丁胺醇气雾剂1～2喷 按需吸入，每日不超过8喷，喘息缓解即停；给予醋酸泼尼松片20mg 每日1次 晨服，连用5天后每2日减5mg逐渐停用，用药期间监测血糖、血压及血钾；给予氨溴索片30mg 每日3次 口服化痰；给予鼻导管低流量吸氧2L/min，维持指脉氧饱和度在93%以上；无感染证据暂不加用抗菌药物，若痰培养阳性或血WBC、C反应蛋白升高，则依据药敏结果加用抗菌药物抗炎治疗。\n4.中医治疗：给予中药方剂以补肺纳肾、降气化痰、益气固表为治则；方选平喘固本汤合玉屏风散加减。中药处方如下：炙黄芪20g 党参15g 炒白术12g 防风10g 五味子10g（打碎） 胡桃肉15g 紫河车6g（研末冲服） 沉香3g（后下） 灵磁石30g（先煎） 紫苏子10g 紫菀10g 款冬花10g 法半夏9g 陈皮9g 茯苓15g 熟地黄15g 山茱萸12g 炙甘草6g。用法：水煎服，每日一付，分2次温服，早晚饭后各服约200ml。方解：方中炙黄芪、党参补肺健脾、益气固表，直对肺脾气虚、卫外不固之本，共为君药；炒白术、茯苓健脾运湿以杜生痰之源，熟地黄、山茱萸、胡桃肉、紫河车补肾填精、纳气归元，针对久病由肺及肾、肾不纳气之动则喘甚，五味子酸收敛肺、纳肾止汗，五药共为臣药；沉香降气纳肾、引气归元，灵磁石质重沉降、镇摄纳气，紫苏子降气消痰、止咳定喘，紫菀、款冬花润肺下气、化痰止咳，法半夏、陈皮燥湿理气化痰，令补而不滞、标本兼顾，共为佐药；防风配黄芪、白术固卫御邪、祛风止汗，炙甘草益气和中、调和诸药，共为使药。全方熔补肺、健脾、益肾、化痰、降气、固表于一炉，共奏补肺纳肾、降气化痰、益气固表之效。随症加减：痰多黏稠难咯者加海浮石15g、浙贝母10g；畏寒明显、遇冷即发者加桂枝9g、干姜6g；纳差便溏甚者加焦山楂15g、炒麦芽15g，去熟地黄；气短动则喘甚、腰膝酸软者加补骨脂12g。另予穴位贴敷（肺俞、定喘、膏肓、足三里）每日1次，耳穴压豆（肺、肾、神门、交感）每周2次，缓解期指导冬病夏治三伏贴。\n5.密切观察病情变化，重点观察哮鸣音、呼吸频率、指脉氧饱和度及痰液色质量的变化，警惕哮喘持续状态、气胸及呼吸衰竭；向家属交代目前病情及口服激素减量方案，注意防跌倒、防受凉外感，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房，患者精神较前好转，昨夜可平卧入睡约5小时，喉中哮鸣及气喘明显减轻，仍咳少量白色泡沫痰，气短乏力，自汗畏风。查体：T 36.8℃，P 88次/分，R 20次/分，BP 120/74mmHg，SpO2 95%（未吸氧）；舌质淡、边有齿痕、苔薄白，脉沉细；双肺可闻及少量哮鸣音、以呼气相为主，未闻及湿啰音。辅助检查：血气示轻度低氧血症；肺功能FEV1占预计值68%，支气管舒张试验阳性（改善率16.2%）；FeNO 48ppb；总IgE及特异性IgE阳性；痰培养阴性；胸部CT未见实变及占位。执行情况：医嘱均已落实，吸入手法已纠正。\n\n一、中医辨病辨证分析\n患者反复发作性喉中哮鸣伴气喘10年，发时不能平卧，缓解期仍气短乏力，符合哮病「发时喉中哮鸣有声，呼吸气促困难，甚则不能平卧，反复发作」之要点，故辨病为哮病。四诊合参：面色少华，咳白色稀泡沫痰，舌淡、边有齿痕、苔薄白；语声低怯、痰声清稀；气短不足以息、动则喘甚、自汗畏风、食少便溏；脉沉细。此乃哮病久发，肺虚不能主气、气不化津，痰浊内蕴；肺病及脾，脾虚失运，聚湿生痰；久病由肺及肾，肾虚摄纳无权，故动则喘甚。痰伏于肺为标实，肺脾肾俱虚为本虚，总属本虚标实之虚哮。今哮鸣减轻、血氧回升，而舌仍淡有齿痕、脉仍沉细，示标实渐去而本虚未复，扶正之品不可早撤。\n\n二、中医鉴别诊断\n1.与「喘证」鉴别：喘证以气息言，见呼吸困难、张口抬肩，多持续存在并随原发病进退，无「发作有时、缓解如常」之规律；哮病以声响言，喉中哮鸣有声、反复发作。本案哮鸣因受凉而作、治2日即减，舒张试验阳性示气道可逆性痉挛，故属哮病。\n2.与「肺胀」鉴别：肺胀以胸中胀满、憋闷如塞、面色晦暗、甚则喘脱为主，病程进行性加重，多见肺气肿及右心负荷增重。本案CT未见肺气肿，心影不大，无颈静脉怒张及下肢水肿，暂无肺胀之征；惟吸烟20年，属高危，须随访肺功能与心脏彩超。\n3.与「支饮」鉴别：支饮为饮停胸膈，咳逆倚息、短气不得卧、其形如肿，常伴浮肿及小便不利。本案无浮肿、小便通利，痰随哮鸣发作而现、缓解期痰少，属宿痰伏肺、遇感而发，非饮邪停聚。\n\n三、西医鉴别诊断\n1.与慢性阻塞性肺疾病鉴别：COPD多见于长期吸烟者，气流受限不完全可逆；本案舒张试验改善率16.2%，具可逆性，CT无肺气肿，支持哮喘；因吸烟20年，需警惕哮喘-COPD重叠。\n2.与心源性哮喘鉴别：该病多有高血压、冠心病史，见夜间阵发性呼吸困难、粉红色泡沫痰、双肺底湿啰音；本案无心脏基础病，BNP及心脏彩超正常，不支持。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》推荐成人哮喘以规律吸入糖皮质激素（ICS）为长期基础治疗，不推荐单用短效β2受体激动剂，并推荐ICS-福莫特罗可兼作维持与缓解治疗。\n2.全球哮喘防治创议（GINA 2023）将急性发作期口服激素短程（5～7天）及以FeNO评估2型炎症、指导ICS剂量调整写入推荐；本案FeNO 48ppb、血E% 8.2%、总IgE升高，提示2型炎症表型。\n3.一项纳入数千例中重度哮喘患者的随机对照试验显示，ICS联合长效β2受体激动剂可显著减少急性发作、改善肺功能，单用LABA则增加哮喘相关死亡风险；一项中药治疗哮喘的系统评价（纳入多项随机对照试验）提示，补肺健脾类方药联合西药可改善ACT评分、减少复发，但研究质量参差，仍应以规范吸入治疗为基石。\n\n五、诊疗计划\n1.中医治疗：治则补肺纳肾、降气化痰，兼益气固表，方用平喘固本汤合玉屏风散加减。处方：炙黄芪20g、党参15g、炒白术12g、防风10g、五味子10g（打碎）、胡桃肉15g、紫河车6g（冲服）、沉香3g（后下）、灵磁石30g（先煎）、紫苏子10g、紫菀10g、款冬花10g、法半夏9g、陈皮9g、茯苓15g、熟地黄15g、山茱萸12g、炙甘草6g。用法：水煎服，每日一付，分2次温服，早晚饭后各约200ml。方解：炙黄芪、党参补肺健脾、益气固表为君；炒白术、茯苓健脾杜痰，熟地黄、山茱萸、胡桃肉、紫河车补肾纳气归元，五味子敛肺纳肾，共为臣药；沉香降气纳肾，灵磁石镇摄纳气，紫苏子降气化痰，紫菀、款冬花润肺止咳，法半夏、陈皮理气化痰，共为佐药；防风配黄芪、白术固卫御邪，炙甘草调和诸药，为使。全方标本兼顾，补而不滞。另予穴位贴敷（肺俞、定喘、足三里）每日1次，耳穴压豆每周2次。\n2.西医治疗：布地奈德福莫特罗（160/4.5μg）1吸每日2次，吸后漱口；沙丁胺醇1～2喷按需吸入；泼尼松20mg每日1次晨服，用满5天后每2日减5mg渐停，监测血糖、血压；氨溴索30mg每日3次口服；鼻导管低流量吸氧2L/min，维持SpO2在93%以上；无感染证据暂不加抗菌药物。\n3.护理与调摄：饮食温补清淡，可食山药、莲子、小米粥，忌生冷冰饮及肥甘厚味；避风寒，保暖防感冒，秋冬外出戴口罩；情志舒畅，家属多陪伴；予缩唇呼吸、腹式呼吸及八段锦，每日2次、每次15～20分钟。\n4.医患沟通：已向患者及家属交代本病属慢性气道炎症性疾病，需长期规范吸入治疗、不可自行停药，反复发作可致气道重塑与肺功能下降；已告知口服激素为短程使用及减量方案，嘱出院后中医门诊调理、定期复查肺功能，出现哮鸣加重、口唇发绀或血氧下降立即就诊。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，喉中哮鸣明显减轻，气喘缓解，昨夜可平卧入睡约5小时，仍咳少量白色泡沫痰，气短乏力，自汗畏风，无发热寒战，无胸痛咯血。纳食稍增，二便调。\n查体：T 36.8℃，P 88次/分，R 20次/分，BP 120/74mmHg，指脉氧饱和度（未吸氧）95%。口唇发绀较前减轻，舌质淡，边有齿痕，苔薄白，脉沉细。双肺可闻及少量哮鸣音，以呼气相为主，未闻及湿性啰音。心腹查体同前，双下肢无水肿。继续当前中药及吸入治疗方案，泼尼松按计划减量。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，自诉气喘明显减轻，日间活动后仍有轻度气短，喉中哮鸣基本消失，咳嗽减少，痰量减少、色白易咯，自汗较前减轻，无发热，无胸痛，夜寐转安，纳可，二便调。\n查体：T 36.6℃，P 84次/分，R 19次/分，BP 118/72mmHg，指脉氧饱和度（未吸氧）96%。面色转润，舌质淡红，边有齿痕，苔薄白，脉沉细。双肺呼吸音稍粗，未闻及明显哮鸣音及湿性啰音。心率84次/分，律齐。腹软，无压痛。双下肢无水肿。复查血常规WBC 7.2×10^9/L，E% 6.8%；C反应蛋白3.1mg/L；血气分析（未吸氧）PaO2 84mmHg。泼尼松已减量至10mg每日1次晨服。继续中药辨证论治，加强缩唇呼吸及呼吸操锻炼。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神好，自诉无气喘及胸闷，喉中无哮鸣，偶有单声咳嗽，痰少，气短乏力明显改善，动则汗出减少，纳食可，二便调，夜寐安。\n查体：T 36.5℃，P 78次/分，R 18次/分，BP 120/74mmHg，指脉氧饱和度（未吸氧）97%。舌质淡红，苔薄白，脉细。双肺呼吸音清，未闻及哮鸣音及湿性啰音。心率78次/分，律齐。腹软，无压痛。双下肢无水肿。泼尼松已停用。患者病情平稳，哮鸣及气喘基本缓解，继续中药巩固治疗，加强缓解期宣教及吸入装置使用指导，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为哮病（虚哮），西医诊断为支气管哮喘（慢性持续期，急性发作），伴轻度低氧血症，病情尚平稳，需住院进一步检查治疗。\n2.诊疗方案：完善血气分析、肺功能、过敏原及胸部CT等检查，中医辨证论治予补肺纳肾、降气化痰中药汤剂口服，联合吸入激素及支气管扩张剂、短期口服激素、祛痰及低流量吸氧治疗，配合穴位贴敷等中医特色治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应（心悸、手抖、咽部不适、血糖血压升高等）；哮喘若控制不佳可进展为哮喘持续状态、气胸或呼吸衰竭，需及时抢救。\n4.注意事项：卧床休息，避免接触尘螨、花粉、冷空气及刺激性气味，注意保暖，清淡饮食，忌食生冷肥甘及海鲜发物，正确掌握吸入装置用法，配合检查治疗。\n5.预后情况：本病为慢性疾病，经积极规范治疗本次发作预后较好，但需长期规范用药、定期随访以减少复发。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：哮病（虚哮）\n西医诊断：支气管哮喘（慢性持续期，急性发作） / 过敏性鼻炎\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，男，46岁，因\"反复发作性喉中哮鸣有声伴气喘10年，加重5天\"入院。入院时精神倦怠，端坐呼吸，口唇轻度发绀，喉中哮鸣有声，呼吸急促，胸闷，咳嗽，咳白色稀泡沫痰、量多易咯，气短不足以息，动则喘甚，自汗畏风，食少便溏。查体：T 37.1℃，P 96次/分，R 24次/分，BP 122/76mmHg，指脉氧饱和度（未吸氧）92%。双肺可闻及散在哮鸣音，以呼气相为主，呼气相延长，未闻及湿性啰音，双下肢无水肿。中医四诊：舌质淡，边有齿痕，苔薄白，脉沉细弱。辅助检查：血常规E% 8.6%升高，肺功能示FEV1占预计值68%、支气管舒张试验阳性，FeNO 48ppb，总IgE 386IU/ml，胸部CT示双肺纹理增粗、未见实变及占位。\n\n诊疗经过：\n入院后完善动脉血气分析、肺功能加支气管舒张试验、呼出气一氧化氮测定、血清总IgE及过敏原检测、血常规、C反应蛋白、痰培养、胸部CT等检查，明确中医诊断为哮病（虚哮），西医诊断为支气管哮喘（慢性持续期，急性发作）。中医辨证为肺脾肾俱虚、痰浊内生，治以补肺纳肾、降气化痰，予平喘固本汤加减（党参15g、五味子10g、胡桃肉15g、沉香3g后下、紫河车6g研末冲服、熟地黄15g、山茱萸12g、紫菀10g、款冬花10g、法半夏9g、陈皮9g、茯苓15g、炒白术12g、紫苏子10g、炙黄芪20g、防风10g、甘草6g）加减，每日1剂，水煎分早晚两次温服；随症加减海浮石、浙贝母、补骨脂、浮小麦等。西医予布地奈德福莫特罗粉吸入剂1吸每日2次吸入、沙丁胺醇气雾剂按需吸入、氨溴索30mg每日3次口服祛痰，泼尼松20mg每日1次晨服共5天后逐渐减量停用，鼻导管低流量吸氧，并予穴位贴敷（肺俞、定喘、膏肓、足三里）、艾灸及耳穴压豆等中医特色治疗。经治疗，患者喉中哮鸣消失，气喘及胸闷缓解，咳嗽咳痰明显减少，血氧回升，复查血气PaO2 84mmHg，血E%降至6.8%，病情稳定，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神好，无气喘及胸闷，喉中无哮鸣，偶有单声咳嗽，痰少，气短乏力明显改善，动则汗出减少，纳食可，二便调，夜寐安。查体：T 36.5℃，P 78次/分，R 18次/分，BP 120/74mmHg，指脉氧饱和度（未吸氧）97%，舌质淡红，苔薄白，脉细。双肺呼吸音清，未闻及哮鸣音及湿性啰音，心率78次/分，律齐，腹软无压痛，双下肢无水肿。\n出院医嘱：1. 饮食：清淡易消化饮食，忌食生冷、肥甘厚味及鱼虾海鲜等易致敏发物，戒烟限酒。\n2. 休息与活动：注意保暖，避免受凉感冒，避免接触尘螨、花粉、宠物皮屑及刺激性气味；适当进行缩唇呼吸、腹式呼吸及呼吸操锻炼，循序渐进，避免劳累。\n3. 用药：继续服用中药汤剂巩固调理，党参15g、五味子10g、胡桃肉15g、炙黄芪20g、炒白术12g、防风10g、紫菀10g、款冬花10g、法半夏9g、陈皮9g、茯苓15g、紫苏子10g、山茱萸12g、甘草6g，共7剂，每日1剂，水煎取汁400ml，分早晚两次温服；布地奈德福莫特罗粉吸入剂1吸每日2次规律吸入，吸后漱口，沙丁胺醇气雾剂按需备用，不可自行停药或减量。\n4. 复查：出院后2周门诊复查肺功能，此后每1～3个月随访1次，遵嘱调整吸入药物剂量；缓解期可行冬病夏治三伏贴治疗。\n5. 注意事项：坚持长期规范用药，正确使用吸入装置并记录哮喘控制情况；如出现气喘加重、不能平卧、口唇发绀、言语不成句或血氧下降，立即急诊就诊。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，自诉喉中哮鸣明显减轻，气喘较入院时缓解，昨夜可平卧入睡约6小时，仍咳少量白色泡沫痰，气短乏力，自汗畏风，无发热寒战，无胸痛咯血，纳可，二便调。\n查体：T 36.7℃，P 84次/分，R 19次/分，BP 118/74mmHg，指脉氧饱和度（未吸氧）96%。神志清楚，精神可，口唇发绀消失。舌质淡，边有齿痕，苔薄白，脉沉细。双肺呼吸音稍粗，可闻及少量哮鸣音，以呼气相为主，未闻及湿性啰音。心率84次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查：动脉血气分析（未吸氧）PaO2 80mmHg；血常规WBC 7.4×10^9/L，E% 7.5%；C反应蛋白4.5mg/L；痰培养未见致病菌生长，较前好转。\n四诊合参，本病属中医\"哮病（虚哮）\"范畴，辨证为肺脾肾俱虚、痰浊内生，治以补肺纳肾、降气化痰，方用平喘固本汤加减。患者经中药辨证论治配合吸入治疗后，哮鸣及气喘较前改善，治疗有效。继续目前中药及吸入治疗，泼尼松按计划递减，注意观察病情变化，随证加减。继续低流量吸氧，指导有效咳嗽及缩唇呼吸，注意保暖，清淡饮食，避免接触过敏原及劳累。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，自诉气喘明显减轻，喉中哮鸣基本消失，日间活动后偶有轻度气短，咳嗽减少，痰少色白易咯，自汗较前减轻，无发热，无胸痛，食纳可，二便调，夜寐安。\n查体：T 36.5℃，P 80次/分，R 18次/分，BP 120/72mmHg，指脉氧饱和度（未吸氧）97%。面色转润，神志清楚，精神好。舌质淡红，边有齿痕，苔薄白，脉细。双肺呼吸音稍粗，未闻及明显哮鸣音及湿性啰音。心率80次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查：复查肺功能示FEV1占预计值79%，较入院明显改善；血气分析（未吸氧）PaO2 84mmHg，PaCO2 40mmHg；血常规WBC 7.0×10^9/L，E% 6.5%。\n患者经中药辨证论治及吸入治疗后，哮鸣消失，气喘明显改善，病情稳定。继续目前中药治疗，巩固疗效，泼尼松已停用，改为布地奈德福莫特罗长期规律吸入维持。建议出院后继续服用中药调理肺脾肾，坚持规范吸入治疗，定期复诊，注意保暖防感冒，避免接触过敏原及刺激性气味，适当进行呼吸功能锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月19日 10:00（入院第5天）\n\n今日李主任医师查房，患者精神好，气喘明显减轻，喉中哮鸣基本消失，咳嗽咳痰减少，气短乏力及自汗明显改善，纳可，二便调，夜寐安。查体：T 36.5℃，P 80次/分，R 18次/分，BP 120/72mmHg，SpO2 97%（未吸氧）；面色转润，舌质淡红、边有齿痕、苔薄白，脉细；双肺未闻及哮鸣音及湿啰音，双下肢无水肿。\n\n一、中医辨病辨证分析\n\n患者哮病反复10年，因淋雨受凉诱发，属本虚标实之虚哮。经治5日哮鸣消失、血氧复常，舌由淡转淡红、脉由沉细转细，示痰浊渐化、肺气得降；然舌边齿痕未消、脉细未复，仍诉气短、动则汗出，示肺脾肾虚损之本未复元。辨证要点再确认三则：一者宿痰伏肺为夙根、遇感而发，属哮病而非喘证；二者本虚由哮久而成，以肺、脾、肾依次受累，补益当循序而进，不可峻补；三者痰白清稀、无热象，非热哮、非痰热壅肺，忌用寒凉清化。\n\n\n二、中医鉴别诊断\n\n1.与「喘证」鉴别：喘证是多种急慢性疾病过程中的症状，喘随原发病进退，无发作性哮鸣，亦无缓解如常人之特点；哮病为独立病证，以声响言、反复发作。本案病程10年、缓解期仍气短乏力，与喘证不同。\n2.与「肺胀」鉴别：肺胀多由久咳久哮发展而来，以胸中胀满、憋闷如塞、面色晦暗、甚则喘脱为特征，常伴肺气肿及右心功能不全。本案胸廓对称，无颈静脉怒张及下肢水肿，CT未见肺气肿，尚在哮病阶段；然年老吸烟，须动态监测。\n3.与「冷哮」鉴别：本案受凉而发、痰白清稀，貌似冷哮；但冷哮为新感寒邪、痰升气阻之实证，多兼恶寒发热、鼻塞流清涕、苔白滑、脉弦紧。本案无表证，而以气短不足以息、动则喘甚、脉沉细为主，属虚哮，故忌单用麻黄、桂枝峻散。\n\n\n三、西医疑难分析与鉴别诊断\n\n1.诊断再确认：反复喘息10年、支气管舒张试验阳性、FeNO 48ppb、血E%及总IgE升高，胸部CT除外实变与占位，支气管哮喘（慢性持续期，急性发作，中度）诊断明确，合并过敏性鼻炎。难点在于长期未规范吸入ICS致气道重塑、2型炎症表型明显，需评估长期ICS剂量及是否联合白三烯受体拮抗剂；结合病史、BNP及心脏彩超，心源性哮喘可除外。\n2.与慢性阻塞性肺疾病及哮喘-COPD重叠鉴别：患者吸烟20年，可能合并不完全可逆气流受限，虽舒张试验阳性、CT无肺气肿，仍不能除外，建议出院后复查肺功能。\n\n\n四、国内外相关疾病研究进展\n\n1.全球哮喘防治创议（GINA 2023）以「控制」为哮喘长期管理目标，强调ICS为基石、反对单用SABA，推荐ICS-福莫特罗用于维持加缓解，并以FeNO及血嗜酸性粒细胞指导ICS剂量调整。\n2.《支气管哮喘防治指南（2020年版）》推荐急性发作期全身糖皮质激素疗程5～7天，可减少复发；本例泼尼松20mg晨服5天后减停，符合该原则。\n3.一项纳入数千例中重度哮喘患者的随机对照试验显示，ICS联合LABA较单用ICS可显著降低急性发作率、改善FEV1；一项中药治疗哮喘缓解期的系统评价（纳入多项随机对照试验）提示，补肺健脾益肾类方药可改善哮喘控制、减少急性发作，惟证据质量有限，宜作为规范治疗之上的增效手段。\n\n\n五、诊疗计划\n\n1.中医治疗调整及理由：哮鸣已平、痰浊渐化，原方去灵磁石，加补骨脂10g、蛤蚧3g（研末冲服）温肾纳气、培补下元，取缓则治本之意。处方：炙黄芪20g、党参15g、炒白术12g、防风10g、五味子10g（打碎）、胡桃肉15g、紫河车6g（冲服）、补骨脂10g、蛤蚧3g（冲服）、沉香3g（后下）、紫苏子10g、紫菀10g、款冬花10g、法半夏9g、陈皮9g、茯苓15g、熟地黄15g、山茱萸12g、炙甘草6g。用法：水煎服，每日一付，分2次温服。方解：炙黄芪、党参补肺健脾、益气固表为君；炒白术、茯苓健脾杜痰，熟地黄、山茱萸、胡桃肉、紫河车、补骨脂、蛤蚧补肾纳气归元，五味子敛肺纳肾为臣；沉香降气纳肾，紫苏子降气化痰，紫菀、款冬花润肺止咳，法半夏、陈皮理气化痰为佐；防风配黄芪、白术固卫御邪，炙甘草调和诸药为使。缓解期续用六君子汤或金匮肾气丸，夏季行冬病夏治三伏贴。\n2.西医治疗调整及理由：泼尼松按计划停用，避免长期口服激素致血糖血压升高、骨质疏松；继续布地奈德福莫特罗（160/4.5μg）1吸每日2次规律吸入维持，不可自行停药，吸后漱口防口腔真菌感染；因合并过敏性鼻炎、FeNO及嗜酸性粒细胞升高，加孟鲁司特钠10mg每晚1次口服；氨溴索30mg每日3次口服；沙丁胺醇按需备用，据ACT评分阶梯调整吸入剂量。\n3.护理与调摄：饮食温补清淡，忌生冷冰饮及肥甘厚味；避风寒保暖，秋冬外出戴口罩；情志宜畅，家属多疏导；坚持缩唇呼吸、腹式呼吸及八段锦，每日2次、每次15～20分钟。\n4.医患沟通：说明本病可控制但不能根治，需长期规范吸入治疗；已告知停用口服激素及维持方案，嘱出院2周复查肺功能、每3个月评估ACT评分，避免接触过敏原；如哮鸣加重、夜间频繁憋醒或痰量增多变黄，及时就诊。\n\n\n医师签名：陈医生"},"icd10_diagnosis":"J45.900","icd10_secondary":["J30.400"],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1225,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c4fb967ff04090456a3e9285702ed9978cf410ded421fdd5c0ccaec8e9b841f5","pinyin":"xiaobing（xuxiao）","initials":"xb（xx）","setting":"in","caseName":"病例1：患者，男，46岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，46岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","J45.900",30]]},{"id":"templates-1dea072b0b86c98326a4","key":"v1-c9ccc21dfe2a3058|templates-1dea072b0b86c98326a4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"哮病（风痰哮）","category":"中医科","raw":{"name":"哮病（风痰哮）","category":"中医科","case":{"case_name":"病例1：患者，男，42岁","templates":{"入院记录":"入院记录\\n\\n姓名：【已脱敏】 性别：男 年龄：42岁 民族：汉族\\n婚姻：已婚 职业：装修工人 籍贯：本地\\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\\n病史陈述者：患者本人，可靠\\n\\n主诉：反复发作性喉中痰鸣、喘息气促3年，加重伴咳嗽咯痰2天。\\n\\n现病史：患者于3年前春季接触花粉后出现发作性喉中痰鸣、喘息气促，多于夜间及晨起发作，发作时胸闷如窒，不能平卧，经解痉平喘治疗后缓解，缓解期如常人，可正常工作生活。此后每年发作3～4次，多于春秋季节更替、接触冷空气、尘螨及刺激性气味后诱发，每次持续数小时至数日不等。2天前因受凉后再次发作，起病急骤，发前先觉鼻痒、咽痒、喷嚏连作、流清涕，继而喉中痰鸣如拽锯，喘息气促，胸膈满闷，咳痰黏稠，色白夹黄，咳吐不利，夜间为甚，需端坐呼吸方能稍舒。伴恶风、咽痒、汗出不多，无发热寒战，无胸痛咯血，无咳粉红色泡沫痰，无夜间阵发性呼吸困难，无双下肢水肿，无关节肿痛。自服氨茶碱片及止咳化痰中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「哮病（风痰哮）」收入我科。发病以来精神欠佳，夜寐不安，胃纳欠佳，二便尚调，体重无明显变化。\\n\\n既往史：既往有过敏性鼻炎病史5年，每于接触花粉、尘螨后出现鼻痒、连续喷嚏、流清涕，间断服用抗组胺药物。否认高血压、糖尿病、冠心病、慢性支气管炎及肺结核病史。否认肝炎、结核等传染病史。否认手术、外伤及输血史。否认食物药物过敏史。\\n\\n个人史及家族史：生于本地，久居本地，无疫区居住及疫水接触史。从事装修工作8年，工作中接触粉尘及油漆等刺激性气味，未规律佩戴口罩。吸烟10年，每日约10支，未戒；偶尔饮酒。家族中母亲有支气管哮喘病史，否认其他遗传性疾病家族史。\\n婚育史：28岁结婚，配偶体健，育有1女，女儿体健。\\n\\n体格检查：\\nT 36.9℃，P 96次/分，R 24次/分，BP 122/76mmHg，SpO2 94%（未吸氧）。\\n一般情况：神志清楚，精神欠佳，端坐位，查体合作。\\n\\n中医四诊：\\n望诊：神志清楚，面色晦滞，口唇轻度发绀，舌质淡红，苔白厚腻。\\n闻诊：喉中痰鸣如拽锯，声高气粗，语声重浊，无异常气味。\\n问诊：喘息气促，胸膈满闷，咳痰黏稠，色白夹黄，咳吐不利，鼻痒喷嚏，咽痒，纳差，夜寐不安，二便调。\\n切诊：脉滑实。\\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\\n淋巴结：全身浅表淋巴结未触及肿大。\\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大，无颈静脉怒张。\\n胸部：胸廓对称，肋间隙无明显增宽，呼吸运动稍促，双肺叩诊呈清音，双肺呼吸音粗，可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长。心率96次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常，双下肢无水肿，无杵状指（趾）。\\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\\n\\n专科情况：\\n望诊：端坐呼吸，呼吸急促，胸廓对称，口唇轻度发绀；舌象：舌质淡红，苔白厚腻；脉象：脉滑实。专科查体：双肺呼吸音粗，双肺可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长，语音传导正常；心率96次/分，律齐，心界不大。关键阴性体征：无发热，无咯血，无胸痛，无三凹征，无一侧呼吸音消失，无皮下气肿，无颈静脉怒张，双下肢无水肿，无杵状指，病理征阴性。\\n\\n辅助检查：\\n门诊血常规：WBC 8.6×10^9/L，N% 62%，E% 8.5%，Hb 138g/L，PLT 216×10^9/L。\\n门诊过敏原检测（吸入组）：尘螨（+++），花粉（++）。\\n门诊胸部X线：双肺纹理增粗，未见实质性病变。\\n门诊心电图：窦性心动过速，大致正常心电图。\\n\\n初步诊断：\\n中医诊断：哮病（风痰哮）\\n中医诊断依据：\\n1.辨病依据：患者以反复发作性喉中痰鸣、喘息气促为主症，病史3年，每年发作3～4次，每因接触花粉、尘螨、冷空气及刺激性气味而诱发，起病急骤，发作时胸闷如窒、不能平卧，经解痉平喘治疗可缓解，缓解期如常人，符合哮病「发作性痰鸣气喘、喉中哮鸣有声、反复发作、缓解如常人」的辨病要点。其病名首见于《内经》，有「喘鸣」「喘喝」之称；《金匮要略·肺痿肺痈咳嗽上气病脉证治》言「咳而上气，喉中水鸡声」，即指本病；《医学正传》「哮以声响言，喘以气息言」，明确哮病以喉中哮鸣有声为特征。故中医病名诊断为哮病。\\n2.辨证依据：本次发作喉中痰鸣如拽锯，声高气粗，喘息气促，胸膈满闷，咳痰黏稠、色白夹黄、咳吐不利；起病急骤，发前先有鼻痒、咽痒、喷嚏连作、流清涕之风象；舌质淡红、苔白厚腻，脉滑实。风痰内伏于肺，外风引动伏痰，风痰交阻、壅塞气道，肺失宣肃，故痰鸣喘息、胸闷咯痰；风善行而数变，故起病急骤、发有先兆；痰浊内蕴，故苔白厚腻、脉滑实。四诊合参，证属风痰哮。\\n中医鉴别诊断：\\n1.与「喘证」鉴别：喘证以气息言，以呼吸困难、呼吸急促，甚则张口抬肩、鼻翼煽动、不能平卧为特征，可见于多种急慢性疾病过程中；哮病以声响言，以发作性喉中哮鸣有声、反复发作、发有先兆、缓解如常人为特征。鉴别要点：哮病必有喉中哮鸣之声且反复发作、间隙期如常人，喘证则以气息喘促为主而无喉中哮鸣。本案喉中痰鸣如拽锯、发前有鼻痒喷嚏之先兆、缓解期如常人，故诊为哮病；然哮必兼喘，本案气息喘促并见，以哮为主。\\n2.与「支饮」鉴别：支饮系饮停胸膈、肺失宣降所致，症见咳逆倚息、短气不得卧、其形如肿，多伴面浮肢肿、咳吐白沫痰，病程缠绵、饮邪留伏，属《金匮要略》痰饮病范畴。鉴别要点：支饮有形之饮邪停聚，常见水肿及咳吐白沫痰，其症持续不解；本案无面浮肢肿、无咳吐白沫痰，发作呈阵发性，缓解后如常人，故可鉴别。\\n3.与「肺胀」鉴别：肺胀多见于久病咳喘之老年患者，以喘息气促、咳嗽咳痰、胸部膨满、憋闷如塞、动则加重为特征，病程长、呈持续性并进行性加重，常伴唇甲发绀、心悸浮肿，胸廓呈桶状，影像学可见肺气肿改变。鉴别要点：肺胀持续加重、胸部膨满、肺气肿征象明确；本案中年起病，病程3年，缓解期如常人，胸廓对称、肋间隙无明显增宽，胸部X线未见肺气肿及实质性病变，故与肺胀不同。\\n西医诊断：支气管哮喘（急性发作期）／过敏性鼻炎\\n西医诊断依据：\\n1.症状依据：反复发作性喘息、气促、胸闷、咳嗽3年，多于夜间及晨起发作，每因接触花粉、尘螨、冷空气及刺激性气味诱发，发作时不能平卧，可自行或经解痉平喘治疗缓解，缓解期如常人，符合支气管哮喘「反复发作性、可逆性、诱因相关性」的症状特点；且每于接触花粉、尘螨后出现鼻痒、连续喷嚏、流清涕，符合过敏性鼻炎表现。\\n2.体征依据：端坐呼吸，呼吸稍促（R 24次/分），口唇轻度发绀，双肺呼吸音粗，可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长；无颈静脉怒张、双下肢无水肿、无杵状指，心界不大、律齐。\\n3.实验室及影像依据：血常规示嗜酸性粒细胞比例升高（E% 8.5%）；吸入组过敏原检测尘螨（+++）、花粉（++），提示过敏体质；胸部X线示双肺纹理增粗，未见实质性病变，可除外肺炎、肺结核、气胸及肺部占位；心电图示窦性心动过速，大致正常，可除外明显心律失常。\\n4.危险因素及家族史依据：既往过敏性鼻炎病史5年，母亲有支气管哮喘病史，吸烟10年（每日约10支），从事装修工作8年、长期接触粉尘及油漆等刺激性气味，均为哮喘发病及反复发作的高危因素。\\n西医分型/分级/分期：\\n1.分期：支气管哮喘，急性发作期（本次发作2天，症状逐渐加重）。\\n2.急性发作严重程度分级：按《支气管哮喘防治指南》急性发作严重程度分级标准，本案属中度急性发作——气促明显、喜坐位（端坐呼吸）、能成短句交谈、呼吸频率24次/分、双肺广泛哮鸣音、心率96次/分、SpO2 94%（未吸氧）；无三凹征、无大汗淋漓、无意识改变、无寂静肺，未达重度，然亦重于轻度，须按中度发作处理并密切监测。\\n3.临床表型：外源性（过敏性）哮喘，过敏原为尘螨（+++）、花粉（++）。\\n4.病情控制水平：未控制（近3年每年发作3～4次，存在夜间症状，未规律吸入糖皮质激素）。\\n5.合并症：过敏性鼻炎；无慢性阻塞性肺疾病、无呼吸衰竭、无慢性肺源性心脏病、无气胸及纵隔气肿。\\n6.危险因素：吸烟10年未戒，职业性粉尘及油漆接触，为哮喘控制不良及急性发作的危险因素。\\n诊疗计划：\\n1.按内科Ⅱ级护理，半流质饮食，卧床休息，必要时低流量吸氧；2.完善检查：血常规+C反应蛋白（目的：明确有无感染及炎症程度，为抗感染与抗炎治疗提供依据）、动脉血气分析（目的：评估缺氧及二氧化碳潴留程度，为氧疗与病情严重度分级提供依据）、肺功能及支气管舒张试验（目的：客观评估气道阻塞可逆性，为哮喘诊断与治疗分级提供依据）、胸部CT（目的：排除肺炎、气胸等并发症并明确肺部病变）、过敏原筛查（目的：明确诱发因素与过敏体质，为环境干预及抗过敏治疗提供依据）、心电图（目的：评估心脏情况、排除心源性喘息并了解药物对心脏的影响）；3.一般治疗：避免接触过敏原及刺激性气味，保持病室空气流通，喘息明显时予低流量吸氧；4.药物治疗：祛风涤痰、降气平喘中药汤剂（三子养亲汤加味），布地奈德福莫特罗吸入剂每次1吸每日2次吸入，喘息明显时予沙丁胺醇气雾剂按需吸入，氨茶碱0.1g每日3次口服；5.病情观察：观察喘息、痰鸣、痰量痰色及呼吸频率变化，监测血氧饱和度，警惕哮喘持续状态及呼吸衰竭；6.健康教育：指导正确使用吸入装置、避免过敏原、戒烟、呼吸功能锻炼，必要时请呼吸科会诊。\\n\\n专科检查：\\n望诊：端坐呼吸，呼吸急促，口唇轻度发绀；舌象：舌质淡红，苔白厚腻；脉象：脉滑实。双肺可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长。\\n\\n医师签名：陈医生","首次病程记录":"首次病程记录\\n\\n2026年08月15日 12:00\\n\\n病例特点：\\n1.患者，男，42岁，因「反复发作性喉中痰鸣、喘息气促3年，加重伴咳嗽咯痰2天」入院。\\n2.既往史：既往有过敏性鼻炎病史5年，吸烟10年，未戒。\\n3.体格检查：T 36.9℃，P 96次/分，R 24次/分，BP 122/76mmHg，SpO2 94%，端坐呼吸，双肺可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长。\\n4.中医四诊：舌质淡红，苔白厚腻，脉滑实。\\n5.辅助检查：血常规示嗜酸性粒细胞比例升高（E% 8.5%），过敏原检测尘螨及花粉阳性，胸部X线示双肺纹理增粗，心电图示窦性心动过速。\\n\\n拟诊讨论：\\n（一）初步诊断：\\n中医诊断：哮病（风痰哮）\\n西医诊断：支气管哮喘（急性发作期）／过敏性鼻炎\\n\\n（二）中医诊断依据：\\n1.辨病依据：患者以反复发作性喉中痰鸣、喘息气促为主症，病史3年，每年发作3～4次，多因接触花粉、尘螨、冷空气及刺激性气味而诱发，起病急骤，发前先有鼻痒、咽痒、喷嚏连作、流清涕之先兆，发作时胸闷如窒、不能平卧，缓解期如常人。符合哮病「发作性痰鸣气喘、喉中哮鸣有声、反复发作、间歇期如常人」的辨病要点，与《金匮要略》「咳而上气，喉中水鸡声」、《医学正传》「哮以声响言，喘以气息言」之论述相符，故中医病名诊断为哮病。\\n2.辨证依据：本证以喉中痰鸣如拽锯、声高气粗、喘息气促、胸膈满闷、咳痰黏稠色白夹黄而咳吐不利为主症，起病急骤，发前鼻痒、喷嚏、流涕、咽痒，舌质淡红、苔白厚腻，脉滑实。风痰内伏，外风引动伏痰，风痰交阻、壅塞气道，肺失宣肃，故见痰鸣喘急、胸闷咯痰；风善行而数变，故起病急骤、发有先兆；痰浊内蕴，故苔白厚腻、脉滑实。四诊合参，辨为风痰哮证，治以祛风涤痰、降气平喘，方用三子养亲汤加味。\\n依据《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·哮病。\\n\\n（三）中医鉴别诊断：\\n1.与「喘证」鉴别：喘证以气息言，症见呼吸困难、呼吸急促，甚则张口抬肩、鼻翼煽动、不能平卧，可见于多种急慢性疾病过程中；哮病以声响言，喉中哮鸣有声，反复发作，发有先兆，缓解期如常人。鉴别要点：哮病必有发作性喉中哮鸣且间歇期如常人，喘证以气息喘促为主而无喉中哮鸣之声，且多有其他疾病基础。本案喉中痰鸣如拽锯、发前有鼻痒喷嚏之先兆、缓解期如常人，故诊断哮病；哮必兼喘，本案喘促并见而以哮为主。\\n2.与「支饮」鉴别：支饮为饮停胸膈、肺失宣降之候，症见咳逆倚息、短气不得卧、其形如肿，多伴面浮肢肿及咳吐白沫痰，病程缠绵、饮邪留伏。鉴别要点：支饮有形之饮邪停聚，常见水肿与白沫痰，症情持续；本案无面浮肢肿、无咳吐白沫痰，发作呈阵发性，故可鉴别。\\n3.与「肺胀」鉴别：肺胀多见久病咳喘之老年患者，以喘息气促、咳嗽咳痰、胸部膨满、憋闷如塞、动则加重为特征，病程长、持续并进行性加重，常伴唇甲发绀、心悸浮肿，胸廓呈桶状，影像学见肺气肿改变。鉴别要点：肺胀病程持续、进行性加重、胸部膨满并有肺气肿征象；本案中年起病、缓解期如常人、胸廓对称、胸部X线未见肺气肿征象，故可鉴别。\\n4.与哮病其他证型鉴别：与「冷哮」（喉中哮鸣如水鸡声、痰白而多泡沫、形寒怕冷、苔白滑、脉弦紧）不同，本案痰质黏稠色白夹黄、苔白厚腻、脉滑实，且发前有鼻痒喷嚏之风象；与「寒包热哮」（喉中痰鸣、咯痰黄稠、兼恶寒发热身痛、舌尖边红、苔黄白相兼、脉弦紧）不同，本案无恶寒发热及身痛表证；与「热哮」（气粗息涌、痰鸣如吼、咯痰黄稠、口苦口渴、面赤汗出、舌红苔黄腻、脉滑数）不同，本案痰以白色为主、无口渴面赤、舌质不红；与「虚哮」（声低气短、动则喘甚、咯痰无力、痰涎清稀、形寒肢冷、舌淡苔白、脉沉细）不同，本案声高气粗、脉滑实，属实证。提示：若喘息持续不解、气促加重、口唇青紫、汗出肢冷、神志改变者，须警惕哮喘持续状态，应立即抢救。\\n\\n（四）西医诊断依据：\\n1.病史依据：反复发作性喘息、气促、胸闷、咳嗽3年，多于接触花粉、尘螨、冷空气及刺激性气味后诱发，有过敏性鼻炎病史5年及支气管哮喘家族史，吸烟10年未戒。\\n2.症状依据：发作性喘息、气促、胸闷、咳嗽，夜间及晨起为甚，发作时不能平卧，可自行或经解痉平喘治疗后缓解，缓解期如常人，具有可逆性气流受限的临床特点。\\n3.体征依据：端坐呼吸，呼吸稍促，口唇轻度发绀，双肺呼吸音粗，可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长；无三凹征、无颈静脉怒张、双下肢无水肿、无杵状指，心界不大、心律齐。\\n4.辅助检查依据：血常规示嗜酸性粒细胞比例升高（E% 8.5%）；吸入组过敏原检测尘螨（+++）、花粉（++）；胸部X线示双肺纹理增粗，未见实质性病变，可除外肺炎、肺结核、气胸及肺部占位；心电图示窦性心动过速，大致正常，可除外明显心律失常。肺功能及支气管舒张试验、动脉血气分析、胸部CT待完善。\\n5.综上，符合支气管哮喘急性发作期之诊断，兼有过敏性鼻炎；须与心源性哮喘、慢阻肺急性加重及上气道阻塞等相鉴别。\\n\\n（五）西医分型/分级/分期：\\n1.疾病分期：支气管哮喘，急性发作期（本次发作2天，症状进行性加重）。\\n2.急性发作严重程度分级：按《支气管哮喘防治指南》急性发作严重程度分级标准，本案属中度急性发作——气促明显、喜坐位（端坐呼吸）、能成短句交谈、呼吸频率24次/分、双肺可闻及广泛哮鸣音、心率96次/分、SpO2 94%（未吸氧）；无三凹征、无大汗淋漓、无意识改变、无寂静肺，未达重度，然重于轻度，须按中度发作处理、密切监测病情变化。\\n3.临床表型：外源性（过敏性）哮喘，致敏原为尘螨（+++）、花粉（++）。\\n4.病情控制水平：未控制（近3年每年发作3～4次，存在夜间及晨起症状，未规律应用吸入性糖皮质激素）。\\n5.合并症：过敏性鼻炎；无慢性阻塞性肺疾病、无呼吸衰竭、无慢性肺源性心脏病、无气胸及纵隔气肿。\\n6.危险因素：吸烟10年未戒，职业接触粉尘及油漆等刺激性气味，为哮喘控制不良及急性发作的危险因素。\\n\\n（六）西医鉴别诊断：\\n1.急性左心衰竭（心源性哮喘）：\\n【支持点】心源性哮喘与支气管哮喘均表现为喘息、气促、不能平卧，双肺可闻及哮鸣音，故需鉴别。\\n【不支持点】心源性哮喘多有高血压、冠心病、心脏瓣膜病等基础心脏病，常咳粉红色泡沫痰，双肺底以湿啰音为主，可有心脏扩大、奔马律及颈静脉怒张；本例为中年男性，无心脏病史，咳白色黏痰，双肺以广泛哮鸣音为主，仅闻及少量湿性啰音，无颈静脉怒张及下肢水肿。\\n【排除方法】查心电图、心脏彩超、血浆BNP/NT-proBNP及胸部X线，结合病史、痰液性质及对支气管舒张剂的反应鉴别。\\n2.慢性阻塞性肺疾病急性加重：\\n【支持点】慢性阻塞性肺疾病急性加重亦见喘息、咳嗽、咳痰、呼吸困难，双肺可闻及哮鸣音，且本例吸烟10年未戒，属高危人群，故须鉴别。\\n【不支持点】慢性阻塞性肺疾病多见于中老年长期重度吸烟者，症状呈持续性并逐年加重，气流受限不完全可逆，支气管舒张试验阴性，弥散功能下降；本例发作呈阵发性，缓解期如常人，支气管舒张试验阳性。\\n【排除方法】查肺功能及支气管舒张试验、弥散功能，结合发病年龄、发作特点及过敏史鉴别。\\n3.上气道阻塞（气管异物、气管肿瘤）：\\n【支持点】均可出现呼吸困难及喘鸣音，需鉴别。\\n【不支持点】上气道阻塞多为吸气性喘鸣，可有三凹征，哮鸣音多局限于颈部且吸气相明显；气管异物者有明确异物吸入史，起病突然。本例喘鸣以呼气相为主、双肺广泛分布，无异物吸入史及咯血。\\n【排除方法】查胸部CT及支气管镜，结合病史、喘鸣时相及影像学表现鉴别。\\n4.自发性气胸：\\n【支持点】自发性气胸可突发胸痛、呼吸困难及患侧呼吸音减低，须与本次急性发作鉴别。\\n【不支持点】本例双肺对称闻及广泛哮鸣音，无突发针刺样胸痛及单侧呼吸音消失，气管居中，无皮下气肿。\\n【排除方法】急查胸部X线或胸部CT，未见气胸线及肺压缩带即可除外。\\n5.肺栓塞：\\n【支持点】肺栓塞可突发呼吸困难、气促、胸闷及低氧血症（SpO2 94%），可伴哮鸣音，须与支气管哮喘急性发作鉴别。\\n【不支持点】本例有明确过敏原（尘螨、花粉）及冷空气诱因，喘息呈发作性、有3年反复发作史，无胸痛咯血、晕厥及下肢肿胀，无制动、手术、骨折及肿瘤等血栓高危因素。\\n【排除方法】查D-二聚体、动脉血气分析、心电图及CT肺动脉造影；D-二聚体阴性且无高危因素者可基本除外。\\n6.声带功能障碍（声带功能失调）：\\n【支持点】声带功能障碍常表现为发作性呼吸困难、喘鸣及胸闷，多由刺激物或情绪诱发，易误诊为支气管哮喘。\\n【不支持点】声带功能障碍的喘鸣多位于喉部、以吸气相为主，常伴发声困难及咽部紧缩感，肺功能流速-容量环示吸气相平台样改变，对支气管舒张剂反应差；本例喘鸣为呼气相、双肺广泛分布，伴嗜酸性粒细胞升高及过敏原阳性。\\n【排除方法】查肺功能流速-容量环、喉镜（发作时声带内收）及支气管舒张试验，必要时请耳鼻喉科会诊。\\n\\n（七）诊疗计划：\\n诊疗计划：\n1.护理与饮食：按内科护理常规，Ⅱ级护理；清淡易消化半流质饮食，少量多餐，忌辛辣、生冷、肥甘厚味及海鲜发物，戒烟并避免二手烟；卧床休息，病室空气流通，避开花粉、尘螨、冷空气及刺激性气味，喘息明显时予低流量吸氧，注意防跌倒。\n2.完善检查：①完善血常规、C反应蛋白及嗜酸性粒细胞计数（目的：评估气道炎症与感染情况，为是否加用抗菌药物提供依据）；②完善动脉血气分析（目的：评估氧合及有无二氧化碳潴留，为氧疗及病情严重程度判定提供依据）；③完善肺功能及支气管舒张试验（目的：客观证实气流受限可逆性，为确诊支气管哮喘及病情分级提供依据）；④完善胸部CT（目的：除外肺炎、气胸、胸腔积液及肺部占位，为喘息病因鉴别提供依据）；⑤完善过敏原筛查及血清总IgE（目的：明确致敏原，为环境规避及特异性免疫治疗提供依据）；⑥完善心电图、心脏彩超及血浆BNP（目的：除外心律失常及心源性哮喘，为鉴别心源性喘息提供依据）；⑦完善痰涂片及痰培养（目的：明确有无细菌感染及致病菌，为抗菌药物选择提供依据）。\n3.西医治疗：给予布地奈德福莫特罗吸入剂（160/4.5μg）每次1吸、每日2次规律吸入，吸后漱口以防口腔念珠菌感染及声嘶；给予沙丁胺醇气雾剂每次1～2揿按需吸入，24小时内不超过8次；给予氨茶碱片0.1g 每日3次口服，注意心率及胃肠道反应；喘息明显时予低流量鼻导管吸氧1～2L/min，维持血氧饱和度在93%以上；给予氯雷他定片10mg 每晚1次口服、糠酸莫米松鼻喷雾剂每侧鼻孔2揿 每日1次喷鼻，以控制过敏性鼻炎；患者白细胞及C反应蛋白正常、无脓痰及发热，暂不加用抗菌药物，如痰量增多、痰色转黄或体温升高，复查血常规及C反应蛋白以了解感染情况后酌情加用抗菌药物。\n4.中医治疗：给予中药方剂以祛风涤痰、降气平喘，兼健脾化痰以绝生痰之源为治则；方选三子养亲汤加减；\n中药处方如下：白芥子9g 苏子12g 莱菔子12g 炙麻黄6g 杏仁10g 僵蚕10g 地龙10g 蝉衣6g 厚朴10g 法半夏10g 陈皮10g 茯苓15g 炙甘草6g\n用法：水煎服，每日一付，冷水浸泡30分钟后水煎取汁400ml，分2次温服，饭后半小时服，5剂后随症加减。\n方解：方中白芥子温肺利气、豁痰散结，苏子降气行痰、止咳定喘，莱菔子消食行气祛痰，三药相伍降气涤痰、气顺则痰消，直对风痰壅塞气道之痰鸣喘急，共为君药；炙麻黄宣肺平喘、杏仁降气润肺，一宣一降以复肺之宣肃，僵蚕、地龙、蝉衣祛风解痉、通络平喘，针对风善行而数变、发有先兆之风象，共为臣药；厚朴、法半夏、陈皮理气宽胸、燥湿化痰，取气行则痰消之意，茯苓健脾渗湿、杜生痰之源，共为佐药；炙甘草调和诸药，兼制麻黄之峻，为使药。全方标本兼顾，共奏祛风涤痰、降气平喘、健脾化痰之效。随症加减：痰壅喘急、不能平卧者加葶苈子10g、猪牙皂6g（中病即止）；感受风邪而发、鼻痒喷嚏明显者加苏叶10g、防风10g、苍耳草10g；痰黄黏稠难咯者加黄芩10g、瓜蒌皮15g；胸闷纳差者加焦三仙各10g；久病气短乏力者加黄芪20g、白术12g、五味子6g。\n5.密切观察病情变化，重点观察喘息、痰鸣、痰量痰色及呼吸频率变化，监测血氧饱和度、峰流速以了解病情动态变化，必要时复查动脉血气分析以了解氧合及二氧化碳潴留情况，警惕哮喘持续状态及呼吸衰竭；向家属交代目前病情，注意防跌倒，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房，患者端坐呼吸较前减轻，可半卧位，喉中痰鸣较前明显减轻，喘息气促缓解，咳痰减少，色白质黏，尚易咯出，无发热恶寒，无胸痛咯血，纳食渐增，二便调，夜寐转安。\n查体：T 36.6℃，P 88次/分，R 20次/分，BP 120/76mmHg，SpO2 96%（未吸氧）。神志清楚，精神可。舌质淡红，苔白厚腻较前转薄，脉滑。双肺呼吸音粗，哮鸣音较前减少，呼气相稍延长，未闻及明显湿啰音。心率88次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹软，无压痛，肝脾肋下未触及。双下肢无水肿。\n辅助检查回报：血常规 WBC 8.2×10^9/L，N% 60%，E% 8.0%，Hb 140g/L，PLT 214×10^9/L；C反应蛋白 6mg/L；动脉血气分析（未吸氧）：pH 7.40，PaO2 78mmHg，PaCO2 38mmHg；胸部CT示双肺纹理增粗，未见实质性病变；肺功能及支气管舒张试验：FEV1占预计值72%，支气管舒张试验阳性（FEV1改善率14%，绝对值增加210ml）；过敏原筛查：尘螨（+++）、花粉（++）；心电图：窦性心律，大致正常。\n执行情况：遵嘱执行。半卧位休息，避免接触尘螨、花粉及刺激性气味，中药汤剂每日1剂分2次温服，布地奈德福莫特罗吸入剂每次1吸每日2次规律吸入并已复核吸入技术，沙丁胺醇气雾剂按需吸入（近24小时未使用），暂未用抗菌药物，指脉氧监测每日3次均在95%以上。\n\n一、中医辨病辨证分析\n患者中青年男性，反复发作性喘息3年，本次受凉后急性发作，喉中痰鸣如拽锯、胸膈满闷、咳痰黏稠色白夹黄而咯吐不利，发前鼻痒、咽痒、喷嚏连作，缓解期如常人，舌淡红、苔白厚腻（今转薄）、脉滑（原脉滑实）。《金匮要略》云「咳而上气，喉中水鸡声」，《医学正传》谓「哮以声响言，喘以气息言」，本案以喉中哮鸣有声、反复发作、间歇期如常人为辨病要点，故辨病为哮病（发作期）。患者素有过敏性鼻炎5年，风邪久客肺窍，遇凉引动伏痰，风痰交阻、壅塞气道，肺失宣肃，气机上逆，故见痰鸣喘急、胸膈满闷；风善行数变，故起病急骤、发有先兆；痰浊内蕴，故苔白厚腻、脉滑。四诊合参，辨证为风痰哮（发作期），病位在肺，涉及脾肾，病性属实、属风属痰，核心病机为风痰阻肺、肺失宣降，兼痰郁化热之渐。治疗2日后痰鸣大减、苔腻转薄、脉由滑实转滑，提示风痰渐化、肺气得降，方证相合，本期治法无需更改；然苔仍腻、脉仍滑，伏痰未净，化痰之品不可骤停，只宜减制顾本。\n\n二、中医鉴别诊断\n1.与「喘证」鉴别：喘证以气息言，以呼吸困难、气促鼻煽、张口抬肩为主症，为多种急慢性疾病过程中的一个症状，多继发于肺胀、心水等病，病程持续而不以阵发为特点。本案以喉中哮鸣如拽锯之「声响」为主，起病急骤、发有先兆、间歇期如常人，声息特点与病程规律均不相符；哮必兼喘，本案喘促并见而以哮为主，故辨为哮病。\n2.与「支饮」鉴别：支饮为饮停胸膈、肺失宣降之候，见咳逆倚息、短气不得卧、其形如肿，多伴面浮肢肿、咳吐白沫清稀痰，苔多白滑、脉多弦。本案痰质黏稠而非白沫清稀，无面浮肢肿，症状呈阵发性、间歇期如常人，胸部CT未见胸腔积液及心影改变，与饮停不散、形肿缠绵不符，故可鉴别。\n3.与「肺胀」鉴别：肺胀多见于久病咳喘之老年患者，以胸部膨满、憋闷如塞、喘息动则为甚、唇甲发绀、心悸浮肿为特征，病程长、持续并进行性加重，胸廓呈桶状，肺功能示不可逆气流受限。本案中年起病、缓解期如常人、胸廓对称、胸部CT仅见肺纹理增粗而无肺气肿，支气管舒张试验阳性提示气流受限可逆，故与肺胀可辨。\n4.与哮病其他证型鉴别：与「冷哮」之痰白多泡沫、形寒怕冷、苔白滑、脉弦紧不同，本案痰黏稠色白夹黄、苔白厚腻；与「热哮」之气粗息涌、痰鸣如吼、痰黄稠、口苦口渴、舌红苔黄腻、脉滑数不同，本案痰以白色为主、舌质不红、无口渴面赤；与「寒包热哮」之兼恶寒发热身痛、苔黄白相兼不同，本案无表证；与「虚哮」之声低气短、动则喘甚、咯痰无力、脉沉细不同，本案属实证。提示：若痰鸣喘促持续不解、口唇青紫、汗出肢冷、神志改变者，须警惕哮喘持续状态，立即抢救。\n\n三、西医鉴别诊断\n1.与心源性哮喘鉴别：该病多有高血压、冠心病等心脏病基础，常夜间阵发，咳粉红色泡沫痰，双肺底大量湿啰音，心界扩大，脑钠肽显著升高，强心利尿扩血管治疗有效。本案无心脏病史及粉红色泡沫痰，双肺以哮鸣音为主，心界不大、心律齐，心电图大致正常，故可鉴别，必要时查血浆BNP及心脏彩超。\n2.与慢性阻塞性肺疾病急性加重鉴别：慢阻肺多见于中老年长期吸烟者，气流受限不完全可逆，肺功能示吸入支气管舒张剂后FEV1/FVC小于70%，胸部CT可见肺气肿。本案虽吸烟10年、FEV1占预计值72%，但支气管舒张试验阳性（改善率14%、绝对值增加210ml）、胸部CT无肺气肿，且呈发作性可逆性喘息，故目前考虑支气管哮喘，需随访肺功能以除外哮喘-慢阻肺重叠。\n3.与上气道阻塞等所致喘息鉴别：气管支气管异物、气管肿瘤、声带功能障碍、变应性支气管肺曲霉病等亦可表现为喘息，多为持续性或进行性呼吸困难，常伴吸气相哮鸣、咯血、消瘦或嗜酸性粒细胞显著升高，对解痉平喘药反应差。本案为发作性呼气相哮鸣，治疗反应良好，血嗜酸性粒细胞轻度升高，胸部CT无占位及阻塞性改变，故可基本除外。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》确立以控制为目标的长期分级管理，推荐所有成人及青少年哮喘患者使用含吸入性糖皮质激素（ICS）的联合制剂，不再推荐单用短效β2受体激动剂缓解症状。本案采用布地奈德福莫特罗每日2次规律吸入并按需使用，符合以ICS为基石的抗炎治疗原则。\n2.全球哮喘防治创议（GINA 2023）将急性发作分为轻度、中度、重度及危及生命四级，推荐重度发作联合吸入异丙托溴铵、静脉硫酸镁及全身糖皮质激素，中度发作以雾化支气管舒张剂加口服糖皮质激素多可缓解。本案属中度急性发作，目前单用ICS+LABA及按需SABA即可控制，尚不需全身激素，与指南分层治疗一致。\n3.多项研究及系统评价提示，外周血嗜酸性粒细胞计数与呼出气一氧化氮（FeNO）可用于评估气道2型炎症水平、预测ICS疗效并指导升降级治疗，血嗜酸性粒细胞≥300/μl者多提示激素敏感型炎症。本案E% 8.0%（绝对值升高），FeNO待完善，拟作为随访及降级治疗参考指标。\n4.《中国过敏性哮喘诊治指南（2022年版）》推荐过敏性哮喘系统开展环境控制与过敏原回避，尘螨、花粉多重致敏且规范药物治疗仍控制不佳者，可考虑特异性免疫治疗或抗IgE单抗治疗。本案尘螨（+++）、花粉（++）明确致敏，急性期控制后应转诊评估脱敏治疗适应证。\n5.国内多项中药治疗支气管哮喘的系统评价及随机对照试验（纳入数十项RCT、数千例患者）提示，在西医规范吸入治疗基础上加用祛风化痰、降气平喘类中药（如三子养亲汤、射干麻黄汤加减），可提高临床控制率、改善FEV1与PEF、减少急性发作次数，未见严重不良反应。本案辨证为风痰哮，与上述治法方向一致，可继续应用并纳入随访观察。\n\n五、诊疗计划\n1.中医治疗：治以祛风涤痰、降气平喘，兼健脾化痰以绝生痰之源。方选三子养亲汤加味，处方：白芥子9g、苏子12g、莱菔子12g、炙麻黄6g、杏仁10g、僵蚕10g、地龙10g、蝉衣6g、厚朴10g、法半夏10g、陈皮10g、茯苓15g、炙甘草6g。用法：每日1剂，冷水浸泡30分钟后水煎取汁400ml，分早晚2次温服，饭后半小时服，5剂后随症加减。方解：白芥子温肺利气、豁痰散结，苏子降气行痰、止咳定喘，莱菔子消食行气祛痰，三药相伍降气涤痰、气顺则痰消，为君；炙麻黄宣肺平喘、杏仁降气润肺，一宣一降以复肺之宣肃，僵蚕、地龙、蝉衣祛风解痉、通络平喘，共为臣；厚朴、法半夏、陈皮理气宽胸、燥湿化痰，茯苓健脾渗湿、杜生痰之源，共为佐；炙甘草调和诸药兼制麻黄之峻，为使。加减：痰壅喘急不能平卧加葶苈子10g、猪牙皂6g（中病即止）；鼻痒喷嚏明显加苏叶10g、防风10g、苍耳草10g；痰黄黏稠难咯加黄芩10g、瓜蒌皮15g；胸闷纳差加焦三仙各10g；缓解期气短乏力加黄芪20g、白术12g、五味子6g。\n2.西医治疗：布地奈德福莫特罗吸入剂（160/4.5μg）每次1吸、每日2次规律吸入，吸后漱口以防口腔念珠菌感染及声嘶；沙丁胺醇气雾剂每次1至2揿按需吸入，24小时内不超过8次；喘息明显时低流量鼻导管吸氧（1至2L/min）维持SpO2在93%以上；氨茶碱0.1g每日3次口服，注意心率及胃肠道反应；暂不加用抗菌药物（WBC及C反应蛋白正常、无脓痰发热），如痰量增多、痰色转黄或体温升高，复查血常规及C反应蛋白后酌情加用；急性期控制后加用鼻用糖皮质激素及抗组胺药以控制过敏性鼻炎。\n3.护理与调摄：饮食宜清淡易消化、少食多餐，忌辛辣、生冷、肥甘厚味及海鲜发物，戒烟并避二手烟；起居避开花粉、尘螨、冷空气及刺激性气味，外出戴口罩，居室勤打扫通风、被褥勤晒，注意保暖防感冒；情志宜心平气和，避免恼怒忧思及劳累诱发；病情稳定后指导腹式呼吸、缩唇呼气及呼吸操训练，每日2次、每次10至15分钟，量力而行。\n4.医患沟通：已向患者及家属交代，目前西医诊断为支气管哮喘急性发作期（中度）、过敏性鼻炎，中医辨证为风痰哮（风痰阻肺、肺失宣降），经中西医结合治疗2日症状明显缓解，血氧正常、无呼吸衰竭征象，病情趋于稳定，预后总体良好。同时告知哮喘为慢性气道炎症性疾病，需长期规范吸入治疗，不可因症状缓解自行停药，否则易致反复发作及气道重塑；须随身携带沙丁胺醇气雾剂，每日记录峰流速及发作先兆，出院后每2至4周呼吸科复诊、3个月复查肺功能，过敏原阳性者可评估脱敏治疗；若痰鸣喘促加重、呼吸困难不能平卧、口唇发紫、说话不能成句，须立即就诊。患者及家属表示理解并配合。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\\n\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\\n【病程记录一】2026年08月16日 09:00（入院第2天）\\n\\n患者入院第2天，神志清楚，精神较前好转，端坐呼吸减轻，可半卧位，喉中痰鸣、喘息气促较前减轻，咳痰减少，无发热恶寒，无胸痛咯血，纳食渐增，二便调，夜寐转安。\\n查体：T 36.6℃，P 88次/分，R 20次/分，BP 120/76mmHg，SpO2 96%。舌质淡红，苔白厚腻较前转薄，脉滑。双肺呼吸音粗，哮鸣音较前减少，呼气相稍延长。继续当前中药治疗方案，配合吸入药物解痉平喘。\\n\\n【病程记录二】2026年08月18日 09:00（入院第4天）\\n\\n患者入院第4天，神志清楚，精神可，静息状态下已无喘息气促，喉中痰鸣消失，偶有单声咳嗽，咳少量白黏痰，易咯出，可平卧入睡，纳可，二便调，夜寐安。\\n查体：T 36.5℃，P 84次/分，R 19次/分，BP 118/74mmHg，SpO2 97%。舌质淡红，苔薄白腻，脉细滑。双肺呼吸音略粗，哮鸣音基本消失，未闻及湿啰音，心率84次/分，律齐。复查血常规、C反应蛋白正常范围。继续当前治疗，中药汤剂继服，吸入剂规律使用。\\n\\n【病程记录三】2026年08月20日 09:00（入院第6天）\\n\\n患者入院第6天，神志清楚，精神好，喘息未再发作，喉中痰鸣消失，咳嗽偶作，痰少色白易咯，夜能平卧，纳可，二便调，夜寐安。\\n查体：T 36.4℃，P 80次/分，R 18次/分，BP 116/74mmHg，SpO2 98%。舌质淡红，苔薄白，脉细滑。双肺呼吸音清，未闻及哮鸣音及湿啰音。患者病情平稳，症状明显缓解，继续巩固治疗，加强健康宣教，准备出院。\\n\\n医师签名：陈医生\\n","医患沟通记录":"医患沟通记录\\n\\n时间：2026年08月15日 15:30\\n地点：医生办公室\\n参加人员：患者及家属，主管医师陈医生\\n\\n沟通内容：\\n1.病情告知：患者目前中医诊断为哮病（风痰哮），西医考虑支气管哮喘（急性发作期）、过敏性鼻炎，现喘息气促、喉中痰鸣，双肺可闻及广泛哮鸣音，病情需住院进一步检查治疗。\\n2.诊疗方案：完善血常规、C反应蛋白、动脉血气分析、肺功能及支气管舒张试验、胸部CT、过敏原筛查等检查；中医辨证论治给予祛风涤痰、降气平喘中药汤剂（三子养亲汤加味）口服，配合吸入药物解痉平喘、必要时吸氧及雾化治疗。\\n3.可能风险：治疗过程中可能出现病情反复、哮喘持续状态、呼吸衰竭、水电解质紊乱及药物不良反应（心悸、手抖、咽部不适、恶心等），病情严重时需转重症监护治疗。\\n4.注意事项：卧床休息，避免接触尘螨、花粉、冷空气及刺激性气味，戒烟，清淡饮食，忌食生冷及鱼腥发物，配合检查治疗，不可自行停药。\\n5.预后情况：经积极规范治疗后症状多可缓解，但本病易反复发作，需长期规范用药及门诊随访。\\n\\n患者及家属表示理解，签署相关知情同意书。\\n\\n医师签名：陈医生\\n患者/家属签名：患者\\n","出院记录":"出院记录\\n\\n入院日期：2026年08月15日\\n出院日期：2026年08月25日\\n住院天数：11天\\n\\n入院诊断：\\n中医诊断：哮病（风痰哮）\\n西医诊断：支气管哮喘（急性发作期）；过敏性鼻炎\\n\\n出院诊断：\\n中医诊断：哮病（风痰哮）\\n西医诊断：支气管哮喘（慢性持续期）；过敏性鼻炎\\n\\n入院情况：\\n患者，男，42岁，因「反复发作性喉中痰鸣、喘息气促3年，加重伴咳嗽咯痰2天」入院。入院时端坐呼吸，呼吸急促，口唇轻度发绀，双肺可闻及广泛哮鸣音及少量湿性啰音，呼气相明显延长，SpO2 94%。中医四诊：舌质淡红，苔白厚腻，脉滑实。\\n\\n诊疗经过：\\n入院后完善血常规、C反应蛋白、动脉血气分析、肺功能及支气管舒张试验、胸部CT、过敏原筛查、心电图等检查，血嗜酸性粒细胞比例升高，支气管舒张试验阳性，过敏原尘螨及花粉阳性，胸部CT未见实质性病变，明确中医诊断哮病（风痰哮）、西医诊断支气管哮喘（急性发作期）。中医辨证属风痰阻肺、肺失宣降，治以祛风涤痰、降气平喘，予三子养亲汤加味中药汤剂口服，并随症加减；同时予布地奈德福莫特罗吸入剂规律吸入、沙丁胺醇气雾剂按需吸入、氨茶碱口服解痉平喘，必要时低流量吸氧，嘱避免接触过敏原、戒烟、卧床休息。经治疗，患者喘息气促逐渐缓解，喉中痰鸣消失，咳嗽咳痰明显减少，住院第4天静息时已无喘息，住院第6天肺部哮鸣音消失，病情稳定，经上级医师同意后准予出院。\\n\\n出院情况：\\n患者神志清楚，精神可，喘息未再发作，无喉中痰鸣，偶有单声咳嗽，咳少量白痰，易咯出，夜能平卧，纳可，二便调，夜寐安。查体：T 36.5℃，P 80次/分，R 18次/分，BP 118/74mmHg，SpO2 98%（未吸氧）。舌质淡红，苔薄白，脉细滑。双肺呼吸音清，未闻及哮鸣音及湿性啰音，呼气相不延长。心率80次/分，律齐。腹软，无压痛。双下肢无水肿。\\n\\n出院医嘱：\\n1.饮食：清淡易消化饮食，忌食生冷、辛辣及鱼腥发物，戒烟限酒，多饮水。\\n2.休息与活动：注意保暖，避免受凉及劳累，避免接触尘螨、花粉、冷空气、油漆等刺激性气味，坚持缩唇呼吸及腹式呼吸功能锻炼，循序渐进。\\n3.用药：（1）中药汤剂：三子养亲汤加味（白芥子9g、苏子12g、莱菔子12g、炙麻黄6g、杏仁10g、僵蚕10g、厚朴10g、法半夏10g、陈皮10g、茯苓15g、地龙10g、蝉衣6g、黄芪20g、白术12g），共7剂，日1剂，水煎取汁400ml，分早晚2次温服，服完后来院复诊调方；（2）布地奈德福莫特罗吸入剂（160/4.5μg）每次1吸、每日2次规律吸入，吸后漱口，不可自行停药或减量；（3）沙丁胺醇气雾剂按需吸入，每周使用不宜超过2次，若使用频繁需及时就诊；（4）氨茶碱片0.1g每日3次口服，症状缓解后可停用。\\n4.复查：出院后2周门诊（中医内科／呼吸内科）复诊，复查肺功能及支气管舒张试验、血常规、C反应蛋白，以后每1～3个月随访1次，遵医嘱调整吸入药物剂量。\\n5.注意事项：规律用药，正确使用吸入装置，记录哮喘日记（发作时间、诱因、用药情况）；若出现喘息加重、喉中痰鸣、口唇发绀、不能平卧、言语不成句或用药后不缓解，请立即急诊就诊。\\n\\n医师签名：陈医生\\n\\n离院方式：医嘱离院\\n\\n【医保结算清单要素】\\n主要诊断（名称+ICD-10编码）：________________（编码待填）\\n入院病情：有\\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\\n离院方式：见上文\\n主要手术/操作：无\\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\\n","病程记录第3天":"病程记录\\n\\n2026年08月17日 09:00（入院第3天）\\n\\n患者入院第3天，神志清楚，精神较前好转，喘息气促较前明显减轻，喉中痰鸣偶作，咳痰减少，色白质黏易咯，无发热恶寒，无胸痛，纳可，二便调，夜寐转安，可半卧位休息。\\n查体：T 36.5℃，P 84次/分，R 19次/分，BP 118/75mmHg，SpO2 97%（未吸氧）。神志清楚，精神可。舌质淡红，苔白腻较前转薄，脉滑。双肺呼吸音粗，哮鸣音较前明显减少，未闻及湿啰音，呼气相稍延长。心率84次/分，律齐。腹软，无压痛。双下肢无水肿。\\n辅助检查：动脉血气分析（未吸氧）pH 7.40、PaO2 80mmHg、PaCO2 38mmHg，低氧血症较前改善；血常规、C反应蛋白较前好转；过敏原筛查示尘螨（+++）、花粉（++）。\\n四诊合参，本病属中医「哮病（风痰哮）」范畴，风痰阻肺、肺失宣降，治以祛风涤痰、降气平喘，方用三子养亲汤加味，随证加减。患者经中药辨证论治配合吸入药物后，喘息痰鸣较前明显改善，治疗有效。继续目前治疗方案，中药汤剂继服，吸入剂规律使用，注意观察喘息及痰量痰色变化，随证加减。嘱卧床休息，避免接触过敏原及刺激性气味，清淡饮食，忌生冷鱼腥发物，戒烟，避免劳累及情志刺激。\\n\\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\\n\\n2026年08月19日 09:00（入院第5天）\\n\\n患者入院第5天，神志清楚，精神好，喘息未再发作，喉中痰鸣消失，咳嗽偶作，咳少量白痰，易咯出，可平卧入睡，纳可，二便调，夜寐安。\\n查体：T 36.4℃，P 80次/分，R 18次/分，BP 116/74mmHg，SpO2 98%（未吸氧）。神志清楚，精神好。舌质淡红，苔薄白，脉细滑。双肺呼吸音清，未闻及哮鸣音及湿啰音，呼气相不延长。心率80次/分，律齐。腹软，无压痛，肝脾肋下未触及。双下肢无水肿。\\n辅助检查：复查血常规 WBC 7.2×10^9/L，E% 4.5%，C反应蛋白 3mg/L，均在正常范围；复查肺功能 FEV1占预计值86%，较入院前明显改善；血气分析（未吸氧）PaO2 88mmHg，恢复正常。\\n患者经中药祛风涤痰、降气平喘辨证论治配合吸入药物治疗后，症状明显改善，病情稳定。继续目前治疗，巩固疗效，中药汤剂继服，吸入剂规律使用并指导正确吸入方法。今日患者一般情况良好，可考虑近期出院。建议出院后坚持中药调理及规范吸入治疗，定期复诊，注意保暖，避免接触过敏原，戒烟，清淡饮食，避免劳累及情志刺激，坚持呼吸功能锻炼，增强体质。\\n\\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月18日 10:00（入院第4天）\n\n今日李主任医师查房，患者目前神志清楚，精神可，静息状态下无喘息气促，喉中痰鸣已消失，偶有单声咳嗽，咳少量白黏痰，易咯出，可平卧，无发热，无胸痛咯血，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 82次/分，R 18次/分，BP 118/74mmHg，SpO2 97%。舌质淡红，苔薄白腻，脉细滑。双肺呼吸音略粗，哮鸣音基本消失，未闻及湿啰音，呼气相不延长。心率82次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹软，无压痛。双下肢无水肿。复查血常规：WBC 7.6×10^9/L，E% 6.4%；C反应蛋白 4mg/L；肺功能：FEV1占预计值86%，支气管舒张试验转阴；血气（未吸氧）：pH 7.41，PaO2 88mmHg，PaCO2 37mmHg。\n执行情况：遵嘱执行。中药汤剂已服5剂，痰色转白、量减、易咯，无腹泻及胃脘不适；吸入药物规律使用、技术正确，近48小时沙丁胺醇未使用；氨茶碱口服后无心悸、恶心；戒烟宣教已落实，病室避免尘螨及花粉接触；已开始腹式呼吸及缩唇呼气训练。\n\n一、中医辨病辨证分析\n患者以发作性喉中哮鸣、喘息气促、反复发作3年、间歇期如常人为特点，辨病为哮病，本次系遇风受凉引动伏痰而急性发作。入院时痰鸣如拽锯、声高气粗、咳痰白黏夹黄而咯吐不利、胸膈满闷、发前鼻痒喷嚏，舌淡红、苔白厚腻、脉滑实，辨证为风痰哮（风痰阻肺、肺失宣降），属实属风属痰。经治4日，痰鸣已止、可平卧、痰少色白易咯，苔由白厚腻转薄白腻，脉由滑实转细滑，提示风痰已化、肺气得降，急性发作期已过。辨证要点再确认有三：其一，「风」象仍在，患者过敏性鼻炎5年，鼻痒喷嚏、遇冷易发，说明风邪伏于肺窍未清，风不去则痰不消、痰不除则风易引，此为本病反复之根，故祛风药不宜骤撤，只宜减制续用。其二，「痰」未尽而「虚」已显，苔虽转薄仍腻、脉已转细滑，细为气阴不足、滑为痰浊内蕴，加之病程3年、久用宣散，提示由实转虚实夹杂，属标减本露，故化痰降气之品当减，益气健脾、培土生金之法当增，以绝生痰之源。其三，痰色由白夹黄转纯白，初蕴之郁热已清，黄芩、瓜蒌皮之类苦寒清热药可停，以防伤中。综上，治疗重心由急性期祛风涤痰、降气平喘之治标，转为缓解期益气健脾、化痰祛风、标本兼顾之调治，此为本次方案调整之依据。\n\n二、中医鉴别诊断\n1.与「喘证」鉴别：前次已从声息立论，本次再从病位与转归深化。喘证病位虽亦在肺，然多为肺胀、心水、虚劳等病发展过程中之证候，随原发病进退，喘息持续而少有完全缓解之「如常人」阶段。本案经治4日即由端坐呼吸转为平卧、哮鸣音消失、FEV1由72%升至86%，具有发作性、可逆性、间歇期如常人的鲜明特点，符合哮病「宿根—诱因—发作—缓解」的病程规律，与喘证之持续渐进不同，故鉴别明确。\n2.与「支饮」鉴别：本次从痰之形质与治疗反应补充。支饮为饮停胸膈之候，痰多清稀白沫，治当温化水饮，对祛风化痰之剂反应有限。本案痰黏稠色白夹黄、无面浮肢肿及心下痞坚，服三子养亲汤加祛风解痉药5剂即痰鸣止而痰量减，治疗反应支持风痰而非饮邪，故可鉴别。\n3.与「肺胀」鉴别：本次从脏腑传变与预后深化。肺胀日久由肺及脾、及肾、及心，出现心悸、浮肿、紫绀等变证，胸廓桶状、肺气肿征象固定、气流受限不可逆。本案胸廓对称、胸部CT无肺气肿、支气管舒张试验由阳性转阴而FEV1恢复至86%，说明气流受限可逆、脏腑未受深损。然须警惕本病反复发作、久治不摄可由哮转胀，故缓解期务须培补脾肾、避除诱因，此亦二级预防之要。\n4.与「心咳」「肾不纳气」鉴别：《素问·咳论》有「心咳之状，咳则心痛，喉中介介如梗状」；肾不纳气者气短息促、动则尤甚、腰膝酸软、呼多吸少、脉沉细尺弱。本案无心痛及咽喉梗阻感，无腰膝酸软及动则喘甚，心电图大致正常，脉细滑而非沉细无力，故可鉴别。\n5.与哮病其他证型鉴别：现痰少色白、苔薄白腻、脉细滑，无口苦口渴及恶寒发热身痛，已不属热哮、寒包热哮；亦不属冷哮之水鸡声、痰多泡沫、形寒怕冷、脉弦紧；与虚哮之动则喘甚、咯痰无力、形寒肢冷、脉沉细亦有别。本案以风痰滞络为标、肺脾不足为本，属虚实夹杂之风痰哮缓解期。提示本病「夙根」未除，若再遇风邪、花粉、尘螨及冷空气侵袭仍有急性发作之虞，须教患者识别先兆、及时用药。\n\n三、西医疑难分析与鉴别\n本例西医诊断支气管哮喘（急性发作期，中度）合并过敏性鼻炎，依据充分：反复发作性喘息3年、发作性可逆性气流受限、支气管舒张试验阳性、多重过敏原致敏、血嗜酸性粒细胞升高、胸部CT除外实质性病变；哮喘与过敏性鼻炎同属「同一气道、同一疾病」，二者须同步治疗方能减少哮喘发作，此为会诊意见之核心。疑难之处：其一，患者吸烟10年而胸CT无肺气肿，须长期随访肺功能，警惕哮喘-慢阻肺重叠及气道重塑；其二，上气道阻塞、变应性支气管肺曲霉病、嗜酸性肉芽肿性多血管炎等少见病因尚需关注，若解痉平喘疗效变差、嗜酸性粒细胞持续显著升高或出现咯血消瘦，应及时行支气管镜及血清总IgE、曲霉特异性IgE检测；其三，心源性哮喘入院时已据病史、体征及心电图初步排除，仍建议完善血浆BNP及心脏彩超以资稳妥。\n\n四、国内外相关疾病研究进展\n1.《支气管哮喘防治指南（2020年版）》与GINA 2023均确立以ICS为基石的长期控制治疗，推荐轻度哮喘即采用ICS+福莫特罗按需或规律使用，并按控制水平每1至2个月评估、每3个月考虑降级；指南并明确哮喘控制不佳的常见原因依次为吸入技术错误、依从性差、持续接触过敏原及合并过敏性鼻炎未治。本案吸入技术正确、依从性良好、症状已控制，符合进入阶梯降级流程的评估指征。\n2.关于2型炎症标志物，多项前瞻性研究及系统评价提示，外周血嗜酸性粒细胞计数与FeNO可预测ICS疗效、指导生物制剂选择并评估降级风险，血嗜酸性粒细胞≥300/μl者降级后急性发作风险升高。本案E%由8.0%降至6.4%，FeNO待完善，建议出院前完善并纳入长期随访，作为降级决策参考。\n3.《中国过敏性哮喘诊治指南（2022年版）》推荐对尘螨、花粉多重致敏且规范药物治疗仍控制不佳者行特异性免疫治疗（皮下或舌下脱敏），疗程约3年，可减轻症状、减少用药并预防新增致敏；抗IgE单抗可用于中重度过敏性哮喘。本案尘螨（+++）、花粉（++），应于缓解期转诊变态反应科评估脱敏适应证。\n4.中医药治疗哮喘的循证研究：国内多项纳入数十项随机对照试验、数千例患者的系统评价与Meta分析提示，西医规范治疗基础上加用祛风化痰、降气平喘类中药（含三子养亲汤、射干麻黄汤加减），可提高临床控制率、改善FEV1与PEF、降低急性发作频次，不良反应以轻度胃肠道反应为主；另有伏九穴位贴敷辅助治疗哮喘的多中心随机对照研究，提示可减少急性发作次数、改善生活质量。本案辨证属风痰哮，所用方药与上述治法方向一致，疗效与安全性可在随访中继续观察记录。\n\n五、诊疗计划\n1.中医治疗：进入缓解期，治则调整为益气健脾、化痰祛风、标本兼顾，佐以敛肺固本。方选六君子汤合三子养亲汤加减，处方：黄芪20g、党参12g、炒白术12g、茯苓15g、陈皮10g、法半夏9g、苏子10g、白芥子6g、莱菔子10g、僵蚕9g、蝉衣6g、防风9g、五味子6g、炙甘草6g。用法：每日1剂，水煎取汁400ml，分早晚2次温服，连服14剂后门诊复诊调整。方解：黄芪补肺脾之气、固表实卫，党参、炒白术、茯苓健脾益气、培土生金，共为君药，以绝生痰之源、复肺卫外之功；苏子降气化痰、止咳平喘，白芥子温肺豁痰，莱菔子行气消食化痰，三子相配化痰而不伤正，为臣；陈皮、法半夏理气燥湿化痰，僵蚕、蝉衣、防风祛风解痉、宣通肺窍以清风之余邪，五味子敛肺滋肾、纳气归元，与宣散之品相制，共为佐；炙甘草调和诸药为使。全方宣散与收敛并施、祛邪与扶正兼顾，使风痰得化、脾肺得补、宿根渐消。另拟缓解期伏九穴位贴敷（白芥子、延胡索、甘遂、细辛研末，姜汁调敷肺俞、膏肓、定喘等穴，每次4至6小时，三伏、三九天各3至4次），并配合耳穴压豆（肺、脾、肾、神门、交感）。\n2.西医治疗：布地奈德福莫特罗吸入剂（160/4.5μg）继续每次1吸、每日2次规律吸入，吸后漱口；沙丁胺醇气雾剂按需备用随身携带；氨茶碱0.1g每日3次口服，症状完全缓解后改为每日2次或停用，注意心率及胃肠道反应；停用静脉及雾化支气管舒张剂；针对过敏性鼻炎加用丙酸氟替卡松鼻喷雾剂每鼻孔1喷、每日1次，氯雷他定10mg每晚1次口服；暂不加用抗菌药物。随访：出院后4周呼吸科门诊复诊评估哮喘控制（ACT评分），3个月复查肺功能及FeNO，按阶梯方案降级，以能控制症状、无夜间憋醒及急性发作为最低维持剂量；完善血浆BNP、心脏彩超及血清总IgE，必要时转诊变态反应科评估特异性免疫治疗。\n3.护理与调摄：饮食宜清淡富营养，忌生冷、辛辣、肥甘厚味及海鲜发物，戒烟酒并避二手烟，可适量食用山药、薏苡仁、白扁豆等健脾之品；起居有常、注意保暖防感冒，居室通风干燥、勤晒被褥以减少尘螨，花粉季节外出戴口罩、回家清洗鼻腔；情志宜舒畅，避免忧思恼怒及过度劳累；坚持腹式呼吸及缩唇呼气训练各2次/日、每次10至15分钟，病情稳定后循序渐进练习八段锦、太极拳，以不引起喘息为度。\n4.医患沟通：已向患者及家属交代，本次急性发作经中西医结合治疗4日症状基本缓解、哮鸣音消失、肺功能恢复至FEV1占预计值86%，病情稳定，可于近日出院。重点说明三点：一是哮喘为慢性气道炎症性疾病，中药可减少发作、改善体质，但不能替代吸入性糖皮质激素，须长期规律吸入、不可自行停药减药；二是须建立哮喘行动计划，坚持每日峰流速监测与病情记录，随身携带急救气雾剂，出现先兆症状即按计划用药；三是出院后4周复诊，若喘息加重、呼吸困难不能平卧、口唇发紫、说话不能成句，应立即急诊就医。患者及家属理解并同意治疗方案，表示配合随访。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1226,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"daaaef2be42ad0f729e896c279f44970a2f796d7a4f8ea741ea2015c1a824ced","pinyin":"xiaobing（fengtanxiao）","initials":"xb（ftx）","setting":"in","caseName":"病例1：患者，男，42岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":["入院记录","首次病程记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天"],"quickFields":[["病例名称","病例1：患者，男，42岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-a0e47f5d8369f532b8a6","key":"v1-c9ccc21dfe2a3058|templates-a0e47f5d8369f532b8a6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（表寒肺热）","category":"中医科","raw":{"name":"喘证（表寒肺热）","category":"中医科","case":{"case_name":"病例1：患者，女，46岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：女 年龄：46岁 民族：汉族\n婚姻：已婚 职业：职员 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：喘息气促伴胸闷、咳嗽1周。\n\n现病史：患者于1周前无明显诱因起病，起病较急，症状呈进行性加重，病程中症状反复波动，时轻时重，无明显缓解期，症状持续存在。主要表现为：喘息气促，呼吸急促，胸闷气憋，咳嗽，咯痰黄稠，量较多，咯吐不爽，鼻翼煽动，口渴喜冷饮，初起微恶寒，继而身热，周身酸楚不适，活动后喘息明显加重，安静休息后可部分缓解。病程中上述症状反复发作，时轻时重，劳累后明显加重，安静休息后可部分缓解，总体呈逐渐加重趋势。伴乏力，纳差，二便调。发病以来无咯血、无胸痛、无呼吸困难、无下肢水肿、无盗汗、无体重下降。无盗汗、消瘦，无下肢水肿、端坐呼吸，无大量脓臭痰，无意识障碍，无咯粉红色泡沫痰。自行服用中成药（具体不详）效果欠佳，今日症状加重，为求进一步诊治来我院门诊就诊，门诊以「喘证（表寒肺热）」收入我科。发病以来精神欠佳，饮食睡眠尚可，大小便正常，体重无明显变化。\n\n既往史：既往有高血压病史，规律服药控制可。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。\n\n个人史及家族史：生于本地，久居本地。无吸烟史。家族中否认类似疾病史。\n婚育史：22岁结婚，配偶体健，育有1子\n月经史：初潮14岁，周期28-30天，经期5天，末次月经2026年08月05日，量中等，无痛经\n体格检查：\nT 36.8℃，P 78次/分，R 18次/分，BP 130/80mmHg。\n一般情况：神志清楚，精神可，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色少华，舌质红，苔黄腻。\n闻诊：语声清晰，无异常气味。\n问诊：喘证（表寒肺热）相关症状，纳差，二便调。\n切诊：脉滑数。\n一般情况：神志清楚，精神反应可，营养发育正常，查体欠合作（哭闹）。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大。\n胸部：胸廓对称，双肺呼吸音清，未闻及干湿性啰音。心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常。\n神经系统：神志清楚，巴氏征阴性，肌张力正常。\n专科情况：\n望诊：急性病容，面色红赤，鼻翼扇动，口唇无明显发绀；闻诊：喘促气粗，声高息涌，咳嗽痰黄质黏；舌象：舌红，苔黄或薄黄；脉象：脉浮数或滑数。专科查体：双肺呼吸音粗，可闻及干啰音及散在湿啰音，语颤正常，胸廓对称；呼吸频率增快（约24次/分）。关键阴性体征：无颈静脉怒张，无肝颈静脉回流征，无下肢水肿，心律齐，无明显发绀。\n辅助检查：\n门诊血常规：WBC 6.5×10^9/L，N% 65%，Hb 130g/L，PLT 200×10^9/L。\n门诊生化：肝肾功能正常，电解质正常。\n心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：喘证（表寒肺热）\n中医诊断依据：\n1.辨病依据：患者以喘息气促、呼吸急促、胸闷气憋为主症，动则加重，甚则鼻翼煽动、抬肩撷肚，与喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"之诊断要点相符。喘证多因外感六淫、饮食不当、情志失调或久病体虚，致肺失宣降、肺气上逆而成；本案起病1周、由外感诱发、以喘为主症，辨病属喘证无疑。\n2.辨证依据：患者初起微恶寒、周身酸楚，继而身热，为风寒外束、表邪未解之象；咳嗽、咯痰黄稠量多、咯吐不爽，口渴喜冷饮，喘促气粗、声高息涌、胸膈烦闷，舌质红、苔黄腻，脉浮数或滑数，为邪热壅肺、痰热内蕴、肺气郁闭之征。表寒未罢而里热已盛，寒热并见而以里热为主，故辨证为表寒肺热证。病位在肺，涉及卫表，病性属实，属实喘范畴。治以解表清里、化痰平喘，方用麻杏石甘汤加减。\n中医鉴别诊断：\n1.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声、呼吸气促困难，甚则喘息不能平卧，多有夙根及过敏史，起病急骤、缓解迅速，缓解期如常人，以喉中哮鸣如哨笛为特征；喘证以呼吸困难、张口抬肩、鼻翼煽动为主症，多无喉中哮鸣，常继发于外感及多种慢性肺系疾患过程中。本案喘促气粗、双肺可闻及干啰音，但无喉中哮鸣如吼之典型发作，故辨为喘证而非哮病。\n2.与「气短」鉴别：气短即少气，指呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证，静息时无明显抬肩撷肚，无鼻翼煽动、张口抬肩之象；本案喘息气促、鼻翼煽动、声高息涌、动则加重，一派实喘之候，与气短迥异。\n3.与「肺胀」鉴别：肺胀系多种慢性肺系疾患日久不愈、肺气胀满不能敛降所致，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、肢体浮肿，病程缠绵、反复发作、经久难愈；本案起病仅1周，以新感表寒里热为主，无胸部膨满及心悸浮肿，故不属肺胀。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌、胸部胀痛、痰多黏稠色黄、身热汗出、渴喜冷饮、面红咽干、苔黄腻、脉滑数，治以清热化痰、宣肺平喘，方用桑白皮汤加减；本案虽痰黄口渴、舌红苔黄，但兼有恶寒身痛、身热无汗之表寒未解之象，故辨为表寒肺热，治当解表与清里并重。\n西医诊断：慢性阻塞性肺疾病急性加重\n西医诊断依据：\n1.症状依据：喘息气促、呼吸急促、胸闷气憋、咳嗽、咯痰黄稠量多、咯吐不爽，活动后喘息明显加重，伴周身酸楚不适、乏力纳差，符合慢性阻塞性肺疾病急性加重期咳嗽、咳痰、气短较平时加重之特点。\n2.体征依据：呼吸频率增快（约24次/分），急性病容，面色红赤，鼻翼扇动，双肺呼吸音粗，可闻及干啰音及散在湿啰音，胸廓对称，语颤正常；无颈静脉怒张、无肝颈静脉回流征、无下肢水肿。\n3.实验室及影像依据：血常规WBC 6.5×10^9/L、N% 65%，Hb 130g/L、PLT 200×10^9/L；生化肝肾功能及电解质正常；心电图示窦性心律、正常心电图，可除外明显心律失常及心肌缺血。血气分析、C反应蛋白及胸部X线待完善，以进一步评估低氧血症程度及肺部病变性质。\n西医分型/分级/分期：慢性阻塞性肺疾病急性加重期，本次为受凉感染诱发之急性加重，按Anthonisen标准（气促加重、痰量增多、痰变脓性）属中度加重。气流受限程度待肺功能检查后按GOLD分级判定：GOLD 1级 FEV1占预计值≥80%；GOLD 2级 50%～79%；GOLD 3级 30%～49%；GOLD 4级 <30%；本次起病新、无既往肺功能资料，暂按急性加重期处理。本次无呼吸衰竭（未吸氧状态下无低氧血症及二氧化碳潴留证据），故未达Ⅱ型呼吸衰竭标准。合并高血压病，本次血压130/80mmHg，属1级（低危），目前控制尚可。\n诊疗计划：\n1.按内科Ⅱ级护理，清淡流质或半流质饮食，多饮水；2.完善检查：血常规+C反应蛋白（目的：明确有无细菌感染及炎症程度，为是否使用抗菌药物提供依据）、血气分析（目的：评估缺氧与二氧化碳潴留程度，为氧疗及病情严重度判断提供依据）、胸部X线（目的：明确有无肺部感染、肺不张等病变，为抗感染治疗提供依据）、心电图（目的：排除心源性喘息并评估心脏基础情况，为用药安全提供依据）；3.一般治疗：吸氧，雾化吸入（布地奈德2mg加异丙托溴铵0.5mg每日2次），拍背排痰；4.药物治疗：宣肺泄热中药汤剂（麻杏石甘汤加减），发热或感染明显者予阿莫西林克拉维酸钾0.625g每日3次口服，喘甚加用沙丁胺醇气雾剂2喷按需吸入；5.病情观察：监测体温、呼吸、血氧饱和度，观察痰液性状及有无发绀、意识改变；6.健康教育：指导戒烟、防寒、规律用药，必要时请呼吸科会诊。\n\n专科检查：\n望诊：急性病容，面色红赤，鼻翼扇动，口唇无明显发绀；闻诊：喘促气粗，声高息涌，咳嗽痰黄质黏；舌象：舌红，苔黄或薄黄；脉象：脉浮数或滑数。专科查体：双肺呼吸音粗，可闻及干啰音及散在湿啰音，语颤正常，胸廓对称；呼吸频率增快（约24次/分）。关键阴性体征：无颈静脉怒张，无肝颈静脉回流征，无下肢水肿，心律齐，无明显发绀。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，女，46岁，因\"反复喘证（表寒肺热）相关症状加重1周。\"入院。\n2.既往史：既往有高血压病史。\n3.体格检查：生命体征平稳，心肺腹查体未见明显异常。\n4.中医四诊：舌质红，苔黄腻，脉滑数。\n5.辅助检查：血常规、生化、心电图结果如上。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：喘证（表寒肺热）\n西医诊断：支气管哮喘\n\n（二）中医诊断依据：\n1.辨病依据：患者喘息气促、呼吸急促、胸闷气憋、咳嗽1周，动则加重，鼻翼煽动，甚则不能平卧，符合喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为主症\"之辨病要点；多因外感六淫致肺失宣降、肺气上逆而发，本案由外感诱发、起病较急，辨病为喘证（实喘）。\n2.辨证依据：初起微恶寒、周身酸楚，继而身热，为风寒束表、表邪未解；喘逆上气、息粗鼻扇、胸胀胸闷，咳嗽咯痰黄稠、咯吐不爽、口渴喜冷饮，舌质红、苔黄腻，脉浮数或滑数，为邪热壅肺、痰热内蕴。表寒里热并见而以里热为主，故辨证为表寒肺热证。\n3.依据《中医内科学》肺系病证·喘证·实喘「表寒肺热」证候：喘逆上气，胸胀或痛，息粗鼻扇，咳而不爽，痰吐稠黏，伴有形寒身热、烦闷身痛、口渴，苔薄白或黄、质红，脉浮数或滑数——治以解表清里、化痰平喘，方用麻杏石甘汤加减。\n\n（三）中医鉴别诊断：\n1.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声、呼吸气促困难，甚则喘息不能平卧，多有夙根及过敏史，起病急骤、缓解迅速，缓解期如常人；喘证以呼吸困难、张口抬肩、鼻翼煽动为主症，多无喉中哮鸣，常继发于外感及多种慢性肺系疾患。本案无喉中哮鸣如哨笛之典型表现，双肺以干啰音及散在湿啰音为主，故辨为喘证。\n2.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，属虚证，多无抬肩撷肚、鼻翼煽动之喘促之象；本案喘促气粗、声高息涌、鼻翼煽动、动则加重，属实喘，与气短不同。\n3.与「肺胀」鉴别：肺胀由多种慢性肺系疾患反复发作、迁延不愈而致肺气胀满不能敛降，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，伴唇甲紫绀、心悸、浮肿，病程缠绵、反复难愈；本案为新起病1周之实喘，无胸部膨满、无紫绀及浮肿，故不属肺胀。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌、胸部胀痛、痰多黏稠色黄、身热汗出、渴喜冷饮、面红咽干、苔黄腻、脉滑数，治以清热化痰、宣肺平喘，方用桑白皮汤加减；本案虽痰黄口渴、舌红苔黄，但兼有恶寒身痛、身热无汗之表寒未解之象，故辨为表寒肺热，治当解表清里并重。\n\n（四）西医诊断依据：\n1.病史依据：患者1周前受凉后急性起病，以喘息、咳嗽、咳痰为主要表现，症状呈进行性加重，既往有高血压病史。\n2.症状依据：喘息气促、呼吸急促、胸闷气憋、咳嗽、咯痰黄稠量多、咯吐不爽，初起微恶寒继而身热，周身酸楚，活动后加重，符合气道急性炎症伴气流受限之表现。\n3.体征依据：急性病容，面色红赤，鼻翼扇动，呼吸频率增快（约24次/分），双肺呼吸音粗，可闻及干啰音及散在湿啰音；无颈静脉怒张、无肝颈静脉回流征、无下肢水肿、无明显发绀。\n4.辅助检查依据：血常规WBC 6.5×10^9/L、N% 65%，暂不支持细菌感染；生化肝肾功能及电解质正常；心电图示窦性心律、正常心电图。血气分析、C反应蛋白及胸部X线待完善，以进一步明确气道炎症、低氧血症及肺部病变情况。\n\n（五）西医分型/分级/分期：\n1.支气管哮喘：按急性发作严重度分轻度、中度、重度、危重四级——轻度：步行或上楼时气短，可平卧，讲话成句，精神安静，呼吸频率轻度增加，无辅助呼吸肌活动及三凹征，哮鸣音散在，PEF占预计值>80%；中度：稍活动即感气促，喜坐位，讲话时断时续，时有焦虑烦躁，呼吸频率增加，可有三凹征，哮鸣音响亮弥漫，PEF占预计值60%～80%；重度：休息时亦气促，端坐呼吸，只能单字讲话，焦虑烦躁，大汗淋漓，呼吸频率>30次/分，常有三凹征，哮鸣音响亮弥漫，可有发绀，PEF占预计值<60%；危重：不能讲话，嗜睡或意识模糊，胸腹矛盾运动，哮鸣音减弱乃至消失（寂静肺），脉细数或心动过缓，可伴呼吸衰竭。本案呼吸频率约24次/分、能成句讲话、双肺闻及干啰音及散在湿啰音、无明显发绀及三凹征，按上述标准属中度急性发作。\n2.按长期控制水平分良好控制、部分控制、未控制三级；按病情严重程度分间歇状态、轻度持续、中度持续、重度持续四级。本案病程仅1周、无既往肺功能及峰流速资料，严重程度分级待支气管舒张试验及峰流速变异率检查后判定。\n3.合并高血压病：本次血压130/80mmHg，属1级（低危），目前控制尚可。\n\n（六）西医鉴别诊断：\n鉴别诊断：\n1.慢性阻塞性肺疾病急性加重期：\n【支持点】本例中老年女性，受凉后急性起病，表现为喘息、咳嗽、咳痰、活动后气促加重，双肺可闻及干啰音及散在湿啰音，与慢性阻塞性肺疾病急性加重时的气道炎症及气流受限表现相似。\n【不支持点】慢性阻塞性肺疾病多有长期吸烟史及慢性咳嗽、咳痰多年、逐年加重、气流受限不完全可逆的病史，查体多见桶状胸、双肺呼吸音减低、呼气相延长；本例平素无慢性咳喘病史，病程仅1周，起病急、症状可随治疗缓解，无桶状胸及长期气流受限依据。\n【排除方法】行肺功能检查（FEV1/FVC、支气管舒张试验）及胸部CT，结合吸烟史、病程长短及气流受限是否可逆进行鉴别。\n2.急性左心衰竭（心源性哮喘）：\n【支持点】急性左心衰竭亦表现为突发呼吸困难、不能平卧、双肺干湿啰音，与本例喘息、胸闷气憋相似，且本例有高血压病史。\n【不支持点】急性左心衰竭多见于中老年心脏病患者，常于夜间熟睡后突发，咳粉红色泡沫痰，双肺底满布对称性湿啰音，可伴颈静脉怒张、肝颈静脉回流征阳性、双下肢水肿，NT-proBNP明显升高，可闻及第三心音奔马律；本例无粉红色泡沫痰，无颈静脉怒张及下肢水肿，心脏听诊无心界扩大及奔马律。\n【排除方法】查心电图、床旁心脏彩超及血浆NT-proBNP，NT-proBNP正常、心脏结构与功能正常者可基本除外。\n3.自发性气胸：\n【支持点】自发性气胸可突发胸痛伴呼吸困难，与本例突发气促的表现有重叠。\n【不支持点】自发性气胸多突发一侧胸痛，患侧呼吸音明显减弱或消失、叩诊呈鼓音，气管可向健侧移位；本例双肺均可闻及呼吸音及啰音，胸廓两侧对称，无剧烈胸痛及单侧呼吸音消失。\n【排除方法】行床旁胸片或胸部CT检查，观察有无气胸线及肺压缩带即可明确。\n4.肺血栓栓塞症：\n【支持点】肺血栓栓塞症亦以突发呼吸困难、气促为主要表现，可伴胸闷、咳嗽。\n【不支持点】肺血栓栓塞症多有下肢深静脉血栓、长期卧床、手术外伤、肿瘤等危险因素，可伴胸痛、咯血、晕厥，低氧血症吸氧后不易纠正，D-二聚体明显升高；本例起病与受凉相关，伴上呼吸道卡他症状，无上述危险因素及咯血、晕厥。\n【排除方法】行D-二聚体、动脉血气分析及Wells评分评估临床可能性，必要时行肺动脉CTA及下肢静脉彩超。\n5.上气道阻塞：\n【支持点】喉头水肿、声带功能障碍等上气道阻塞亦可出现呼吸急促、喘鸣及呼吸困难。\n【不支持点】上气道阻塞多为吸气性呼吸困难，可闻及喉鸣或喘鸣，常伴声音嘶哑、犬吠样咳嗽；本例为呼气相为主的呼吸困难，双肺闻及干啰音及湿啰音，无声音嘶哑及吸气性三凹征。\n【排除方法】行肺功能流量-容积曲线（吸气相平台样改变提示上气道阻塞）、喉镜或颈部CT检查。\n6.气道异物吸入：\n【支持点】气道异物吸入可突发剧烈咳嗽、喘息及呼吸困难，需注意除外。\n【不支持点】气道异物多有明确呛咳或异物吸入史，起病突然，多为单侧呼吸音减低，可有三凹征；本例无明显异物吸入史，双肺呼吸音对称。\n【排除方法】详细询问进食及呛咳史，行胸部CT（含三维重建）或支气管镜检查以明确。\n\n（七）诊疗计划：\n诊疗计划：\n1.护理与饮食：按中医内科护理常规，Ⅱ级护理；清淡易消化半流质饮食，多饮温水，忌辛辣油腻、海鲜发物及烟酒，食盐每日＜5g以兼顾血压；卧床休息，避风寒，保持病室温度22～24℃、湿度50%～60%，定时开窗通风。\n2.完善检查：完善血常规、C反应蛋白、降钙素原（目的：评估有无细菌感染及炎症反应程度，为是否加用抗菌药物提供依据）；完善动脉血气分析（目的：明确PaO2、PaCO2及酸碱状态，为判断低氧血症程度、决定氧疗方式提供依据）；完善胸部X线或胸部CT（目的：明确有无肺部感染、气胸、肺气肿及纵隔病变，为鉴别喘息病因、评估病情严重度提供依据）；完善心电图（目的：了解有无心律失常、心肌缺血及右心负荷加重，为鉴别心源性喘息提供依据）；完善肺功能、支气管舒张试验及峰流速变异率（目的：客观评估气流受限程度及其可逆性，明确支气管哮喘诊断并作急性发作严重度分级，为吸入糖皮质激素及支气管舒张剂长期治疗方案提供依据）；完善血清总IgE、过敏原检测及外周血嗜酸性粒细胞计数（目的：明确过敏状态及气道炎症表型，为个体化抗炎治疗、指导避免诱因提供依据）；完善脑钠肽（目的：排除心源性喘息，鉴别心力衰竭所致呼吸困难）；完善肝肾功能、电解质（目的：了解基础脏器功能，为用药安全及剂量调整提供依据）。\n3.西医治疗：\n（1）抗炎平喘：注射用甲泼尼龙琥珀酸钠40mg加0.9%氯化钠注射液100ml，静脉滴注，每日2次，连用3日后减量，改布地奈德混悬液2mg加异丙托溴铵溶液0.5mg，氧气驱动雾化吸入，每日2次。\n（2）支气管舒张：硫酸沙丁胺醇气雾剂100μg，每次2喷，喘息明显时按需吸入，24小时不超过8喷；症状控制后改沙美特罗替卡松粉吸入剂50μg/250μg，每次1吸，每日2次，吸入后立即漱口。\n（3）祛痰：盐酸氨溴索片30mg，口服，每日3次；痰液黏稠难咯者可加用乙酰半胱氨酸泡腾片0.6g溶于温水，口服，每日1次。\n（4）抗感染：目前血常规WBC 6.5×10^9/L、N% 65%，暂不加用抗菌药物；若出现脓性痰、体温＞38.5℃或C反应蛋白明显升高，给予阿莫西林克拉维酸钾片0.625g，口服，每日3次，疗程5～7日；青霉素过敏者改左氧氟沙星片0.5g，口服，每日1次。\n（5）氧疗与对症：持续低流量吸氧2L/min，维持血氧饱和度≥93%；体温＞38.5℃时予布洛芬混悬液15ml口服退热，必要时6小时后重复，24小时不超过4次。\n（6）血压管理：监测血压每日2次，暂不加用降压药，若血压持续≥140/90mmHg，予苯磺酸氨氯地平片5mg口服每日1次，并请心内科会诊。\n4.中医治疗：四诊合参，患者喘逆上气、息粗鼻扇、胸胀胸闷，咯痰黄稠不爽，初起微恶寒、周身酸楚，继而身热，口渴喜冷饮，舌质红、苔黄腻，脉浮数，证属表寒未解、邪热壅肺、痰热内蕴之表寒肺热证，治以解表散寒、清热化痰、宣肺平喘为治则；方选麻杏石甘汤合清金化痰汤加减。中药处方如下：麻黄6g、杏仁10g、生石膏30g（先煎）、炙甘草6g、黄芩10g、桑白皮12g、瓜蒌皮12g、桔梗10g、浙贝母10g、鱼腥草20g、枇杷叶10g、陈皮10g、茯苓15g、生姜3片。用法：水煎服，每日一付，分2次温服，每次约200ml，餐后半小时服用。方解：方中麻黄辛温发汗、宣肺平喘，开表闭以散未尽之寒，生石膏辛甘大寒、清泄肺胃郁热，二药一温一寒、相反相成，共为君药，且石膏用量五倍于麻黄，清里而不助表寒；杏仁降利肺气、止咳平喘，黄芩、桑白皮清肺泄热、化痰止咳，瓜蒌皮、浙贝母、鱼腥草清热化痰散结，共为臣药，以除痰热之壅滞；桔梗宣肺利咽、枇杷叶降气止咳，一宣一降以复肺之宣肃，陈皮理气燥湿、茯苓健脾渗湿以绝生痰之源，生姜助麻黄解表并和胃，共为佐药；炙甘草调和诸药，缓和麻黄、石膏寒温之性并防其伤正，为使药。全方解表与清里并重、宣肃同施、标本兼顾，共奏解表散寒、清热化痰、宣肺平喘之效。因患者有高血压病史，麻黄减量至6g并密切监测血压，若血压明显升高则加钩藤15g（后下）、夏枯草12g清肝降压；若喘促缓解而痰仍黏稠者，去麻黄，加地龙10g、葶苈子10g（包煎）以化痰通络。同时予耳穴压豆（肺、气管、神门、交感）每日按压3次，每次1～2分钟；穴位贴敷（肺俞、定喘、膻中）每日1次，每次4～6小时。\n5.密切观察病情变化，向家属交代目前病情，注意防跌倒、防坠床，积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房，患者神志清楚，精神较昨日好转，喘促气急较入院时略有减轻，仍诉胸闷气憋、动则喘甚，咳嗽咯痰黄稠量多、咯吐不爽，无夜间阵发性呼吸困难，无咯血胸痛，无发热恶寒加重，纳差，二便调。查体：体温36.9℃，脉搏88次/分，呼吸22次/分，血压134/82mmHg，血氧饱和度（未吸氧）94%；急性病容，面色红赤，鼻翼扇动较前减轻，口唇无明显发绀；舌质红，苔黄腻，脉滑数。双肺呼吸音粗，可闻及散在干啰音及少量湿啰音，未闻及哮鸣音；心律齐，无颈静脉怒张，无双下肢水肿。辅助检查回报：血常规WBC 6.5×10^9/L、N% 65%，C反应蛋白8.6mg/L，暂不支持细菌感染；血气分析示pH 7.42、PaO2 76mmHg、PaCO2 38mmHg，提示轻度低氧血症；胸部X线示双肺纹理增粗紊乱，未见实变及气胸；心电图窦性心律、正常心电图；肝肾功能、电解质正常。\n执行情况：Ⅱ级护理、清淡半流质饮食、吸氧（2L/min）、布地奈德2mg加异丙托溴铵0.5mg雾化吸入每日2次、盐酸氨溴索30mg口服每日3次及麻杏石甘汤加减汤剂均已遵嘱执行，患者未诉药物不良反应，吸入后已按要求漱口。\n\n主治医师查房分析：\n一、中医辨病辨证分析\n患者以喘息气促、呼吸急促、胸闷气憋为主症，动则加重，甚则鼻翼煽动、抬肩撷肚，合于喘证「以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征」之辨病要点，故中医辨病为喘证，属实喘范畴。辨证求因：患者一周前受凉起病，初起微恶寒、周身酸楚，继而身热汗出不畅，此为风寒束表、卫阳被遏、表邪未解；旋即喘逆上气、息粗鼻扇、胸胀胸闷，咳嗽咯痰黄稠、咯吐不爽、口渴喜冷饮，舌质红、苔黄腻，脉滑数，此为表邪入里化热、邪热壅肺、痰热内蕴、肺失宣降。其病位在肺，涉及卫表，病机总括为风寒外束、热邪壅肺、痰热阻络、肺气上逆，属本虚（肺气不足）标实（表寒里热）而以标实为急之证，四诊合参，辨证为表寒肺热证，与首程辨证一致，舌脉与主症均支持，辨证依据充分。\n\n二、中医鉴别诊断\n1.与「哮病」鉴别：哮病为发作性痰鸣气喘之疾，发时喉中哮鸣有声如哨笛，呼吸气促困难，甚则喘息不能平卧，多有夙根与过敏史，起病急骤、缓解亦速，缓解期一如常人，且以「哮鸣音」为必具体征；本案虽喘促气粗、双肺闻及干啰音，但始终无喉中哮鸣之声，且起病有明确受凉诱因、病程一周持续未骤然缓解，舌红苔黄腻、脉滑数属痰热之象，与哮病之「痰鸣如吼、时发时止」不同，故辨为喘证而非哮病。\n2.与「肺胀」鉴别：肺胀由久病肺系疾患反复发作、迁延不愈，致肺气胀满、不能敛降，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、下肢浮肿，其病机为「本虚标实、虚实夹杂」，病程缠绵、反复难愈；本案病程仅一周，为新起之实喘，胸廓对称无桶状胸、无颈静脉怒张、无下肢水肿、无明显发绀，且无多年咳喘宿疾，故不属肺胀。\n3.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，声低息微而无声高息涌之象，多属虚证，常伴神疲乏力、脉虚细；本案喘促气粗、声高息涌、张口抬肩、鼻翼煽动、动则加重，声息有力而脉滑数，实象明显，故与气短迥异。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌、胸部胀痛、痰多黏稠色黄或血痰、身热汗出、面红咽干、渴喜冷饮，舌红苔黄腻、脉滑数，治以清热化痰、宣肺平喘（桑白皮汤加减）；本案痰黄口渴、舌红苔黄腻与之相似，但兼有恶寒身痛、身热无汗、脉浮之表寒未解征象，为「寒包火」之候，故不辨为单纯痰热郁肺，而当辨为表寒肺热，治须解表与清里并重。\n\n三、西医鉴别诊断\n1.与支气管哮喘（急性发作）鉴别：哮喘以发作性呼气性呼吸困难伴双肺弥漫哮鸣音为特征，多有过敏史及既往反复发作史，支气管舒张试验阳性、峰流速变异率＞10%可支持；本案双肺以干啰音及散在湿啰音为主、无弥漫哮鸣音，既往无反复喘息史，入院初期双肺呼吸音清，哮喘诊断依据尚不充分，待肺功能及支气管舒张试验、峰流速变异率回报后判定。\n2.与慢性阻塞性肺疾病急性加重鉴别：该病多见于长期吸烟或粉尘接触者，以慢性咳嗽咳痰、活动后气促为特点，肺功能示吸入支气管舒张剂后FEV1/FVC＜70%可确诊；本案无长期咳痰喘史及吸烟史，胸廓对称、无桶状胸及呼吸音减弱，暂不支持，需肺功能检查进一步排除。\n3.与急性左心衰竭（心源性哮喘）鉴别：心源性哮喘多于夜间熟睡后发作，咳吐粉红色泡沫痰，伴端坐呼吸、大汗、双肺底湿啰音，可有心脏扩大、病理性杂音及脑钠肽升高；本案虽有高血压病史，但无夜间阵发性呼吸困难、无粉红色泡沫痰、无颈静脉怒张及下肢水肿，心电图正常，脑钠肽待查，心源性因素暂可排除。\n\n四、国内外相关疾病研究进展\n1.《中国支气管哮喘防治指南（2020年版）》及2023年全球哮喘防治创议（GINA）报告均强调，哮喘急性发作期以反复吸入短效β2受体激动剂联合吸入糖皮质激素为基础治疗，并推荐在急性发作早期短程口服糖皮质激素以减少复发与住院；同时明确反对无指征地使用抗菌药物，指出仅当存在发热、脓性痰、白细胞及C反应蛋白明显升高等细菌感染证据时才考虑加用。本案WBC 6.5×10^9/L、N% 65%、C反应蛋白8.6mg/L，暂不加用抗菌药物，符合上述原则。\n2.一项纳入1000余例急性发作期哮喘患者的随机对照试验显示，与单用支气管舒张剂相比，早期联合吸入糖皮质激素可使喘息缓解时间缩短约1天，并显著降低急性发作复发率与住院率。\n3.一项纳入16项随机对照试验、共1100余例患者的系统评价提示，麻杏石甘汤联合西医常规治疗哮喘急性发作，在提高临床总有效率、改善FEV1及降低复发率方面优于单纯西医治疗，且未见严重不良反应，为本案中西医结合治疗提供了依据。\n4.国内多项研究提示，本病「表寒肺热」证型与气道炎症介质水平升高、气道高反应性及嗜酸性粒细胞活化相关，中医「寒包火」病机认识与气道炎症急性加剧的病理过程具有一致性，提示辨证论治需兼顾解表与清里。\n\n五、诊疗计划\n1.中医治疗：治以解表散寒、清热化痰、宣肺平喘，方选麻杏石甘汤合清金化痰汤加减。处方：麻黄6g、杏仁10g、生石膏30g（先煎）、炙甘草6g、黄芩10g、桑白皮12g、瓜蒌皮12g、桔梗10g、浙贝母10g、鱼腥草20g、枇杷叶10g、陈皮10g、茯苓15g、生姜3片。用法：水煎服，每日一付，分2次温服，每次约200ml，餐后半小时服用。方解：方中麻黄辛温发汗、宣肺平喘，开表闭以散未尽之寒，生石膏辛甘大寒、清泄肺胃郁热，二药一温一寒、相反相成，共为君药，且石膏用量倍于麻黄，清里而不助表寒；杏仁降利肺气、止咳平喘，黄芩、桑白皮清肺泄热、化痰止咳，瓜蒌皮、浙贝母、鱼腥草清热化痰散结，共为臣药，以除痰热之壅滞；桔梗宣肺利咽、枇杷叶降气止咳，一宣一降以复肺之宣肃，陈皮、茯苓理气健脾渗湿以绝生痰之源，生姜助麻黄解表并和胃，共为佐药；炙甘草调和诸药兼防麻黄、石膏伤正，为使药。全方解表与清里并重、宣肃同施、标本兼顾。因患者有高血压病史，麻黄减量至6g并密切监测血压，若血压明显升高则加用钩藤15g（后下）、夏枯草12g清肝降压；若喘促缓解而痰仍黏稠者，去麻黄，加地龙10g、葶苈子10g（包煎）以化痰通络。同时予耳穴压豆（肺、气管、神门、交感）每日按压3次，每次1～2分钟。\n2.西医治疗：布地奈德混悬液2mg加异丙托溴铵0.5mg，氧气驱动雾化吸入，每日2次；沙丁胺醇气雾剂100μg，每次2喷，喘息明显时按需吸入，24小时不超过8喷；盐酸氨溴索30mg，口服，每日3次；暂不加用抗菌药物，若出现脓性痰、体温＞38.5℃或C反应蛋白明显升高，再考虑阿莫西林克拉维酸钾0.625g口服每日3次。持续低流量吸氧2L/min，维持血氧饱和度≥93%；监测血压每日2次，暂不加用降压药；完善肺功能及支气管舒张试验、峰流速变异率（评估气流受限可逆性）、血清总IgE及外周血嗜酸性粒细胞计数（明确过敏状态与炎症表型）、脑钠肽（排除心源性喘息）。\n3.护理与调摄：饮食宜清淡易消化，以半流质为主，多饮温水，忌辛辣、油腻、海鲜发物及烟酒，食盐每日＜5g以兼顾血压；起居避风寒、戒烟，室内温度22～24℃、湿度50%～60%，勤换床单、避免尘螨花粉等过敏原，外出戴口罩；情志上予耐心疏导，避免恼怒紧张，可听轻音乐、练习腹式呼吸与缩唇呼气；功能锻炼予床上踝泵、坐位缓慢扩胸，缓解期散步、打太极拳，以不感气促为度，每日用峰流速仪监测并记录。\n4.医患沟通：已向患者及家属交代，目前中医辨为喘证（表寒肺热）、西医考虑支气管哮喘中度急性发作，病情属中度、暂无生命危险，经中西医结合治疗多数可在一周左右明显缓解；解释麻黄可能引起心悸、血压升高、失眠，需按量服用不可自行加量；说明暂不使用抗菌药物的理由；嘱继续规范吸入治疗、吸入后漱口，勿自行停药；告知出现喘息加重不能平卧、讲话断续、口唇发紫、吸入药无效或峰流速明显下降时立即告知医护人员；出院后1～2周呼吸科复诊，定期复查肺功能。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月16日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前好转，主诉症状较前略有改善，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体同前。继续当前中药治疗方案。\n\n【病程记录二】2026年08月18日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神可，主诉症状较前明显好转，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。继续当前治疗。\n\n【病程记录三】2026年08月20日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。\n查体：生命体征平稳，心肺腹查体未见明显异常。患者病情平稳，继续巩固治疗，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者 及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为喘证（表寒肺热），病情平稳，需住院进一步检查治疗。\n2.诊疗方案：完善相关检查，中医辨证论治，中药汤剂口服，对症支持治疗。\n3.可能风险：治疗过程中可能出现病情变化、药物不良反应等。\n4.注意事项：注意休息，清淡饮食，配合检查治疗。\n5.预后情况：经积极治疗后预后较好。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月25日\n住院天数：11天\n\n入院诊断：\n中医诊断：喘证（表寒肺热）\n西医诊断：相关疾病\n\n出院诊断：同入院诊断\n\n入院情况：\n患者，女，46岁，因\"反复喘证（表寒肺热）相关症状加重1周。\"入院。入院查体：生命体征平稳，心肺腹查体未见明显异常。中医四诊：舌质红，苔黄腻，脉滑数。\n\n诊疗经过：\n入院后完善相关检查，明确中医诊断，给予辨证论治，中药汤剂口服，对症支持治疗，患者病情逐渐好转，症状缓解，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神可，主诉症状基本缓解，无新发不适，饮食睡眠可，大小便正常。查体：生命体征平稳。\n出院医嘱：1. 饮食：低盐低脂清淡饮食，戒烟限酒。\n2. 休息与活动：注意休息，避免劳累，适当活动，循序渐进。\n3. 用药：按医嘱规律服药，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后1-2周门诊复查，如有病情变化随时就诊。\n5. 注意事项：监测血压、血糖等指标，保持良好生活习惯，遵医嘱定期随访。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者病例1：患者，入院第3天，神志清楚，精神较前好转，主诉症状较前改善，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 125/78mmHg。神志清楚，精神可。舌质红，苔黄腻，脉弦细。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。专科情况较前有所改善。\n辅助检查：相关检查结果回报，较前有所好转。\n四诊合参，本病属中医\"喘证（表寒肺热）\"范畴，辨证论治，随证加减。患者经中药辨证论治后，症状较前改善，治疗有效。继续目前中药治疗，注意观察病情变化，随证加减。注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，主诉症状明显改善，纳可，二便调，夜寐安。\n查体：T 36.4℃，P 74次/分，R 18次/分，BP 124/76mmHg。神志清楚，精神好。舌质红，苔黄腻，脉和缓。双肺呼吸音清，心率74次/分，律齐。腹软，无压痛。专科情况明显改善。\n辅助检查：复查相关指标正常或较前明显改善。\n患者经中药辨证论治后，症状明显改善，病情稳定。继续目前治疗，巩固疗效。今日可出院。建议出院后继续服用中药调理，定期复诊，注意休息，清淡饮食，避免劳累及情志刺激，适当锻炼，增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月17日 10:00（入院第3天）\n\n今日李副主任医师查房，患者神志清楚，精神可，喘促气急较入院时明显减轻，静息状态下已无明显气促，可平卧，咳嗽咯痰量减少、痰由黄稠转白稠，胸闷较前缓解，活动后仍稍感气短，无发热恶寒，纳食改善，二便调。查体：体温36.7℃，脉搏82次/分，呼吸20次/分，血压132/80mmHg，血氧饱和度（未吸氧）96%；面色转红润，无鼻翼扇动，口唇无发绀；舌质红、苔薄黄腻，脉滑稍数；双肺呼吸音粗，干啰音较前明显减少，湿啰音消失；心律齐，腹软无压痛，双下肢无水肿。复查血常规WBC 6.2×10^9/L、N% 62%，C反应蛋白5.2mg/L；血气分析PaO2 84mmHg、PaCO2 38mmHg；胸部X线示双肺纹理增粗，未见实变；肺功能及支气管舒张试验、峰流速变异率、血清总IgE、外周血嗜酸性粒细胞计数、脑钠肽已送检，部分报告待回。\n执行情况：原方案已遵嘱执行，患者服药及吸入依从性好，未诉心悸、失眠等不适，血压平稳，无药物不良反应。\n\n主任医师查房分析：\n一、中医辨病辨证分析（辨证要点再确认）\n患者以喘息气促、呼吸急促、胸闷气憋、动则加重为主症，符合《中医内科学》喘证之辨病要点，中医辨病为喘证无疑。就辨证而言，本案关键在「表寒」与「肺热」之孰轻孰重、孰主孰次：其初起微恶寒、周身酸楚、身热无汗，为风寒外束之表证；继而喘逆上气、息粗鼻扇、痰黄稠难咯、口渴喜冷饮，舌红苔黄腻、脉滑数，为邪热壅肺、痰热内蕴之里证。今表证已十去其八，恶寒身痛已除，然苔尚黄腻、脉仍滑数，说明痰热未清、肺气未肃，属「表解而里热未尽、痰热留恋」之阶段。故辨证仍为喘证·表寒肺热证，但当前以痰热壅肺为主、表寒为次，此为辨证要点之再确认，亦为下一步治法调整之依据。本病病位在肺，涉及卫表与脾胃，病机为外邪束表、入里化热、痰热阻肺、肺失宣降，兼有患者素有肺气不足之本，属本虚标实而以标实为急，治当清化痰热、宣肺平喘为主，佐以透表达邪，不可一味辛温发散，亦不可纯用苦寒，以防凉遏留邪、伤及脾胃。\n\n二、中医鉴别诊断\n1.与「哮病」鉴别：哮病以「发时喉中哮鸣有声」为审证之第一要义，其病有夙根，多因过敏原、冷空气诱发，发作与缓解均速，止时如常人，且哮鸣音为必备体征，舌象可如常人或见苔白滑；本案起病以受凉为因，历时一周不骤解，查体始终未闻及喉中哮鸣及弥漫哮鸣音，且舌红苔黄腻、脉滑数痰热之象贯穿始终，是以辨为喘证。然《医学正传》有「哮以声响言，喘以气息言」之论，若本案后续出现发作性喉中痰鸣、双肺弥漫哮鸣音，则当考虑喘哮并病，需及时修正诊断。\n2.与「肺胀」鉴别：肺胀为多种肺系疾病日久不愈、肺脾肾虚损、痰瘀阻结而致肺气胀满、不能敛降，症见胸中膨满、憋闷如塞、咳喘上气、痰多，动则尤甚，常伴唇甲紫绀、心悸、浮肿、舌暗脉涩，其病程长、反复发作、以本虚为主；本案病程仅一周、无桶状胸、无紫绀浮肿、无宿疾基础，舌脉以痰热实象为主，故不属肺胀。\n3.与「虚喘（肺气虚耗）」鉴别：虚喘以呼吸短促难续、深吸为快、气怯声低、动则喘息更甚为特点，伴倦怠乏力、自汗畏风、脉虚弱无力，舌淡苔薄；本案虽亦动则加重，但声高息涌、痰黄稠、苔黄腻、脉滑数，实象显然，且无久病虚损之貌，故非虚喘，提示本案不可过早投以补益，以免恋邪。\n4.与「痰浊阻肺」鉴别：痰浊阻肺者喘而胸满闷窒、咳嗽痰多黏腻色白、咯吐不爽、兼呕恶纳呆、苔白厚腻、脉滑，治以化痰降气（二陈汤合三子养亲汤加减）；本案痰黄稠、口渴喜冷饮、舌红苔黄，热象明显，与痰浊之白腻痰、苔白厚腻有别，故辨为痰热而非痰浊，用药当清热豁痰并进。\n\n三、西医疑难分析与鉴别\n1.与急性左心衰竭鉴别：患者有高血压病史，属心源性喘息高危人群，但无夜间阵发性呼吸困难、无粉红色泡沫痰、无颈静脉怒张及下肢水肿，心电图正常，脑钠肽已送检，若脑钠肽正常则基本除外。\n2.与慢性阻塞性肺疾病急性加重鉴别：患者无长期吸烟史及慢性咳痰喘史，胸廓对称、无桶状胸，本次为新起病，肺功能若示舒张后FEV1/FVC≥70%可除外。\n3.本次之疑难在于病原学与表型判定尚未明确：血常规及C反应蛋白不高，不支持细菌感染；肺功能、支气管舒张试验、峰流速变异率及血清总IgE、嗜酸性粒细胞计数尚未回报，故支气管哮喘之诊断依据仍不充分，需警惕嗜酸性粒细胞性支气管炎、变应性咳嗽等其他慢性气道疾病之可能，若支气管舒张试验阴性而峰流速变异率亦不升高，则需重新评估诊断，不可固守初始判断。\n\n四、国内外相关疾病研究进展\n1.《中国支气管哮喘防治指南（2020年版）》与2023年全球哮喘防治创议（GINA）报告推荐：急性发作期以短效β2受体激动剂联合吸入糖皮质激素为一线方案，中重度发作可短程口服糖皮质激素，并强调抗菌药物不作常规使用；本次未加用抗菌药物符合指南精神。\n2.《中药新药临床研究指导原则》及中医喘证诊疗相关共识明确：喘证实喘以「喘逆上气、息粗鼻扇、咳痰稠黏、苔黄、脉浮数或滑数」为表寒肺热证之辨证要点，治以解表清里、化痰平喘，麻杏石甘汤为代表方，为本案辨证用药提供了规范依据。\n3.一项纳入16项随机对照试验、1100余例患者的系统评价提示，麻杏石甘汤联合西医常规治疗哮喘急性发作，可提高临床总有效率、改善FEV1并降低复发率，且不良反应轻微，支持中西医结合治疗策略。\n4.国内多项临床研究提示，中药复方可通过下调气道炎症介质、调节辅助性T细胞1型／2型免疫失衡而减轻气道高反应性，对急性发作期气道炎症具有辅助控制作用，但证据等级以中低质量为主，仍需大样本随机对照试验进一步验证。\n\n五、诊疗计划（方案调整及理由）\n1.中医治疗：治则调整为「清热化痰、宣肺平喘为主，佐以透表」，方选麻杏石甘汤合清金化痰汤加减。处方：炙麻黄6g、杏仁10g、生石膏24g（先煎）、炙甘草6g、黄芩10g、桑白皮15g、瓜蒌皮12g、浙贝母10g、鱼腥草20g、地龙10g、枇杷叶10g、陈皮10g、茯苓15g、生姜3片。用法：水煎服，每日一付，分2次温服，每次约200ml，餐后服用。方解：方中炙麻黄宣肺平喘、生石膏清泄肺热，二药寒温并用、相反相成为君，石膏倍于麻黄，清里热而不助表邪；黄芩、桑白皮、瓜蒌皮、浙贝母、鱼腥草清热化痰、泄肺降气为臣，其中鱼腥草、黄芩清热解毒力专，桑白皮兼泻肺中水气，瓜蒌皮、浙贝母豁痰散结；杏仁降气止咳，地龙清热通络、解痉平喘，枇杷叶清肺降逆，三者宣降相因为佐，以复肺之宣肃之职；陈皮、茯苓理气健脾、渗湿杜痰源，生姜和胃并助麻黄透表，炙甘草调和诸药、缓和麻黄发散之力，共为佐使。全方清热化痰、宣肺平喘而不伤正。调整理由：患者表寒已解、痰热未清，故麻黄改用炙麻黄并减石膏至24g，减轻发散之力；因痰黄难咯，加地龙以解痉通络、化痰平喘，与前「解表清里」相比，现更重化痰通络。继续耳穴压豆（肺、气管、神门、交感）及穴位贴敷（肺俞、定喘、膻中、天突）。\n2.西医治疗：布地奈德混悬液2mg加异丙托溴铵0.5mg，雾化吸入，每日2次；盐酸氨溴索30mg口服每日3次；沙丁胺醇气雾剂按需吸入，不超过8喷/日；继续低流量吸氧2L/min，维持血氧饱和度≥93%，病情稳定后逐渐改为按需吸氧；暂不加用抗菌药物，如复查C反应蛋白进行性升高、出现脓性痰或体温＞38.5℃再考虑阿莫西林克拉维酸钾0.625g口服每日3次；血压每日监测2次，若持续≥140/90mmHg，加用氨氯地平5mg每日1次口服，并注意与麻黄类中药的协同升压作用。待肺功能及支气管舒张试验、峰流速变异率、总IgE、嗜酸性粒细胞计数回报后，明确是否按支气管哮喘制定长期控制方案（吸入糖皮质激素联合长效β2受体激动剂）。\n3.护理与调摄：饮食清淡易消化，多饮温水，忌辛辣油腻、海鲜发物及烟酒，食盐每日＜5g；起居避风寒、戒烟，室内温湿度适宜，避免尘螨、花粉、冷空气及油烟刺激，外出戴口罩；情志调畅，避免恼怒忧思，可练腹式呼吸与缩唇呼气，每次10分钟、每日2次；功能锻炼循序渐进，缓解期散步、八段锦、太极拳，以不感气促为度，每日记录峰流速值。\n4.医患沟通：向患者及家属说明目前中医辨证仍为喘证（表寒肺热），表证已解、痰热渐清，病情好转，治疗方案已作相应调整；解释哮喘诊断尚待肺功能等检查确认，若确诊需长期规范吸入治疗、不可症状缓解即自行停药；告知麻黄类中药可能升压、加快心率，需继续监测血压并遵嘱服药；嘱出院后1～2周呼吸科复诊，复查肺功能，随身携带急救气雾剂，出现喘息加重、讲话断续、口唇发紫、峰流速明显下降时立即就诊；本次治疗有效，若病情持续稳定、复查指标好转，可考虑近期出院并做好随访计划。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1227,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6065b00cf455f6fe096d014d6b0238694fd83cc6603da31e82b6d207d71f64ea","pinyin":"chuanzheng（biaohanfeire）","initials":"cz（bhfr）","setting":"in","caseName":"病例1：患者，女，46岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，46岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-e22af95c368a6cc2d43a","key":"v1-c9ccc21dfe2a3058|templates-e22af95c368a6cc2d43a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（正虚喘脱）","category":"中医科","raw":{"name":"喘证（正虚喘脱）","category":"中医科","case":{"case_name":"病例1：患者，男，72岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：72岁 民族：汉族\n婚姻：已婚 职业：退休工人 籍贯：本地\n入院时间：2026年09月10日 15:40 记录时间：2026年09月10日 17:30\n病史陈述者：患者本人及家属，可靠\n\n主诉：反复咳喘10余年，加重伴气短不足以息、汗出肢冷3天。\n\n现病史：患者于10余年前起病，每因受凉或季节更替即发咳嗽、咳痰、喘息，逐年加重，曾在当地医院诊断为“慢性支气管炎、慢性阻塞性肺疾病”，多次住院治疗，平素长期口服茶碱缓释片及间断吸入沙丁胺醇气雾剂，病情控制一般。半个月前受凉后咳喘再发，咳白色黏痰，量中等，动则气促。近3天来气短明显加重，静息时亦感呼吸浅促、气不接续，活动后尤甚，需高枕卧位方可稍安，伴精神萎靡、汗出不止（动则汗出、汗凉）、畏寒肢冷、心慌胸闷、口燥咽干而不欲多饮、乏力纳差。自服氨茶碱及止咳化痰中成药（具体不详）效果欠佳，症状进行性加重，今日由家属急送我院门诊，门诊查指脉氧饱和度82%（未吸氧状态下），血气分析提示Ⅱ型呼吸衰竭，以“喘证（正虚喘脱）”收入我科。发病以来无咯血，无意识障碍，无抽搐，无胸痛剧烈难忍，无夜间阵发性呼吸困难及粉红色泡沫痰，无少尿、无尿，无双下肢水肿骤然加重。精神萎靡，饮食减少，睡眠差（不能平卧），大小便尚调，体重无明显变化。\n\n既往史：慢性阻塞性肺疾病病史10余年，慢性肺源性心脏病病史5年，高血压病史8年，血压最高160/90mmHg，规律服用苯磺酸氨氯地平5mg每日1次，血压控制在130-140/80-85mmHg。2年前因“慢性阻塞性肺疾病急性加重、Ⅱ型呼吸衰竭”在我院住院，经无创通气治疗好转。否认糖尿病、冠心病、脑卒中病史。否认肝炎、结核等传染病史。否认手术、外伤及输血史。否认食物、药物过敏史。预防接种史不详。\n\n个人史及家族史：生于本地，久居本地，无疫区及疫水接触史。吸烟史40余年，每日约20支，已戒烟5年；偶有饮酒，已戒。无粉尘及有害气体长期接触史。家族中否认类似疾病史及遗传性疾病史。\n婚育史：24岁结婚，配偶体健，育有1子1女，子女体健。\n\n体格检查：\nT 36.9℃，P 112次/分，R 28次/分，BP 138/84mmHg，SpO2 82%（未吸氧）。\n一般情况：神志清楚，精神萎靡，形体偏瘦，自动体位（半卧位），查体合作。发育正常，营养中等。\n中医四诊：\n望诊：神志清楚，精神萎靡，面色㿠白无华，口唇及爪甲轻度发绀，呼吸浅促、抬肩撷肚，形体偏瘦，舌质淡紫、边有齿痕，苔薄白而润。\n闻诊：语声低怯，气息微弱，时有断续，咳声低弱无力，咳白色黏痰，无异味，无异常气味闻及。\n问诊：气短不足以息，动则喘甚，神疲乏力，自汗出而汗凉，畏寒肢冷，心慌胸闷，口燥咽干不欲多饮，纳差，夜寐差，不能平卧，二便尚调。\n切诊：脉细弱无力，尺脉尤甚，重按欲绝；肌肤湿冷，四肢末端不温。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性稍差，口唇发绀。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：颈软，无抵抗，气管居中，甲状腺未触及肿大，颈静脉充盈。\n胸部：胸廓呈桶状，肋间隙增宽，双侧呼吸动度减弱，叩诊呈过清音，双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音，以双下肺为著。心率112次/分，律齐，剑突下可见心脏搏动，三尖瓣听诊区可闻及Ⅱ级收缩期吹风样杂音，肺动脉瓣区第二心音亢进。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，肝颈静脉回流征阳性，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，双下肢轻度指凹性水肿，四肢末端发凉。\n神经系统：神志清楚，生理反射存在，巴氏征阴性，肌张力正常。\n专科情况：呼吸浅促，28次/分，呈呼气性呼吸困难，辅助呼吸肌参与呼吸运动，三凹征弱阳性；双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音；心率112次/分，律齐；口唇发绀，颈静脉充盈，肝颈静脉回流征阳性，双下肢轻度指凹性水肿。关键阴性体征：无意识障碍及扑翼样震颤，无颈项强直，无咯血，无胸膜摩擦音，无单侧呼吸音消失，无周围循环衰竭表现（血压尚平稳）。\n\n辅助检查：\n门诊血气分析（未吸氧）：pH 7.31，PaO2 52mmHg，PaCO2 68mmHg，HCO3- 32mmol/L，BE +5mmol/L，提示Ⅱ型呼吸衰竭、代偿性呼吸性酸中毒。\n门诊血常规：WBC 12.6×10^9/L，N% 86%，Hb 138g/L，PLT 186×10^9/L。\n门诊生化：ALT 28U/L，AST 32U/L，BUN 8.6mmol/L，Cr 96μmol/L，K+ 3.4mmol/L，Na+ 136mmol/L，Cl- 96mmol/L。\n门诊NT-proBNP：1860pg/mL。\n门诊胸部CT：双肺弥漫性肺气肿，双肺纹理增粗紊乱，双下肺少许斑片状渗出影，肺动脉增宽，右心室增大。\n门诊心电图：窦性心动过速，心率114次/分，肺型P波，电轴右偏，不完全性右束支传导阻滞。\n\n初步诊断：\n中医诊断：喘证（正虚喘脱）\n中医诊断依据：\n1.辨病依据：患者以气短不足以息、静息时呼吸浅促、气不接续、动则喘甚、不能平卧、张口抬肩、鼻翼煽动为主症，与喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"相符；患者反复咳喘10余年、本次加重3天，静息亦喘、抬肩撷肚，辨病为喘证，属虚喘范畴。\n2.辨证依据：喘逆剧甚，稍动则喘剧欲绝，心慌动悸，烦躁不安，面色㿠白无华，口唇及爪甲发绀，汗出不止而汗凉，畏寒肢冷，肌肤湿冷、四肢末端不温，舌质淡紫、边有齿痕、苔薄白而润，脉细弱无力、尺脉尤甚、重按欲绝。此乃喘促日久，肺肾俱虚，气阴耗伤，阴不敛阳，阳气欲脱之候，四诊合参，辨证为喘证之正虚喘脱证，属虚喘重证、危候。治以扶阳固脱、镇摄肾气，方用参附汤送服黑锡丹，配合蛤蚧粉。\n中医鉴别诊断：\n1.与「肺胀」鉴别：肺胀系多种慢性肺系疾患反复发作、迁延不愈，致肺气胀满、不能敛降，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲发绀、心悸、肢体浮肿，病位在肺、久则累及心肾，其喘为原发病的组成部分；喘证以呼吸困难、气短不足以息为主症，病位主要在肺、涉及肾。本患者虽有咳喘日久、桶状胸、胸部膨满之肺胀基础，但本次以喘逆剧甚、汗出肢冷、脉微欲绝为急，故以喘证（正虚喘脱）为第一诊断。\n2.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声、呼吸气促困难，甚则喘息不能平卧，多有夙根及过敏史，发作与缓解均较迅速、缓解期如常人；喘证以呼吸困难、气短不足以息为主，多呈持续性、进行性加重，无喉中哮鸣如哨笛之特征，常继发于久咳久喘之后。本患者本次为持续性喘促加重，喉中无典型哮鸣如吼之音，故不诊断为哮病。\n3.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证范畴，但无抬肩撷肚、鼻翼煽动等喘促之象，亦无发绀、汗出肢冷之脱象；本患者喘促显著、张口抬肩、汗出肢冷、脉微欲绝，非单纯气短可比。\n4.与「厥证」鉴别：厥证以突然昏倒、不省人事、四肢厥冷、移时方苏为特征，多因气机逆乱、阴阳失调所致，发作时无典型喘促不能平卧之象；正虚喘脱虽有汗出肢冷、脉微欲绝之阳脱表现，但以喘逆剧甚、张口抬肩、不能平卧为主症，神志多清楚，可资鉴别。若喘脱进一步加重出现神昏、嗜睡、球结膜水肿，则属肺性脑病范畴，须中西医结合紧急抢救。\n西医诊断：1.慢性阻塞性肺疾病急性加重期；2.Ⅱ型呼吸衰竭；3.慢性肺源性心脏病 右心功能不全；4.高血压病2级（很高危）\n西医诊断依据：\n1.病史依据：老年男性，慢性阻塞性肺疾病病史10余年、慢性肺源性心脏病病史5年，吸烟史40余年（已戒烟5年），2年前曾因慢性阻塞性肺疾病急性加重、Ⅱ型呼吸衰竭住院行无创通气治疗，本次受凉后咳喘加重3天。\n2.症状依据：气短不足以息，静息时呼吸浅促、气不接续，动则喘甚，不能平卧，咳白色黏痰，伴神疲乏力、汗出而凉、畏寒肢冷、心慌胸闷、口燥咽干不欲多饮、纳差，符合慢性阻塞性肺疾病急性加重合并呼吸衰竭及右心功能不全之临床表现。\n3.体征依据：T 36.9℃，P 112次/分，R 28次/分，BP 138/84mmHg，SpO2 82%（未吸氧）；神志清楚，精神萎靡，面色㿠白，口唇及爪甲发绀，呼吸浅促，辅助呼吸肌参与呼吸运动，三凹征弱阳性；胸廓呈桶状，肋间隙增宽，双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音；心率112次/分，剑突下可见心脏搏动，三尖瓣听诊区Ⅱ级收缩期吹风样杂音，肺动脉瓣区第二心音亢进；颈静脉充盈，肝颈静脉回流征阳性，双下肢轻度指凹性水肿，四肢末端发凉。\n4.实验室及影像依据：血气分析（未吸氧）pH 7.31、PaO2 52mmHg（<60mmHg）、PaCO2 68mmHg（>50mmHg）、HCO3- 32mmol/L、BE +5mmol/L，符合Ⅱ型呼吸衰竭伴代偿性呼吸性酸中毒；血常规WBC 12.6×10^9/L、N% 86%，提示细菌感染；NT-proBNP 1860pg/mL，提示右心功能不全；生化示K+ 3.4mmol/L，提示低钾血症，肝肾功能基本正常；胸部CT示双肺弥漫性肺气肿、双下肺少许斑片状渗出影、肺动脉增宽、右心室增大；心电图示窦性心动过速、肺型P波、电轴右偏、不完全性右束支传导阻滞，支持慢性肺源性心脏病诊断。\n西医分型/分级/分期：1.慢性阻塞性肺疾病急性加重期，按Anthonisen标准三项（气促加重、痰量增多、痰变脓性）具备，属重度急性加重，须住院治疗；气流受限程度按GOLD分级属GOLD 3级（FEV1占预计值30%～49%，依据病史、肺气肿影像及反复急性加重综合判定），按GOLD综合评估属急性加重高风险组（E组）。2.Ⅱ型呼吸衰竭（高碳酸血症型）：PaO2 52mmHg<60mmHg且PaCO2 68mmHg>50mmHg，按PaO2分度属中度低氧血症（40～59mmHg），伴代偿性呼吸性酸中毒（pH 7.31），属失代偿边缘状态，须密切监测并备无创正压通气。3.慢性肺源性心脏病失代偿期，合并右心功能不全，心功能Ⅲ级（NYHA分级：Ⅰ级日常活动不受限；Ⅱ级日常活动轻度受限；Ⅲ级日常活动明显受限，低于日常活动即引起症状；Ⅳ级休息时亦有症状）。4.高血压病2级（很高危）：血压最高160/90mmHg，合并靶器官损害（肺心病、右心功能不全）及呼吸衰竭，危险分层属很高危。5.低钾血症（K+ 3.4mmol/L），属轻度低钾（3.0～3.5mmol/L）。\n诊疗计划：1.按内科Ⅰ级护理，病重，心电监护，持续低流量吸氧（1-2L/min），记24小时出入量，绝对卧床休息；2.完善检查：复查血气分析（目的：动态评估缺氧及二氧化碳潴留，为氧疗与机械通气决策提供依据）、血常规+C反应蛋白+降钙素原（目的：明确感染严重程度，为抗感染方案升级或降级提供依据）、肝肾功能+电解质（目的：评估内环境紊乱与药物代谢能力，为补液及用药调整提供依据）、心肌酶谱+NT-proBNP（目的：评估心功能与心肌损伤，排除心源性喘脱）、D-二聚体（目的：排除肺栓塞，为抗凝决策提供依据）、痰培养+药敏（目的：明确致病菌及耐药性，指导抗菌药物选择）、心电图+床旁胸片及心脏彩超（目的：评估心肺结构与功能变化，为抢救治疗决策提供依据）；3.中医治疗：益气养阴、回阳固脱，方用生脉散合参附汤加减，日1剂，水煎取汁300mL，分2次温服；4.西医治疗：抗感染（哌拉西林他唑巴坦4.5g每8小时1次静滴）、平喘化痰（多索茶碱0.2g每日2次静滴、氨溴索30mg每日2次静滴）、糖皮质激素（甲泼尼龙40mg每日1次静滴）、纠正电解质紊乱及营养支持，必要时无创正压通气；5.病情观察：密切监测神志、呼吸频率、血氧饱和度、血压及血气变化，注意有无意识改变、球结膜水肿等肺性脑病早期表现；6.健康教育：嘱家属加强陪护，避免受凉，坚持家庭氧疗，规范吸入药物，戒烟，定期复诊，必要时请重症医学科会诊。\n\n专科检查：\n望诊：面色㿠白，口唇发绀，呼吸浅促、抬肩撷肚，舌质淡紫、边有齿痕，苔薄白而润；闻诊：语声低怯，气息微弱，咳声低弱无力；切诊：脉细弱无力，尺脉尤甚，肌肤湿冷，四肢末端不温。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年09月10日 18:00\n\n病例特点：\n1.患者，男，72岁，退休工人，因“反复咳喘10余年，加重伴气短不足以息、汗出肢冷3天”入院。\n2.既往有慢性阻塞性肺疾病病史10余年、慢性肺源性心脏病病史5年、高血压病史8年，2年前曾因Ⅱ型呼吸衰竭住院行无创通气治疗。\n3.主要症状：气短不足以息，静息时亦感呼吸浅促、气不接续，动则喘甚，神疲乏力，自汗出而汗凉，畏寒肢冷，心慌胸闷，口燥咽干不欲多饮，纳差，夜寐差，不能平卧。\n4.主要体征：T 36.9℃，P 112次/分，R 28次/分，BP 138/84mmHg，SpO2 82%（未吸氧）；神志清楚，精神萎靡，面色㿠白，口唇及爪甲发绀，呼吸浅促，辅助呼吸肌参与呼吸运动；胸廓呈桶状，双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音；心率112次/分，律齐，三尖瓣听诊区可闻及Ⅱ级收缩期吹风样杂音，肺动脉瓣区第二心音亢进；颈静脉充盈，肝颈静脉回流征阳性，双下肢轻度指凹性水肿。\n5.中医四诊：舌质淡紫、边有齿痕，苔薄白而润；语声低怯，气息微弱，咳声低弱无力；脉细弱无力，尺脉尤甚，重按欲绝；肌肤湿冷，四肢末端不温。\n6.辅助检查：血气分析示pH 7.31、PaO2 52mmHg、PaCO2 68mmHg；血常规WBC 12.6×10^9/L、N% 86%；NT-proBNP 1860pg/mL；胸部CT示双肺弥漫性肺气肿、右心室增大；心电图示窦性心动过速、肺型P波、电轴右偏。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：喘证（正虚喘脱）\n西医诊断：1.慢性阻塞性肺疾病急性加重期；2.Ⅱ型呼吸衰竭；3.慢性肺源性心脏病 右心功能不全；4.高血压病2级（很高危）\n\n（二）中医诊断依据：\n1.辨病依据：患者以气短不足以息、静息时呼吸浅促、气不接续、动则喘甚、不能平卧、张口抬肩、鼻翼煽动为主症，与喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"相符；反复咳喘10余年、本次加重3天，静息亦喘、抬肩撷肚，辨病为喘证（虚喘重证）。\n2.辨证依据：喘逆剧甚，稍动则喘剧欲绝，心慌动悸，烦躁不安，面色㿠白无华，口唇及爪甲发绀，汗出不止而汗凉，畏寒肢冷，肌肤湿冷、四肢末端不温；舌质淡紫、边有齿痕、苔薄白而润，脉细弱无力、尺脉尤甚、重按欲绝。此乃喘促日久，肺肾俱虚，气阴耗伤，阴不敛阳，阳气欲脱之候，四诊合参，辨证为喘证之正虚喘脱证。\n3.依据《中医内科学》肺系病证·喘证·虚喘「正虚喘脱」证候：喘逆剧甚，张口抬肩，鼻扇气促，端坐不能平卧，稍动则喘剧欲绝，心慌动悸，烦躁不安，面青唇紫，汗出如珠，肢冷，脉浮大无根或见歇止，或脉微欲绝——治以扶阳固脱、镇摄肾气，方用参附汤送服黑锡丹，配合蛤蚧粉。\n4.随症加减：汗出不止者加龙骨、牡蛎、浮小麦收敛止汗；喘甚不能平卧者加紫石英、沉香降气平喘；面唇发绀明显者加丹参、川芎活血通脉；纳差者加焦三仙、鸡内金健脾开胃；阳虚肢冷甚者加桂枝、干姜温阳散寒；痰黏难咯者加川贝母、瓜蒌皮润肺化痰。\n\n（三）中医鉴别诊断：\n1.与「肺胀」鉴别：肺胀是多种慢性肺系疾患反复发作、迁延不愈，导致肺气胀满、不能敛降的一种病证，临床表现为胸部膨满、憋闷如塞、喘息气促、咳嗽痰多、烦躁、心慌等，其喘为持续性，多伴胸部膨满胀闷，可有唇甲发绀、心悸、水肿，病位在肺，久则累及心肾；喘证以呼吸困难、气短不足以息为主，病位主要在肺，涉及肾；肺胀多由喘证、哮病等日久发展而成，肺胀之喘为原发病的组成部分，而喘证之喘以喘为主症。本患者既有咳喘日久、胸廓呈桶状、胸部膨满等肺胀之候，本次以喘逆剧甚、汗出肢冷、脉微欲绝为主，故以喘证（正虚喘脱）为第一诊断。\n2.与「哮病」鉴别：哮病是一种发作性的痰鸣气喘疾患，发时喉中哮鸣有声，呼吸气促困难，甚则喘息不能平卧，其特点为发作性、可自行或经治疗后缓解，缓解期如常人；喘证以呼吸困难、气短不足以息为主，多呈持续性、进行性加重，无喉中哮鸣如哨笛之特征，常继发于久咳、久喘之后。本患者本次为持续性喘促加重，喉中无典型哮鸣如吼之音，故不诊断为哮病。\n3.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，但无抬肩撷肚、鼻翼煽动等喘促之象，多由气虚所致，属虚证范畴，一般无发绀、无汗出肢冷之脱象。本患者喘促显著、张口抬肩、汗出肢冷、脉微欲绝，非单纯气短可比。\n4.与「厥证」鉴别：厥证以突然昏倒、不省人事、四肢厥冷、移时方苏为特征，多因气机逆乱、阴阳失调所致，发作时无典型喘促不能平卧之象；正虚喘脱虽有汗出肢冷、脉微欲绝之阳脱表现，但以喘逆剧甚、张口抬肩、不能平卧为主症，神志多清楚，可资鉴别。若喘脱进一步加重出现神昏、嗜睡、球结膜水肿，则属肺性脑病范畴，须中西医结合紧急抢救。\n来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肺系病证·喘证。提示：喘证正虚喘脱证属危重证候，若出现神昏、烦躁、嗜睡、球结膜水肿、呼吸浅慢或节律不整者，提示肺性脑病或呼吸衰竭加重，须立即抢救并考虑机械通气。\n\n（四）西医诊断依据：\n1.病史依据：老年男性，慢性阻塞性肺疾病病史10余年、慢性肺源性心脏病病史5年，长期吸烟史40余年，2年前有Ⅱ型呼吸衰竭住院史，本次受凉后咳喘加重3天。\n2.症状依据：气短不足以息，静息时呼吸浅促，动则喘甚，不能平卧，咳白色黏痰，伴乏力、汗出、畏寒肢冷、心慌胸闷，符合慢性阻塞性肺疾病急性加重及呼吸衰竭的临床表现。\n3.体征依据：呼吸28次/分，呈呼气性呼吸困难，辅助呼吸肌参与呼吸运动；胸廓呈桶状，双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音；心率112次/分，剑突下心脏搏动，三尖瓣区Ⅱ级收缩期吹风样杂音，肺动脉瓣区第二心音亢进；颈静脉充盈，肝颈静脉回流征阳性，双下肢轻度指凹性水肿；SpO2 82%（未吸氧）。\n4.辅助检查依据：血气分析示pH 7.31、PaO2 52mmHg（<60mmHg）、PaCO2 68mmHg（>50mmHg），符合Ⅱ型呼吸衰竭诊断；血常规WBC 12.6×10^9/L、N% 86%提示细菌感染；NT-proBNP 1860pg/mL提示右心功能不全；胸部CT示双肺弥漫性肺气肿、肺动脉增宽、右心室增大；心电图示肺型P波、电轴右偏、不完全性右束支传导阻滞，支持慢性肺源性心脏病诊断。血钾3.4mmol/L，提示低钾血症。\n\n（五）西医分型/分级/分期：\n1.慢性阻塞性肺疾病急性加重期：按Anthonisen标准（气促加重、痰量增多、痰变脓性）三项均具备，属重度急性加重；气流受限程度按GOLD分级属GOLD 3级（FEV1占预计值30%～49%，结合病史、肺气肿影像及反复急性加重综合判定）；按GOLD综合评估（症状+急性加重风险）属急性加重高风险组（E组），须长期规范吸入治疗并减少急性加重。\n2.Ⅱ型呼吸衰竭（高碳酸血症型）：PaO2 52mmHg<60mmHg且PaCO2 68mmHg>50mmHg，按PaO2分度属中度低氧血症（40～59mmHg），伴代偿性呼吸性酸中毒（pH 7.31），须密切监测血气并备无创正压通气。\n3.慢性肺源性心脏病：失代偿期（急性加重期），合并右心功能不全，心功能Ⅲ级（NYHA分级：Ⅰ级日常活动不受限；Ⅱ级日常活动轻度受限；Ⅲ级日常活动明显受限，低于日常活动即引起症状；Ⅳ级休息时亦有症状）。\n4.高血压病2级（很高危）：血压最高160/90mmHg，合并靶器官损害（慢性肺源性心脏病、右心功能不全）及Ⅱ型呼吸衰竭，危险分层属很高危。\n5.低钾血症：K+ 3.4mmol/L，按血钾水平分级属轻度低钾（3.0～3.5mmol/L；中度2.5～3.0mmol/L；重度<2.5mmol/L）。\n\n（六）西医鉴别诊断：\n1.支气管哮喘急性发作：\n【支持点】两者均可表现为喘息、呼吸困难、双肺哮鸣音，均可因感染或过敏因素诱发加重。\n【不支持点】支气管哮喘多见于青少年起病，发作呈阵发性、可逆性，缓解期如常人，多有过敏史及家族史，对支气管舒张剂反应良好；本患者老年起病，咳喘持续10余年并进行性加重，有长期吸烟史，肺功能呈不可逆性气流受限，胸部CT示肺气肿及右心室增大，本次以Ⅱ型呼吸衰竭为主要表现。\n【排除方法】结合病史、起病年龄、发作特点、吸烟史、肺功能检查及对支气管舒张剂的反应性综合判断，必要时行支气管舒张试验及过敏原检测。\n2.急性左心衰竭：\n【支持点】两者均可出现呼吸困难、不能平卧、发绀及双肺湿啰音。\n【不支持点】急性左心衰竭多有高血压、冠心病、瓣膜病等基础心脏病史，常于夜间突发，咳粉红色泡沫痰，双肺满布湿啰音，NT-proBNP显著升高，心电图及心脏彩超示左心扩大、左室射血分数下降；本患者以呼气性呼吸困难为主，有桶状胸及肺气肿表现，PaCO2升高，NT-proBNP升高以右心负荷增加为主，心脏彩超以右心室增大、肺动脉高压为特征。\n【排除方法】行床旁心脏彩超、NT-proBNP动态监测及心电图检查，结合基础心脏病史鉴别。\n3.自发性气胸：\n【支持点】均可出现突发呼吸困难加重。\n【不支持点】自发性气胸多突发一侧胸痛伴呼吸困难，患侧呼吸音消失、叩诊呈鼓音，气管向健侧移位；本患者双肺均可闻及呼吸音及啰音，无单侧呼吸音消失，无突发剧烈胸痛。\n【排除方法】床旁胸片或胸部CT可明确有无气胸。\n4.肺血栓栓塞症：\n【支持点】本患者有慢性肺源性心脏病、右心功能不全及活动受限卧床背景，本次突发气短加重、SpO2 82%、心率112次/分，符合肺血栓栓塞症的常见表现，须高度警惕。\n【不支持点】肺血栓栓塞症多突发胸痛、咯血、晕厥，D-二聚体明显升高，心电图可见SⅠQⅢTⅢ征及右心负荷加重的动态改变，低氧血症吸氧后难以纠正；本患者起病与受凉、咳喘痰量增多相关，3天来呈渐进性加重，无咯血及晕厥，心电图以肺型P波、电轴右偏为主。\n【排除方法】查D-二聚体、下肢静脉彩超及动脉血气分析，行Wells评分评估临床可能性，必要时行肺动脉CTA。\n5.重症肺炎：\n【支持点】本患者WBC 12.6×10^9/L、N% 86%升高，咳痰增多，双肺可闻及中细湿啰音，提示合并细菌感染，须与重症肺炎鉴别。\n【不支持点】重症肺炎多以发热、咳黄脓痰及肺部实变体征为主，胸部CT可见片状实变影及支气管充气征，并需符合重症肺炎的主要或次要标准；本患者胸部CT为弥漫性肺气肿改变，未见大片实变，体温无明显升高。\n【排除方法】复查胸部CT、降钙素原、C反应蛋白及痰培养+药敏，必要时行支气管镜防污染采样。\n6.支气管扩张症：\n【支持点】两者均为慢性气道疾病，均可出现慢性咳嗽、咳痰及肺部湿啰音。\n【不支持点】支气管扩张症以反复咳大量脓痰、间断咯血、痰液静置分层为特征，啰音位置固定持久，影像可见支气管柱状或囊状扩张；本患者痰为白色黏痰、无咯血，胸部CT为肺气肿表现，无支气管扩张征象。\n【排除方法】胸部高分辨率CT可明确有无支气管扩张，本患者胸部CT已不支持该诊断。\n\n（七）诊疗计划：\n1.护理与饮食：按中医内科护理常规，Ⅰ级护理，病重，心电监护，持续低流量吸氧（1～2L/min），记24小时出入量，绝对卧床休息，取半卧位；饮食清淡低盐（食盐每日＜3g）、低脂易消化，少量多餐，适当进食鱼、蛋、瘦肉及新鲜蔬菜，水肿者控制饮水量。\n2.完善检查：复查动脉血气分析（目的：动态监测PaO2、PaCO2及pH，判断Ⅱ型呼吸衰竭及呼吸性酸中毒的纠正情况，为是否行无创正压通气、调整吸氧浓度提供依据）；完善血常规、C反应蛋白、降钙素原（目的：评估肺部感染的严重程度及抗感染疗效，为抗菌药物选择与疗程提供依据）；完善痰培养+药敏（目的：明确致病菌及耐药情况，为目标性抗感染治疗提供依据）；完善肝肾功能、电解质（目的：评估重要脏器功能及有无低钾血症等电解质紊乱，为安全用药及补钾治疗提供依据）；完善心肌酶谱、NT-proBNP（目的：评估心肌损伤及心功能状态，为鉴别右心功能不全与急性冠脉事件、指导抗心力衰竭治疗提供依据）；完善D-二聚体（目的：筛查肺血栓栓塞症，为抗凝治疗决策提供依据）；完善心电图、床旁胸片（目的：了解心律失常、右心房右心室负荷情况以及有无气胸、肺部感染进展，为病情评估提供依据）；完善床旁心脏彩超（目的：评估肺动脉压力、右心大小及左室射血分数，明确慢性肺源性心脏病及右心功能不全程度，为指导治疗提供依据）。\n3.西医治疗：给予哌拉西林他唑巴坦注射液4.5g加入0.9%氯化钠注射液100mL静滴，每8小时1次，抗感染；给予多索茶碱注射液0.2g静滴，每日2次，解痉平喘；给予氨溴索注射液30mg静滴，每日2次，化痰；给予注射用甲泼尼龙40mg加入0.9%氯化钠注射液100mL静滴，每日1次，抗炎、减轻气道水肿；给予10%氯化钾注射液10mL加入补液中静滴，维持血钾4.0～4.5mmol/L；予持续低流量吸氧1～2L/min，加强营养支持，维持水电解质与酸碱平衡，必要时行无创正压通气。\n4.中医治疗：本例属喘证之正虚喘脱证，治以扶阳固脱、益气养阴、镇摄肾气，兼活血化痰、降气平喘为治则；方选参附汤合生脉散加减。中药处方如下：红参15g（另煎兑服）、制附子10g（先煎）、麦冬15g、五味子10g、山茱萸20g、龙骨30g（先煎）、牡蛎30g（先煎）、紫石英20g（先煎）、沉香5g（后下）、丹参15g、川芎10g、葶苈子12g（包煎）、瓜蒌皮15g、炙甘草6g。用法：水煎服，每日一付，水煎取汁300mL，分2次温服。方解：方中红参大补元气、益气固脱，制附子峻补元阳、回阳救逆，二者相须为君，使欲脱之阳气得以挽回；麦冬养阴生津，五味子敛肺止汗、收敛耗散之气，山茱萸补益肝肾、敛汗固脱，三药为臣，与君药相合而益气养阴、敛耗散之津气，防阳脱阴竭；龙骨、牡蛎重镇安神、收敛止汗，紫石英、沉香温肾纳气、降气平喘，丹参、川芎活血通脉以除面唇发绀，葶苈子、瓜蒌皮泻肺化痰、宽胸利气，共为佐药，标本兼顾；炙甘草益气和中、调和诸药，为使。全方共奏扶阳固脱、益气养阴、化痰活血、降气平喘之效。因黑锡丹含铅不宜久服，故以龙骨、牡蛎、紫石英、沉香镇摄肾气替代；另予蛤蚧粉3g冲服，补肺纳肾、定喘；中成药予参附注射液40mL、生脉注射液40mL分别加入5%葡萄糖注射液250mL静滴，每日1次。随症加减：汗出不止加浮小麦30g；喘甚不能平卧加旋覆花10g（包煎）；面唇发绀明显加桃仁10g；纳差加焦三仙各10g。\n5.密切观察病情变化，予心电监护，密切监测神志、呼吸频率、心率、血压、血氧饱和度及血气变化，注意有无意识改变、球结膜水肿、扑翼样震颤等肺性脑病早期表现，注意有无胸闷胸痛、咯血等肺栓塞征象；向家属交代目前病情，说明本例为慢阻肺急性加重合并Ⅱ型呼吸衰竭、慢性肺源性心脏病、右心功能不全，中医属喘证之正虚喘脱重证，病情危重，随时可能出现呼吸衰竭加重、肺性脑病、心力衰竭乃至猝死，不可自行撤减药物或调大氧流量；注意防跌倒、防坠床、防压疮，卧床期床上活动下肢以防深静脉血栓，积极医患沟通，及时请上级医师查看病人。\n医师签名：陈医生\n\n医师签名：陈医生\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年09月11日 09:00（入院第2天）\n\n今日张主治医师查房。患者神志清楚，精神较前稍振，气短略减，夜间可平卧约2小时，仍动则汗出、畏寒肢冷，咳白色黏痰量减，纳欠佳。查体：T 36.7℃，P 98次/分，R 24次/分，BP 132/80mmHg，SpO2 90%（吸氧2L/min）。面色转润，发绀减轻，舌质淡紫、边有齿痕，苔薄白，脉细弱较前有力；桶状胸，双肺呼吸音减低，散在哮鸣音及少量中细湿啰音；心率98次/分、律齐，三尖瓣区Ⅱ级收缩期吹风样杂音；肝颈静脉回流征阳性，双下肢指凹性水肿减轻。辅助检查：血气pH 7.34、PaO2 66mmHg、PaCO2 62mmHg；WBC 10.2×10^9/L、N% 80%；C反应蛋白36mg/L；血钾3.7mmol/L；NT-proBNP 1420pg/mL；痰培养待回报。\n\n一、中医辨病辨证分析\n患者以气短不足以息、静息呼吸浅促、动则喘甚、不能平卧、张口抬肩为主症，与《中医内科学》喘证「呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧」之临床特征相符，辨病为喘证，属虚喘重证。四诊合参：面色转润、发绀减轻，舌淡紫、边有齿痕、苔薄白而润；语声低怯、气息微弱；动则汗出而汗凉、畏寒肢冷、心悸胸闷、口燥咽干不欲多饮；脉细弱、尺脉尤甚，肌肤湿冷、四肢末端不温。辨证为正虚喘脱证，阳气渐回而气阴未复，兼痰瘀阻肺。病机：久患肺胀喘证十余年，肺脾肾三脏俱虚，肺不主气、肾不纳气，气阴耗伤日久，阴损及阳，阴不敛阳，阳气欲脱；复因外感引动伏痰，痰浊壅肺、瘀血阻络，肺气胀满不能敛降，本虚标实而以喘脱为急。经治两日汗减、发绀减轻、脉较前有力，阳气渐回，然尺脉仍弱、汗出未止、肢冷未除，脱象未尽，不可因小效而骤减回阳固脱之品。\n\n二、中医鉴别诊断\n1.与「肺胀」鉴别：肺胀以胸部膨满、喘咳痰多、心悸浮肿为主症，其喘呈持续性并与胸部膨满并存。本案虽有桶状胸之肺胀宿根，但此次以喘逆剧甚、汗出肢冷、尺脉尤甚为突出，属急则治标，故以喘证（正虚喘脱）为第一诊断、肺胀列兼病，标本不可混同。\n2.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声，要点在发作性、可缓解、缓解期如常人，多有过敏诱因；喘证以呼吸困难、气短不足以息为主，多呈持续性加重。本案喘促持续加重，喉中无哮鸣如吼之音，故不诊为哮病；若闻及喉中痰鸣辘辘，当考虑喘哮并病。\n3.与「厥证」鉴别：厥证以突然昏倒、不省人事、四肢厥冷、移时方苏为特征，由气机逆乱、阴阳失调所致，发作时无喘促不能平卧之象。本案虽有汗出肢冷、脉细弱之阳脱表现，但神志始终清楚、以喘逆剧甚为主症，故与厥证不同；若出现神昏嗜睡、球结膜水肿，则属喘脱并发肺性脑病，须紧急抢救。\n\n三、西医鉴别诊断\n1.与支气管哮喘急性发作鉴别：哮喘多有过敏及发作性喘息史，发作时双肺满布哮鸣音，缓解后可如常，血气早期为低氧伴PaCO2降低；本案老年起病、长期吸烟、桶状胸、喘促持续，血气呈Ⅱ型呼吸衰竭，故以慢阻肺急性加重为主。\n2.与急性左心衰竭鉴别：后者多有高血压、冠心病基础，咳粉红色泡沫痰、双肺大量湿啰音、端坐呼吸，NT-proBNP显著升高且随心衰纠正迅速下降；本案以右心功能不全合并肺部感染为主、双肺湿啰音量少，可资鉴别。\n\n四、国内外相关疾病研究进展\n1.《慢性阻塞性肺疾病诊治指南（2021年修订版）》推荐急性加重期控制性氧疗，目标SpO2 88%~92%，以防高浓度吸氧加重二氧化碳潴留；本例吸氧1~2L/min、SpO2约90%，与推荐一致。\n2.2023年GOLD报告及国内专家共识推荐急性加重期全身糖皮质激素疗程5~7天（如泼尼松40mg/d），可缩短恢复、减少复发；抗菌药物应依痰培养及药敏及时降阶梯。\n3.一项纳入数百例慢阻肺急性加重伴高碳酸血症患者的多中心随机对照试验及系统评价提示，早期无创正压通气可降低气管插管率与住院病死率；本例若pH持续低于7.35且呼吸窘迫加重，应尽早启动。\n\n五、诊疗计划\n1.中医治疗：治以益气养阴、回阳固脱，兼活血化痰、降气平喘，方用参附汤合生脉散加减。处方：红参15g（另煎兑服）、制附子10g（先煎）、麦冬15g、五味子10g、山茱萸20g、龙骨30g（先煎）、牡蛎30g（先煎）、紫石英20g（先煎）、沉香5g（后下）、丹参15g、川芎10g、葶苈子12g（包煎）、瓜蒌皮15g、炙甘草6g。用法：水煎服，每日一付，水煎取汁300mL，分2次温服。方解：红参大补元气、益气固脱，制附子峻补元阳、回阳救逆，二药相须为君；麦冬养阴生津，五味子敛肺止汗，山茱萸补益肝肾、敛汗固脱，为臣以益气养阴、敛耗散之津气；龙骨、牡蛎重镇止汗，紫石英、沉香温肾纳气平喘，丹参、川芎活血通脉，葶苈子、瓜蒌皮泻肺化痰宽胸，共为佐药；炙甘草益气和中、调和诸药，为使。因黑锡丹含铅，以龙骨、牡蛎、紫石英、沉香镇摄肾气替代，另予蛤蚧粉3g冲服补肺纳肾。随症加减：汗出不止加浮小麦30g；喘甚加旋覆花10g（包煎）；纳差加焦三仙各10g。中成药予参附注射液40mL、生脉注射液40mL分别加入5%葡萄糖注射液250mL静滴，每日1次。\n2.西医治疗：哌拉西林他唑巴坦4.5g加0.9%氯化钠注射液100mL静滴，每8小时1次；多索茶碱0.2g静滴每日2次；氨溴索30mg静滴每日2次；甲泼尼龙40mg静滴每日1次；10%氯化钾10mL加入补液静滴，维持血钾4.0~4.5mmol/L；持续低流量吸氧1~2L/min，必要时予无创正压通气。\n3.护理与调摄：饮食清淡低盐（食盐每日小于3g）、低脂易消化，少量多餐，记24小时出入量；取半卧位，卧床期床上活动下肢防血栓；家属多陪伴安慰，避免焦虑耗气；病情稳定后行缩唇呼吸、腹式呼吸训练，每日2~3次。\n4.医患沟通：已向家属交代，本例为慢阻肺急性加重合并Ⅱ型呼吸衰竭、慢性肺源性心脏病、右心功能不全，中医属喘证之正虚喘脱重证，病情危重，随时可能出现呼吸衰竭加重、肺性脑病、心力衰竭乃至猝死；目前治疗初见成效，须继续住院监护，不可自行撤减药物或调大氧流量；若出现神志改变、大汗肢冷、口唇发紫加重、痰多变黄、尿少浮肿加重，须立即告知医护人员。家属表示理解并配合。\n\n执行情况：遵嘱执行。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年09月11日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前稍振，气短较入院时略有减轻，夜间可平卧入睡约2小时，仍动则汗出、畏寒肢冷，咳白色黏痰，量较前减少，无咯血及胸痛，纳欠佳，二便尚调。\n查体：T 36.7℃，P 98次/分，R 24次/分，BP 132/80mmHg，SpO2 90%（吸氧2L/min）。口唇发绀较前减轻，舌质淡紫、边有齿痕，苔薄白，脉细弱、较前稍有力。双肺哮鸣音及湿啰音较前减少，双下肢水肿较前减轻。\n辅助检查：血气分析示pH 7.34、PaO2 66mmHg、PaCO2 62mmHg；血钾3.7mmol/L。\n四诊合参，仍属喘证之正虚喘脱，治以扶阳固脱、镇摄肾气，继续原方中药汤剂口服，日1剂，分2次温服；继续抗感染、平喘化痰、糖皮质激素及氧疗，密切观察病情变化。\n\n【病程记录二】2026年09月13日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神好转，自诉气短明显减轻，静息时已无明显喘息，可平卧入睡，汗出减少，畏寒肢冷缓解，咳痰量少易咯，纳食渐增，二便正常。\n查体：T 36.5℃，P 86次/分，R 20次/分，BP 128/78mmHg，SpO2 94%（吸氧2L/min）。面色转润，口唇发绀明显减轻，舌质淡红、边有齿痕，苔薄白，脉细弱但较前有力。双肺呼吸音略低，散在哮鸣音基本消失，双下肺可闻及少量细湿啰音。心率86次/分，律齐。腹平软，肝颈静脉回流征转为阴性，双下肢水肿消退。\n辅助检查：复查血气分析pH 7.38、PaO2 74mmHg、PaCO2 52mmHg；血常规WBC 8.2×10^9/L，N% 70%；C反应蛋白12mg/L；电解质正常。\n患者经益气养阴、回阳固脱中药及西医综合治疗后，阳气渐复，喘脱之象已除，病情明显好转。中药去制附子、沉香，减红参为10g，加太子参15g、山药15g以益气健脾，继续巩固治疗。\n\n【病程记录三】2026年09月16日 09:00（入院第7天）\n\n患者入院第7天，神志清楚，精神可，静息时无喘息，活动后稍感气短，汗出已止，四肢转温，咳痰少，纳可，夜寐安，二便调。\n查体：T 36.4℃，P 78次/分，R 18次/分，BP 126/76mmHg，SpO2 96%（吸氧1L/min）。面色转红润，口唇无发绀，舌质淡红、苔薄白，脉细。双肺呼吸音略低，未闻及明显干湿性啰音。心率78次/分，律齐。双下肢无水肿。\n辅助检查：复查血气分析pH 7.40、PaO2 78mmHg、PaCO2 46mmHg；血常规及C反应蛋白恢复正常范围；NT-proBNP降至420pg/mL。\n患者病情稳定，喘脱危象已解，正气渐复，继续中药益气养阴、补肺健脾调理，逐步下调吸氧流量，指导呼吸功能锻炼，准备出院。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年09月10日 19:30\n地点：医生办公室\n参加人员：患者及家属（其子），主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为喘证（正虚喘脱），西医诊断为慢性阻塞性肺疾病急性加重期、Ⅱ型呼吸衰竭、慢性肺源性心脏病 右心功能不全、高血压病2级（很高危），病情危重，属正虚喘脱之候，随时可能出现阳气暴脱、神昏等变证。\n2.诊疗方案：予Ⅰ级护理、病重、心电监护、持续低流量吸氧，中医以扶阳固脱、镇摄肾气中药汤剂口服，西医予抗感染、平喘化痰、糖皮质激素及纠正电解质紊乱治疗，必要时行无创正压通气或机械通气。\n3.可能风险：病情可能进一步加重，出现呼吸衰竭加重、肺性脑病、心力衰竭、心律失常、消化道出血、水电解质紊乱、药物不良反应等，严重时可危及生命；机械通气相关风险已另行告知。\n4.注意事项：绝对卧床休息，半卧位，避免受凉及情绪激动，配合翻身拍背排痰，低盐低脂易消化饮食，严格遵医嘱用药，不得自行停减药物。\n5.预后情况：本病属慢性病急性加重，经积极中西医结合治疗，多数患者症状可缓解，但肺功能损害不可逆，易反复发作，需长期家庭氧疗及规范用药，预后与年龄、基础肺功能及依从性相关。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：家属（患者之子）\n","出院记录":"出院记录\n\n入院日期：2026年09月10日\n出院日期：2026年09月20日\n住院天数：11天\n\n入院诊断：\n中医诊断：喘证（正虚喘脱）\n西医诊断：1.慢性阻塞性肺疾病急性加重期；2.Ⅱ型呼吸衰竭；3.慢性肺源性心脏病 右心功能不全；4.高血压病2级（很高危）\n\n出院诊断：\n中医诊断：喘证（正虚喘脱）\n西医诊断：1.慢性阻塞性肺疾病急性加重期；2.Ⅱ型呼吸衰竭（已纠正）；3.慢性肺源性心脏病 右心功能不全（好转）；4.高血压病2级（很高危）；5.低钾血症（已纠正）\n\n入院情况：\n患者，男，72岁，退休工人，因“反复咳喘10余年，加重伴气短不足以息、汗出肢冷3天”入院。入院时神志清楚，精神萎靡，面色㿠白，口唇及爪甲发绀，呼吸浅促、抬肩撷肚。查体：T 36.9℃，P 112次/分，R 28次/分，BP 138/84mmHg，SpO2 82%（未吸氧）；胸廓呈桶状，双肺呼吸音减低，可闻及散在哮鸣音及中细湿啰音；心率112次/分，律齐，三尖瓣听诊区可闻及Ⅱ级收缩期吹风样杂音；颈静脉充盈，肝颈静脉回流征阳性，双下肢轻度指凹性水肿。中医四诊：舌质淡紫、边有齿痕，苔薄白而润，脉细弱无力、尺脉尤甚，重按欲绝，肌肤湿冷。辅助检查：血气分析pH 7.31、PaO2 52mmHg、PaCO2 68mmHg；血常规WBC 12.6×10^9/L、N% 86%；NT-proBNP 1860pg/mL。\n\n诊疗经过：\n入院后完善血气分析、血常规、C反应蛋白、降钙素原、肝肾功能、电解质、心肌酶谱、NT-proBNP、痰培养、心电图、胸部CT及心脏彩超等检查，明确中医诊断为喘证（正虚喘脱），西医诊断为慢性阻塞性肺疾病急性加重期、Ⅱ型呼吸衰竭、慢性肺源性心脏病 右心功能不全、高血压病2级（很高危）。中医治以扶阳固脱、镇摄肾气，方用参附汤送服黑锡丹，配合蛤蚧粉，药用红参、制附子、龙骨、牡蛎、山茱萸、五味子、麦冬、紫石英、沉香、丹参、炙甘草，日1剂，水煎取汁300mL，分2次温服；随症加减：汗出不止加浮小麦，喘甚加降气之品，发绀明显加丹参、川芎。西医予持续低流量吸氧、哌拉西林他唑巴坦抗感染、多索茶碱平喘、氨溴索化痰、甲泼尼龙抗炎、纠正低钾血症及营养支持治疗，病情好转后抗生素降阶梯并停用激素。经治疗，患者喘促明显减轻，阳气渐复，汗出止，肢温转暖，发绀消退，血气分析恢复正常，血常规及C反应蛋白恢复正常，NT-proBNP降至420pg/mL，复查胸部影像渗出影吸收。经上级医师同意，准予出院。\n\n出院情况：\n患者神志清楚，精神可，静息时无喘息，活动后稍感气短，汗出已止，四肢转温，咳痰少，纳可，夜寐安，二便调。查体：T 36.4℃，P 78次/分，R 18次/分，BP 126/76mmHg，SpO2 96%（吸氧1L/min）。面色转红润，口唇无发绀，舌质淡红、苔薄白，脉细。双肺呼吸音略低，未闻及明显干湿性啰音。心率78次/分，律齐。腹平软，肝颈静脉回流征阴性，双下肢无水肿。\n出院医嘱：\n1. 饮食：低盐低脂、清淡易消化饮食，适当增加优质蛋白摄入，少量多餐，戒烟限酒。\n2. 休息与活动：注意休息，避免受凉及劳累，循序渐进行呼吸功能锻炼（缩唇呼吸、腹式呼吸），每日坚持，避免去人群密集场所。\n3. 用药：出院带中药7剂，方用生脉散合补肺汤加减：太子参15g、麦冬15g、五味子10g、黄芪30g、熟地黄15g、紫菀10g、桑白皮15g、山茱萸15g、山药15g、丹参15g、炙甘草6g。煎服法：日1剂，冷水浸泡30分钟，水煎2次，取汁约300mL，分早晚2次温服，饭后半小时服用。西药继续按医嘱规律服用，不可自行停药或改量；如有不适及时就诊。\n4. 复查：出院后2周门诊复查（中医内科/呼吸内科），复查血气分析、血常规、C反应蛋白、NT-proBNP及肺功能；出院后1个月复诊评估家庭氧疗及吸入药物方案。\n5. 注意事项：坚持长期家庭氧疗（每日15小时以上，流量1-2L/min）；规范使用吸入药物，掌握正确吸入方法；监测血压、血氧饱和度并记录；如出现喘促加重、发绀、神志改变、下肢水肿加重等，立即就近就诊。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：慢性阻塞性肺疾病伴急性加重 J44.100（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：Ⅱ型呼吸衰竭 J96.000；慢性肺源性心脏病 I27.900；右心功能不全 I50.900；高血压病2级 I10.x00；低钾血症 E87.600（含并发症/合并症）（编码待填）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年09月12日 09:00（入院第3天）\n\n患者入院第3天，神志清楚，精神较前好转，气短较前进一步减轻，静息时喘息不著，夜间可平卧入睡约4小时，汗出明显减少，畏寒肢冷减轻，咳白色黏痰，量少易咯，纳食渐增，二便调，夜寐欠安。\n查体：T 36.6℃，P 90次/分，R 22次/分，BP 130/80mmHg，SpO2 93%（鼻导管吸氧2L/min）。神志清楚，精神可，面色较前转润，口唇发绀减轻。舌质淡紫、边有齿痕，苔薄白，脉细弱、较前稍有力。胸廓呈桶状，双肺呼吸音减低，可闻及散在哮鸣音及少量细湿啰音，较前减少。心率90次/分，律齐，三尖瓣听诊区可闻及Ⅱ级收缩期吹风样杂音。腹平软，肝颈静脉回流征阳性，双下肢指凹性水肿较前明显减轻。\n辅助检查：复查血气分析（吸氧2L/min）pH 7.36，PaO2 70mmHg，PaCO2 58mmHg，HCO3- 31mmol/L；血常规WBC 9.4×10^9/L，N% 76%；C反应蛋白24mg/L；电解质K+ 3.9mmol/L、Na+ 137mmol/L；痰培养回报为肺炎克雷伯菌，对哌拉西林他唑巴坦敏感。\n四诊合参，本病属中医“喘证（正虚喘脱）”范畴，患者久病肺肾两虚、气阴耗伤、阴不敛阳，经扶阳固脱、镇摄肾气中药汤剂治疗后，喘促减轻，汗出减少，肢冷缓解，脉象渐趋有力，提示阳气渐复、脱象渐除，治疗有效。中药守原方，日1剂，水煎取汁300mL，分2次温服，随证加减；继续抗感染、平喘化痰、糖皮质激素及低流量吸氧治疗，根据痰培养结果继续哌拉西林他唑巴坦抗感染。注意观察神志、呼吸频率及血氧饱和度变化，防止二氧化碳潴留加重；鼓励翻身拍背排痰，注意休息，清淡饮食，避免劳累及情志刺激。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年09月14日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，气短明显减轻，静息时无喘息，活动后稍感气促，汗出已止，四肢转温，咳痰量少，纳可，二便调，夜寐转安。\n查体：T 36.5℃，P 82次/分，R 19次/分，BP 126/78mmHg，SpO2 95%（吸氧1L/min）。神志清楚，精神好，面色转润，口唇无明显发绀。舌质淡红、边有齿痕，苔薄白，脉细弱但较前有力。双肺呼吸音略低，散在哮鸣音消失，双下肺可闻及少量细湿啰音。心率82次/分，律齐。腹平软，肝颈静脉回流征转阴，双下肢水肿消退。\n辅助检查：复查血气分析pH 7.39，PaO2 76mmHg，PaCO2 50mmHg；血常规WBC 7.8×10^9/L，N% 68%；C反应蛋白8mg/L；电解质正常；NT-proBNP 620pg/mL；复查胸片示双下肺渗出影较前吸收。\n患者经中医扶阳固脱、镇摄肾气及西医综合治疗后，喘脱之象已除，阳气渐复，病情明显好转并趋于稳定。中药去制附子、沉香，红参减为10g，加太子参15g、山药15g以益气健脾、补肺固本，继续巩固疗效。西医抗生素已降阶梯为头孢呋辛，激素减量至甲泼尼龙20mg每日1次，继续化痰及低流量吸氧，逐步下调吸氧流量。嘱患者循序渐进进行呼吸功能锻炼，注意保暖，避免受凉，加强营养，为出院做准备。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年09月15日 10:00（入院第6天）\n\n今日李主任医师查房。患者神志清楚，精神好转，气短明显减轻，静息无喘息，活动后稍感气促，汗出已止，四肢转温，咳痰少，纳可，二便调，夜寐安。查体：T 36.5℃，P 80次/分，R 19次/分，BP 126/78mmHg，SpO2 95%（吸氧1L/min）。面色转润，口唇无发绀，舌质淡红、边有齿痕，苔薄白，脉细；双肺呼吸音略低，未闻及干湿性啰音；肝颈静脉回流征阴性，双下肢无水肿。血气分析基本正常，血常规及C反应蛋白恢复正常，NT-proBNP降至正常，痰培养回报肺炎克雷伯菌、对哌拉西林他唑巴坦敏感。\n\n一、中医辨病辨证分析\n患者病名仍属喘证，证型已随病情演变而转换。入院时喘逆剧甚、汗出如珠、肢冷、脉细弱而尺脉欲绝，属正虚喘脱危候；经回阳固脱、益气养阴治疗五日，现喘平汗止、四肢转温、发绀消退，舌由淡紫转淡红，脉由细弱转细而稍缓，提示阳气已回、脱象已除，证型转为「肺脾气虚、气阴两虚，兼痰瘀未净」。病机核心为本虚标实：肺脾肾三脏俱虚为本，痰浊瘀血为标；急期阳气浮越欲脱，故以参附回阳为先；今阳回脱固，若继用附子、红参峻补，恐温燥耗阴，故转为益气养阴、补肺健脾、兼化痰通络，缓图根本。辨证要点再确认：一者舌色转红、脉象渐和，辨证方向无误；二者仍有活动后气促、咳少量白痰，为痰浊未净，不可纯补；三者宜平补缓图，防「虚不受补」。\n\n二、中医鉴别诊断\n1.与「肺胀」鉴别：肺胀以胸部膨满、喘咳痰多、心悸浮肿为主症，属本虚标实而以标实为著的慢性进展性病证，其喘与胸部膨满长期共存，缓解期亦见气短、动则加重。本案系在肺胀宿根之上出现喘证正虚喘脱，今急象已解、转入缓解期调治，故治以补肺健脾、益气养阴为本，佐化痰通络以防复。\n2.与「哮病」鉴别：哮病发病急、缓解快，以喉中哮鸣有声为特征，缓解期如常人，多有过敏诱因；本案无喉中哮鸣、起病渐进、缓解亦缓，属喘证范畴。二者缓解期均需补益肺脾肾，但哮病重在祛风化痰，喘证重在补肺纳肾、益气养阴。\n3.与「虚劳」鉴别：虚劳以脏腑亏损、气血阴阳虚衰为病机，多见多脏腑虚损，表现为形瘦、乏力、短气、食少，病程长而进展缓慢，无急性喘逆剧甚之发作。本案虽见气短乏力之虚象，但以喘促为主症且有明确急性加重过程，故不以虚劳论，仍以喘证（虚喘）为本。\n\n三、西医疑难分析与鉴别诊断\n本例难点在于老年慢阻肺急性加重同时并存Ⅱ型呼吸衰竭、右心功能不全与肺部感染三个互相加重的环节，治疗须三者兼顾。1.与急性左心衰竭鉴别：后者多有高血压、冠心病基础，咳粉红色泡沫痰，NT-proBNP显著升高且随心衰纠正迅速下降；本例以右心功能不全为主，抗感染平喘后NT-proBNP迅速回落，可除外。2.与肺血栓栓塞症鉴别：后者多突发呼吸困难、胸痛，血气为低氧伴低碳酸血症，D-二聚体升高；本例渐进加重、PaCO2升高、D-二聚体正常，可基本除外。\n\n四、国内外相关疾病研究进展\n1.2023年GOLD报告与《慢性阻塞性肺疾病诊治指南（2021年修订版）》均强调，急性加重缓解后应尽早启动肺康复（缩唇呼吸、腹式呼吸、呼吸肌训练），可改善呼吸困难评分与运动耐量、降低再住院率，并推荐出院前评估长期氧疗指征。\n2.《中国慢性肺源性心脏病诊治专家共识》及多项随机对照试验提示，PaO2低于55mmHg或伴肺动脉高压者，每日家庭氧疗不少于15小时，可延缓肺动脉压进展、降低病死率；一项纳入数千例慢阻肺患者的研究及系统评价亦显示，每年接种流感疫苗可降低急性加重及住院风险约30%~40%。\n3.中药复方（生脉散合六君子汤类）辅助治疗慢阻肺稳定期及肺源性心脏病缓解期的系统评价（纳入多项随机对照试验）提示，加用益气养阴、补肺健脾中药可改善肺功能及运动耐量、减少急性加重次数，但研究方法学质量参差，仍需高质量试验验证。\n\n五、诊疗计划（调整）\n1.中医治疗：治则调整为益气养阴、补肺健脾、化痰活血通络，方用生脉散合六君子汤加减。处方：党参15g、黄芪30g、麦冬15g、五味子10g、山茱萸15g、炒白术15g、茯苓15g、陈皮10g、法半夏10g、山药20g、丹参15g、川芎10g、地龙10g、炙甘草6g。用法：水煎服，每日一付，水煎取汁300mL，分2次温服。方解：黄芪补肺健脾、益气固表，党参补中益气、健脾益肺，为君以复肺脾之气；麦冬养阴润肺，五味子敛肺滋肾，山茱萸补益肝肾，为臣以益气养阴、敛肺纳肾，既复耗伤之气阴，又防阳气再脱；炒白术、茯苓健脾渗湿，陈皮、法半夏理气化痰，山药补脾益肾，为佐以除未尽之痰浊；丹参、川芎、地龙活血通络，亦为佐；炙甘草益气和中、调和诸药，为使。全方补而不滞、温而不燥。停用制附子、红参、龙骨、牡蛎、紫石英、沉香等峻品。随症加减：痰多加瓜蒌皮15g、川贝母6g；动则气促加蛤蚧粉3g（冲服）。中成药予生脉饮口服液10mL每日3次、百令胶囊1g每日3次。\n2.西医治疗：甲泼尼龙静滴改为泼尼松片30mg每日1次晨服，5~7天内阶梯减量至停用；依药敏继续哌拉西林他唑巴坦4.5g每8小时1次静滴，疗程满7~10天后评估停用；停多索茶碱静滴，改为噻托溴铵粉雾剂18μg每日1次、沙美特罗替卡松粉吸入剂50/500μg每日2次吸入；氨溴索改片剂30mg每日3次口服；继续低流量吸氧1L/min；监测血气、电解质、肝肾功能及血糖，复查胸部影像。\n3.护理与调摄：饮食予高蛋白、易消化之品，食盐每日小于3g，少量多餐；注意保暖防感冒，严格戒烟并避免烟尘刺激；情志宜安定乐观；坚持缩唇呼吸、腹式呼吸及呼吸肌锻炼，每日2~3次。\n4.医患沟通：向患者及家属说明，本次急性加重已获控制、脱象已除，但慢阻肺与肺源性心脏病属慢性进展性疾病，肺功能损害不可逆，仍可能反复急性加重；出院后须坚持吸入药物与家庭氧疗，不可自行停药或调大氧流量，按时接种流感及肺炎疫苗，定期复查血气、肺功能，2周内门诊复诊；并告知复发先兆（痰量增多变黄、气促加重、下肢浮肿、神志改变）及就诊时机。家属表示理解并配合。\n5.下一步计划：出院前复查血气分析、肺功能、心脏彩超及NT-proBNP；制定长期吸入方案与家庭氧疗处方；完成慢阻肺自我管理教育；建立随访档案，1个月、3个月门诊随访。\n\n执行情况：遵嘱执行。\n\n医师签名：陈医生"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1228,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"de7d3b91d5a2647c571a338030b8aad44bce097a8a1f94892257d4dbc9329a4f","pinyin":"chuanzheng（zhengxuchuantuo）","initials":"cz（zxct）","setting":"in","caseName":"病例1：患者，男，72岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，72岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","",30]]},{"id":"templates-a81b4684601d1e3a3745","key":"v1-c9ccc21dfe2a3058|templates-a81b4684601d1e3a3745","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（痰浊阻肺）","category":"中医科","raw":{"name":"喘证（痰浊阻肺）","category":"中医科","case":{"case_name":"病例1：患者，男，62岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：62岁 民族：汉族\n婚姻：已婚 职业：退休工人 籍贯：本地\n入院时间：2026年08月15日 09:30 记录时间：2026年08月15日 11:00\n病史陈述者：患者本人，可靠\n\n主诉：反复咳嗽咳痰伴气喘3年，加重1周。\n\n现病史：患者3年前受凉后出现咳嗽、咳痰，痰多色白，每年冬春季节及受凉后反复发作，每次持续2～3个月，经抗感染、化痰平喘等治疗后缓解，平素咳嗽时轻时重，晨起及夜间为著，咳痰量多，每天约30～50ml。1周前因气候变化受凉后症状复发并逐渐加重，咳声重浊，痰量明显增多，每日咳痰约80～100ml，痰白黏腻、咯吐不爽，胸闷如窒，气短喘促，动则尤甚，稍事活动即感喘息，伴头身困重，脘腹胀满，食少纳呆，口黏不渴，大便偏溏，每日1～2次；无发热、恶寒，无鼻塞流涕，无痰中带血，无胸痛及夜间阵发性呼吸困难，无下肢浮肿。自服急支糖浆、复方甘草片效果不显，为求进一步系统诊治来我院门诊，门诊查血常规示白细胞及中性粒细胞比例正常，胸部CT示双肺纹理增粗紊乱、可见散在斑片状模糊影，以右下肺为著，肺气肿征；门诊以「喘证（痰浊阻肺）」收入我科。发病以来神志清楚，精神欠佳，因夜间咳嗽及气喘影响睡眠，夜眠差，饮食量减，小便正常，大便偏溏，体重无明显减轻。\n\n既往史：既往有慢性支气管炎病史3年，平素未规律用药。既往有高血压病史5年，服苯磺酸氨氯地平片5mg每日1次，血压控制在130/80mmHg左右。否认糖尿病、冠心病病史，否认肝炎、结核等传染病史。否认手术、外伤及输血史。否认食物、药物过敏史。\n\n个人史及家族史：生于本地，久居本地，无疫区及疫水接触史。吸烟30年，每日约20支，未戒烟；偶饮少量白酒。家族中否认类似疾病史。\n婚育史：26岁结婚，配偶体健，育有1子1女，子女体健。\n\n体格检查：\nT 37.2℃，P 92次/分，R 22次/分，BP 138/84mmHg。\n一般情况：神志清楚，精神欠佳，自动体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，面色萎黄少华，口唇无紫绀，舌质淡红，舌体稍胖，边有齿痕，苔白厚腻。\n闻诊：语声重浊，咳声重浊，喉中可闻及痰鸣音；无异常气味。\n问诊：咳嗽咳痰，痰白黏腻量多，胸闷气喘，动则加重，头身困重，脘腹胀满，食少纳呆，口黏不渴，夜寐差，大便偏溏，小便正常。\n切诊：脉滑。\n\n一般情况：神志清楚，精神反应可，营养发育正常，查体合作。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大，颈静脉无怒张。\n胸部：胸廓呈桶状，前后径稍增大，肋间隙稍增宽，呼吸运动对称，双侧语颤减弱，双肺叩诊呈过清音，肺肝界下移，双肺呼吸音粗，可闻及散在干啰音及湿性啰音，以右下肺为著，未闻及胸膜摩擦音。心率92次/分，律齐，心音稍遥远，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常，双下肢无凹陷性浮肿。\n神经系统：神志清楚，巴氏征阴性，肌张力正常，生理反射存在，病理征未引出。\n专科情况：\n望诊：面色萎黄，口唇无紫绀，舌质淡红，舌体稍胖，边有齿痕，苔白厚腻；咳声重浊。\n闻诊：语声重浊，可闻及痰鸣音。\n问诊：咳嗽咳痰，痰白黏腻、咯吐不爽，胸闷如窒，气短喘促，动则加重，脘痞食少。\n切诊：脉滑。\n专科查体：桶状胸，双肺叩诊过清音，肺肝界位于右锁骨中线第6肋间；双肺呼吸音粗，两肺可闻及散在干啰音及湿性啰音，以右下肺为著，未闻及哮鸣音及胸膜摩擦音。关键阴性体征：无三凹征，无鼻翼扇动，无口唇及肢端紫绀，无杵状指，无颈静脉怒张，无下肢浮肿，无夜间阵发性呼吸困难，无嗜睡及意识改变。\n\n辅助检查：\n门诊血常规：WBC 8.2×10^9/L，N% 68%，Hb 138g/L，PLT 210×10^9/L，E% 2.1%。\n门诊超敏C反应蛋白：12mg/L；降钙素原：0.08ng/ml。\n门诊胸部CT：双肺纹理增粗紊乱，可见散在斑片状模糊影，以右下肺为著，双肺见肺气肿征，未见实变、空洞及胸腔积液。\n门诊肺功能：FEV1/FVC 68%，FEV1占预计值78%，支气管舒张试验阴性。\n门诊心电图：窦性心律，心率92次/分，大致正常心电图。\n门诊痰涂片及培养：未见致病菌生长。\n\n初步诊断：\n中医诊断：喘证（痰浊阻肺）\n中医诊断依据：\n1.辨病依据：患者反复咳嗽咳痰伴气喘3年，每因受凉或冬春季节发作，本次受凉后复发加重1周，以胸闷如窒、气短喘促、动则尤甚、咳声重浊、痰多为主症，符合喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"之辨病要点，属喘证之实喘范畴。\n2.辨证依据：咳声重浊，痰白黏腻量多、咯吐不爽，胸闷如窒，气短喘促，动则尤甚，伴头身困重、脘腹胀满、食少纳呆、口黏不渴、大便偏溏；舌质淡红，舌体稍胖，边有齿痕，苔白厚腻，脉滑。此为脾失健运、聚湿生痰，痰浊内蕴、上干于肺，肺气不清、宣降失常之候，四诊合参，辨证为痰浊阻肺证，病位在肺、涉及脾，病性属实，为本虚标实、以标实为主。治以化痰降逆、宣肺平喘，方用二陈汤合三子养亲汤加减。\n中医鉴别诊断：\n1.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声、呼吸气促困难，甚则喘息不能平卧，多有夙根及过敏史，起病急、缓解快，缓解期如常人，以喉中哮鸣如哨笛为特征；喘证以呼吸困难、气短不足以息为主，多呈持续性、进行性加重，无喉中哮鸣之特征。本例双肺未闻及哮鸣音，以干湿性啰音为主，无发作性喉中痰鸣如水鸡声之表现，故辨为喘证。\n2.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证，无抬肩撷肚、鼻翼煽动及胸满闷窒之象；本例喘而胸满闷窒、痰涎壅盛、苔厚腻、脉滑，属痰浊壅肺之实喘，与气短不同。\n3.与「肺胀」鉴别：肺胀系多种慢性肺系疾患日久不愈、肺气胀满不能敛降所致，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、肢体浮肿，病程缠绵、经久难愈；本例虽有桶状胸及肺气肿征，但无唇甲紫绀、无颈静脉怒张、无下肢浮肿，心音稍遥远而无右心衰体征，本次以痰浊壅肺之喘促加重为主，故仍以喘证（痰浊阻肺）为诊断。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌，胸部胀痛，痰多黏稠色黄或夹血丝，伴胸中烦热、身热有汗、渴喜冷饮、面红、咽干，苔黄或腻、脉滑数，治以清热化痰、宣肺平喘，方用桑白皮汤加减；本例痰白不黄、身不热、口黏不渴、苔白厚腻而非黄腻，故与痰热郁肺不同，属痰浊（湿痰）阻肺。\n西医诊断：慢性阻塞性肺疾病急性加重期；高血压病2级（中危）\n西医诊断依据：\n1.病史依据：慢性咳嗽、咳痰、气喘病史3年，每年冬春季节及受凉后反复发作，每次持续2～3个月，累计超过3个月/年，吸烟史30年（每日约20支），本次受凉后急性加重1周。\n2.症状依据：咳嗽、咳痰量明显增多（每日约80～100ml），痰液变黏稠、咯吐不爽，气短喘促较平时加重，活动耐力下降，伴胸闷如窒、食欲减退。\n3.体征依据：T 37.2℃，P 92次/分，R 22次/分，BP 138/84mmHg；桶状胸，前后径稍增大，双侧语颤减弱，双肺叩诊过清音、肺肝界下移（右锁骨中线第6肋间），双肺呼吸音粗，可闻及散在干啰音及湿性啰音，以右下肺为著，未闻及哮鸣音及胸膜摩擦音；无紫绀、无三凹征、无颈静脉怒张、无下肢浮肿。\n4.实验室及影像依据：肺功能FEV1/FVC 68%，提示持续气流受限，FEV1占预计值78%，支气管舒张试验阴性；胸部CT示双肺纹理增粗紊乱、散在斑片状模糊影（以右下肺为著）及肺气肿征，未见实变、空洞及胸腔积液；血常规WBC 8.2×10^9/L、N% 68%，超敏C反应蛋白12mg/L、降钙素原0.08ng/mL，痰涂片及培养未见致病菌生长，提示细菌感染依据不足；心电图大致正常。\n西医分型/分级/分期：1.慢性阻塞性肺疾病急性加重期，本次为受凉诱发，咳嗽、咳痰、气促较平时加重且痰量增多、痰液变黏稠，按Anthonisen标准具备两项，属中度急性加重。2.气流受限程度按GOLD分级属GOLD 2级（中度气流受限：FEV1占预计值50%～79%，本例78%），支气管舒张试验阴性提示气流受限持续存在、不完全可逆。3.按GOLD综合评估（症状+急性加重风险），患者有长期咳嗽咳痰气喘症状、既往每年急性加重，倾向急性加重高风险组（E组），长期分组待CAT评分及近1年急性加重次数确定后判定（A组：低风险少症状；B组：低风险多症状；E组：高风险）。4.影像学呈肺气肿伴气道炎症改变，属慢性阻塞性肺疾病之气道炎症伴肺气肿表型。5.高血压病2级（中危）：血压138/84mmHg，规律服用苯磺酸氨氯地平片5mg每日1次，血压基本达标，危险分层属中危。6.本次急性加重细菌感染依据不足（降钙素原0.08ng/mL、白细胞及中性粒细胞比例正常、痰培养阴性），暂不列为细菌性加重。\n诊疗计划：\n1.按内科Ⅱ级护理，低盐低脂普通饮食，卧床休息，持续低流量吸氧（1～2L/min）；2.完善检查：复查血常规+超敏C反应蛋白（目的：评估感染控制情况与炎症程度，为抗感染疗程调整提供依据）、血气分析（目的：评估缺氧与二氧化碳潴留程度，为氧疗及通气支持提供依据）、痰培养及药敏（目的：明确致病菌与耐药情况，指导抗菌药物精准选择）、胸部CT（目的：明确肺部感染及气道病变范围，评估治疗效果）、心电图+心脏彩超（目的：评估心功能与右心负荷，排除心源性喘息）；3.一般治疗：翻身拍背排痰、雾化吸入（吸入用异丙托溴铵溶液）、必要时机械辅助排痰；4.药物治疗：中药汤剂化痰降气、健脾益肺（二陈汤合三子养亲汤加减），氨溴索30mg每日3次口服化痰，多索茶碱0.2g每日2次口服解痉平喘，苯磺酸氨氯地平片5mg每日1次控制血压，暂不经验性使用抗生素，视痰培养及炎症指标决定；5.中医特色治疗：针刺（肺俞、定喘、膻中、足三里、丰隆）每日1次，中药穴位贴敷（肺俞、膏肓、定喘）每日1次；6.病情观察：观察咳嗽、咳痰、气喘及痰色痰量变化，监测体温、呼吸、指脉氧饱和度，注意有无紫绀、意识改变及呼吸衰竭征象；7.健康教育：绝对戒烟、避免受凉及烟尘刺激、腹式呼吸及缩唇呼吸功能锻炼、冬病夏治知识宣教。\n\n专科检查：\n望诊：舌质淡红，舌体稍胖，边有齿痕，苔白厚腻。\n闻诊：语声重浊，可闻及痰鸣音。\n问诊：咳嗽咳痰，痰白黏腻、咯吐不爽，胸闷气短，动则加重，脘痞食少，大便偏溏。\n切诊：脉滑。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月15日 12:00\n\n病例特点：\n1.患者，男，62岁，因「反复咳嗽咳痰伴气喘3年，加重1周」入院，起病缓慢，病程缠绵，反复发作。\n2.既往有慢性支气管炎病史3年、高血压病史5年，吸烟30年，每日约20支，未戒烟。\n3.本次受凉后症状加重，咳声重浊，痰白黏腻量多、咯吐不爽，胸闷如窒，气短喘促，动则尤甚，伴头身困重、脘痞食少、口黏不渴、大便偏溏。\n4.体格检查：T 37.2℃，P 92次/分，R 22次/分，BP 138/84mmHg；桶状胸，双肺叩诊过清音，肺肝界下移，双肺呼吸音粗，可闻及散在干啰音及湿性啰音，以右下肺为著，未闻及哮鸣音；无紫绀、无三凹征、无下肢浮肿。\n5.中医四诊：舌质淡红，舌体稍胖，边有齿痕，苔白厚腻，脉滑。\n6.辅助检查：血常规WBC 8.2×10^9/L、N% 68%，超敏C反应蛋白12mg/L，降钙素原0.08ng/ml；胸部CT示双肺纹理增粗紊乱伴散在斑片状模糊影，以右下肺为著，肺气肿征；肺功能FEV1/FVC 68%，支气管舒张试验阴性；痰涂片及培养未见致病菌生长。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：喘证（痰浊阻肺）\n西医诊断：慢性阻塞性肺疾病急性加重期；高血压病2级（中危）\n\n（二）中医诊断依据：\n1.辨病依据：患者反复咳嗽咳痰伴气喘3年，每因受凉或冬春季节发作，本次受凉后复发加重1周，以胸闷如窒、气短喘促、动则尤甚、咳声重浊、痰多为主症，符合喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"之辨病要点，属喘证之实喘范畴。\n2.病史依据：反复咳嗽咳痰伴气喘3年，病程缠绵、反复不愈，本次受凉后复发加重1周。\n3.症状依据：咳声重浊，痰白黏腻量多、咯吐不爽，胸闷如窒，气短喘促，动则尤甚，头身困重，脘腹胀满，食少纳呆，口黏不渴，大便偏溏。\n4.舌脉依据：舌质淡红，舌体稍胖，边有齿痕，苔白厚腻，脉滑；双肺可闻及散在干湿性啰音。\n5.辨证分析：痰浊内蕴，上干于肺，肺气不清，宣降失常，故咳嗽痰多、胸闷气喘；脾失健运，聚湿生痰，故痰白黏腻、咯吐不爽；湿浊中阻，故头身困重、脘痞食少、口黏不渴、大便偏溏；舌淡红体胖有齿痕、苔白厚腻、脉滑，均为痰湿内盛之象。四诊合参，本病属中医「喘证」范畴，证属痰浊阻肺，病位在肺，涉及脾，病性属实，为本虚标实、以标实为主。\n6.依据《中医内科学》喘证「痰浊阻肺」证候：喘而胸满闷窒，甚则胸盈仰息，咳嗽痰多黏腻色白，咯吐不利，兼有呕恶、纳呆、口黏不渴，苔厚腻色白，脉滑。治以化痰降逆、宣肺平喘，方用二陈汤合三子养亲汤加减。\n\n（三）中医鉴别诊断：\n1.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，发时喉中哮鸣有声、呼吸气促困难，甚则喘息不能平卧，多有夙根及过敏史，起病急、缓解快，缓解期如常人，以喉中哮鸣如哨笛为特征；喘证以呼吸困难、气短不足以息为主，多呈持续性、进行性加重，无喉中哮鸣之特征。本例双肺未闻及哮鸣音，以干湿性啰音为主，无发作性喉中痰鸣如水鸡声之表现，故辨为喘证而非哮病。\n2.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证，无抬肩撷肚、鼻翼煽动及胸满闷窒之象；本例喘而胸满闷窒、痰涎壅盛、苔厚腻、脉滑，属痰浊壅肺之实喘，与气短不同。\n3.与「肺胀」鉴别：肺胀系多种慢性肺系疾患日久不愈、肺气胀满不能敛降所致，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、肢体浮肿，病程缠绵、经久难愈；本例虽有桶状胸及肺气肿征，但无唇甲紫绀、无颈静脉怒张、无肝颈静脉回流征阳性、双下肢无浮肿，心音稍遥远而无右心衰体征，故仍以喘证（痰浊阻肺）为诊断。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌，胸部胀痛，痰多黏稠色黄或夹血丝，伴胸中烦热、身热有汗、渴喜冷饮、面红、咽干，苔黄或腻、脉滑数，治以清热化痰、宣肺平喘，方用桑白皮汤加减；本例痰白不黄、身不热、口黏不渴、苔白厚腻而非黄腻，故与痰热郁肺不同，属痰浊（湿痰）阻肺。\n5.与「风寒壅肺」鉴别：风寒壅肺者喘急胸闷，咳痰清稀色白，兼见恶寒发热、头痛鼻塞、无汗，苔薄白，脉浮紧，治以宣肺散寒，方用麻黄汤合华盖散加减；本例无恶寒发热、无鼻塞流涕、无浮紧之脉，而痰量多黏腻、苔白厚腻、脉滑，以痰浊内阻为主，可资鉴别。\n来源：《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·喘证。提示：喘证若见喘促持续不解、张口抬肩、鼻扇气促、面唇青紫、脉浮大无根，为喘脱危候，须立即抢救。\n\n（四）西医诊断依据：\n1.病史依据：慢性咳嗽、咳痰、气喘病史3年，每年发作累计3个月以上，吸烟史30年，本次受凉后急性加重1周。\n2.症状依据：咳嗽、咳痰量增多，痰液变黏稠，气短喘促较平时加重，活动耐力下降，伴胸闷、食欲减退。\n3.体征依据：桶状胸，双肺叩诊过清音，肺肝界下移，双肺呼吸音粗，可闻及散在干啰音及湿性啰音，以右下肺为著。\n4.辅助检查依据：肺功能FEV1/FVC 68%提示持续气流受限，支气管舒张试验阴性；胸部CT示肺气肿征及散在斑片状模糊影，无实变及空洞；降钙素原0.08ng/ml、白细胞及中性粒细胞比例正常，提示细菌感染依据不足。\n\n（五）西医分型/分级/分期：\n1.慢性阻塞性肺疾病急性加重期：本次受凉诱发，咳嗽、咳痰、气促较平时加重，痰量增多、痰液变黏稠，按Anthonisen标准具备两项，属中度急性加重；气流受限程度按GOLD分级属GOLD 2级（中度气流受限：FEV1占预计值50%～79%，本例78%），支气管舒张试验阴性提示气流受限持续存在、不完全可逆；按GOLD综合评估（症状+急性加重风险），患者症状负荷较重且反复急性加重，倾向急性加重高风险组（E组），长期分组待CAT评分及近1年急性加重次数确定后判定（A组：低风险少症状；B组：低风险多症状；E组：高风险）。\n2.影像学呈肺气肿伴气道炎症改变，属慢性阻塞性肺疾病之气道炎症伴肺气肿表型。\n3.高血压病2级（中危）：血压138/84mmHg，规律服用苯磺酸氨氯地平片5mg每日1次，血压基本达标，危险分层属中危。\n4.感染分级：降钙素原0.08ng/mL、白细胞及中性粒细胞比例正常、痰培养未见致病菌生长，提示本次急性加重细菌感染依据不足，暂不列为细菌性加重。\n\n（六）西医鉴别诊断：\n1.支气管哮喘：\n【支持点】两者均为慢性气道疾病，均以反复发作的喘息、气促、胸闷、咳嗽为主要表现，均可闻及肺部啰音。\n【不支持点】哮喘多于幼年或青年起病，症状呈发作性、有明确过敏原及季节诱因，发作间期可完全缓解，多伴鼻痒、喷嚏等过敏表现，支气管舒张试验多阳性，外周血嗜酸性粒细胞及IgE升高；本例为中老年起病，症状呈慢性持续性并进行性加重，有长期吸烟史，支气管舒张试验阴性。\n【排除方法】详细询问起病年龄、发作特点及过敏史，行支气管舒张试验、峰流速变异率、血清总IgE及过敏原检测，必要时支气管激发试验。\n2.支气管扩张症：\n【支持点】两者均可见慢性咳嗽、咳大量痰液，肺部可闻及湿性啰音。\n【不支持点】支气管扩张以反复咳大量脓痰、间断咯血为特征，痰液静置后分层，肺部啰音位置固定且持久，可有杵状指；本例痰液为白色黏腻痰、无咯血、无杵状指，啰音不固定。\n【排除方法】胸部高分辨率CT可见支气管柱状或囊状扩张即可确诊；本例胸部CT未见支气管扩张改变。\n3.肺结核：\n【支持点】两者均见慢性咳嗽、咳痰、乏力，病程迁延。\n【不支持点】肺结核多伴午后低热、盗汗、消瘦、痰中带血，肺部病变多位于上叶尖后段，血沉增快；本例无低热盗汗及消瘦，无咯血，病变位于双肺纹理及右下肺。\n【排除方法】行痰抗酸杆菌涂片及培养、结核感染T细胞检测、胸部CT随访，必要时支气管镜检查。\n4.慢性肺源性心脏病：\n【支持点】两者均见于长期慢性肺病患者，均可出现气促、活动耐力下降。\n【不支持点】肺心病有肺动脉高压及右心功能不全表现，如颈静脉怒张、肝颈静脉回流征阳性、下肢浮肿、P2亢进；本例无颈静脉怒张、无下肢浮肿，心音稍遥远但无右心衰体征。\n【排除方法】行心脏彩超评估肺动脉压及右心大小，结合血气分析、心电图动态观察。\n5.肺血栓栓塞症：\n【支持点】肺血栓栓塞症亦可出现气促、活动后呼吸困难加重及低氧血症，与本例急性加重期气促加重相似。\n【不支持点】肺血栓栓塞症多有下肢深静脉血栓、长期卧床、手术外伤或肿瘤等危险因素，可伴突发胸痛、咯血、晕厥，D-二聚体明显升高，吸氧后低氧血症不易纠正；本例起病与受凉相关，伴咳嗽咳痰增多，无上述危险因素及咯血、晕厥。\n【排除方法】查D-二聚体、下肢静脉彩超及动脉血气分析，必要时行肺动脉CTA。\n6.自发性气胸：\n【支持点】自发性气胸可突发呼吸困难加重，与本例气促加重有重叠，且慢性阻塞性肺疾病患者为自发性气胸的高危人群。\n【不支持点】自发性气胸多突发一侧胸痛，患侧呼吸音减弱或消失、叩诊呈鼓音，气管向健侧移位；本例双肺均可闻及呼吸音及啰音，两侧对称，无突发剧烈胸痛。\n【排除方法】床旁胸片或胸部CT可明确有无气胸线及肺压缩。\n\n（七）诊疗计划：\n1.护理与饮食：按中医科肺系病证护理常规，内科Ⅱ级护理；低盐低脂、清淡易消化饮食，忌生冷、油腻、甜黏及辛辣之品以免助湿生痰，戒烟酒，可佐食山药、薏米、陈皮等健脾化痰之品；卧床休息，持续低流量吸氧1～2L/min，注意保暖防受凉，避免烟尘及冷空气刺激。\n2.完善检查：复查血常规、超敏C反应蛋白、降钙素原（目的：评估本次急性加重有无细菌感染及炎症程度，为是否经验性抗感染治疗提供依据）；完善动脉血气分析（目的：明确PaO2、PaCO2及酸碱失衡情况，判断有无呼吸衰竭，为选择氧疗方式提供依据）；完善痰培养及药敏（目的：明确致病菌及药物敏感性，为抗感染方案的调整提供依据）；完善胸部CT（目的：明确肺气肿、气道炎症及有无新发肺部感染、气胸、胸腔积液，为病情评估及疗效判断提供依据）；完善心电图、心脏彩超（目的：评估有无心律失常、肺动脉高压及右心功能不全，为鉴别心源性疾病、指导治疗提供依据）；完善肺功能（含支气管舒张试验）及CAT评分（目的：评估气流受限程度与症状负荷，为GOLD分级分组及长期吸入治疗方案提供依据）；完善动态血压监测及血脂、血糖、肾功能（目的：评估高血压靶器官损害及心血管危险因素，为降压药物选择与危险分层提供依据）。\n3.西医治疗：给予氨溴索片30mg 每日3次口服，化痰祛痰、降低痰液黏稠度以利咯出；给予多索茶碱片0.2g 每日2次口服，解痉平喘、改善气道痉挛，注意心率及胃肠道反应，避免与喹诺酮类药物同用；给予苯磺酸氨氯地平片5mg 每日1次口服，控制血压并达标；给予吸入用异丙托溴铵溶液2ml 每日2次雾化吸入，抗胆碱能舒张支气管、减轻喘息；持续低流量吸氧1～2L/min，维持指脉氧饱和度90%以上；辅以翻身拍背助排痰，必要时机械辅助排痰。患者降钙素原0.08ng/ml、白细胞及中性粒细胞比例正常，细菌感染依据不足，暂不经验性使用抗生素；若痰量增多、痰色转黄绿或体温升高，及时复查血常规、超敏C反应蛋白及降钙素原，并考虑加用抗感染治疗（如注射用头孢呋辛1.5g 每8小时1次静脉滴注，或左氧氟沙星氯化钠注射液0.5g 每日1次静脉滴注，后者与多索茶碱联用时需减量并监测心率）。\n4.中医治疗：给予中药方剂以化痰降逆、宣肺平喘、佐以健脾化湿为治则；方选二陈汤合三子养亲汤加减；中药处方如下：法半夏10g 陈皮10g 茯苓15g 紫苏子10g 白芥子6g 莱菔子10g 厚朴10g 苦杏仁10g 紫菀10g 款冬花10g 焦三仙各10g 炙甘草6g。用法：水煎服，每日一付，分2次温服，早晚饭后半小时各服1次，共开5剂。方解：方中法半夏燥湿化痰、降逆和胃，紫苏子降气消痰、止咳平喘，二药一燥一降，直折痰浊壅肺之标实，切中喘而胸满闷窒、痰多黏腻之主症，共为君药；白芥子温肺利气、豁痰散结，善消皮里膜外之痰，莱菔子消食导滞、降气化痰，既助君药化痰平喘，又兼顾食少纳呆，二药为臣，与紫苏子合为三子养亲之意，降气化痰而不伤正；陈皮理气燥湿，气顺则痰自消，茯苓健脾渗湿以杜生痰之源，厚朴下气宽中、消胀除满，苦杏仁降气止咳平喘，紫菀、款冬花润肺化痰止咳，焦三仙消食和胃以助脾运，上药共为佐药，标本兼顾、肺脾同治；炙甘草化痰止咳、调和诸药，为使药。全方化痰与健脾并施，降气与宣肺同用，使痰无再生之源、肺复宣降之职，共奏化痰降逆、宣肺平喘、健脾化湿之效。加减法：痰多黏稠难咯者加海蛤粉15g（包煎）、瓜蒌皮15g以化痰散结；胸闷窒甚者加瓜蒌15g、薤白10g以宽胸理气；食少脘痞者加鸡内金10g以消食健脾；脾虚便溏者加炒党参15g、炒白术15g以健脾益气；寒痰较重、痰白清稀者加干姜6g、细辛3g以温肺化痰；喘甚不得卧者加葶苈子10g（包煎）、地龙10g以泻肺平喘。服药期间忌生冷、油腻、甜黏及辛辣之品，服中药与西药间隔1小时以上，服药3～5剂后复诊，依痰量、痰色及舌脉变化随证调方。其他中医治疗：针刺取肺俞、定喘、膻中、足三里、丰隆，平补平泻，留针20分钟，每日1次；中药穴位贴敷（白芥子、细辛、甘遂、延胡索研末姜汁调敷）取肺俞、膏肓、定喘，每日1次，每次2～4小时。\n5.密切观察病情变化，重点观察咳嗽、咳痰、气喘及痰色痰量变化，监测体温、呼吸频率、指脉氧饱和度，注意有无紫绀、意识改变及呼吸衰竭征象；向家属交代目前病情，注意防跌倒、防坠床，加强呼吸功能锻炼（每日缩唇呼吸、腹式呼吸各2～3次、每次10分钟），积极医患沟通，及时请上级医师查看病人。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月16日 09:00（入院第2天）\n\n今日张主治医师查房。患者神志清楚，精神较入院时好转，诉咳嗽较前减轻，咳痰较前顺畅，痰量减少至每日约60ml，仍为白色黏痰，胸闷气喘有所减轻，活动后仍有气短，无发热恶寒，无胸痛咯血，食纳渐增，脘腹痞满减轻，夜间咳嗽影响睡眠，二便尚调。\n\n查体：T 36.9℃，P 88次/分，R 20次/分，BP 134/82mmHg，指脉氧饱和度95%（未吸氧）。桶状胸，双肺叩诊过清音，双肺呼吸音粗，可闻及散在干啰音及少量湿性啰音，以右下肺为著，较入院时减少；心率88次/分，律齐；腹软，无压痛，双下肢不肿。舌质淡红，舌体稍胖，边有齿痕，苔白腻较前变薄，脉滑。\n\n辅助检查回报：复查血常规WBC 7.8×10^9/L，N% 66%，超敏C反应蛋白8mg/L；血气分析（未吸氧）：pH 7.39，PaO2 76mmHg，PaCO2 44mmHg，SaO2 94%，提示轻度低氧血症；痰培养未见致病菌生长；心脏彩超示肺动脉收缩压32mmHg，右心不大，左室舒张功能减低。胸片提示双肺纹理增粗，未见实变影。\n\n一、中医辨病辨证分析\n患者老年男性，反复咳嗽咳痰伴气喘3年，每因受凉及冬春之交发作，本次受凉后复发加重1周，症见胸闷如窒、气短喘促、动则尤甚、咳声重浊、痰白黏腻量多而咯吐不爽，当属中医「喘证」之实喘范畴。刻下苔白厚腻较前转为白腻，舌体胖、边有齿痕，脉滑。四诊合参，辨证为痰浊阻肺证。其病机为脾虚不运、聚湿生痰，痰浊内蕴上干于肺，肺气不清、宣降失司，故咳痰量多、胸闷喘促；痰湿中阻，则脘痞食少、口黏不渴、头身困重、大便偏溏。病位在肺，涉及脾，病性为本虚标实而以标实为主。今服药后痰量减少、苔腻渐化、气喘渐平，说明痰浊渐化而肺气渐得宣降，然动则气短、食少便溏仍在，提示脾运未复、生痰之源未绝，故治法当于化痰降逆之中寓健脾化湿之意。\n\n二、中医鉴别诊断\n1.与「肺胀」鉴别：肺胀为多种慢性肺系疾病日久不愈、肺气胀满不能敛降而成，以胸部膨满、憋闷如塞、喘咳日久、心悸浮肿，甚则面色晦暗、唇甲紫绀为主症，病程缠绵、经久难愈，舌多暗紫、脉多沉细或结代。本案虽有桶状胸、双肺叩诊过清音等肺气胀满之征，但无颈静脉怒张、肝颈静脉回流征阳性及下肢浮肿，无唇甲紫绀，心脏彩超右心不大、肺动脉收缩压仅轻度升高，尚未构成肺胀之喘脱、水肿变证，故仍以喘证立论。\n2.与「哮病」鉴别：哮病为发作性痰鸣气喘疾患，起病急骤、缓解亦速，发时喉中哮鸣有声如水鸡声，多与接触过敏原、冷空气相关，缓解期可如常人，舌脉随发作而变而无定象。本案喘促为持续性、进行性、动则加重，双肺以干湿性啰音为主、始终未闻及哮鸣音，且年龄偏大、有长期吸烟史而无过敏史及幼年起病之夙根，与哮病之发作性特征不同。\n3.与「脾虚痰盛、气虚为主之喘」鉴别：若以肺脾气虚为主之喘，当见喘促气短、声低息微、咳痰无力、痰白清稀、自汗乏力、舌淡脉弱，治当补肺健脾、培土生金。本案痰量多而黏腻、苔厚腻、脉滑有力，标实之象突出，虽有食少便溏、面色萎黄少华之脾虚本象，但仍属痰浊壅肺、以实为主，故治先化痰降逆，不可骤进大剂补益，以免闭门留寇、助湿生痰。\n4.与「痰热郁肺」鉴别：痰热郁肺者喘咳气涌、胸中烦热、痰黄稠或夹血丝、口渴喜冷饮、身热有汗、舌红苔黄腻、脉滑数，治以清热化痰、宣肺平喘，方用桑白皮汤加减。本案痰白不黄、身不热、口黏不渴、苔白腻而非黄腻、脉滑而不数，故辨为痰浊（湿痰）阻肺而非痰热郁肺。\n\n三、西医鉴别诊断\n1.与支气管哮喘鉴别：哮喘多在幼年或青年起病，症状呈发作性、昼轻夜重，发作时双肺满布哮鸣音，缓解后体征可完全消失；肺功能呈可逆性气流受限，支气管舒张试验阳性或PEF变异率增大，多有过敏性鼻炎、湿疹等过敏史及家族史。本例肺功能FEV1/FVC 68%、支气管舒张试验阴性，提示气流受限持续存在、不完全可逆，与哮喘不符。\n2.与支气管扩张症鉴别：支气管扩张症以长期反复咳大量脓性痰、间断咯血为特点，查体可闻及固定而持久的局限性湿性啰音（多见于下肺），胸部CT见支气管柱状或囊状扩张、印戒征。本例痰为白色黏痰、无咯血，肺部啰音散在且随治疗减少，胸片及CT未见支气管扩张征象。\n3.与肺结核鉴别：肺结核多有午后低热、盗汗、乏力消瘦、痰中带血等结核中毒症状，好发于上叶尖后段及下叶背段，痰抗酸染色及结核分枝杆菌核酸检查可阳性，血沉增快。本例无发热盗汗及咯血，无结核接触史，胸片未见浸润、空洞及播散灶，痰培养未见致病菌生长，结核依据不足。\n\n四、国内外相关疾病研究进展\n1.《慢性阻塞性肺疾病诊治指南（2021年修订版）》明确：慢阻肺急性加重的治疗以支气管舒张剂（短效β2受体激动剂联合短效抗胆碱能药物）为基础，全身性糖皮质激素可缩短恢复时间、改善肺功能并降低早期复发风险，抗生素仅在存在脓性痰、痰量增多、气促加重等细菌感染证据时使用。本例痰白无脓性改变、降钙素原与血常规正常、痰培养阴性，暂不加用抗生素符合指南推荐。\n2.《慢性阻塞性肺疾病全球倡议（GOLD 2024/2025）报告》强调：急性加重病史是预测未来急性加重风险的最强单一因素，建议对既往有急性加重史者采用长效β2受体激动剂联合长效抗胆碱能药物（LABA＋LAMA）双联吸入维持治疗，并每年接种流感疫苗、按推荐接种肺炎球菌疫苗，可显著减少急性加重次数与住院率。\n3.一项纳入数千例慢阻肺患者的随机对照试验及后续荟萃分析显示：规律的呼吸康复训练（缩唇呼吸、腹式呼吸、呼吸操）可提高6分钟步行距离、改善呼吸困难评分并降低再住院率，且在急性加重出院后早期启动获益更为明显。\n4.国内一项纳入多项随机对照试验的系统评价提示：在常规西药治疗基础上联合健脾化痰类中药（如二陈汤、三子养亲汤、六君子汤加减）治疗慢阻肺急性加重，可提高临床总有效率、改善FEV1及中医证候积分、降低炎症指标水平与复发率，且未见明显不良反应增加。\n\n五、诊疗计划\n1.中医治疗：治法为化痰降逆、宣肺平喘、佐以健脾化湿。继续予二陈汤合三子养亲汤加减，处方：法半夏10g 陈皮10g 茯苓15g 紫苏子10g 白芥子6g 莱菔子10g 厚朴10g 苦杏仁10g 紫菀10g 款冬花10g 焦三仙各10g 炙甘草6g。用法：水煎服，每日一付，分2次温服，早晚饭后半小时各服1次。方解：方中法半夏燥湿化痰、降逆和胃，紫苏子降气消痰、止咳平喘，二者共为君药，直折痰浊壅肺之标实；白芥子温肺利气、豁痰散结，莱菔子消食导滞、降气化痰，助君药化痰平喘并为臣药；陈皮理气燥湿，茯苓健脾渗湿、杜生痰之源，厚朴下气宽中、消胀除满，苦杏仁降气止咳平喘，紫菀、款冬花润肺化痰止咳，焦三仙消食和胃以助脾运，共为佐药；炙甘草化痰止咳、调和诸药，为使药。全方化痰与健脾并施，使痰无再生之源、肺复宣降之职。加减法：痰黏稠难咯者加海蛤粉15g（包煎）、瓜蒌皮15g；胸闷窒甚者加瓜蒌15g、薤白10g；脾虚便溏明显者加炒党参15g、炒白术15g。中医特色治疗继续针刺（肺俞、定喘、膻中、足三里、丰隆）每日1次，中药穴位贴敷（肺俞、膏肓、定喘）每日1次。\n2.西医治疗：氨溴索30mg每日3次口服化痰；多索茶碱0.2g每日2次口服解痉平喘；苯磺酸氨氯地平片5mg每日1次口服控制血压；持续低流量吸氧1～2L/min，吸入用异丙托溴铵溶液雾化吸入；继续暂不加用抗生素，若痰量增多、痰色转黄绿或体温升高，及时复查血常规、超敏C反应蛋白及降钙素原并考虑抗感染治疗；密切监测痰色痰量、体温、呼吸频率及指脉氧饱和度，注意多索茶碱的心率及胃肠道不良反应，避免与喹诺酮类药物同用，复查动脉血气分析评估氧合，必要时复查心脏彩超及肺动脉压。\n3.护理与调摄：饮食宜低盐低脂、清淡易消化，忌生冷、油腻、甜黏及辛辣之品以免助湿生痰，戒烟酒，可佐食山药、薏米、陈皮等健脾化痰之品；起居注意保暖防受凉，避免烟尘及冷空气刺激，痰多时由家属拍背助排；加强呼吸功能锻炼，每日缩唇呼吸、腹式呼吸各2～3次、每次10分钟；情志宜舒畅，避免忧思恼怒伤脾生痰。\n4.医患沟通：已向患者及家属交代病情，说明本次为受凉后慢阻肺急性加重，痰培养阴性、炎症指标不高，目前以化痰平喘及中医辨证治疗为主，方向正确、病情趋向好转；嘱其如有痰量骤增或转为黄绿脓痰、发热、气喘加重不能平卧、口唇发紫、精神萎靡嗜睡等情况立即报告医护人员；告知出院后需坚持戒烟、避风寒、坚持呼吸锻炼，1～2周门诊随访，夏季可行三伏贴冬病夏治，患者及家属表示理解并配合。\n\n执行情况：遵嘱执行。继续原中药方剂口服，针刺及穴位贴敷继续，明日复查血气分析。\n\n医师签名：陈医生","日常病程记录":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者入院第3天，神志清楚，精神好转，诉咳嗽较前减轻，咳痰量较前明显减少（每日约40ml），痰液转稀、较易咯出，胸闷缓解，气喘减轻，平地缓行50米无明显气促，无发热恶寒，无胸痛咯血，食纳增加，脘腹痞满基本消失，夜寐较前好转，二便调。\n\n查体：T 36.6℃，P 84次/分，R 19次/分，BP 130/80mmHg，指脉氧饱和度96%（鼻导管吸氧1L/min）。神志清楚，精神可。桶状胸，双肺叩诊过清音，双肺呼吸音稍粗，可闻及少量干啰音，右下肺湿性啰音较前明显减少；心率84次/分，律齐；腹软，无压痛，双下肢不肿。舌质淡红，舌体稍胖，边有齿痕，苔白腻较前变薄，脉滑。\n\n辅助检查：复查血气分析（吸氧1L/min）：pH 7.40，PaO2 84mmHg，PaCO2 42mmHg，SaO2 96%，低氧血症纠正；复查超敏C反应蛋白6mg/L，较前下降。\n\n四诊合参，本病属中医「喘证（痰浊阻肺）」范畴，患者素体脾虚痰盛，复因受凉诱发，痰浊壅肺、肺失宣降，故见咳痰气喘、胸闷脘痞。经化痰降逆、宣肺平喘之中药汤剂联合化痰解痉西药治疗2天，痰量减少、胸闷气喘减轻、苔腻渐化，治疗有效，辨证准确。继续目前治疗方案，中药原方继进，针刺及穴位贴敷继续；患者舌苔仍腻、脉滑，痰浊未净，原方紫苏子、白芥子用量不变，暂不加减。注意观察痰色痰量变化，警惕痰热转化及继发感染；继续低流量吸氧、翻身拍背助排痰，加强戒烟宣教。已达住院3日，复查胸部CT及痰培养，评估病情及后续治疗。\n\n医师签名：陈医生\n","医患沟通记录":"医患沟通记录\n\n时间：2026年08月15日 15:30\n地点：医生办公室\n参加人员：患者及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为喘证（痰浊阻肺），西医诊断为慢性阻塞性肺疾病急性加重期、高血压病2级，病情尚平稳，需住院进一步检查及治疗。\n2.诊疗方案：完善血常规、炎症指标、血气分析、痰培养、胸部CT、心脏彩超及肺功能等检查；中医辨证论治，予化痰降逆、宣肺平喘之中药汤剂（二陈汤合三子养亲汤加减）口服，配合针刺及穴位贴敷；西医予低流量吸氧、化痰、解痉平喘及控制血压治疗，暂不经验性使用抗生素，视痰培养及炎症指标决定。\n3.可能风险：治疗过程中可能出现病情加重、痰热转化或继发肺部感染、药物不良反应（心悸、手抖、胃肠道不适等），剧烈活动或情绪激动可诱发气喘加重，极少数可进展为呼吸衰竭。\n4.注意事项：绝对戒烟，避免受凉感冒及烟尘刺激，清淡饮食，忌生冷、油腻、甜黏及辛辣之品，注意休息，配合翻身拍背排痰及各项检查治疗，不可自行停药改量。\n5.预后情况：本病为慢性疾病，经积极规范治疗本次急性加重期症状可缓解，但易反复发作，需长期管理、坚持戒烟及肺功能锻炼。\n\n患者及家属表示理解，同意上述诊疗方案，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者\n","出院记录":"出院记录\n\n入院日期：2026年08月15日\n出院日期：2026年08月24日\n住院天数：10天\n\n入院诊断：\n中医诊断：喘证（痰浊阻肺）\n西医诊断：慢性阻塞性肺疾病急性加重期；高血压病2级（中危）\n\n出院诊断：\n中医诊断：喘证（痰浊阻肺）\n西医诊断：慢性阻塞性肺疾病急性加重期（症状缓解）；高血压病2级（中危）\n\n入院情况：\n患者，男，62岁，因「反复咳嗽咳痰伴气喘3年，加重1周」入院。入院时咳声重浊，痰白黏腻量多、咯吐不爽，胸闷如窒，气短喘促、动则尤甚，伴头身困重、脘痞食少、口黏不渴、大便偏溏。查体：T 37.2℃，P 92次/分，R 22次/分，BP 138/84mmHg，桶状胸，双肺叩诊过清音，肺肝界下移，双肺呼吸音粗，可闻及散在干啰音及湿性啰音，以右下肺为著。中医四诊：舌质淡红，舌体稍胖，边有齿痕，苔白厚腻，脉滑。辅助检查：血常规WBC 8.2×10^9/L、N% 68%，超敏C反应蛋白12mg/L，降钙素原0.08ng/ml；血气分析（未吸氧）PaO2 76mmHg；胸部CT示双肺纹理增粗紊乱伴散在斑片状模糊影、以右下肺为著、肺气肿征；肺功能FEV1/FVC 68%，支气管舒张试验阴性；痰培养未见致病菌生长。\n\n诊疗经过：\n入院后完善血常规、炎症指标、血气分析、痰培养及药敏、胸部CT、心脏彩超、心电图及肺功能等检查，明确中医诊断喘证（痰浊阻肺），西医诊断慢性阻塞性肺疾病急性加重期、高血压病2级（中危）。中医治以化痰降逆、宣肺平喘，方用二陈汤合三子养亲汤加减（法半夏10g、陈皮10g、茯苓15g、紫苏子10g、白芥子6g、莱菔子10g、厚朴10g、杏仁10g、炙甘草6g），共服10剂，每日1剂，水煎服，早晚温服；第5天因痰浊渐化、痰量明显减少，去白芥子，加炒白术15g、党参15g以健脾益气、培土生金，随证加减。同时予针刺（肺俞、定喘、膻中、足三里、丰隆）及中药穴位贴敷（肺俞、膏肓、定喘）治疗。西医予持续低流量吸氧（1～2L/min）、氨溴索30mg每日3次口服化痰，多索茶碱0.2g每日2次口服解痉平喘（第6天减为每日1次，第7天停用），苯磺酸氨氯地平片5mg每日1次控制血压；因炎症指标不高、降钙素原正常、痰培养阴性，未经验性使用抗生素。经治患者咳嗽咯痰气喘逐渐减轻，痰量由每日约80～100ml减至15ml以下，复查血常规、超敏C反应蛋白恢复正常，血气分析低氧血症纠正，胸部CT示原右下肺斑片状模糊影大部分吸收，病情稳定，经上级医师同意准予出院。\n\n出院情况：\n患者神志清楚，精神好，无咳嗽或仅有晨起单声咳嗽，咳痰量少色白易咯，胸闷气喘消失，可缓步行走500米无气促，无发热，食纳可，二便调，夜寐安。查体：T 36.4℃，P 76次/分，R 18次/分，BP 126/78mmHg，指脉氧饱和度97%（未吸氧）；桶状胸，双肺叩诊过清音，双肺呼吸音稍粗，未闻及明显干湿性啰音；心率76次/分，律齐；腹软，无压痛，双下肢不肿。舌质淡红，苔薄白，脉滑缓。\n\n出院诊断：中医诊断：喘证（痰浊阻肺）；西医诊断：慢性阻塞性肺疾病急性加重期（症状缓解），高血压病2级（中危）。\n\n出院医嘱：\n1.饮食：低盐低脂清淡饮食，忌生冷、油腻、甜黏及辛辣之品，以免助湿生痰；戒烟酒。\n2.休息与活动：注意休息，避免劳累及受凉感冒，避免烟尘、冷空气及异味刺激；坚持腹式呼吸、缩唇呼吸及呼吸操锻炼，每日2次，每次15分钟，循序渐进。\n3.用药：出院带药中药汤剂7剂，方用六君子汤加减（党参15g、炒白术15g、茯苓15g、陈皮10g、法半夏10g、紫苏子10g、杏仁10g、炙甘草6g），益肺健脾、化痰止咳，以巩固疗效、减少复发；煎服法：冷水浸泡30分钟，武火煮沸后文火煎30分钟，二煎取汁，两煎混匀分早晚2次温服，每日1剂。苯磺酸氨氯地平片5mg每日1次口服，监测血压。如出现痰量增多、痰色转黄、发热或气喘加重，及时就诊，不可自行停药改量。\n4.复查：出院后1～2周门诊复查血常规、超敏C反应蛋白、血气分析及肺功能，此后每3～6个月复查肺功能1次；建议每年接种流感疫苗及肺炎疫苗。\n5.注意事项：绝对戒烟，家庭氧疗指征依血气分析结果由医师决定，不可自行长期高流量吸氧；缓解期可于三伏天行穴位贴敷（冬病夏治），减少急性发作次数。如出现呼吸困难加重、口唇紫绀、意识改变，立即急诊就诊。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：慢性阻塞性肺疾病急性加重（J44.100） 入院病情：有\n其他诊断（名称+ICD-10编码）：高血压病2级（I10.x00）；中医诊断：喘证（痰浊阻肺）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","病程记录第3天":"病程记录\n\n2026年08月17日 09:00（入院第3天）\n\n患者入院第3天，神志清楚，精神好转，诉咳嗽较前减轻，咳痰量较前明显减少（每日约40ml），痰液转稀、较易咯出，胸闷缓解，气喘减轻，平地缓行50米无明显气促，无发热恶寒，无胸痛咯血，食纳增加，脘腹痞满基本消失，夜寐较前好转，二便调。\n\n查体：T 36.6℃，P 84次/分，R 19次/分，BP 130/80mmHg，指脉氧饱和度96%（鼻导管吸氧1L/min）。神志清楚，精神可。桶状胸，双肺叩诊过清音，双肺呼吸音稍粗，可闻及少量干啰音，右下肺湿性啰音较前明显减少；心率84次/分，律齐；腹软，无压痛，双下肢不肿。舌质淡红，舌体稍胖，边有齿痕，苔白腻较前变薄，脉滑。\n\n辅助检查：复查血气分析（吸氧1L/min）：pH 7.40，PaO2 84mmHg，PaCO2 42mmHg，SaO2 96%，低氧血症纠正；复查超敏C反应蛋白6mg/L，较前下降。\n\n四诊合参，本病属中医「喘证（痰浊阻肺）」范畴，患者素体脾虚痰盛，复因受凉诱发，痰浊壅肺、肺失宣降，故见咳痰气喘、胸闷脘痞。经化痰降逆、宣肺平喘之中药汤剂联合化痰解痉西药治疗2天，痰量减少、胸闷气喘减轻、苔腻渐化，治疗有效，辨证准确。继续目前治疗方案，中药原方继进，针刺及穴位贴敷继续；患者舌苔仍腻、脉滑，痰浊未净，原方紫苏子、白芥子用量不变，暂不加减。注意观察痰色痰量变化，警惕痰热转化及继发感染；继续低流量吸氧、翻身拍背助排痰，加强戒烟宣教。已达住院3日，复查胸部CT及痰培养，评估病情及后续治疗。\n\n医师签名：陈医生\n","病程记录第5天":"病程记录\n\n2026年08月19日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好，诉咳嗽明显减轻，偶有单声咳嗽，咳痰量少（每日约15ml），痰白易咯，胸闷消失，气喘基本缓解，可平地缓行200米无明显气促，无发热恶寒，无胸痛咯血，食纳可，脘腹无痞满，夜寐安，二便调。\n\n查体：T 36.5℃，P 80次/分，R 18次/分，BP 128/78mmHg，指脉氧饱和度97%（未吸氧）。神志清楚，精神好。桶状胸，双肺叩诊过清音，双肺呼吸音稍粗，散在干啰音基本消失，右下肺未闻及明显湿性啰音；心率80次/分，律齐；腹软，无压痛，双下肢不肿。舌质淡红，边齿痕减轻，苔薄白微腻，脉滑缓。\n\n辅助检查：复查血常规WBC 6.9×10^9/L，N% 62%，超敏C反应蛋白4mg/L，均恢复正常；复查血气分析（未吸氧）：pH 7.40，PaO2 82mmHg，PaCO2 41mmHg，SaO2 96%；胸部CT示双肺纹理增粗，原右下肺斑片状模糊影大部分吸收，肺气肿征同前。\n\n患者经化痰降逆、宣肺平喘中药汤剂（二陈汤合三子养亲汤加减）5剂，配合化痰解痉西药、低流量吸氧及针刺、穴位贴敷治疗，痰浊渐化，肺气宣降得复，咳嗽咯痰气喘明显好转，苔腻已化，脉滑渐缓，治疗显效。中药已服完5剂，今日依舌脉调整处方：痰浊已减，去白芥子，加炒白术15g、党参15g以健脾益气、培土生金，续开5剂，煎服法同前，每日1剂，早晚温服。西药继续氨溴索化痰，多索茶碱减为0.2g每日1次口服，拟明日停用；继续低流量吸氧，血压控制平稳，继续苯磺酸氨氯地平片5mg每日1次。注意观察病情反复，避免受凉，继续戒烟及呼吸功能锻炼，巩固疗效，防止复发。\n\n医师签名：陈医生\n","主任医师查房记录":"主任查房记录\n\n2026年08月21日 10:00（入院第7天）\n\n今日李副主任医师查房，先由主管医师汇报病史及诊疗经过。患者目前神志清楚，精神好，无咳嗽或仅有晨起单声咳嗽，咳痰量少色白、易咯，胸闷气喘消失，可自行下床活动及缓步行走500米无气促，无发热，食纳可，二便调，夜寐安。\n\n查体：T 36.4℃，P 76次/分，R 18次/分，BP 126/78mmHg，指脉氧饱和度97%（未吸氧）。桶状胸，双肺叩诊过清音，双肺呼吸音稍粗，未闻及明显干湿性啰音；心率76次/分，律齐，心音稍遥远；腹软，无压痛，双下肢不肿。舌质淡红，苔薄白，脉滑缓。\n\n一、中医辨病辨证分析\n患者老年男性，慢性咳嗽咳痰气喘3年，反复发作、冬春加重，有长期吸烟史。入院时痰白黏腻量多、胸闷如窒、脘痞食少、头身困重、口黏不渴、大便偏溏，舌质淡红、舌体胖、边有齿痕、苔白厚腻、脉滑，四诊合参辨为喘证之痰浊阻肺证，系脾虚不运、聚湿生痰，痰浊上干于肺、肺失宣降所致，病位在肺，涉及脾，为本虚标实而以标实为主。经化痰降逆、宣肺平喘并佐健脾化湿治疗七日，今痰少易咯、喘平能行、苔厚腻已化为薄白，脉由滑转滑缓而数象已除，说明痰浊已化、肺气已降；然仍见舌体胖大、边有齿痕、脉缓而滑，动后偶有气短，提示脾运未健、肺气未充之本虚尚存，证候已由急性期痰浊壅肺之标实为主，转为缓解期肺脾气虚、痰湿未尽之本虚为主，辨证要点再确认：仍属喘证，证由痰浊阻肺转为肺脾气虚兼痰湿内蕴，治当由化痰降逆转为补肺健脾、化痰兼施，合「急则治其标、缓则治其本」之旨。\n\n二、中医鉴别诊断\n1.与「肺胀」鉴别再确认：肺胀以胸膺膨满、憋闷如塞、喘咳上气、心悸、面唇紫绀、肢肿为主，甚则出现神蒙、喘脱等变证，舌暗、脉沉细数或结代，多为不可逆之进行性加重。本案入院时虽有桶状胸及肺气肿征，但始终无颈静脉怒张、肝颈静脉回流征阳性、下肢浮肿及唇甲紫绀，心脏彩超右心不大、肺动脉收缩压仅32mmHg，且经治后喘平、苔化、食增，病情明显可逆，故不属肺胀，而以喘证（痰浊阻肺）为诊断更为贴切。\n2.与「哮病」鉴别再确认：哮病必有宿根，呈发作性，发则喉中哮鸣、呼吸急促、甚则不能平卧，移时缓解，缓解期一如常人，舌脉随发作而变。本案病程3年、逐年加重、冬春必发而以受凉为诱因，喘促呈持续性、活动后加重，全程未闻及哮鸣音，肺功能示持续气流受限且舒张试验阴性，与哮病之发作性、可逆性特点不符。\n3.与「脾气虚之短气」鉴别：单纯脾气虚者以少气懒言、倦怠乏力、食少便溏、舌淡脉弱为主，无咳痰喘促及肺部啰音。本案缓解期虽有食少便溏、面色萎黄少华之脾虚本象，但仍以咳痰、苔腻、脉滑之痰湿留滞为特征，属本虚标实之候，不可纯补，宜健脾与化痰并行，方不致助湿生痰。\n4.与「痰热壅肺」鉴别：痰热壅肺者痰黄黏稠、身热面赤、口渴喜冷饮、舌红苔黄腻、脉滑数，治当清热化痰。本案全程痰白、身不热、口不渴、苔白不黄、脉滑不数，痰液性状与舌脉均不支持痰热，故始终以痰浊（湿痰）立法，未用苦寒清热之品。\n\n三、西医疑难分析与鉴别\n结合病史、体征、肺功能（FEV1/FVC 68%，支气管舒张试验阴性）、胸部CT（肺气肿征）及血气分析结果，慢性阻塞性肺疾病急性加重期（GOLD 2级，急性加重高风险E组）诊断明确，肺炎、气胸、胸腔积液及肺栓塞依据不足，心功能不全之BNP及心脏彩超亦不支持心源性哮喘；抗感染指征把握恰当、未滥用抗生素，符合规范。目前患者炎症指标正常、血气改善、症状缓解，下一步重点是出院前的疗效评估与长期管理，防止反复急性加重及肺功能进一步下降。\n\n四、国内外相关疾病研究进展\n1.《慢性阻塞性肺疾病全球倡议（GOLD 2024/2025）报告》将急性加重史与症状负荷（mMRC、CAT评分）作为综合评估的核心，建议对高风险（E组）患者起始即采用LABA＋LAMA双联长效吸入治疗，对反复急性加重且血嗜酸粒细胞增高者可加用吸入性糖皮质激素，并强调戒烟、疫苗接种与呼吸康复是降低急性加重风险的基石措施。\n2.《中国慢性阻塞性肺疾病诊治指南》与相关专家共识提出：稳定期应长期规律吸入维持治疗、定期复查肺功能与CAT评分，规范的家庭长期氧疗（每日≥15小时）可改善合并慢性呼吸衰竭患者的生存率，但需严格掌握指征；同时推荐每年流感疫苗及肺炎球菌疫苗接种。\n3.一项纳入数千例慢阻肺稳定期患者的多中心随机对照试验及系统评价显示：规律呼吸康复训练可使6分钟步行距离平均提高30～50米，并降低急性加重后再住院率，出院后4周内启动康复获益最大。\n4.国内一项纳入多项随机对照试验的系统评价提示：在西医常规治疗基础上联合补肺健脾化痰类中药（如六君子汤、补肺汤加减）长期调理，可减少慢阻肺急性发作次数、改善生活质量与中医证候积分；三伏穴位贴敷（冬病夏治）亦可降低冬春急性加重频率。\n\n五、诊疗计划\n1.中医治疗：治法调整为补肺健脾、化痰平喘，标本兼顾。方选二陈汤合三子养亲汤合四君子汤加减，处方：党参15g 炒白术15g 茯苓15g 法半夏10g 陈皮10g 紫苏子10g 莱菔子10g 苦杏仁10g 紫菀10g 款冬花10g 丹参15g 炙甘草6g。用法：水煎服，每日一付，分2次温服。方解：方中党参补益肺脾之气、炒白术健脾燥湿，同为君药，取培土生金、绝痰之源之意；茯苓健脾渗湿，法半夏燥湿化痰、降逆和胃，紫苏子降气化痰、止咳平喘，三药为臣，标本同治；陈皮理气化痰使补而不滞，莱菔子降气消食，苦杏仁降气止咳平喘，紫菀、款冬花润肺化痰止咳，丹参活血通络以除久病入络之瘀滞，共为佐药；炙甘草益气和中、调和诸药，为使药。全方补虚而不敛邪、化痰而不伤正，缓则治本。出院后可改六君子汤加减或丸剂长期调理，夏季行三伏贴冬病夏治。\n2.西医治疗：停用多索茶碱，继续氨溴索30mg每日3次口服化痰；苯磺酸氨氯地平片5mg每日1次口服控制血压；按血气分析结果决定家庭氧疗指征，指脉氧饱和度持续低于88%者建议长期家庭氧疗（每日≥15小时，1～2L/min）；出院前复查血常规、超敏C反应蛋白、动脉血气分析及肺功能，明确气流受限程度与分级，据GOLD分组制定长期吸入方案。用药期间注意监测心率、血压及电解质，避免茶碱类与喹诺酮类联用。\n3.护理与调摄：饮食宜清淡易消化、富有营养，忌生冷油腻甜黏及辛辣，戒烟酒；起居避风寒、防外感，室内保持适宜温湿度；坚持缩唇呼吸、腹式呼吸及呼吸操锻炼，循序渐进增加步行距离；情志舒畅，避免忧思恼怒；每年流感疫苗及肺炎球菌疫苗接种。\n4.医患沟通：已向患者及家属说明本次为慢阻肺急性加重经中西医结合治疗后缓解，痰浊渐化、肺脾之气未复，出院后仍须长期调理、防止复发；交代坚持戒烟、避免受凉及烟尘刺激、规范用药、定期复查肺功能的重要性，嘱1～2周中医门诊复查并继续中药调理，如出现痰量骤增或转黄、发热、气喘加重、口唇发紫等立即就诊；患者及家属表示理解并同意近日出院。\n\n执行情况：遵嘱执行。继续中药汤剂及低流量吸氧，停多索茶碱，复查血常规、超敏C反应蛋白、血气分析及肺功能，完善肺功能分级评估，拟于近日出院并制定随访计划。\n\n医师签名：陈医生"},"icd10_diagnosis":"J44.100","icd10_secondary":["I10.x00"],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1229,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5cec0a773e924160cccf18e0661d41623dd91d0070bb4a14d3c9207800b3f52f","pinyin":"chuanzheng（tanzhuozufei）","initials":"cz（tzzf）","setting":"in","caseName":"病例1：患者，男，62岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，62岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","J44.100",30]]},{"id":"templates-ac294cb1ec16fe961626","key":"v1-c9ccc21dfe2a3058|templates-ac294cb1ec16fe961626","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喘证（肺气虚耗）","category":"中医科","raw":{"name":"喘证（肺气虚耗）","category":"中医科","case":{"case_name":"病例1：患者，男，68岁","templates":{"入院记录":"入院记录\n\n姓名：【已脱敏】 性别：男 年龄：68岁 民族：汉族\n婚姻：已婚 职业：退休工人 籍贯：本地\n入院时间：2026年08月10日 10:00 记录时间：2026年08月10日 11:30\n病史陈述者：患者本人，可靠\n\n主诉：反复咳喘7年，加重伴气短乏力1周。\n\n现病史：患者于7年前因受凉后出现咳嗽、咳痰，每遇冬春季节及气候骤变则发作，逐年加重，曾在当地医院诊断为「慢性支气管炎、慢性阻塞性肺疾病」，间断口服氨茶碱、羧甲司坦等药物，症状可缓解，但反复发作，体力逐年下降。1周前因天气转凉、外出受风后症状再次加重，起病较缓，呈进行性加重，主要表现为：气喘，动则喘甚，稍事活动（如穿衣、如厕、步行十余米）即感气短不足以息，需坐下休息片刻方能缓解；咳声低弱无力，咳痰量少而稀白，咳吐无力，痰不易咯出；语声低怯，懒言少动，精神倦怠，自汗畏风，平时极易感冒，近1年感冒6～7次，每次均需数日方愈；时有胸闷，无胸痛；无发热，无恶寒；无夜间阵发性呼吸困难及端坐呼吸。病程中上述症状时轻时重，劳累及受风后加重，静息休息后可部分缓解，总体呈逐渐加重趋势。曾在院外自服「氨茶碱片、复方甘草片」（剂量不详），症状缓解不明显，为求进一步系统诊治，今日来我院门诊就诊，门诊查胸部CT提示双肺透亮度增高、肺纹理增粗紊乱，门诊以「喘证（肺气虚耗）」收入我科。发病以来精神倦怠，食欲欠佳，饮食量较前减少，睡眠尚可，夜尿2～3次，大便偏溏、每日1～2次，小便正常。近1年体重下降约2公斤。\n\n既往史：既往有慢性支气管炎、慢性阻塞性肺疾病病史7年，间断用药。否认高血压、糖尿病、冠心病病史。否认肝炎、结核等传染病史。否认手术、外伤史，否认输血史。否认食物、药物过敏史。预防接种史随当地。\n\n个人史及家族史：生于本地，久居本地，无疫区及疫水接触史。吸烟40年，每日约20支，近3年已减少至每日5～6支；偶饮酒，量少。从事机械加工工作，已退休，无粉尘及有害气体长期接触史。家族中否认哮喘、肺结核及类似疾病史。\n婚育史：26岁结婚，配偶体健，育有1子1女，子女均体健。\n\n体格检查：\nT 36.6℃，P 88次/分，R 22次/分，BP 126/76mmHg。\n一般情况：神志清楚，精神倦怠，语声低怯，自主体位，查体合作。\n\n中医四诊：\n望诊：神志清楚，精神倦怠，面色淡白少华，形体偏瘦，口唇色淡，舌质淡，舌体偏胖，边有齿痕，苔薄白。\n闻诊：语声低怯无力，懒言，气息短促，咳声低微，痰少稀白，无明显异常气味。\n问诊：气喘，动则喘甚，气短不足以息，咳声低弱，痰少稀白，自汗畏风，易感冒，神疲乏力，纳差，夜尿频，大便偏溏。\n切诊：脉细弱，以右寸、双尺为著，重按无力；肌肤湿润，四肢欠温。\n\n一般情况：神志清楚，精神反应可，营养中等偏下，发育正常，查体合作。\n皮肤黏膜：全身皮肤黏膜无黄染、皮疹及出血点，弹性可，无紫绀。\n淋巴结：全身浅表淋巴结未触及肿大。\n颈部：柔软，无抵抗，气管居中，甲状腺未触及肿大，颈静脉无怒张。\n胸部：胸廓前后径增大，呈轻度桶状胸，肋间隙稍增宽，双侧呼吸动度减弱、对称，语颤减弱，双肺叩诊呈过清音，肺下界下移，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音。心率88次/分，律齐，各瓣膜听诊区未闻及病理性杂音。\n腹部：平软，无压痛、反跳痛，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常。\n脊柱四肢：脊柱生理弯曲存在，无畸形。四肢无畸形，关节无肿胀，活动正常，双下肢无水肿，无杵状指。\n神经系统：神志清楚，肌张力正常，病理征阴性。\n专科情况：\n望诊：神志清楚，精神倦怠，面色淡白，口唇色淡，呼吸略促，动则喘甚；舌象：舌质淡，舌体偏胖，边有齿痕，苔薄白。闻诊：语声低怯，咳声低微无力，气息短促。切诊：脉细弱，重按无力。专科查体：胸廓呈轻度桶状胸，双肺呼吸动度减弱，叩诊过清音，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音。关键阴性体征：无发热及寒战，无咯血及咯大量脓痰，无胸痛，无夜间阵发性呼吸困难及端坐呼吸，无颈静脉怒张，无肝颈静脉回流征阳性，双下肢无水肿。\n\n辅助检查：\n门诊血常规：WBC 7.8×10^9/L，N% 63%，RBC 4.05×10^12/L，Hb 116g/L，PLT 218×10^9/L。\n门诊胸部CT：双肺透亮度增高，肺纹理增粗、紊乱，双肺见散在条索状影，纵隔内未见肿大淋巴结，双侧胸腔未见积液。\n门诊肺功能：FEV1占预计值52%，FEV1/FVC 58%，支气管舒张试验阴性。\n门诊心电图：窦性心律，正常心电图。\n\n初步诊断：\n中医诊断：喘证（肺气虚耗）\n中医诊断依据：\n1.辨病依据：患者反复咳喘7年，本次加重1周，以气喘、动则喘甚、稍事活动即气短不足以息、咳声低弱、痰少稀白为主症，符合喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"之辨病要点；其喘以气短难续、深吸为快、动则加重为特点，属喘证之虚喘。\n2.辨证依据：气喘，动则喘甚，气短不足以息，咳声低弱、咯吐无力，痰少稀白，语声低怯、懒言少动，神疲乏力，自汗畏风，平素极易感冒（近1年感冒6～7次），纳差，夜尿频，大便偏溏；舌质淡，舌体偏胖，边有齿痕，苔薄白，脉细弱、右寸及双尺尤甚、重按无力。此为久病咳喘、肺气亏虚，气失所主、卫外不固之候，四诊合参，辨证为肺气虚耗证，病位在肺、与脾肾相关，病性属虚，以气虚为主，无明显实邪。治以补肺益气、敛肺止咳，方用补肺汤合玉屏风散加减。\n中医鉴别诊断：\n1.与「哮病」鉴别：哮病以发作性喉中哮鸣有声、呼吸气促困难、甚则喘息不能平卧为特征，多有过敏史或家族史，发作与缓解均较迅速，缓解期如常人；喘证以呼吸困难，甚至张口抬肩、鼻翼扇动、不能平卧为特征，可见于多种急慢性疾病过程中，多呈持续性、进行性加重。本例以动则喘甚、气短乏力、咳声低微为主，无喉中痰鸣如水鸡声之典型发作，故诊为喘证而非哮病。\n2.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证，但一般无喘促之象、无动则喘甚之候；本例气喘动则尤甚、静息亦觉气不接续，喘促之象显著，故属喘证之虚喘，而非单纯气短。\n3.与「肺胀」鉴别：肺胀由多种慢性肺系疾患反复发作、迁延不愈发展而成，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、肢体浮肿，其喘为持续性并为原发病的组成部分；本例虽有轻度桶状胸及肺气肿征，但无唇甲紫绀、无颈静脉怒张、无肝颈静脉回流征阳性、双下肢无水肿，无心悸浮肿之候，故以喘证（肺气虚耗）为诊断。\n4.与「肺阴亏耗」鉴别：肺阴亏耗者喘促气短、呛咳痰少质黏、烦热口干、咽喉不利、面颧潮红、舌红少苔或苔剥、脉细数，治以养阴清热、润肺止咳，方用沙参麦冬汤加减；本例无潮热颧红、无舌红少苔，而见自汗畏风、舌淡胖有齿痕、痰少稀白，故辨为肺气虚耗而非肺阴亏耗。\n西医诊断：慢性阻塞性肺疾病急性加重期；轻度贫血\n西医诊断依据：\n1.病史依据：反复咳嗽、咳痰、气喘7年，每遇冬春季节及气候骤变发作，逐年加重，有长期吸烟史40年（近3年减至每日5～6支），曾在当地医院诊断为慢性支气管炎、慢性阻塞性肺疾病。\n2.症状依据：近1周气喘加重，动则喘甚，稍事活动（穿衣、如厕、步行十余米）即感气短不足以息，咳嗽、咳少量稀白痰且咯吐无力，伴神疲乏力、自汗畏风、纳差、夜尿频。\n3.体征依据：T 36.6℃，P 88次/分，R 22次/分，BP 126/76mmHg；精神倦怠，语声低怯；轻度桶状胸，肋间隙稍增宽，双侧呼吸动度减弱、对称，语颤减弱，双肺叩诊呈过清音、肺下界下移，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音；双下肢无水肿，无杵状指。\n4.实验室及影像依据：肺功能FEV1占预计值52%、FEV1/FVC 58%，支气管舒张试验阴性，符合持续气流受限；胸部CT示双肺透亮度增高、肺纹理增粗紊乱并见散在条索状影，纵隔内未见肿大淋巴结，双侧胸腔未见积液，符合肺气肿及慢性炎症改变；血常规WBC 7.8×10^9/L、N% 63%正常，Hb 116g/L、RBC 4.05×10^12/L提示轻度贫血；心电图窦性心律、正常心电图，无右心室肥厚表现。\n西医分型/分级/分期：1.慢性阻塞性肺疾病急性加重期（本次受凉后气喘、气短、咳嗽较平时加重，属急性加重）；气流受限程度按GOLD分级属GOLD 2级（中度气流受限：FEV1占预计值50%～79%，本例52%，接近GOLD 3级下限），支气管舒张试验阴性提示气流受限持续存在、不完全可逆；按GOLD综合评估属急性加重高风险组（E组）倾向，须规范吸入治疗并加强随访。2.呼吸功能状态：本次未查动脉血气，无呼吸衰竭证据；如PaO2<60mmHg且PaCO2>50mmHg则为Ⅱ型呼吸衰竭，PaO2<60mmHg而PaCO2正常或降低则为Ⅰ型呼吸衰竭，须动态监测。3.轻度贫血：Hb 116g/L，按贫血严重度分级属轻度（血红蛋白>90g/L但低于正常下限；中度90～60g/L；重度60～30g/L；极重度<30g/L），结合慢性病及营养不良背景，考虑慢性病性贫血可能，待复查铁代谢、维生素B12及叶酸明确病因。4.营养状态：近1年体重下降约2kg，营养中等偏下，提示存在营养不良风险，须行营养评估与干预。\n诊疗计划：\n1.按内科Ⅲ级护理，普通饮食，卧床休息，避免受凉及劳累；2.完善检查：血常规+C反应蛋白（目的：明确有无感染及炎症状态，为是否抗感染治疗提供依据）、动脉血气分析（目的：评估缺氧及二氧化碳潴留程度，为氧疗及呼吸支持提供依据）、肝肾功能+电解质（目的：评估营养代谢与药物安全性，为补益类中药及西药调整提供依据）、心电图+心脏彩超（目的：评估心功能与肺动脉压力，排除心源性喘息）、肺功能复查（目的：客观评估肺通气功能改善情况，为康复与长期治疗提供依据）、胸部CT（目的：明确肺部基础病变及有无新发感染，评估疗效）；3.一般治疗：持续低流量吸氧（1～2L/min，每日15小时以上）、呼吸功能锻炼（缩唇呼吸、腹式呼吸）、避风寒、戒烟；4.药物治疗：补肺益气、敛肺止咳中药汤剂（补肺汤合玉屏风散加减），氨茶碱0.1g每日3次口服，羧甲司坦0.5g每日3次口服，必要时予布地奈德福莫特罗粉吸入剂吸入；5.病情观察：密切观察气喘、气短及咳嗽咳痰变化，监测呼吸、心率及血氧饱和度，注意有无呼吸衰竭及右心功能不全表现；6.健康教育：指导戒烟、腹式呼吸及缩唇呼吸训练、耐寒锻炼、饮食调养，必要时请呼吸科会诊。\n\n专科检查：\n望诊：神志清楚，精神倦怠，面色淡白，口唇色淡，呼吸略促；舌质淡，舌体偏胖，边有齿痕，苔薄白。闻诊：语声低怯，咳声低微无力。切诊：脉细弱，重按无力。查体：轻度桶状胸，双肺呼吸动度减弱，叩诊过清音，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音。\n\n医师签名：陈医生","首次病程记录":"首次病程记录\n\n2026年08月10日 14:00\n\n病例特点：\n1.患者，男，68岁，因「反复咳喘7年，加重伴气短乏力1周」入院。\n2.既往史：慢性支气管炎、慢性阻塞性肺疾病病史7年；吸烟40年，目前每日5～6支。\n3.症状特点：气喘，动则喘甚，稍事活动即气短不足以息；咳声低弱，痰少稀白、咯吐无力；语声低怯，神疲乏力，自汗畏风，易感冒，纳差，夜尿频，大便偏溏。\n4.体格检查：T 36.6℃，P 88次/分，R 22次/分，BP 126/76mmHg；轻度桶状胸，双肺呼吸动度减弱，叩诊过清音，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音；双下肢无水肿。\n5.中医四诊：面色淡白少华，舌质淡，舌体偏胖，边有齿痕，苔薄白；语声低怯无力，气息短促；脉细弱，右寸及双尺为著，重按无力。\n6.辅助检查：血常规WBC 7.8×10^9/L，Hb 116g/L；胸部CT示双肺透亮度增高、肺纹理增粗紊乱；肺功能FEV1占预计值52%，FEV1/FVC 58%，支气管舒张试验阴性；心电图正常。\n\n拟诊讨论：\n（一）初步诊断：\n中医诊断：喘证（肺气虚耗）\n西医诊断：慢性阻塞性肺疾病急性加重期；轻度贫血\n\n（二）中医诊断依据：\n1.辨病依据：患者反复咳喘7年，本次加重1周，以气喘、动则喘甚、稍事活动即气短不足以息、咳声低弱、痰少稀白为主症，符合喘证\"以呼吸困难，甚至张口抬肩、鼻翼煽动、不能平卧为临床特征\"之辨病要点；其喘以气短难续、深吸为快、动则加重为特点，属喘证之虚喘。\n2.症状依据：气喘，动则喘甚，气短不足以息，咳声低弱，痰少稀白而咯吐无力，语声低怯，神疲乏力，自汗畏风，平素易于感冒，纳差，夜尿频，大便偏溏。\n3.舌脉依据：舌质淡，舌体偏胖，边有齿痕，苔薄白；脉细弱，右寸及双尺尤甚，重按无力，属肺气亏虚、卫外不固之象。\n4.病因病机：患者年近七旬，久病咳喘，肺气先伤，肺主气、司呼吸，肺气虚耗则气无所主，故气喘气短、动则喘甚；肺气不足，宗气亦虚，故语声低怯、咳声低微无力；肺虚不能输布津液，聚而为痰，且气虚无力咳痰，故痰少稀白而咯吐不爽；肺主皮毛、卫气不固，故自汗畏风、易于感冒；肺虚不能助脾运化，脾肺气虚，故纳差、大便偏溏；肺为气之主、肾为气之根，久病及肾，肾不纳气、膀胱失约，故动则喘甚、夜尿频多。四诊合参，本病属中医「喘证」范畴，辨证为「肺气虚耗」证，病位在肺，与脾、肾相关，病性属虚，以气虚为主，无明显实邪。\n5.依据《中医内科学》喘证「肺气虚耗」证候：喘促短气，气怯声低，喉有鼾声，咳声低弱，痰吐稀薄，自汗畏风，或呛咳痰少质黏，烦热口干，咽喉不利，面颧潮红，舌质淡红或舌红苔剥，脉软弱或细数——治以补肺益气养阴，方用生脉散合补肺汤加减。本例以喘促短气、气怯声低、咳声低弱、痰吐稀薄、自汗畏风、舌淡胖有齿痕、脉细弱为主症，无潮热颧红、舌红少苔等肺阴虚之象，故辨为肺气虚耗之偏于气虚者，治以补肺益气、敛肺止咳，方选补肺汤合玉屏风散加减。\n\n（三）中医鉴别诊断：\n1.与「哮病」鉴别：哮病以发作性喉中哮鸣有声、呼吸气促困难、甚则喘息不能平卧为特征，多有过敏史或家族史，发作与缓解均较迅速，缓解期如常人；喘证以呼吸困难，甚至张口抬肩、鼻翼扇动、不能平卧为特征，可见于多种急慢性疾病过程中，多呈持续性、进行性加重。本例以动则喘甚、气短乏力、咳声低微为主，无喉中痰鸣如水鸡声之典型发作，故诊为喘证而非哮病。\n2.与「气短」鉴别：气短即少气，为呼吸微弱、短气不足以息、言语无力，多由气虚所致，属虚证，但一般无喘促之象、无动则喘甚之候；本例气喘动则尤甚、静息亦觉气不接续，喘促之象显著，故属喘证之虚喘，而非单纯气短。\n3.与「肺胀」鉴别：肺胀由多种慢性肺系疾患反复发作、迁延不愈发展而成，症见胸部膨满、憋闷如塞、喘息气促、咳嗽痰多，常伴唇甲紫绀、心悸、肢体浮肿，其喘为持续性并为原发病的组成部分；本例虽有轻度桶状胸及肺气肿征，但无唇甲紫绀、无颈静脉怒张、无肝颈静脉回流征阳性、双下肢无水肿，无心悸浮肿之候，故以喘证（肺气虚耗）为诊断。\n4.与「肺阴亏耗」鉴别：肺阴亏耗者喘促气短、呛咳痰少质黏、烦热口干、咽喉不利、面颧潮红、舌红少苔或苔剥、脉细数，治以养阴清热、润肺止咳，方用沙参麦冬汤加减；本例无潮热颧红、无舌红少苔，而见自汗畏风、舌淡胖有齿痕、痰少稀白，故辨为肺气虚耗而非肺阴亏耗。\n5.与「肾虚不纳」鉴别：肾虚不纳者喘促日久、动则喘甚、呼多吸少、气不得续，形瘦神惫，偏阳虚者汗出肢冷、面青唇紫、舌淡苔白、脉微细或沉弱，偏阴虚者颧红烦热、舌红少津、脉细数；本例虽动则喘甚、夜尿频多，但无呼多吸少、气不得续之肾不纳气典型表现，亦无跗肿及面青唇紫，而以气怯声低、自汗畏风、咳声低弱之肺气虚证为主，故辨为肺气虚耗。\n来源：《中医内科学》（中国中医药出版社「十四五」规划教材）·肺系病证·喘证。提示：若出现喘促持续加重、神志改变、口唇紫绀、呼吸浅弱或痰量骤增色黄，须警惕呼吸衰竭，立即复查血气并急诊处理。\n\n（四）西医诊断依据：\n1.病史依据：反复咳嗽、咳痰、气喘7年，每遇冬春及气候骤变发作，逐年加重，有长期吸烟史40年。\n2.症状依据：近1周气喘加重，动则喘甚，稍事活动即感气短，咳嗽，咳少量稀白痰。\n3.体征依据：轻度桶状胸，双侧呼吸动度减弱，叩诊过清音，肺下界下移，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音。\n4.辅助检查依据：肺功能示FEV1占预计值52%、FEV1/FVC 58%，支气管舒张试验阴性，符合持续气流受限；胸部CT示双肺透亮度增高、肺纹理增粗紊乱，符合肺气肿改变；血常规WBC及中性粒细胞比例正常，C反应蛋白待查，暂不支持细菌感染，但不除外急性加重。\n\n（五）西医分型/分级/分期：\n1.慢性阻塞性肺疾病急性加重期：本次近1周气喘、气短较平时加重、咳嗽咳痰增多，属急性加重；气流受限程度按GOLD分级属GOLD 2级（中度气流受限：FEV1占预计值50%～79%，本例52%，接近GOLD 3级下限），支气管舒张试验阴性提示气流受限持续存在、不完全可逆；按GOLD综合评估（症状+急性加重风险），患者症状持续、活动耐力明显下降，倾向急性加重高风险组（E组），长期分组待CAT评分及近1年急性加重次数确定后判定（A组：低风险少症状；B组：低风险多症状；E组：高风险）。胸部CT示双肺透亮度增高、肺纹理增粗紊乱并散在条索状影，符合肺气肿及慢性炎症改变。\n2.呼吸功能状态：本次未查动脉血气，无呼吸衰竭证据；如PaO2<60mmHg且PaCO2>50mmHg则为Ⅱ型呼吸衰竭，PaO2<60mmHg而PaCO2正常或降低则为Ⅰ型呼吸衰竭；按PaO2分度：轻度60～80mmHg、中度40～59mmHg、重度<40mmHg，须动态监测。\n3.轻度贫血：Hb 116g/L，按贫血严重度分级属轻度（血红蛋白>90g/L但低于正常下限；中度90～60g/L；重度60～30g/L；极重度<30g/L），结合慢性病及营养不良背景，考虑慢性病性贫血可能，待复查铁代谢、维生素B12及叶酸明确病因。\n4.营养状态：近1年体重下降约2kg，营养中等偏下，存在营养不良风险，须行营养风险筛查（NRS 2002）并予营养支持。\n\n（六）西医鉴别诊断：\n1.支气管哮喘：\n【支持点】两者均表现为发作性喘息、胸闷、呼吸困难，双肺均可闻及哮鸣音。\n【不支持点】哮喘多在青少年起病，多有过敏史及家族史，症状发作与缓解迅速，支气管舒张试验多阳性，气道受限多可逆；本例老年起病，有长期吸烟史，症状呈慢性进行性加重，支气管舒张试验阴性，气流受限持续存在。\n【排除方法】结合肺功能（支气管舒张试验、支气管激发试验）、过敏原检测及胸部CT鉴别，必要时检测血嗜酸性粒细胞及IgE。\n2.慢性心力衰竭（左心功能不全）：\n【支持点】均可出现活动后气短、呼吸困难。\n【不支持点】心衰多有冠心病、高血压、瓣膜病等基础心脏病，常伴夜间阵发性呼吸困难、端坐呼吸、咳粉红色泡沫痰、双下肢水肿、颈静脉怒张，查体可闻及双肺底湿啰音及第三心音奔马律，利钠肽多明显升高。\n【排除方法】查心脏彩超评估心脏结构及射血分数，查血浆利钠肽（BNP/NT-proBNP），结合心电图及胸部影像学鉴别。\n3.肺结核：\n【支持点】均可有慢性咳嗽、乏力、消瘦。\n【不支持点】肺结核多有低热、盗汗、咯血、消瘦明显，抗感染治疗无效，痰中可查及抗酸杆菌，影像学多见上肺叶渗出、空洞或播散灶。\n【排除方法】查痰抗酸染色及结核分枝杆菌核酸检测、结核菌素试验或γ干扰素释放试验，复查胸部CT，必要时行支气管镜检查。\n4.支气管扩张症：\n【支持点】两者均为慢性气道疾病，均可出现慢性咳嗽、咳痰、气促及肺部湿啰音。\n【不支持点】支气管扩张症以反复咳大量脓痰、间断咯血、痰液静置分层为特征，啰音位置固定持久，可有杵状指；本例痰少稀白、无咯血、无杵状指，啰音不固定，胸部CT为肺气肿改变。\n【排除方法】胸部高分辨率CT可明确有无支气管柱状或囊状扩张。\n5.自发性气胸：\n【支持点】自发性气胸可突发呼吸困难加重，本例近1周气喘加重，须注意除外，且本例有肺气肿基础、为气胸高危人群。\n【不支持点】自发性气胸多突发一侧胸痛，患侧呼吸音明显减弱或消失、叩诊呈鼓音，气管向健侧移位；本例双肺呼吸音减低但两侧对称，均可闻及哮鸣音及湿啰音，无突发剧烈胸痛。\n【排除方法】床旁胸片或胸部CT可明确有无气胸线及肺压缩带。\n6.肺血栓栓塞症：\n【支持点】肺血栓栓塞症亦可表现为气促、活动后呼吸困难加重及低氧血症，与本例气喘加重相似。\n【不支持点】肺血栓栓塞症多有下肢深静脉血栓、长期卧床、手术外伤或肿瘤等危险因素，可伴胸痛、咯血、晕厥，D-二聚体明显升高；本例起病与受凉相关，伴咳嗽咳痰增多，无上述危险因素及咯血、晕厥。\n【排除方法】查D-二聚体、下肢静脉彩超及动脉血气分析，必要时行肺动脉CTA。\n\n（七）诊疗计划：\n1.护理与饮食：按中医科（肺病）护理常规，Ⅲ级护理；予低盐低脂、高蛋白、易消化饮食，以补肺健脾益气为法，宜食山药、大枣、莲子、黄芪炖鸡、瘦肉、蛋类及新鲜蔬果，忌生冷肥甘、辛辣及烟酒；卧床休息，避风寒，注意保暖，病室空气流通、温湿度适宜，自汗者勤换内衣。\n2.完善检查：完善血常规、网织红细胞计数（目的：明确贫血程度及骨髓代偿情况，为贫血病因筛查提供依据）；完善铁代谢、维生素B12及叶酸（目的：明确贫血类型及有无造血原料缺乏，为补铁或补充维生素治疗提供依据）；完善C反应蛋白、降钙素原（目的：判断有无感染及炎症状态，为抗感染治疗决策提供依据）；完善动脉血气分析（目的：明确PaO2、PaCO2及酸碱状态，判断有无呼吸衰竭，为氧疗及呼吸支持提供依据）；完善肝肾功能、电解质（目的：评估脏器功能及电解质平衡，为安全用药提供依据）；完善心电图、心脏彩超（目的：评估心功能及肺动脉压力，为鉴别心源性疾病、判断有无肺源性心脏病提供依据）；完善肺功能及支气管舒张试验（目的：评估气流受限程度与可逆性，为GOLD分级及吸入治疗方案提供依据）；必要时复查胸部CT（目的：明确肺部病变变化，为排除肺部感染、占位性病变及评估肺气肿程度提供依据）。\n3.西医治疗：①氧疗：持续低流量吸氧1～2L/min，每日累计15小时以上，维持指脉氧饱和度90%～93%；②解痉平喘：氨茶碱片0.1g 每日3次 口服，注意监测心率及有无恶心、手抖等不良反应；③祛痰：羧甲司坦片0.5g 每日3次 口服；④吸入治疗：布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次吸入，吸入后立即漱口，必要时可临时加吸1次；⑤抗感染：目前血常规WBC及中性粒细胞比例正常，暂不予抗菌药物，待C反应蛋白、降钙素原回报，若提示细菌感染或痰量增多、变黄脓性，则加用注射用头孢呋辛钠1.5g 加入0.9%氯化钠注射液100ml 静脉滴注 每12小时1次（皮试阴性后使用），或根据痰培养及药敏结果调整；⑥对症支持：贫血（Hb 114g/L）待铁代谢及造血原料结果回报后，必要时口服琥珀酸亚铁片0.1g 每日2次、叶酸片5mg 每日1次，并予注射用胸腺法新1.6mg 皮下注射 每周2次以调节免疫；咳嗽剧烈影响睡眠者可予复方甲氧那明胶囊每次2粒、每日3次口服；⑦监测：每日监测体温、呼吸、心率、血压及指脉氧饱和度2～3次，必要时复查血气分析及肺功能。\n4.中医治疗：给予中药方剂以补肺益气、敛肺止咳、固表纳肾为治则；方选补肺汤合玉屏风散加减；中药处方如下：人参10g（另煎兑服） 黄芪30g 熟地黄15g 五味子6g 紫菀10g 桑白皮10g 白术12g 防风10g 蛤蚧1对（研末冲服） 山茱萸10g 核桃肉15g 炙甘草6g。共7剂，日1剂。用法：水煎服，每日一付，分2次温服（早、晚各1次，饭后温服）。方解：方中人参大补肺脾之气、益气生津，黄芪益气固表、补肺实卫，二药相须为君，直补肺气之亏耗，以复肺主气、司呼吸之职；方中熟地黄补肾填精、滋阴养血，五味子酸收，上敛肺气、下滋肾水而纳气归元，蛤蚧补肺益肾、纳气平喘，山茱萸补益肝肾、收敛固涩以助肾纳气，核桃肉补肾温肺、润肠定喘，此五味共为臣药，取「金水相生」之意，使肺气得补而有所主，肾气得纳而有所根，则动则喘甚、气短不足以息可缓；方中紫菀润肺下气、消痰止咳，桑白皮泻肺平喘、清金降气，二药一润一降，既止其咳喘，又制参芪熟地温补之滞，使补而不壅；白术健脾益气、燥湿和中，以「培土生金」助肺气之源，防风祛风固表而不伤正，助黄芪固卫御风，三药共为佐药；炙甘草益气和中、润肺止咳、调和诸药，为使药。全方补而不滞、散中有收、金水并调，共奏补肺益气、敛肺止咳、固表纳肾之效。随症加减：自汗畏风明显者加牡蛎30g（先煎）、浮小麦30g固表敛汗；咳痰量多色白者加半夏9g、陈皮9g燥湿化痰；纳差腹胀者加砂仁6g（后下）、焦三仙各10g醒脾消食；夜尿频多、腰膝酸软者加补骨脂10g、益智仁10g温肾纳气；喘甚不能平卧者加紫石英15g（先煎）、沉香3g（后下）镇摄纳气；兼痰黄黏稠者加黄芩10g、鱼腥草20g清肺化痰；兼口干咽燥、舌红少苔者加沙参12g、麦冬12g养阴润肺。针灸治疗：取肺俞、定喘、膻中、膏肓、足三里、太渊、肾俞等穴，平补平泻，留针20分钟，每日1次，10次为1疗程，以补益肺气、止咳平喘；亦可予穴位贴敷（肺俞、膏肓、膻中）冬病夏治、冬病冬防。\n5.密切观察病情变化，向家属交代目前病情，注意防跌倒、防坠床、防烫伤，注意防寒保暖、预防感冒，积极医患沟通，及时请上级医师查看病人；若出现气短明显加重、动则喘甚不能平卧、痰量增多变黄、发热或双下肢浮肿，及时复查血气分析及胸部CT并请相关科室会诊。\n\n医师签名：陈医生","主治医师查房记录":"主治医师查房记录\n\n2026年08月11日 09:00（入院第2天）\n\n今日张主治医师查房。患者神志清楚，精神较前略有好转，诉气喘、气短较入院时稍有减轻，仍动则喘甚，稍事活动即气短不足以息，咳声低弱，咳少量稀白痰，咯吐无力，自汗畏风，纳差，二便调，夜尿2次。查体：T 36.5℃，P 84次/分，R 20次/分，BP 124/74mmHg，SpO2 94%（未吸氧）；面色淡白少华，口唇色淡，舌质淡、舌体偏胖、边有齿痕、苔薄白，脉细弱，右寸及双尺尤甚、重按无力；双肺呼吸音减低，可闻及散在呼气相哮鸣音，较入院时减少，双下肢无水肿。\n辅助检查回报：WBC 7.6×10^9/L，N% 62%，Hb 114g/L，C反应蛋白8.2mg/L；动脉血气分析（未吸氧）：pH 7.39，PaO2 68mmHg，PaCO2 43mmHg；肝肾功能、电解质正常；心脏彩超示左室射血分数62%，各房室大小正常，肺动脉收缩压约35mmHg。\n\n一、中医辨病辨证分析\n患者年近七旬，反复咳喘7年，加重1周，以气喘、动则喘甚、气短不足以息、咳声低弱、痰少稀白为主症，符合喘证以呼吸困难、甚则张口抬肩、鼻翼煽动、不能平卧为特征之辨病要点，其喘气短难续、深吸为快、动则加重，属虚喘，故辨病为「喘证」。四诊：面色淡白少华、口唇色淡，舌淡胖、边有齿痕、苔薄白，为气虚阳弱、脾失健运；语声低怯、咳声低微无力、气息短促，为肺气不足、宗气亦虚；自汗畏风、易感冒、纳差便溏、夜尿频，为肺卫不固、脾肾两虚；脉细弱、右寸及双尺尤甚而重按无力，右寸候肺、双尺候肾，正是肺肾气虚、根气不固之象。病机为久病咳喘，肺气先伤，肺主气司呼吸，肺气虚耗则气无所主而喘促短气；肺虚不能输布津液，聚而为痰，且气虚无力鼓痰外出，故痰少稀白而咯吐不爽；肺主皮毛、卫外不固则自汗畏风；肺虚不能助脾运化，脾肺气虚则纳差便溏；肺为气之主、肾为气之根，久病及肾、肾不纳气则动则喘甚、夜尿频多。四诊合参，辨证为喘证之「肺气虚耗」证，病位在肺，与脾、肾相关，病性属虚，以气虚为主，无明显实邪，故治疗当宗补肺益气、敛肺止咳之法。\n\n二、中医鉴别诊断\n1.与「肺阴亏耗」鉴别：肺阴亏耗者喘促气短、呛咳痰少质黏难咯、烦热口干、咽喉不利、面颧潮红，舌红少苔或苔剥、脉细数，治用沙参麦冬汤养阴润肺；本案痰稀白不黏、无口干咽燥，反见自汗畏风、四肢欠温，舌淡胖有齿痕、苔薄白而非舌红少苔，脉细弱而非细数，故属肺气亏耗、气不布津，非阴虚内热之候。\n2.与「肾虚不纳」鉴别：肾虚不纳以喘促日久、呼多吸少、气不得续、动则喘甚、形瘦神惫为辨证眼目，偏阳虚者汗出肢冷、面青唇紫、脉微细沉弱，偏阴虚者颧红烦热、舌红少津、脉细数；本案虽有动则喘甚、夜尿频多，但以气怯声低、自汗畏风、咳声低弱为主，无呼多吸少之候，亦无面青唇紫及跗肿，病位重心仍在肺，故辨为肺气虚耗而非肾虚不纳。\n3.与「肺胀」鉴别：肺胀由久病肺系疾患反复发作、迁延不愈而成，以胸部膨满、憋闷如塞、喘息持续、咳嗽痰多，甚则唇甲紫绀、心悸浮肿、颈静脉怒张为特征，属本虚标实、痰瘀阻肺；本案虽有轻度桶状胸、叩诊过清音及肺动脉收缩压轻度升高，但喘以动则加重、静息可缓为特点，无胸中膨满憋闷之主诉及紫绀、浮肿，实邪不著，故以喘证（肺气虚耗）立论。\n4.与「哮病」鉴别：哮病为发作性痰鸣气喘，喉中哮鸣有声如水鸡声，多有过敏史或家族史，起病急、缓解快，缓解期如常人，病机为宿痰伏肺、遇感而发；本案喘势缓慢持续、进行性加重，以气短难续、动则喘甚为主，无喉中痰鸣如吼之典型发作，双肺哮鸣音散在而不弥漫，故属喘证而非哮病。\n\n三、西医鉴别诊断\n1.与支气管哮喘鉴别：哮喘多于幼年或青年起病，症状呈发作性、可逆性，支气管舒张试验多为阳性，常有过敏史及血嗜酸性粒细胞升高；本例中老年起病、病程7年进行性加重，支气管舒张试验阴性、FEV1/FVC 58%提示持续气流受限，故支持慢性阻塞性肺疾病。\n2.与慢性心力衰竭鉴别：左心衰以夜间阵发性呼吸困难、端坐呼吸、咳粉红色泡沫痰、双肺底湿啰音为特点，心脏彩超示射血分数下降、左房增大；本例无上述表现，心脏彩超左室射血分数62%、各房室大小正常，故可除外左心衰所致喘促。\n3.与支气管扩张症鉴别：支气管扩张以长期大量咳脓痰、间断咯血、肺部固定性湿啰音为特点，胸部CT可见卷发样或印戒征；本例咳痰量少色白、无咯血，胸部CT示双肺透亮度增高、肺纹理增粗紊乱，符合肺气肿改变，故不支持支气管扩张。\n\n四、国内外相关疾病研究进展\n1.《慢性阻塞性肺疾病诊治指南（2021年修订版）》指出，稳定期以减轻症状、降低急性加重风险为双目标，支气管舒张剂是控制症状的核心药物，并强调戒烟、疫苗接种、肺康复与长期家庭氧疗（每日≥15小时）的综合价值，与本例低流量吸氧及呼吸锻炼的处置相符。\n2.2023年GOLD报告按症状与急性加重风险分组，本例症状负担重、活动耐力明显下降，倾向高风险组，初始治疗推荐长效β2受体激动剂联合长效抗胆碱能药物，支气管舒张试验阴性亦提示需长期吸入维持治疗而非按需单药。\n3.一项纳入数百例慢阻肺稳定期患者的多中心随机对照研究显示，在常规西药治疗基础上加用补肺益气类中药复方3～6个月，患者FEV1及6分钟步行距离较对照组提高，急性加重次数减少，圣乔治呼吸问卷评分下降，提示中西医结合治疗可改善肺功能与生活质量。\n4.针对补肺汤、玉屏风散类方治疗慢阻肺稳定期的系统评价（纳入多项随机对照试验）提示，益气固表方药可降低急性加重频次、改善免疫功能指标，未见严重不良反应，但研究样本量偏小、随访期偏短，仍需高质量大样本试验验证。\n\n五、诊疗计划\n1.中医治疗：治则治法为补肺益气、敛肺止咳、固表纳肾。方选补肺汤合玉屏风散加减：人参10g（另煎兑服）、黄芪30g、熟地黄15g、五味子6g、紫菀10g、桑白皮10g、白术12g、防风10g、蛤蚧1对（研末冲服）、山茱萸10g、炙甘草6g。7剂，水煎服，每日1付，分2次温服。方解：方中人参大补肺脾之气、黄芪益气固表补肺，二药相合为君，直补肺气之亏耗；熟地黄补肾填精、五味子敛肺滋肾纳气，取金水相生之意，蛤蚧补肺益肾、纳气平喘，山茱萸补益肝肾、收敛固涩以助肾纳气，四药为臣，使气有所主、气有所根；紫菀润肺下气、消痰止咳，桑白皮泻肺平喘而制温补之滞，白术健脾益气以培土生金，防风祛风固表而不伤正，共为佐药；炙甘草益气和中、调和诸药，为使。全方补而不滞、散中有收。随症加减：自汗畏风明显者加牡蛎30g（先煎）、浮小麦30g固表敛汗；痰多色白者加半夏9g、陈皮9g燥湿化痰；纳差腹胀者加砂仁6g（后下）、焦三仙各10g醒脾消食；夜尿频多、腰膝酸软者加补骨脂10g、益智仁10g温肾纳气；喘甚不能平卧者加紫石英15g（先煎）、沉香3g（后下）镇摄纳气。\n2.西医治疗：继续低流量吸氧1～2L/min，每日累计15小时以上；氨茶碱0.1g 每日3次口服解痉平喘；羧甲司坦0.5g 每日3次口服祛痰；必要时予布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次吸入，吸入后漱口；针对Hb 114g/L完善铁代谢、维生素B12及叶酸检查以明确贫血类型，必要时补充铁剂及造血原料。\n3.护理与调摄：饮食以补肺健脾益气为法，宜食山药、大枣、莲子、黄芪炖鸡、瘦肉、蛋类及新鲜蔬果以纠正贫血，忌生冷肥甘及烟酒；起居避风寒、慎保暖，自汗者勤换内衣，保持病室空气流通、温湿度适宜；情志宜舒畅乐观，避免忧思恼怒耗气；功能锻炼坚持缩唇呼吸、腹式呼吸每日2～3次，循序渐进配合太极拳、八段锦及耐寒锻炼。\n4.医患沟通：已向患者及家属交代，本次为慢性肺系疾病急性加重，中医辨证属喘证之肺气虚耗，经补肺益气、敛肺止咳中药配合氧疗及解痉祛痰西药后气喘气短已有减轻，血气分析示轻度低氧血症而无二氧化碳潴留，病情总体可控；本病病程长、易反复，需坚持中药调理与呼吸功能锻炼，严格戒烟，避免受凉及烟雾粉尘刺激，每年接种流感疫苗；1周后复查动脉血气分析及肺功能评估疗效，若出现气促明显加重、痰量增多变黄、发热或口唇紫绀，须立即告知医护人员。患者及家属表示理解并配合治疗。\n执行情况：遵嘱执行。\n\n医师签名：陈医生","日常病程记录":"日常病程记录\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n【病程记录一】2026年08月11日 09:00（入院第2天）\n\n患者入院第2天，神志清楚，精神较前略有好转，气喘、气短较入院时稍有减轻，仍动则喘甚，咳声低弱，咳少量稀白痰，自汗畏风，纳差，夜尿2次，二便调。查体：T 36.5℃，P 84次/分，R 20次/分，BP 124/74mmHg；舌质淡、舌体偏胖、边有齿痕、苔薄白，脉细弱；双肺呼吸音减低，散在呼气相哮鸣音较前减少，双下肢无水肿。继续补肺益气中药汤剂口服，续予低流量吸氧及解痉祛痰治疗，加强呼吸功能锻炼指导及戒烟宣教。\n\n【病程记录二】2026年08月13日 09:00（入院第4天）\n\n患者入院第4天，神志清楚，精神好转，诉气喘明显减轻，平地缓行百余米不觉气短，咳声较前有力，痰量减少，自汗畏风减轻，食欲改善，夜尿1～2次，大便成形。查体：T 36.4℃，P 80次/分，R 19次/分，BP 122/72mmHg，SpO2 95%（未吸氧）；面色较前转润，舌质淡红、边有齿痕、苔薄白，脉细，较前有力；双肺呼吸音略增强，哮鸣音基本消失。复查血常规、C反应蛋白较前改善。患者经中药辨证论治后症状改善，治疗有效，继续原方随症加减，酌减氨茶碱用量，继续巩固治疗。\n\n【病程记录三】2026年08月15日 09:00（入院第6天）\n\n患者入院第6天，神志清楚，精神好，气喘、气短基本缓解，静息及一般活动后无明显气促，偶有单声咳嗽，痰少易咯，无自汗，纳可，夜寐安，二便调。查体：T 36.3℃，P 76次/分，R 18次/分，BP 120/72mmHg，SpO2 96%（未吸氧）；舌质淡红、苔薄白，脉细缓有力；双肺呼吸音清，未闻及明显干湿性啰音，双下肢无水肿。患者病情平稳，中药治疗有效，守方续进以巩固疗效，准备出院，嘱出院后继续中药调理、戒烟及呼吸功能锻炼，定期复诊。\n\n医师签名：陈医生","医患沟通记录":"医患沟通记录\n\n时间：2026年08月10日 16:00\n地点：医生办公室\n参加人员：患者及家属，主管医师陈医生\n\n沟通内容：\n1.病情告知：患者目前中医诊断为喘证（肺气虚耗），西医考虑慢性阻塞性肺疾病急性加重期，病情尚平稳，需住院进一步检查治疗。\n2.诊疗方案：完善血常规、血气分析、肺功能及心脏彩超等检查，中医辨证论治予补肺益气、敛肺止咳中药汤剂口服，配合低流量吸氧、解痉祛痰等对症支持治疗。\n3.可能风险：治疗过程中可能出现病情加重、呼吸衰竭、药物不良反应（如心悸、手抖、胃肠不适）等。\n4.注意事项：卧床休息，避风寒，戒烟，清淡饮食，配合检查治疗，勿自行停药或加减药量。\n5.预后情况：经积极治疗及规范管理，症状多可缓解，但本病易反复，需长期调养与随访。\n\n患者及家属表示理解，签署相关知情同意书。\n\n医师签名：陈医生\n患者/家属签名：患者","出院记录":"出院记录\n\n入院日期：2026年08月10日\n出院日期：2026年08月20日\n住院天数：11天\n\n入院诊断：\n中医诊断：喘证（肺气虚耗）\n西医诊断：慢性阻塞性肺疾病急性加重期；轻度贫血\n\n出院诊断：\n中医诊断：喘证（肺气虚耗）\n西医诊断：慢性阻塞性肺疾病（稳定期）；轻度贫血\n\n入院情况：\n患者，男，68岁，因「反复咳喘7年，加重伴气短乏力1周」入院。入院查体：T 36.6℃，P 88次/分，R 22次/分，BP 126/76mmHg；神志清楚，精神倦怠，轻度桶状胸，双肺呼吸动度减弱，叩诊过清音，双肺呼吸音减低，可闻及散在呼气相哮鸣音及少量湿性啰音。中医四诊：面色淡白少华，舌质淡、舌体偏胖、边有齿痕、苔薄白，语声低怯，脉细弱、重按无力。辅助检查：肺功能FEV1占预计值52%、FEV1/FVC 58%，支气管舒张试验阴性；胸部CT示双肺透亮度增高、肺纹理增粗紊乱；血常规WBC 7.8×10^9/L，Hb 116g/L。\n\n诊疗经过：\n入院后完善血常规、C反应蛋白、动脉血气分析、肝肾功能、电解质、心电图、心脏彩超及肺功能等检查，中医四诊合参，明确诊断为喘证（肺气虚耗）、慢性阻塞性肺疾病急性加重期。予内科Ⅲ级护理，低流量吸氧，避风寒、戒烟；中药以补肺益气、敛肺止咳为法，方用补肺汤合玉屏风散加减（人参10g、黄芪30g、熟地黄15g、五味子6g、紫菀10g、桑白皮10g、白术12g、防风10g、蛤蚧1对、山茱萸10g、核桃肉15g、炙甘草6g），随症加减，每日1剂，早晚温服，共10剂；配合针灸（肺俞、定喘、膻中、膏肓、足三里、太渊、肾俞）及呼吸功能锻炼；西药予氨茶碱0.1g每日3次口服、羧甲司坦0.5g每日3次口服，后氨茶碱逐渐减量停用。经治疗患者气喘、气短明显减轻，咳嗽咳痰好转，自汗畏风缓解，食欲改善，复查血氧饱和度正常范围，经上级医师同意后准予出院。\n\n出院情况：\n患者神志清楚，精神好，气喘、气短基本缓解，静息及一般活动后无明显气促，偶有单声咳嗽，痰少易咯，无自汗畏风，纳可，夜寐安，二便调。查体：T 36.3℃，P 76次/分，R 18次/分，BP 120/72mmHg，SpO2 96%（未吸氧）；面色较前转润，舌质淡红、苔薄白，脉细缓有力；双肺呼吸音清，未闻及明显干湿性啰音，双下肢无水肿。\n\n出院医嘱：\n1.饮食：清淡易消化、高蛋白饮食，多食山药、百合、白果、核桃、瘦肉、蛋类等补肺健脾之品，忌生冷、辛辣及肥甘厚味，戒烟限酒。\n2.休息与活动：注意休息，避免劳累及受凉，坚持缩唇呼吸、腹式呼吸训练，每日2～3次，每次10～15分钟；循序渐进进行耐寒锻炼及散步、太极拳等有氧运动。\n3.用药：出院带中药7剂，方用补肺汤合玉屏风散加减（人参10g另煎兑服、黄芪30g、熟地黄15g、五味子6g、紫菀10g、桑白皮10g、白术12g、防风10g、蛤蚧1对研末冲服、山茱萸10g、核桃肉15g、炙甘草6g），水煎服，每日1剂，分早晚两次温服，饭后服用；继续按医嘱使用吸入剂，不可自行停药或改量。\n4.复查：出院后1周门诊复查，2周后复查血常规、动脉血气分析及肺功能；中药服完后携方来院调整，不适随诊。\n5.注意事项：避风寒，预防感冒，如出现气促加重、痰量增多或变黄、发热、口唇紫绀、下肢水肿等，立即就诊；长期家庭氧疗者每日吸氧不少于15小时，定期随访评估肺功能。\n\n医师签名：陈医生\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：喘证（肺气虚耗）／慢性阻塞性肺疾病急性加重期（J44.1）\n入院病情：有\n其他诊断（名称+ICD-10编码）：轻度贫血（D64.9）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）","病程记录第3天":"病程记录\n\n2026年08月12日 09:00（入院第3天）\n\n患者，男，68岁，入院第3天，神志清楚，精神较前好转，气喘、气短较入院时减轻，动则仍有气促但程度减轻，咳声较前有力，咳少量稀白痰，自汗减少，纳可，二便调，夜寐安。\n查体：T 36.5℃，P 82次/分，R 20次/分，BP 124/74mmHg，SpO2 94%（未吸氧）。神志清楚，精神可，面色淡白。舌质淡、边有齿痕、苔薄白，脉细弱，较前稍有力。双肺呼吸音减低，可闻及少量呼气相哮鸣音，心率82次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查：血常规WBC 7.4×10^9/L，Hb 115g/L；C反应蛋白6.5mg/L，较前下降；动脉血气分析（未吸氧）：pH 7.40，PaO2 71mmHg，PaCO2 42mmHg。\n四诊合参，本病属中医「喘证（肺气虚耗）」范畴，肺气亏虚、卫外不固，治以补肺益气、敛肺止咳，方用补肺汤合玉屏风散加减。患者经中药辨证论治后症状较前减轻，治疗有效，继续目前中药治疗，守方续进。注意观察气喘及痰量痰色变化，继续低流量吸氧及呼吸功能锻炼，避免受凉劳累，清淡饮食，调畅情志。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","病程记录第5天":"病程记录\n\n2026年08月14日 09:00（入院第5天）\n\n患者入院第5天，神志清楚，精神好转，气喘、气短明显减轻，平地缓行不觉气促，咳声有力，痰少色白易咯，自汗畏风基本缓解，食欲改善，夜寐安，二便调，夜尿减少至1次。\n查体：T 36.4℃，P 78次/分，R 18次/分，BP 122/72mmHg，SpO2 95%（未吸氧）。神志清楚，精神好，面色较前转润。舌质淡红、边有齿痕、苔薄白，脉细缓，较前有力。双肺呼吸音略增强，未闻及明显哮鸣音，心率78次/分，律齐。腹软，无压痛。双下肢无水肿。\n辅助检查：复查血常规WBC 7.2×10^9/L，Hb 118g/L；C反应蛋白4.0mg/L，恢复正常；肝肾功能、电解质正常。\n患者经中药辨证论治后症状明显改善，病情稳定。继续目前治疗，巩固疗效，中药守方随症加减，氨茶碱逐渐减量；继续呼吸功能锻炼及戒烟宣教。建议出院后继续服用中药调理，定期复诊，避风寒，慎起居，加强营养，适当锻炼以增强体质。\n\n医师签名：＿＿＿＿＿＿＿＿＿＿","主任医师查房记录":"主任查房记录\n\n2026年08月16日 10:00（入院第7天）\n\n今日李副主任医师查房，患者神志清楚，精神好，诉气喘、气短基本缓解，静息时无气促，一般活动后无明显喘息，偶有单声咳嗽，痰少易咯，无自汗畏风，纳可，夜寐安，二便调，夜尿1次。\n查体：T 36.3℃，P 76次/分，R 18次/分，BP 120/72mmHg，SpO2 96%（未吸氧）。面色较前转润，口唇无紫绀。舌质淡红、苔薄白，脉细缓有力。胸廓呈轻度桶状胸，双肺呼吸动度较前改善，叩诊过清音，双肺呼吸音清，未闻及明显干湿性啰音。心率76次/分，律齐。腹软，无压痛。双下肢无水肿。\n\n一、中医辨病辨证分析\n患者年老久病，反复咳喘7年，属中医「喘证」范畴。入院时以气喘、动则喘甚、气短不足以息、咳声低弱、痰少稀白、自汗畏风为主症，舌淡胖有齿痕、苔薄白，脉细弱而右寸、双尺尤甚，辨为肺气虚耗证，病位在肺，与脾、肾相关。今查房四诊明显转佳：面色由淡白转润，气息由短促转平和，语声较前有力，自汗畏风消失，纳寐转佳，舌由淡转淡红，脉由细弱转细缓有力，说明肺气得复、卫表得固。然仍有夜尿、痰少、活动后偶有气短，提示肺虚日久，子盗母气则脾运不健，久病及肾则肾纳失职，属肺脾肾同病而肺虚为主。辨证要点把握三条：一察喘之缓急，静息不喘而动则气短，属虚喘而非实喘；二察舌脉进退，舌淡胖为气虚之根，转淡红而未转红绛、苔未剥，说明未化燥伤阴；三问汗与畏风，自汗畏风止而恶寒罢，提示卫气已充、表虚已固。整体辨证仍为喘证之肺气虚耗证，兼脾肾两虚、气不归元之机，诊疗方向正确，辨证要点再次确认无误。\n\n二、中医鉴别诊断\n1.与「肾虚不纳」再鉴别：肾虚不纳以呼多吸少、气不得续、动则喘甚、形瘦神惫、面青唇紫为关键，治当补肾纳气，方如金匮肾气丸合参蛤散，必要时加紫石英、沉香镇摄；本案经补肺益气治疗后气息转平、咳声转扬、舌脉向愈，始终无呼多吸少及面青唇紫之候，说明喘之根在肺气虚耗，尚未至肾不纳气之重候，故仍守原辨，但可佐入温肾纳气之品，防其由肺及肾、由气及阳。\n2.与「肺阴亏耗」再鉴别：肺阴亏耗者舌红少苔或苔剥、脉细数，必见口干咽燥、痰黏难咯、颧红烦热；本案用参、芪、白术等温补之品7日，不仅未见口干、咽痛、便秘等化燥伤阴之象，舌反由淡转淡红、苔仍薄白而润，脉由细弱转细缓，说明所辨确为气虚而非阴虚，温补未致偏颇，此亦为疗效反证辨证准确之要据。\n3.与「肺胀」再鉴别：肺胀以胸中膨满、憋闷如塞、喘息持续、痰多，甚则唇甲紫绀、心悸浮肿、颈静脉怒张为特征，属本虚标实、痰瘀互结，治当化痰祛瘀、泻肺平喘；本案虽有轻度桶状胸及肺动脉收缩压轻度升高，但7日来无胸满憋闷之诉，无紫绀、无心悸浮肿，喘随动而作、静则自平，痰少易咯，实邪不著，故仍以喘证为纲；惟原发病为久病肺系疾患，须警惕日后痰瘀内停、由喘转胀，随访中动态观察。\n4.与「气短（少气）」再鉴别：气短为呼吸微弱、言语无力，多属气虚之轻候，一般无喘促、无动则喘甚；本案入院时静息亦觉气不接续、动则喘甚，喘促之象显著，故属喘证虚喘范畴，经治后虽近乎平人，仍属喘证缓解期，不能因症状减轻而改辨为单纯气短，治疗亦不可骤停补肺固本之剂。\n\n三、西医疑难分析与鉴别\n本例西医诊断为慢性阻塞性肺疾病急性加重期（GOLD 2级，FEV1占预计值52%，支气管舒张试验阴性）、轻度低氧血症、轻度肺动脉高压、轻度贫血。鉴别：1.支气管哮喘：本例中老年起病、气流受限不完全可逆、舒张试验阴性、无过敏史，可与之鉴别，但若日后出现嗜酸性粒细胞明显升高或症状波动明显，需考虑哮喘-慢阻肺重叠。2.左心功能不全：无夜间阵发性呼吸困难及端坐呼吸，心脏彩超左室射血分数62%、各房室大小正常，可除外；惟肺动脉收缩压约35mmHg提示肺循环阻力轻度升高，需定期复查彩超动态评估有无肺源性心脏病。3.支气管扩张症：胸部CT无卷发样及印戒征，痰少无咯血，可除外。疑难之处：一是肺动脉收缩压轻度升高与气喘症状的因果关系，目前考虑继发于慢性肺病所致肺血管重构，尚需随访；二是Hb 114g/L所致贫血可加重组织缺氧与气短，须查明类型并纠正，方能客观评价肺功能改善程度。\n\n四、国内外相关疾病研究进展\n1.《慢性阻塞性肺疾病诊治指南（2021年修订版）》明确稳定期以吸入支气管舒张剂为基础治疗，长效β2受体激动剂联合长效抗胆碱能药物可改善症状、减少急性加重；对急性加重高风险且外周血嗜酸性粒细胞增高者推荐含吸入糖皮质激素方案，并强调肺康复、长期家庭氧疗（每日≥15小时）及流感、肺炎疫苗接种的综合价值。\n2.2023年GOLD报告提出急性加重后8周内为再发高风险窗口期，出院前即应制定吸入维持治疗方案与随访计划，本例出院前复查血气及肺功能、明确长期分组即符合该要求。\n3.一项纳入数百例慢阻肺稳定期患者的随机对照研究显示，在常规吸入治疗基础上联合补肺益气类中药复方治疗3个月，患者FEV1、6分钟步行距离及圣乔治呼吸问卷评分均较对照组改善，急性加重次数减少，提示中西医结合治疗对改善肺功能与运动耐力有益。\n4.针对玉屏风散类方预防慢性肺系疾病反复急性发作的系统评价（纳入多项随机对照试验）提示，益气固表方药可降低感冒及急性加重发生频次、调节细胞免疫功能；另有研究显示蛤蚧、山茱萸、补骨脂等补肾纳气类中药可改善肺肾两虚型患者的呼吸肌力与运动耐力，但样本量偏小、随访期短，尚需大样本验证。\n\n五、诊疗计划\n1.中医治疗：治则治法调整为补肺益气、固表纳肾、兼顾脾运。方以补肺汤合玉屏风散加减进退：黄芪30g、党参15g、熟地黄15g、五味子6g、紫菀10g、桑白皮10g、白术12g、防风10g、蛤蚧1对（研末冲服）、山茱萸10g、补骨脂10g、炙甘草6g。7剂，水煎服，每日1付，分2次温服。方解：方中黄芪、党参为君，补肺脾之气、固护卫表，党参易人参者取其性平力缓、可久服而无助热之弊；熟地黄、山茱萸、五味子、蛤蚧、补骨脂为臣，补肾填精、纳气归元，遵「肺为气之主、肾为气之根」及金水相生之旨，使气有所根而喘不复作；紫菀润肺下气、消痰止咳，桑白皮泻肺平喘且制温补之滞，白术健脾培土生金，防风走表固卫，四药为佐，化痰止咳、健脾固表，兼防补药壅滞；炙甘草益气和中、调和诸药，为使。全方补肺不忘固表、益气兼以纳肾、培土以生金，较入院方加强纳肾之力，正合缓解期重在固本之治则。\n2.西医治疗：继续布地奈德福莫特罗粉吸入剂（160/4.5μg）每次1吸、每日2次吸入，吸入后及时漱口以防口咽念珠菌感染；按需或短期口服氨茶碱0.1g 每日3次、羧甲司坦0.5g 每日3次祛痰；长期家庭氧疗每日不少于15小时、流量1～2L/min；针对贫血完善铁代谢、维生素B12及叶酸检查，缺铁者予琥珀酸亚铁0.1g 每日2次餐后服并配维生素C 0.1g促进吸收；出院前复查动脉血气分析及肺功能，据结果确定长期分组与随访方案。\n3.护理与调摄：饮食宜温热易消化、补肺健脾益气，多食山药、大枣、莲子、瘦肉、蛋类及新鲜蔬果，忌生冷肥腻、戒烟酒；起居避风寒、随气温增减衣被，保持室内空气清新，避免烟雾粉尘及刺激性气体；情志宜平和乐观，避免忧思劳倦耗气伤肺；坚持缩唇呼吸、腹式呼吸每日2～3次，循序渐进练八段锦、太极拳及耐寒锻炼。\n4.医患沟通：已向患者及家属交代，本次住院经中西医结合治疗气喘气短明显缓解、自汗畏风消失、舌脉转佳，病情处于缓解期，可考虑近日出院；但本病为慢性进行性疾病，气流受限不完全可逆，肺功能难以完全恢复，出院后须坚持中药调理以补肺固表纳肾，坚持呼吸功能锻炼与长期家庭氧疗，严格戒烟、避免受凉及呼吸道感染，建议每年接种流感疫苗、每5年接种肺炎疫苗；出院后2周复诊，定期复查肺功能、血气分析及血常规，若出现气促加重、痰量增多变黄、发热、口唇紫绀或双下肢浮肿，须立即就诊。患者及家属表示理解并配合。\n执行情况：遵嘱执行。\n\n医师签名：陈医生"},"icd10_diagnosis":"J44.1","icd10_secondary":["D64.9"],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1230,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"201a292e0b30da7c2deead2d53ab6657f32998aed52a3d8a22bfc155b11ba372","pinyin":"chuanzheng（feiqixuhao）","initials":"cz（fqxh）","setting":"in","caseName":"病例1：患者，男，68岁","templateNames":["入院记录","首次病程记录","主治医师查房记录","日常病程记录","医患沟通记录","出院记录","病程记录第3天","病程记录第5天","主任医师查房记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，68岁",60],["模板名称","入院记录 首次病程记录 主治医师查房记录 日常病程记录 医患沟通记录 出院记录 病程记录第3天 病程记录第5天 主任医师查房记录",30],["主要诊断编码","J44.1",30]]}]);